insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check, reviewer_notes) values
(1121, 0, 'يكوّن الفوسفور خمس روابط أحادية P–Cl، كل منها زوج إلكترونات، فيحيط به 5 × 2 = 10 إلكترونات، أي أكثر من الثمانية.', '["","افترض تحقق قاعدة الثمانية، لكن خمس روابط تعني خمسة أزواج = 10 إلكترونات.","5 هو عدد إلكترونات تكافؤ الفوسفور، لا عدد الإلكترونات المحيطة به بعد تكوين الروابط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (67%)"}],"at":"2026-10-11T11:15:01.571Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1122, 1, 'يكوّن الكبريت ست روابط أحادية S–F، فيحيط به 6 × 2 = 12 إلكترونًا، وهو مثال على تمدد الثمانية.', '["6 هو عدد إلكترونات تكافؤ الكبريت أو عدد الروابط، لا عدد الإلكترونات المحيطة به.","","افترض تحقق قاعدة الثمانية، لكن ست روابط تعني ستة أزواج = 12 إلكترونًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (67%)"}],"at":"2026-10-11T11:15:01.572Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1123, 2, 'في SF₆ يحيط بالكبريت 12 إلكترونًا (ست روابط)، وهو من أمثلة الاستثناء (أكثر من 8).', '["في BF₃ يحيط بالبورون 6 إلكترونات فقط، أي أقل من الثمانية.","في NH₃ يحيط بالنيتروجين 8 إلكترونات تمامًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T11:15:01.572Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1124, 1, 'تستطيع ذرات عناصر الدورة الثالثة وما بعدها (مثل P وS) استيعاب أكثر من ثمانية إلكترونات لتوافر المستوى الفرعي d، أما النيتروجين في الدورة الثانية فلا يمتلك مستوى d في غلاف تكافؤه فلا تتجاوز إلكتروناته ثمانية.', '["لكل من الفوسفور والنيتروجين 5 إلكترونات تكافؤ لأنهما في المجموعة 15.","","النيتروجين أعلى كهروسالبية من الفوسفور، والكهروسالبية ليست سبب عدم تكوّن NCl₅."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T11:15:01.572Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1125, 2, 'عدد الإلكترونات حول الذرة المركزية = عدد الروابط × 2 (لا أزواج حرة عليها): PCl₅ = 10 وSF₆ = 12، وكلاهما أكثر من ثمانية. أما NF₃ ففيه زوج حر على N فيحيط به 8.', '["SF₆ يتجاوز الثمانية فعلًا، لكن N في NF₃ يحيط به 8 إلكترونات (ثلاث روابط وزوج حر).","PCl₅ يتجاوز الثمانية فعلًا، لكن N في NF₃ يحيط به 8 إلكترونات فقط.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T11:15:01.573Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1126, 1, 'مجموع الإلكترونات = 5 + 5 × 7 = 40 (20 زوجًا): خمسة أزواج رابطة، و15 زوجًا حرًا تُوزع ثلاثة على كل Cl، فلا يبقى زوج حر على P.', '["زوج حر على P يرفع المجموع إلى 42 إلكترونًا، وهو أكثر من إلكترونات التكافؤ (40).","","زوجان على كل Cl لا يكملان ثمانية الكلور ويتركان 10 إلكترونات دون توزيع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-11T11:15:01.573Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1127, 0, 'حول S أربعة أزواج رابطة (8 إلكترونات) وزوج حر (إلكترونان) = 10 إلكترونات، فهو مثال آخر على تمدد الثمانية.', '["","احتسب الأزواج الرابطة الأربعة فقط وأهمل الزوج الحر على S.","افترض وجود زوجين حرين على S، لكن المجموع (34) لا يسمح إلا بزوج حر واحد بعد إكمال ثمانيات F."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-11T11:15:01.575Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1128, null, null, null, 'الخطوات: (1) مجموع الإلكترونات = 5 + 5 × 7 = 40 إلكترونًا = 20 زوجًا. (2) P ذرة مركزية وذرات Cl الخمس جانبية، نضع رابطة أحادية P–Cl مع كل منها (5 أزواج). (3) نكمل ثمانيات ذرات Cl: ثلاثة أزواج حرة على كل Cl (15 زوجًا). (4) تنفد الأزواج العشرون، ولا يبقى زوج حر على P.
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check, reviewer_notes) values
(1239, null, null, null, 'تذوب في الماء: الكحول وHCl لأن جزيئاتهما قطبية مثل جزيئات الماء. لا تذوب في الماء: CCl₄ والزيت لأن جزيئاتهما غير قطبية (CCl₄ متماثل الشكل فمحصلة قطبيته صفر)، والمذاب غير القطبي لا يذوب في المذيب القطبي.', '["الكحول يذوب","HCl يذوب","CCl₄ لا يذوب","الزيت لا يذوب","السبب: الأشباه تذوب في الأشباه"]'::jsonb, '[]'::jsonb, '[{"element":"تصنيف الكحول وHCl","marks":2},{"element":"تصنيف CCl₄ والزيت","marks":2},{"element":"ذكر السبب بالقطبية","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تصنيف صحيح للمواد الأربع مع السبب"},{"level":"4 درجات","description":"تصنيف صحيح دون سبب واضح أو خطأ في مادة واحدة مع السبب"},{"level":"2–3 درجات","description":"تصنيف صحيح لمادتين أو ثلاث"},{"level":"1 درجة","description":"تصنيف صحيح لمادة واحدة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تصنيف CCl₄ قطبيًا لأن روابطه قطبية","إهمال ذكر السبب","القول إن HCl لا يذوب لأنه غاز"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T11:15:01.649Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1240, null, null, null, 'الخطوات: نضع كمية من الماء في كل أنبوب، ونضيف الكحول إلى الأنبوب الأول وزيت الطبخ إلى الثاني، ثم نرج الأنبوبين ونتركهما قليلًا. الملاحظة: في الأنبوب الأول يتكون محلول متجانس طبقة واحدة، وفي الثاني تنفصل طبقتان (الزيت فوق الماء). الاستنتاج: الكحول القطبي ذاب في الماء القطبي، والزيت غير القطبي لم يذب فيه، فالمركبات القطبية تذوب في المذيبات القطبية.', '["خطوات واضحة مع مقارنة","ملاحظة الأنبوب الأول","ملاحظة الأنبوب الثاني","استنتاج مرتبط بالقطبية"]'::jsonb, '[]'::jsonb, '[{"element":"خطوات التجربة","marks":1},{"element":"ملاحظة الكحول مع الماء","marks":1},{"element":"ملاحظة الزيت مع الماء","marks":1},{"element":"الاستنتاج","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"ذكر نصف العناصر تقريبًا مع ربط ضعيف"},{"level":"1 درجة","description":"عنصر واحد صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدم استخدام أنبوب مقارنة (الزيت)","استنتاج أن الزيت لا يذوب لأنه أخف من الماء","عكس الملاحظتين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T11:15:01.649Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1241, 1, 'الزيت مادة غير قطبية والبنزين مذيب غير قطبي، فيذوب الزيت فيه (مثال المذكرة: الزيت في البنزين).', '["الماء مذيب قطبي لا يذيب المواد غير القطبية.","","الكحول مذيب قطبي فلا يذيب الزيت جيدًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T11:15:01.651Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1242, 0, 'وفق قاعدة «الأشباه تذوب في الأشباه» تذوب المواد غير القطبية في المذيبات غير القطبية.', '["","المذيبات القطبية كالماء لا تذيب المواد غير القطبية.","المواد غير القطبية تذوب جيدًا في المذيبات المشابهة لها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T11:15:01.651Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1243, 2, 'الشحم مادة غير قطبية، فيذوب في مذيب غير قطبي مثل الجازولين، أما الماء (مالحًا كان أو باردًا) فمذيب قطبي لا يذيبه.', '["الماء قطبي فلا يذيب الشحم غير القطبي.","إضافة الملح لا تجعل الماء مذيبًا غير قطبي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T11:15:01.652Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1244, 1, 'البارافين غير قطبي وCCl₄ مذيب غير قطبي، فيذوب البارافين فيه. أما الماء فقطبي لا يذيب البارافين ولا الزيت.', '["البارافين غير قطبي والماء قطبي فلا يذوب.","","الزيت غير قطبي والماء قطبي فتنفصل طبقتان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T11:15:01.652Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1245, 2, 'شكل جزيء CCl₄ رباعي الأوجه متماثل، فتتعادل قطبيات الروابط الأربع وتكون محصلة القطبية صفرًا، فيكون الجزيء غير قطبي ويذيب المواد غير القطبية.', '["ذرة الكربون تشارك بإلكتروناتها في الروابط الأربع.","روابط C–Cl تساهمية قطبية وليست أيونية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:01.652Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1246, 0, 'جزيء I₂ ثنائي الذرة متماثل فهو غير قطبي، وCCl₄ غير قطبي، فيذوب اليود فيه وفق «الأشباه تذوب في الأشباه»، بينما لا يذوب جيدًا في الماء القطبي.', '["","ذرتا اليود متماثلتان فالجزيء غير قطبي، وCCl₄ أيضًا غير قطبي.","الذوبان هنا عملية فيزيائية وليس تفاعلًا كيميائيًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:01.652Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1247, 1, 'الزيت والبنزين غير قطبيين فيذوب أحدهما في الآخر مكونين محلولًا متجانسًا، أما الزيت والماء فيختلفان في القطبية فينفصلان إلى طبقتين.', '["الزيت يذوب في البنزين لأنهما غير قطبيين.","","الزيت لا يذوب في الماء القطبي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T11:15:01.652Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1248, null, null, null, 'الزيت مادة غير قطبية والبنزين مذيب غير قطبي، فتتشابه طبيعة القوى بين جزيئاتهما (قوى تشتت ضعيفة)، فتنتشر جزيئات الزيت بين جزيئات البنزين ويذوب فيه. أما الماء فمذيب قطبي تتجاذب جزيئاته بقوة فيما بينها، ولا تنجذب لجزيئات الزيت غير القطبية بالقدر الكافي، فلا يذوب الزيت فيه وتنفصل طبقتان. وهذا تطبيق لقاعدة «الأشباه تذوب في الأشباه».', '["الزيت غير قطبي","البنزين غير قطبي فيذيبه","الماء قطبي فلا يذيبه","ذكر قاعدة الأشباه تذوب في الأشباه"]'::jsonb, '[]'::jsonb, '[{"element":"الزيت غير قطبي","marks":1},{"element":"البنزين غير قطبي فيذيبه","marks":1},{"element":"الماء قطبي فلا يذيبه","marks":1},{"element":"القاعدة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"ذكر نصف العناصر تقريبًا مع ربط ضعيف"},{"level":"1 درجة","description":"عنصر واحد صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الزيت لا يذوب في الماء لأنه أخف منه","وصف البنزين بأنه مذيب قطبي","الاكتفاء بذكر القاعدة دون تطبيق"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T11:15:01.653Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1249, null, null, null, 'الماء: جزيء قطبي لأن روابطه قطبية وشكله منحنٍ غير متماثل فمحصلة القطبية لا تساوي صفرًا؛ يذيب المواد القطبية مثل الكحول. CCl₄: جزيء غير قطبي، فروابطه قطبية لكن شكله رباعي الأوجه متماثل فتلغي القطبيات بعضها؛ يذيب المواد غير القطبية مثل اليود أو الزيت أو البارافين.', '["الماء قطبي","سبب قطبية الماء (شكل غير متماثل)","CCl₄ غير قطبي","سبب عدم قطبيته (شكل متماثل)","مثال لكل مذيب"]'::jsonb, '[]'::jsonb, '[{"element":"قطبية الماء وسببها","marks":2},{"element":"عدم قطبية CCl₄ وسببه","marks":2},{"element":"مثالان صحيحان","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"مقارنة كاملة بالأسباب والأمثلة"},{"level":"3–4 درجات","description":"مقارنة صحيحة مع نقص سبب أو مثال"},{"level":"1–2 درجة","description":"تحديد القطبية فقط دون أسباب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن CCl₄ قطبي لأن روابطه قطبية","إغفال دور شكل الجزيء","ذكر مثال مذاب قطبي لـ CCl₄"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:01.653Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1250, null, null, null, 'اليود I₂: جزيء غير قطبي (ذرتان متماثلتان) فيذوب في البنزين غير القطبي. الكحول: قطبي فيذوب في الماء القطبي. شمع البارافين: غير قطبي فيذوب في البنزين غير القطبي. والقاعدة: الأشباه تذوب في الأشباه.', '["اليود في البنزين","الكحول في الماء","البارافين في البنزين","التعليل بالقطبية"]'::jsonb, '[]'::jsonb, '[{"element":"اليود في البنزين مع التعليل","marks":1},{"element":"الكحول في الماء مع التعليل","marks":1},{"element":"البارافين في البنزين مع التعليل","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة صحيحة"},{"level":"2 درجتان","description":"إجابة صحيحة ينقصها عنصر"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اختيار الماء لليود","عدم ربط الاختيار بقطبية المادة","الظن أن البارافين قطبي لأنه صلب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T11:15:01.653Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1251, 0, 'قوى فان دير فالس هي قوى التجاذب بين الجزيئات (قوى بين جزيئية)، وهي أضعف من الروابط داخل الجزيء.', '["","الترابط بين ذرات الجزيء الواحد روابط تساهمية (قوى جزيئية) وليست قوى فان دير فالس.","التجاذب بين الأيونات رابطة أيونية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-11T11:15:01.655Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1252, 2, 'قوى فان دير فالس قوى بين جزيئية، فهي تعمل بين جزيء Cl₂ والجزيئات المجاورة، أما الذرتان داخل الجزيء فترتبطان برابطة تساهمية.', '["الذرتان داخل الجزيء ترتبطان برابطة تساهمية أحادية.","جذب النواة لإلكتروناتها داخل الذرة ليس قوة بين الجزيئات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-11T11:15:01.656Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1253, 1, 'حسب المذكرة: القوى بين الجزيئية (قوى فان دير فالس) أضعف من القوى الجزيئية (الروابط داخل الجزيء).', '["الروابط داخل الجزيء أقوى بكثير من التجاذب بين الجزيئات.","","القوتان مختلفتان في المقدار والموضع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T11:15:01.656Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1254, 0, 'قوى التشتت وقوى ثنائية القطب من القوى بين الجزيئية (قوى فان دير فالس)، أما البديلان الآخران فقوى جزيئية (روابط كيميائية).', '["","الرابطتان الأيونية والفلزية قوى جزيئية وليست بين جزيئية.","الأحادية والثنائية أنواع للرابطة التساهمية داخل الجزيء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:01.656Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1255, 2, 'الغليان تغير فيزيائي تبقى فيه جزيئات H₂O كما هي، فالطاقة تُستهلك في التغلب على قوى التجاذب بين الجزيئات لا في كسر الروابط داخلها.', '["لو كُسرت روابط O–H لتحلل الماء إلى عناصره، وهذا لا يحدث عند الغليان.","جزيئات الماء لا ترتبط بروابط أيونية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-11T11:15:01.656Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1256, 0, 'كلما زادت قوى التجاذب بين الجزيئات احتاجت المادة إلى طاقة أكبر لتغلي، وBr₂ أعلى درجة غليان فقوى التجاذب بين جزيئاته هي الأقوى.', '["","F₂ أقل درجة غليان فقوى التجاذب بين جزيئاته هي الأضعف.","اختلاف درجات الغليان يدل على اختلاف قوى التجاذب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:01.656Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1257, 2, 'قوى فان دير فالس قوى تجاذب ضعيفة بين الجزيئات، وقوتها تحدد كثيرًا من الخواص الفيزيائية كدرجات الانصهار والغليان.', '["انتقال الإلكترونات يكوّن روابط أيونية لا قوى بين جزيئية.","هي قوى بين الجزيئات في المواد الجزيئية التساهمية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-11T11:15:01.657Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1258, null, null, null, 'قوى فان دير فالس: قوى التجاذب بين الجزيئات. من أنواعها: قوى التشتت (بين الجزيئات غير القطبية مثل Cl₂) وقوى ثنائية القطب (بين الجزيئات القطبية مثل HCl). الفرق: قوى فان دير فالس تعمل بين جزيء وآخر وهي ضعيفة، أما الرابطة التساهمية فتعمل بين الذرات داخل الجزيء الواحد وهي أقوى بكثير.', '["تعريف صحيح","نوعان صحيحان","الفرق في الموضع","الفرق في القوة"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"نوعان صحيحان","marks":1},{"element":"الموضع","marks":1},{"element":"القوة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"ذكر نصف العناصر تقريبًا مع ربط ضعيف"},{"level":"1 درجة","description":"عنصر واحد صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعريفها بأنها روابط بين الذرات","ذكر الرابطة الأيونية من أنواعها","القول إنها أقوى من الروابط التساهمية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T11:15:01.657Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1259, null, null, null, 'تحول اليود إلى بخار تغير فيزيائي يتطلب التغلب على قوى فان دير فالس بين جزيئات I₂ فقط، وهي قوى ضعيفة فيكفيها تسخين خفيف. أما الرابطة التساهمية بين ذرتي اليود داخل الجزيء فأقوى بكثير ولا تنكسر بهذا التسخين، لذا يبقى الجزيء I₂ سليمًا في البخار.', '["التبخر يتغلب على القوى بين الجزيئات","هذه القوى ضعيفة","الرابطة داخل الجزيء أقوى ولا تنكسر"]'::jsonb, '[]'::jsonb, '[{"element":"التغلب على القوى بين الجزيئات","marks":1},{"element":"ضعف هذه القوى","marks":1},{"element":"بقاء الرابطة التساهمية داخل الجزيء","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة صحيحة"},{"level":"2 درجتان","description":"إجابة صحيحة ينقصها عنصر"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن التسخين يكسر الرابطة بين ذرتي اليود","عدم التمييز بين القوى الجزيئية والبين جزيئية","تفسير الظاهرة بالرابطة الأيونية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-11T11:15:01.657Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1260, null, null, null, 'الترتيب تصاعديًا حسب قوة التجاذب: CH₄ < C₂H₆ < C₃H₈. التفسير: درجة الغليان تزداد بزيادة قوى التجاذب بين الجزيئات، وC₃H₈ أعلاها درجة غليان. وبما أن الجزيئات غير قطبية فالقوى بينها قوى تشتت تزداد بزيادة عدد الإلكترونات (CH₄: 10، C₂H₆: 18، C₃H₈: 26 إلكترونًا).', '["الترتيب الصحيح","ربط درجة الغليان بقوة التجاذب","قوى التشتت تزداد بزيادة عدد الإلكترونات"]'::jsonb, '["عدد الإلكترونات: CH₄ = 6 + 4 = 10 ، C₂H₆ = 12 + 6 = 18 ، C₃H₈ = 18 + 8 = 26","مقارنة درجات الغليان: −162 < −89 < −42","الاستنتاج: قوة التجاذب تزداد بالترتيب نفسه"]'::jsonb, '[{"element":"الترتيب","marks":1},{"element":"الربط بدرجة الغليان","marks":1},{"element":"التفسير بعدد الإلكترونات","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"ترتيب صحيح وتفسير كامل"},{"level":"3 درجات","description":"ترتيب صحيح وتفسير ينقصه عدد الإلكترونات"},{"level":"2 درجتان","description":"ترتيب صحيح دون تفسير"},{"level":"1 درجة","description":"ربط صحيح دون ترتيب سليم"},{"level":"صفر","description":"إجابة خاطئة"}]'::jsonb, '["عكس الترتيب لأن القيم سالبة","التفسير بكسر الروابط C–H","عدّ الإلكترونات خطأً"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:01.657Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1261, 2, 'Br₂ جزيء غير قطبي (ذرتان متماثلتان)، وقوى التشتت هي القوى بين الجزيئات غير القطبية كما في المذكرة (H₂، Cl₂، F₂، Br₂).', '["HCl جزيء قطبي فتوجد بين جزيئاته قوى ثنائية القطب أيضًا.","بين جزيئات الماء روابط هيدروجينية إضافة إلى غيرها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T11:15:01.661Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1262, 0, 'قوى التشتت قوى تجاذب ضعيفة بين الجزيئات تنتج عن إزاحة مؤقتة لكثافة الإلكترونات فتتكون ثنائيات قطب مؤقتة، وهي القوى السائدة بين الجزيئات غير القطبية.', '["","التجاذب بين الأيونات رابطة أيونية.","هذا وصف قوى ثنائية القطب بين الجزيئات القطبية الدائمة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T11:15:01.661Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1263, 2, 'تزداد قوة التشتت بزيادة عدد الإلكترونات، وI₂ أكثرها إلكترونات (106)، فقوى التشتت بين جزيئاته هي الأقوى.', '["F₂ أقل الجزيئات إلكترونات (18) فقوى التشتت فيه هي الأضعف.","Cl₂ (34 إلكترونًا) أقل من I₂ في عدد الإلكترونات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-11T11:15:01.662Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1264, 1, 'الجزيئات الثلاثة غير قطبية، والقوى بينها قوى تشتت تزداد بزيادة عدد الإلكترونات من Cl₂ إلى I₂، فتزداد درجات الانصهار والغليان فتتغير الحالة من غاز إلى سائل إلى صلب.', '["الجزيئات الثلاثة غير قطبية لأن كل جزيء من ذرتين متماثلتين.","","كل جزيء فيه رابطة تساهمية أحادية واحدة فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T11:15:01.662Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1265, 0, 'حسب المذكرة: تزداد قوة التشتت بزيادة عدد الإلكترونات، لأن السحابة الإلكترونية الأكبر يسهل إزاحتها مؤقتًا.', '["","هذا عكس العلاقة الصحيحة.","عدد الإلكترونات هو العامل الرئيس المؤثر في قوة التشتت."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-11T11:15:01.662Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1266, 2, 'حسب ترتيب المذكرة: الرابطة الهيدروجينية > ثنائية القطب > التشتت، فقوى التشتت هي الأضعف بين القوى بين الجزيئية.', '["الرابطة الهيدروجينية هي الأقوى في ترتيب المذكرة.","لا يحدث انتقال للإلكترونات، وإنما إزاحة مؤقتة لكثافتها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T11:15:01.662Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1267, 0, 'كلا الجزيئين غير قطبي، فالقوى بينهما قوى تشتت تزداد بزيادة عدد الإلكترونات؛ O₂ له إلكترونات أكثر فقوى التشتت أكبر ودرجة غليانه أعلى (−183 °C مقابل −196 °C).', '["","N₂ أقل إلكترونات فقوى التشتت فيه أضعف.","كونهما غير قطبيين لا يعني تساوي قوى التشتت؛ فهي تعتمد على عدد الإلكترونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-11T11:15:01.663Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1268, null, null, null, 'قوى التشتت: قوى تجاذب ضعيفة بين الجزيئات تنشأ عن إزاحة مؤقتة لكثافة الإلكترونات (ثنائيات قطب مؤقتة). تسود بين الجزيئات غير القطبية مثل H₂ وCl₂ (أو F₂ وBr₂). وتزداد قوتها بزيادة عدد الإلكترونات في الجزيء.', '["تعريف صحيح","الجزيئات غير القطبية","مثالان","زيادة القوة بزيادة عدد الإلكترونات"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"نوع الجزيئات","marks":1},{"element":"مثالان","marks":1},{"element":"العامل المؤثر","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"ذكر نصف العناصر تقريبًا مع ربط ضعيف"},{"level":"1 درجة","description":"عنصر واحد صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إنها تسود بين الجزيئات القطبية","ذكر HCl مثالًا","القول إنها أقوى القوى بين الجزيئية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-11T11:15:01.663Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1269, null, null, null, 'جزيئات الهالوجينات كلها غير قطبية لأن كل جزيء من ذرتين متماثلتين، فالقوى بين جزيئاتها قوى تشتت. ومن البيانات نلاحظ أن درجة الغليان تزداد من F₂ إلى I₂ مع زيادة عدد الإلكترونات، لأن قوى التشتت تزداد بزيادة عدد الإلكترونات، فتحتاج الجزيئات إلى طاقة أكبر للانفصال عن بعضها.', '["الجزيئات غير قطبية","القوى بينها قوى تشتت","ربط زيادة الإلكترونات بزيادة قوى التشتت","ربط ذلك بارتفاع درجة الغليان"]'::jsonb, '[]'::jsonb, '[{"element":"الجزيئات غير قطبية وقواها تشتت","marks":1},{"element":"الملاحظة من البيانات","marks":1},{"element":"زيادة التشتت بزيادة الإلكترونات","marks":1},{"element":"الربط بدرجة الغليان","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"ذكر نصف العناصر تقريبًا مع ربط ضعيف"},{"level":"1 درجة","description":"عنصر واحد صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تفسير الاختلاف بالقطبية","القول إن الغليان يكسر الروابط بين ذرتي الهالوجين","الخلط في قراءة القيم السالبة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T11:15:01.663Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1270, null, null, null, 'عدد الإلكترونات: CH₄ = 6 + 4(1) = 10 إلكترونات، وC₄H₁₀ = 4(6) + 10(1) = 34 إلكترونًا. بما أن قوى التشتت تزداد بزيادة عدد الإلكترونات، فقوى التشتت بين جزيئات البيوتان أكبر، لذا درجة غليان البيوتان أعلى من درجة غليان الميثان.', '["حساب إلكترونات CH₄","حساب إلكترونات C₄H₁₀","قوى التشتت أكبر في البيوتان","درجة غليان البيوتان أعلى"]'::jsonb, '["CH₄: 1×6 + 4×1 = 10","C₄H₁₀: 4×6 + 10×1 = 34","34 > 10 ⇐ قوى تشتت أكبر في C₄H₁₀","درجة غليان C₄H₁₀ أعلى"]'::jsonb, '[{"element":"عدد الإلكترونات للجزيئين","marks":2},{"element":"مقارنة قوى التشتت","marks":1},{"element":"توقع درجة الغليان","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"ذكر نصف العناصر تقريبًا مع ربط ضعيف"},{"level":"1 درجة","description":"عنصر واحد صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الذرات بدل الإلكترونات","القول إن البيوتان قطبي","عكس العلاقة بين الإلكترونات وقوى التشتت"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T11:15:01.663Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1271, 0, 'قوى ثنائية القطب قوى تجاذب بين الجزيئات القطبية، إذ ينجذب الطرف الموجب جزئيًا لجزيء إلى الطرف السالب جزئيًا لجزيء مجاور.', '["","هذا وصف قوى التشتت.","هذا وصف الرابطة الأيونية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T11:15:01.666Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1272, 1, 'HCl جزيء قطبي له طرف δ+ (H) وطرف δ− (Cl)، فتنشأ بين جزيئاته قوى ثنائية القطب كما في أمثلة المذكرة (HCl، H₂O، NH₃).', '["F₂ جزيء غير قطبي، والقوى بين جزيئاته قوى تشتت.","","H₂ جزيء غير قطبي، والقوى بين جزيئاته قوى تشتت."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-11T11:15:01.666Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1273, 2, 'تنشأ قوى ثنائية القطب بين الجزيئات القطبية التي تحمل أطرافًا ذات شحنات جزئية دائمة (δ+ وδ−).', '["المركبات الأيونية لا تتكون من جزيئات، والتجاذب فيها رابطة أيونية.","الرابطة الثنائية نوع من الروابط التساهمية ولا تعني قطبية الجزيء.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-11T11:15:01.666Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1274, 0, 'الكلور أعلى كهروسالبية فيحمل δ−، والهيدروجين يحمل δ+، فتنجذب ذرة H (δ+) في جزيء إلى ذرة Cl (δ−) في الجزيء المجاور.', '["","طرفا Cl كلاهما δ− فيتنافران ولا يتجاذبان.","الكلور أعلى كهروسالبية فيحمل δ− لا δ+."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T11:15:01.667Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1275, 2, 'تساوي عدد الإلكترونات يجعل قوى التشتت متقاربة، لكن HCl قطبي فتوجد بين جزيئاته قوى ثنائية القطب إضافية، فتزداد قوة التجاذب وترتفع درجة الغليان.', '["الرابطة الهيدروجينية تتطلب H مرتبطًا بـ F أو O أو N، وF₂ لا يحتوي H.","كتلة F₂ (38) أكبر قليلًا من HCl (36.5) ومع ذلك درجة غليانه أقل، فالكتلة ليست السبب.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-10-11T11:15:01.667Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1276, 1, 'ترتيب المذكرة: الرابطة الهيدروجينية > قوى ثنائية القطب > قوى التشتت، فقوى ثنائية القطب في المرتبة الوسطى.', '["هذا الترتيب معكوس تمامًا.","","الرابطة الهيدروجينية أقوى من قوى ثنائية القطب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:01.667Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1277, 0, 'H₂S جزيء قطبي (شكله منحنٍ غير متماثل)، فتنشأ بين جزيئاته قوى ثنائية القطب. أما CO₂ وCH₄ فجزيئاتهما غير قطبية.', '["","CO₂ خطي متماثل فمحصلة قطبيته صفر وقواه تشتت.","CH₄ غير قطبي، والقوى بين جزيئاته تشتت فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-11T11:15:01.667Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1278, null, null, null, 'قوى ثنائية القطب: قوى تجاذب بين الجزيئات القطبية، ينجذب فيها الطرف الموجب جزئيًا لجزيء إلى الطرف السالب جزئيًا لجزيء مجاور. في HCl يحمل Cl شحنة δ− لأنه أعلى كهروسالبية، ويحمل H شحنة δ+؛ فتصطف الجزيئات بحيث يقابل H (δ+) في جزيء ذرة Cl (δ−) في الجزيء المجاور: δ+H–Clδ− ··· δ+H–Clδ−.', '["تعريف صحيح","تحديد δ− على Cl وδ+ على H","وصف اتجاه التجاذب بين الجزيئات"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"تحديد الشحنات الجزئية","marks":1},{"element":"وصف الانتظام","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة صحيحة"},{"level":"2 درجتان","description":"إجابة صحيحة ينقصها عنصر"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["وضع δ+ على Cl","رسم التجاذب داخل الجزيء نفسه","الخلط بينها وبين الرابطة الأيونية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T11:15:01.668Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1279, null, null, null, 'قوى ثنائية القطب: توجد بين الجزيئات القطبية، وتنشأ من شحنات جزئية دائمة (δ+ وδ−)، وهي أقوى من قوى التشتت؛ مثالها HCl. قوى التشتت: هي القوى السائدة بين الجزيئات غير القطبية، وتنشأ من إزاحة مؤقتة لكثافة الإلكترونات، وهي أضعف القوى بين الجزيئية؛ مثالها Cl₂.', '["نوع الجزيئات لكل منهما","أصل النشوء لكل منهما","القوة النسبية","مثال لكل منهما"]'::jsonb, '[]'::jsonb, '[{"element":"نوع الجزيئات","marks":1},{"element":"أصل النشوء","marks":1},{"element":"القوة النسبية","marks":1},{"element":"المثالان","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"ذكر نصف العناصر تقريبًا مع ربط ضعيف"},{"level":"1 درجة","description":"عنصر واحد صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس القوة النسبية","وصف قوى التشتت بأنها دائمة","ذكر مثال قطبي لقوى التشتت السائدة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T11:15:01.668Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1280, null, null, null, 'HCl: ثنائية القطب لأن الجزيء قطبي. Br₂: تشتت لأن الجزيء غير قطبي (ذرتان متماثلتان). H₂S: ثنائية القطب لأن الجزيء قطبي (منحنٍ غير متماثل). CO₂: تشتت لأن الجزيء خطي متماثل غير قطبي رغم قطبية روابطه.', '["HCl ثنائية القطب","Br₂ تشتت","H₂S ثنائية القطب","CO₂ تشتت","التعليل بالقطبية"]'::jsonb, '[]'::jsonb, '[{"element":"HCl","marks":1},{"element":"Br₂","marks":1},{"element":"H₂S","marks":1},{"element":"CO₂","marks":1},{"element":"التعليل","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تصنيف صحيح للمواد الأربع مع التعليل"},{"level":"3–4 درجات","description":"تصنيف صحيح لثلاث أو أربع مواد دون تعليل كامل"},{"level":"1–2 درجة","description":"تصنيف صحيح لمادة أو مادتين"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تصنيف CO₂ ثنائي القطب لأن روابطه قطبية","عدم ذكر سبب القطبية","تصنيف H₂S ضمن الروابط الهيدروجينية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T11:15:01.668Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1281, 1, 'حسب المذكرة: الرابطة الهيدروجينية تجاذب بين ذرة H متصلة بذرة عالية الكهروسالبية (F أو O أو N) في جزيء، وذرة F أو O أو N في جزيء آخر، فهي قوة بين جزيئية.', '["الرابطة بين ذرتي H في جزيء H₂ رابطة تساهمية غير قطبية داخل الجزيء.","","التجاذب بين الأيونات رابطة أيونية وليس رابطة هيدروجينية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T11:15:01.670Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1282, 2, 'تتكون الرابطة الهيدروجينية عندما ترتبط ذرة H بذرة صغيرة عالية الكهروسالبية: F أو O أو N.', '["كهروسالبية هذه الذرات غير كافية لتكوين رابطة هيدروجينية.","هذه فلزات قليلة الكهروسالبية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T11:15:01.671Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1283, 0, 'في NH₃ ترتبط ذرات H بذرة N عالية الكهروسالبية، فتنجذب ذرة H في جزيء إلى ذرة N في جزيء مجاور مكونة رابطة هيدروجينية.', '["","ذرات H في CH₄ مرتبطة بالكربون، وهو ليس من F أو O أو N.","H₂ جزيء غير قطبي لا توجد فيه ذرة عالية الكهروسالبية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-11T11:15:01.671Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1284, 2, 'يرتبط H في الماء بذرة O عالية الكهروسالبية، فتتكون روابط هيدروجينية بين جزيئاته، وهي أقوى القوى بين الجزيئية، فترتفع درجة غليانه كثيرًا عن H₂S الذي لا يكوّنها.', '["كتلة H₂O (18) أقل من كتلة H₂S (34)، فالكتلة لا تفسر ارتفاع غليان الماء.","الروابط O–H تساهمية قطبية، والغليان لا يكسرها أصلًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:01.671Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1285, 1, 'الرابطة الهيدروجينية قوة تجاذب بين الجزيئات وليست رابطة كيميائية داخل الجزيء، وترتيبها في المذكرة: هيدروجينية > ثنائية القطب > تشتت.', '["هي قوة بين الجزيئات، وأضعف من الرابطة التساهمية.","","أضعف القوى بين الجزيئية هي قوى التشتت."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:01.671Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1286, 0, 'تحمل ذرة H شحنة جزئية موجبة لارتباطها بالأكسجين، فتنجذب إلى ذرة O (التي تحمل شحنة جزئية سالبة) في جزيء ماء مجاور.', '["","ذرتا O تحملان الشحنة الجزئية نفسها (δ−) فتتنافران.","الرابطة الهيدروجينية بين جزيئين مختلفين لا داخل الجزيء نفسه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T11:15:01.672Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1287, 2, 'ترتبط H في HF بذرة F (أعلى العناصر كهروسالبية) فتتكون روابط هيدروجينية قوية بين الجزيئات، فترتفع درجة الغليان رغم أن إلكترونات HF (10) أقل من HCl (18).', '["إلكترونات HF أقل، فقوى التشتت فيه أضعف لا أكبر.","HCl جزيء قطبي وبين جزيئاته قوى ثنائية القطب.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T11:15:01.672Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1288, null, null, null, 'الرابطة الهيدروجينية: قوة تجاذب بين ذرة هيدروجين متصلة بذرة عالية الكهروسالبية في جزيء، وذرة F أو O أو N في جزيء آخر. شرطها: أن ترتبط ذرة H بإحدى الذرات F أو O أو N. مثالان: الماء H₂O، والأمونيا NH₃ (أو فلوريد الهيدروجين HF).', '["تعريف صحيح","الشرط (H مرتبطة بـ F أو O أو N)","مثالان صحيحان"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"الشرط","marks":1},{"element":"مثالان","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة صحيحة"},{"level":"2 درجتان","description":"إجابة صحيحة ينقصها عنصر"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعريفها بأنها رابطة تساهمية بين ذرتي هيدروجين","ذكر CH₄ أو H₂ مثالًا","إغفال أنها بين جزيئين مختلفين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T11:15:01.672Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1289, null, null, null, 'يرتبط الهيدروجين في الماء بالأكسجين، وهو عالي الكهروسالبية، فتتكون روابط هيدروجينية قوية بين جزيئات الماء تحتاج إلى طاقة كبيرة للتغلب عليها، فترتفع درجة غليانه (100 °C) ويبقى سائلًا عند درجة حرارة الغرفة. أما في H₂S فيرتبط الهيدروجين بالكبريت، وهو ليس من F أو O أو N، فلا تتكون روابط هيدروجينية، والقوى بين جزيئاته أضعف، فدرجة غليانه منخفضة (−60 °C) ويكون غازًا. وزيادة الكتلة لا تعوض غياب الروابط الهيدروجينية.', '["الماء يكوّن روابط هيدروجينية لارتباط H بـ O","الروابط الهيدروجينية أقوى القوى بين الجزيئية فترتفع درجة الغليان","H₂S لا يكوّن روابط هيدروجينية لأن S ليس من F/O/N","القوى بين جزيئات H₂S أضعف فهو غاز"]'::jsonb, '[]'::jsonb, '[{"element":"روابط هيدروجينية في الماء وسببها","marks":1},{"element":"ربطها بارتفاع درجة الغليان","marks":1},{"element":"غيابها في H₂S وسببه","marks":1},{"element":"الاستنتاج عن الحالة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"ذكر نصف العناصر تقريبًا مع ربط ضعيف"},{"level":"1 درجة","description":"عنصر واحد صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["التفسير بكسر روابط O–H عند الغليان","القول إن الكتلة الأكبر تعني دائمًا غليانًا أعلى","اعتبار الكبريت قادرًا على تكوين روابط هيدروجينية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:01.672Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1290, null, null, null, 'تتكون روابط هيدروجينية بين جزيئات: H₂O (H مرتبطة بـ O)، وNH₃ (H مرتبطة بـ N)، وHF (H مرتبطة بـ F). لا تتكون في CH₄ لأن H مرتبطة بالكربون، ولا في H₂S لأن H مرتبطة بالكبريت، وكلاهما ليس من F أو O أو N.', '["H₂O تكوّن","NH₃ تكوّن","HF تكوّن","CH₄ وH₂S لا تكوّنان","التعليل بالذرة المرتبطة بالهيدروجين"]'::jsonb, '[]'::jsonb, '[{"element":"H₂O وNH₃ وHF","marks":3},{"element":"CH₄ وH₂S","marks":1},{"element":"التعليل","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تحديد صحيح للمواد الخمس مع التعليل"},{"level":"3–4 درجات","description":"تحديد صحيح مع خطأ واحد أو تعليل ناقص"},{"level":"1–2 درجة","description":"تحديد صحيح لمادة أو مادتين"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اعتبار وجود H في الجزيء كافيًا لتكوين الرابطة","إدراج H₂S لتشابهه مع H₂O في الصيغة","إغفال HF"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-11T11:15:01.673Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1291, 2, 'السكر (السكروز) مركب تساهمي جزيئي تترابط ذراته داخل الجزيء بروابط تساهمية، أما ملح الطعام NaCl فمركب أيوني يتكون من أيونات Na⁺ وCl⁻.', '["السكر لا يتكون من أيونات بل من جزيئات.","ملح الطعام مركب أيوني وليس جزيئيًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T11:15:01.675Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1292, 1, 'انصهار السكر تغير فيزيائي يتطلب التغلب على القوى بين الجزيئية الضعيفة نسبيًا، ولا تنكسر الروابط التساهمية داخل الجزيء.', '["الروابط داخل الجزيء أقوى بكثير ولا تنكسر عند الانصهار.","","السكر مركب جزيئي لا يحتوي أيونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T11:15:01.675Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1293, 0, 'NaCl مركب أيوني ترتبط أيوناته Na⁺ وCl⁻ في شبكة بلورية بتجاذب كهروستاتيكي قوي جدًا، فيحتاج إلى طاقة كبيرة جدًا للانصهار (نحو 801 °C).', '["","الملح مركب أيوني لا يتكون من جزيئات ولا روابط هيدروجينية فيه.","ضعف القوى يسهّل الانصهار، فلا يفسر عدم انصهار الملح."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (58%)"}],"at":"2026-10-11T11:15:01.675Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1294, 0, 'درجة انصهار الملح (801 °C) أعلى بكثير من السكر (نحو 186 °C)، والدرجة الأعلى تدل على قوى أقوى يجب التغلب عليها، وهي التجاذب بين الأيونات في الملح.', '["","درجة انصهار السكر أقل، فالقوى بين جزيئاته أضعف.","الفرق بين الدرجتين كبير جدًا فلا تكون القوى متقاربة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T11:15:01.676Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1295, 2, 'الملح ينصهر، لكنه يحتاج إلى درجة حرارة عالية جدًا (نحو 801 °C) بسبب قوة التجاذب بين أيوناته، لذلك لا ينصهر بالتسخين المعتدل.', '["هذا مفهوم خاطئ؛ فالملح ينصهر عند نحو 801 °C.","درجة انصهار الملح أعلى بكثير من السكر.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T11:15:01.676Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1296, 1, 'السكر مركب تساهمي جزيئي قواه بين الجزيئية ضعيفة فينصهر بالتسخين المعتدل، أما الملح فمركب أيوني يحتاج إلى حرارة عالية جدًا فيبقى صلبًا.', '["هذا عكس الصحيح؛ فالملح أعلى درجة انصهار.","","درجتا انصهارهما مختلفتان كثيرًا فلا تنصهران معًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T11:15:01.676Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1297, 2, 'يكفي التسخين المعتدل للتغلب على القوى بين جزيئات السكر لأنها ضعيفة، لكنه لا يكفي للتغلب على التجاذب الكهروستاتيكي القوي بين أيونات الملح.', '["الروابط التساهمية داخل الجزيء أقوى من القوى بين الجزيئات لا أضعف.","الكتلة المولية للسكر (342 g/mol) أكبر من NaCl (58.5 g/mol)، فالكتلة ليست السبب.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-11T11:15:01.676Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1298, null, null, null, 'السكر مركب تساهمي جزيئي، تترابط جزيئاته في الحالة الصلبة بقوى بين جزيئية ضعيفة نسبيًا، فيكفي التسخين المعتدل للتغلب عليها فينصهر (دون كسر الروابط التساهمية داخل الجزيء). أما ملح الطعام NaCl فمركب أيوني، ترتبط أيوناته Na⁺ وCl⁻ في شبكة بلورية بتجاذب كهروستاتيكي قوي جدًا، فيحتاج إلى طاقة كبيرة جدًا للانصهار (نحو 801 °C)، فلا ينصهر بالتسخين المعتدل.', '["السكر تساهمي جزيئي","قواه بين جزيئية ضعيفة فينصهر بسهولة","الملح أيوني","التجاذب بين أيوناته قوي فيحتاج إلى طاقة كبيرة"]'::jsonb, '[]'::jsonb, '[{"element":"السكر تساهمي جزيئي","marks":1},{"element":"ضعف القوى بين جزيئاته","marks":1},{"element":"الملح أيوني","marks":1},{"element":"قوة التجاذب بين الأيونات","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"ذكر نصف العناصر تقريبًا مع ربط ضعيف"},{"level":"1 درجة","description":"عنصر واحد صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن انصهار السكر يكسر روابطه التساهمية","القول إن الملح لا ينصهر أبدًا","تفسير الفرق بالكتلة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (58%)"}],"at":"2026-10-11T11:15:01.676Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1299, null, null, null, 'السكر: مركب تساهمي جزيئي، وحداته البنائية جزيئات، ويُتغلب عند انصهاره على قوى بين جزيئية ضعيفة، فدرجة انصهاره منخفضة نسبيًا. ملح الطعام: مركب أيوني، وحداته البنائية أيونات Na⁺ وCl⁻ في شبكة بلورية، ويُتغلب عند انصهاره على تجاذب كهروستاتيكي قوي بين الأيونات، فدرجة انصهاره عالية جدًا.', '["نوع المركب","الوحدات البنائية","نوع القوى","درجة الانصهار النسبية"]'::jsonb, '[]'::jsonb, '[{"element":"نوع المركب","marks":1},{"element":"الوحدات البنائية","marks":1},{"element":"نوع القوى","marks":1},{"element":"درجة الانصهار","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"ذكر نصف العناصر تقريبًا مع ربط ضعيف"},{"level":"1 درجة","description":"عنصر واحد صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["وصف السكر بأنه يتكون من أيونات","ذكر الروابط التساهمية داخل الجزيء كقوى يُتغلب عليها","عكس درجات الانصهار"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T11:15:01.677Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1300, null, null, null, 'العبارة خاطئة. الانصهار تغير فيزيائي تبقى فيه جزيئات السكر كما هي، فالتسخين المعتدل يتغلب فقط على القوى بين جزيئات السكر (وهي ضعيفة نسبيًا)، ولا يكسر الروابط التساهمية داخل الجزيء لأنها أقوى بكثير. التصحيح: «عند انصهار السكر تضعف القوى بين جزيئاته فتتحرك الجزيئات بحرية أكبر دون أن تنكسر الروابط داخلها».', '["الحكم بخطأ العبارة","الانصهار تغير فيزيائي","التغلب على القوى بين الجزيئات فقط","الروابط التساهمية لا تنكسر لقوتها"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"الانصهار تغير فيزيائي","marks":1},{"element":"التغلب على القوى بين الجزيئات","marks":1},{"element":"بقاء الروابط التساهمية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"ذكر نصف العناصر تقريبًا مع ربط ضعيف"},{"level":"1 درجة","description":"عنصر واحد صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الموافقة على العبارة","الحكم بالخطأ دون تعليل","الخلط بين الانصهار والتكرمل (التحلل)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T11:15:01.677Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1301, 0, 'القوى بين جزيئات كثير من المركبات الجزيئية ضعيفة، فتكفي طاقة درجة حرارة الغرفة لفصل الجزيئات عن بعضها، فتكون غازات ذات درجات غليان منخفضة.', '["","الروابط التساهمية داخل الجزيء قوية، والحالة الفيزيائية تحددها القوى بين الجزيئات.","المركبات الجزيئية لا تتكون من أيونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (59%)"}],"at":"2026-10-11T11:15:01.679Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1302, 2, 'حسب المذكرة: للمركبات التساهمية درجات انصهار وغليان منخفضة لضعف القوى بين جزيئاتها، وكثير منها غازات.', '["هذه من خواص المركبات الأيونية والمواد التساهمية الشبكية.","المركبات التساهمية الجزيئية لا توصل الكهرباء في الحالة الصلبة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T11:15:01.679Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1303, 1, 'تكون المادة غازًا عند 25 °C إذا كانت درجة غليانها أقل من 25 °C. درجة غليان الماء 100 °C فيكون سائلًا، أما CH₄ وNH₃ فدرجتا غليانهما أقل بكثير فهما غازان.', '["درجة غليان الميثان −162 °C أقل من 25 °C فهو غاز.","","درجة غليان الأمونيا −33 °C أقل من 25 °C فهي غاز."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-11T11:15:01.679Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1304, 2, 'إذا كانت درجة الغليان أقل من درجة حرارة الغرفة فالمادة تكون قد تجاوزت درجة غليانها، فتوجد غازًا، وهذا يدل على ضعف القوى بين جزيئاتها.', '["الغليان يتغلب على القوى بين الجزيئات ولا يكسر الروابط التساهمية.","المادة تكون غازًا لا صلبة إذا تجاوزت درجة الحرارة درجة غليانها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-11T11:15:01.680Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1305, 0, 'الميثان جزيء غير قطبي صغير (10 إلكترونات)، فالقوى بين جزيئاته قوى تشتت ضعيفة جدًا، فدرجة غليانه منخفضة جدًا (−162 °C) ويوجد غازًا.', '["","ذرات H في الميثان مرتبطة بالكربون فلا تتكون روابط هيدروجينية.","الميثان غير قطبي فلا توجد بين جزيئاته قوى ثنائية القطب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-11T11:15:01.680Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1306, 1, 'عدد إلكترونات Cl₂ (34) أقل من I₂ (106)، فقوى التشتت بين جزيئات الكلور أضعف، فدرجة غليانه منخفضة ويوجد غازًا عند درجة حرارة الغرفة.', '["الجزيئان كلاهما غير قطبي لأن كلًا منهما من ذرتين متماثلتين.","","الحالة الفيزيائية تحددها القوى بين الجزيئات لا الرابطة داخل الجزيء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-11T11:15:01.680Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1307, 0, 'CO₂ مركب جزيئي صغير غير قطبي، القوى بين جزيئاته ضعيفة فيوجد غازًا. أما البارافين فمادة جزيئية كبيرة صلبة لينة، والألماس مادة تساهمية شبكية صلبة جدًا.', '["","البارافين مادة جزيئية كبيرة الجزيئات توجد صلبة لينة (الشمع).","الألماس مادة تساهمية شبكية لا تتكون من جزيئات منفصلة، ودرجة انصهاره عالية جدًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T11:15:01.682Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1308, null, null, null, 'جزيئات هذه المركبات صغيرة وغير قطبية، فالقوى بين جزيئاتها (قوى التشتت) ضعيفة جدًا، فلا تحتاج إلى طاقة كبيرة للتغلب عليها، لذلك تكون درجات غليانها منخفضة جدًا (أقل من درجة حرارة الغرفة)، فتكون طاقة الجزيئات عند درجة حرارة الغرفة كافية لإبقائها منفصلة متباعدة في الحالة الغازية. أما الروابط التساهمية داخل الجزيء فقوية، لكنها لا تحدد الحالة الفيزيائية.', '["القوى بين الجزيئات ضعيفة","درجات الغليان منخفضة (أقل من درجة حرارة الغرفة)","طاقة الغرفة كافية لفصل الجزيئات","التمييز بين القوى داخل الجزيء وبينها"]'::jsonb, '[]'::jsonb, '[{"element":"ضعف القوى بين الجزيئات","marks":1},{"element":"انخفاض درجة الغليان","marks":1},{"element":"كفاية طاقة الغرفة","marks":1},{"element":"التمييز بين نوعي القوى","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"ذكر نصف العناصر تقريبًا مع ربط ضعيف"},{"level":"1 درجة","description":"عنصر واحد صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الروابط التساهمية داخل الجزيء ضعيفة","إغفال الربط بدرجة الغليان","وصف CO₂ بأنه قطبي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (59%)"}],"at":"2026-10-11T11:15:01.682Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1309, null, null, null, 'الغازات عند 25 °C: CH₄ وNH₃ وCO₂ لأن درجات غليانها (أو تساميها) أقل من 25 °C. غير الغازات: الماء H₂O لأن درجة غليانه 100 °C أعلى من 25 °C فيكون سائلًا. يشذ الماء لأن بين جزيئاته روابط هيدروجينية قوية متعددة (كل جزيء له ذرتا H وزوجان حران على O)، فتحتاج إلى طاقة أكبر للتغلب عليها فترتفع درجة غليانه.', '["تصنيف CH₄ وNH₃ وCO₂ غازات","تصنيف H₂O سائلًا","قاعدة المقارنة بـ 25 °C","تفسير شذوذ الماء بالروابط الهيدروجينية"]'::jsonb, '[]'::jsonb, '[{"element":"التصنيف الصحيح","marks":2},{"element":"قاعدة المقارنة","marks":1},{"element":"تفسير شذوذ الماء","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"تصنيف صحيح وتفسير كامل"},{"level":"3–4 درجات","description":"تصنيف صحيح مع تفسير ناقص"},{"level":"1–2 درجة","description":"تصنيف جزئي دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط في مقارنة القيم السالبة","تصنيف NH₃ سائلًا لوجود روابط هيدروجينية بين جزيئاته","تفسير شذوذ الماء بقوة روابط O–H داخل الجزيء"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T11:15:01.683Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1310, null, null, null, 'الميثان غاز عند درجة حرارة الغرفة لأن جزيئه صغير قليل الإلكترونات (10 إلكترونات)، فقوى التشتت بين جزيئاته ضعيفة جدًا. أما البارافين فصلب لين لأن جزيئاته كبيرة كثيرة الإلكترونات، فقوى التشتت بينها أكبر بكثير تكفي لإبقائه صلبًا، لكنها تبقى أضعف من الروابط الأيونية أو التساهمية الشبكية فيكون لينًا منخفض الانصهار.', '["الميثان غاز","البارافين صلب","التفسير بحجم الجزيء وعدد الإلكترونات وقوى التشتت"]'::jsonb, '[]'::jsonb, '[{"element":"حالة الميثان","marks":1},{"element":"حالة البارافين","marks":1},{"element":"التفسير بقوى التشتت وعدد الإلكترونات","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة صحيحة"},{"level":"2 درجتان","description":"إجابة صحيحة ينقصها عنصر"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["التفسير بالقطبية مع أن كليهما غير قطبي","القول إن البارافين مركب أيوني لأنه صلب","إغفال عدد الإلكترونات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-11T11:15:01.683Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1311, 2, 'ذكرت المذكرة أن المركبات التساهمية الجزيئية الصلبة لينة، ومثالها البارافين الموجود في الشمع.', '["الألماس مادة تساهمية شبكية شديدة الصلابة.","ملح الطعام مركب أيوني صلب صلد هش.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:01.685Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1312, 0, 'جزيئات هذه المواد يرتبط بعضها ببعض بقوى بين جزيئية ضعيفة، فيسهل إزاحة الجزيئات أو فصلها بقوة صغيرة، فتكون المادة لينة.', '["","الروابط التساهمية داخل الجزيء قوية، والليونة تحددها القوى بين الجزيئات.","المركبات الجزيئية لا تتكون من أيونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-11T11:15:01.685Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1313, 1, 'الخدش يزيح الجزيئات عن مواقعها دون كسر الروابط داخلها، وهذا سهل لأن قوى التجاذب بين جزيئات البارافين ضعيفة.', '["الروابط التساهمية داخل الجزيء أقوى بكثير من أن يكسرها الظفر.","","الشمع مادة جزيئية لا تحتوي أيونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-11T11:15:01.685Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1314, 2, 'المادة (ج) لينة ودرجة انصهارها منخفضة ولا توصل الكهرباء، وهذه خواص المركبات الجزيئية التساهمية التي تترابط جزيئاتها بقوى ضعيفة.', '["صلبة جدًا وعالية الانصهار جدًا وغير موصلة: خواص مادة تساهمية شبكية.","صلبة هشة عالية الانصهار ومصهورها يوصل الكهرباء: خواص مركب أيوني.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:01.686Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1315, 0, 'ضعف القوى بين الجزيئات يجعل إزاحة الجزيئات سهلة (ليونة)، ويجعل التغلب عليها بالتسخين سهلًا (انصهار منخفض)، فالخاصيتان لهما السبب نفسه.', '["","المواد اللينة كالبارافين منخفضة الانصهار لا مرتفعته.","الخاصيتان مرتبطتان بقوة التجاذب بين الجزيئات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T11:15:01.686Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1316, 2, 'البارافين يتكون من جزيئات منفصلة تترابط بقوى بين جزيئية ضعيفة فيكون لينًا، أما الألماس فشبكة متصلة ترتبط فيها كل ذرة C بأربع ذرات C بروابط تساهمية قوية فيكون شديد الصلابة.', '["البارافين مادة تساهمية جزيئية وليس أيونيًا.","العكس هو الصحيح: الألماس شبكة والبارافين جزيئات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T11:15:01.686Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1317, 1, 'حسب المذكرة: المركبات التساهمية الجزيئية درجات انصهارها وغليانها منخفضة، والصلبة منها لينة، بسبب ضعف القوى بين جزيئاتها.', '["هذه خواص المواد التساهمية الشبكية.","","المركبات الجزيئية لا توصل الكهرباء لعدم وجود أيونات أو إلكترونات حرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-11T11:15:01.686Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1318, null, null, null, 'البارافين مركب جزيئي تساهمي، تتكون مادته الصلبة من جزيئات منفصلة يرتبط بعضها ببعض بقوى بين جزيئية ضعيفة (قوى تشتت). لذلك يسهل إزاحة الجزيئات عن مواقعها بقوة صغيرة كالخدش بالظفر أو الضغط باليد، فتكون المادة لينة سهلة التشكيل، دون أن تنكسر الروابط التساهمية القوية داخل الجزيئات.', '["البارافين مركب جزيئي تساهمي","القوى بين جزيئاته ضعيفة","سهولة إزاحة الجزيئات = ليونة","الروابط داخل الجزيء لا تنكسر"]'::jsonb, '[]'::jsonb, '[{"element":"نوع المادة","marks":1},{"element":"ضعف القوى بين الجزيئات","marks":1},{"element":"ربط ذلك بسهولة الإزاحة والليونة","marks":1},{"element":"التمييز عن الروابط داخل الجزيء","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"ذكر نصف العناصر تقريبًا مع ربط ضعيف"},{"level":"1 درجة","description":"عنصر واحد صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الروابط التساهمية داخل الجزيء ضعيفة","وصف البارافين بأنه مركب أيوني","الاكتفاء بقول «لأنه شمع»"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T11:15:01.687Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1319, null, null, null, 'البارافين: وحداته البنائية جزيئات منفصلة، ترتبط بقوى بين جزيئية ضعيفة، فهو لين. الألماس: وحداته البنائية ذرات كربون مترابطة في شبكة متصلة، ترتبط كل ذرة بأربع ذرات كربون بروابط تساهمية قوية، فهو شديد الصلابة.', '["الوحدات البنائية لكل منهما","نوع القوى لكل منهما","الصلابة لكل منهما"]'::jsonb, '[]'::jsonb, '[{"element":"الوحدات البنائية","marks":2},{"element":"نوع القوى","marks":2},{"element":"الصلابة","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"مقارنة كاملة صحيحة للمادتين في البنود الثلاثة"},{"level":"4–5 درجات","description":"مقارنة صحيحة مع خطأ أو نقص في بند واحد"},{"level":"2–3 درجات","description":"مقارنة صحيحة في بند واحد أو لمادة واحدة"},{"level":"1 درجة","description":"معلومة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الألماس يتكون من جزيئات C منفصلة","عكس الصلابة","وصف قوى البارافين بأنها روابط تساهمية قوية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T11:15:01.687Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1320, null, null, null, 'المادة مركب جزيئي تساهمي. الأدلة: الليونة تدل على ضعف القوى بين الجسيمات (جزيئات ترتبط بقوى بين جزيئية ضعيفة)، وانخفاض درجة الانصهار يدل على أن التغلب على هذه القوى يحتاج إلى طاقة قليلة، وعدم توصيل المصهور للكهرباء يدل على عدم وجود أيونات، فليست مركبًا أيونيًا.', '["تحديد النوع: مركب جزيئي تساهمي","دلالة الليونة","دلالة انخفاض درجة الانصهار","دلالة عدم التوصيل"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد النوع","marks":1},{"element":"دلالة الليونة","marks":1},{"element":"دلالة الانصهار","marks":1},{"element":"دلالة عدم التوصيل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"ذكر نصف العناصر تقريبًا مع ربط ضعيف"},{"level":"1 درجة","description":"عنصر واحد صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تصنيفها أيونية لأنها صلبة","تصنيفها شبكية","تحديد النوع دون أدلة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-11T11:15:01.687Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1321, 0, 'حسب المذكرة: من أمثلة المواد الصلبة التساهمية الشبكية الألماس والكوارتز.', '["","السكر والبارافين مركبات جزيئية تساهمية وليست شبكية.","هذان مركبان أيونيان وليسا تساهميين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-11T11:15:01.689Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1322, 2, 'الألماس مادة تساهمية شبكية تتكون من ذرات الكربون فقط، ترتبط كل ذرة منها بأربع ذرات كربون.', '["السيليكون يدخل في تركيب الكوارتز لا الألماس.","الأكسجين يدخل في تركيب الكوارتز (SiO₂) لا الألماس.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T11:15:01.689Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1323, 1, 'الكوارتز هو ثاني أكسيد السيليكون SiO₂، وفيه ترتبط ذرات Si وO بروابط تساهمية في شبكة متصلة.', '["CO₂ مركب جزيئي غازي وليس شبكيًا.","","CaCO₃ (كربونات الكالسيوم) مركب أيوني."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-11T11:15:01.689Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1324, 0, 'الكوارتز شبكة متصلة من ذرات Si وO مرتبطة بروابط تساهمية. أما الجليد واليود فمواد جزيئية تترابط جزيئاتها بقوى بين جزيئية.', '["","الجليد صلب جزيئي تترابط جزيئات الماء فيه بروابط هيدروجينية.","اليود الصلب يتكون من جزيئات I₂ منفصلة تترابط بقوى تشتت."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-11T11:15:01.690Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1325, 2, 'المادة (ع) شديدة الصلابة، ودرجة انصهارها عالية جدًا، ولا توصل الكهرباء صلبة أو منصهرة، وهذه خواص المواد التساهمية الشبكية كالألماس والكوارتز.', '["لينة منخفضة الانصهار: خواص مركب جزيئي.","مصهورها يوصل الكهرباء: خواص مركب أيوني.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T11:15:01.690Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1326, 1, 'في الألماس ترتبط كل ذرة كربون بأربع ذرات كربون بروابط تساهمية، فتمتد الروابط في شبكة متصلة ثلاثية الأبعاد ولا توجد جزيئات منفصلة.', '["الروابط في الألماس تساهمية لا أيونية.","","لا توجد في الألماس جزيئات منفصلة، فالبلورة كلها شبكة واحدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T11:15:01.690Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1327, 0, 'المكون الرئيس لكثير من الرمل هو الكوارتز (ثاني أكسيد السيليكون SiO₂)، وهو مادة صلبة تساهمية شبكية.', '["","NaCl مركب أيوني (ملح الطعام) وليس شبكة تساهمية.","البارافين مركب جزيئي لين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-11T11:15:01.690Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1328, null, null, null, 'المثالان: الألماس ويتكون من ذرات الكربون C، والكوارتز ويتكون من السيليكون والأكسجين (SiO₂). يُصنفان مواد صلبة تساهمية شبكية لأن ذراتهما ترتبط بروابط تساهمية في شبكة متصلة تمتد في البلورة كلها، فلا توجد جزيئات منفصلة.', '["الألماس","الكوارتز","مكونات كل منهما","سبب التصنيف"]'::jsonb, '[]'::jsonb, '[{"element":"المثالان","marks":2},{"element":"مكونات كل منهما","marks":1},{"element":"سبب التصنيف","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"ذكر نصف العناصر تقريبًا مع ربط ضعيف"},{"level":"1 درجة","description":"عنصر واحد صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر ملح الطعام مثالًا","ذكر السكر أو البارافين مثالًا","القول إن الألماس يتكون من جزيئات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-10-11T11:15:01.691Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1329, null, null, null, 'تساهمية شبكية: الألماس، الكوارتز. جزيئية تساهمية: السكر، البارافين، اليود. أيونية: ملح الطعام.', '["الألماس والكوارتز شبكية","السكر والبارافين واليود جزيئية","ملح الطعام أيوني"]'::jsonb, '[]'::jsonb, '[{"element":"الشبكية","marks":2},{"element":"الجزيئية","marks":2},{"element":"الأيونية","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تصنيف صحيح للمواد الست"},{"level":"3–4 درجات","description":"خطأ في مادة أو مادتين"},{"level":"1–2 درجة","description":"تصنيف صحيح لمادتين أو ثلاث"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تصنيف ملح الطعام شبكيًا لصلابته","تصنيف السكر أيونيًا لأنه بلوري","تصنيف اليود شبكيًا لأنه صلب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-11T11:15:01.691Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1330, null, null, null, 'العبارة خاطئة. مع تشابه الصيغتين، فإن CO₂ يتكون من جزيئات منفصلة تترابط بقوى بين جزيئية ضعيفة، لذلك يتسامى عند درجة حرارة منخفضة (−78 °C). أما الكوارتز SiO₂ فمادة صلبة تساهمية شبكية، ترتبط فيها ذرات Si وO بروابط تساهمية في شبكة متصلة لا جزيئات منفصلة فيها، فهو شديد الصلابة ودرجة انصهاره عالية جدًا (نحو 1700 °C). فتشابه الصيغة لا يعني تشابه التركيب.', '["الحكم بخطأ العبارة","CO₂ جزيئات منفصلة بقوى ضعيفة","SiO₂ شبكة تساهمية متصلة","الاستدلال بالخواص"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"وصف CO₂","marks":1},{"element":"وصف SiO₂","marks":1},{"element":"الاستدلال بالخواص","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"ذكر نصف العناصر تقريبًا مع ربط ضعيف"},{"level":"1 درجة","description":"عنصر واحد صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الموافقة على العبارة","عدّ الكوارتز مركبًا أيونيًا","الحكم دون تعليل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T11:15:01.691Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1331, 1, 'حسب المذكرة: المواد الصلبة التساهمية الشبكية هشة، غير موصلة، شديدة الصلابة، ودرجات انصهارها عالية جدًا.', '["هذه الخواص تخالف المواد الشبكية تمامًا.","","قابلية الطرق والتوصيل من خواص الفلزات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-11T11:15:01.693Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1332, 0, 'انصهار المادة الشبكية يتطلب كسر روابط تساهمية قوية كثيرة، بينما انصهار المادة الجزيئية يتطلب التغلب على قوى بين جزيئية ضعيفة، لذا درجات انصهار الشبكية أعلى بكثير.', '["","المواد الجزيئية هي ذات درجات الانصهار المنخفضة.","الفرق كبير جدًا بين النوعين (مثلًا الكوارتز نحو 1700 °C والبارافين نحو 60 °C)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T11:15:01.694Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1333, 2, 'كل إلكترونات التكافؤ في الألماس تشارك في روابط تساهمية بين ذرات الكربون، فلا توجد إلكترونات حرة الحركة ولا أيونات، فلا يوصل الكهرباء.', '["روابط الألماس تساهمية لا أيونية.","ذرات الكربون في الألماس متقاربة ومرتبطة بقوة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-11T11:15:01.694Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1334, 2, 'صلابة شديدة جدًا، ودرجة انصهار عالية جدًا، وعدم توصيل الكهرباء حتى في الحالة المنصهرة: هذه خواص المواد الصلبة التساهمية الشبكية.', '["مصهور المركب الأيوني يوصل الكهرباء، وهذه المادة لا يوصل مصهورها.","المواد الجزيئية لينة ومنخفضة الانصهار.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-11T11:15:01.695Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1335, 0, 'الألماس من أشد المواد صلابة لأن ذراته مترابطة بروابط تساهمية قوية في شبكة متصلة، لذلك يستخدم في أدوات القطع والحفر.', '["","الألماس ليس لينًا بل شديد الصلابة.","الألماس لا يوصل الكهرباء، وهذه الخاصية لا علاقة لها بالقطع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:01.696Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1336, 1, 'المواد التساهمية الشبكية صلبة جدًا لكنها هشة؛ فالضربة القوية تكسر الروابط في مستويات معينة فتتفتت البلورة بدل أن تتشكل.', '["القابلية للطرق تعني التشكل دون كسر، وهي خاصية الفلزات.","","الليونة تعني سهولة الخدش والتشكيل، وهي خاصية المواد الجزيئية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:01.696Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1337, 2, 'المواد الشبكية كالألماس والكوارتز لا تذوب في الماء ولا تكوّن محاليل موصلة لأن ذراتها مترابطة بروابط تساهمية قوية في شبكة ولا تحتوي أيونات. أما البديلان الآخران فصحيحان.', '["عبارة صحيحة: فانصهارها يتطلب كسر روابط تساهمية كثيرة.","عبارة صحيحة وردت في المذكرة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-11T11:15:01.696Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1338, null, null, null, 'الخصائص: 1) شديدة الصلابة. 2) هشة. 3) غير موصلة للكهرباء. 4) درجات انصهارها عالية جدًا. المثالان: الألماس والكوارتز.', '["شديدة الصلابة","هشة","غير موصلة للكهرباء","درجات انصهار عالية جدًا","مثالان"]'::jsonb, '[]'::jsonb, '[{"element":"الخصائص الأربع","marks":4},{"element":"المثالان","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"أربع خصائص صحيحة ومثالان"},{"level":"3–4 درجات","description":"ثلاث خصائص أو أربع دون أمثلة"},{"level":"1–2 درجة","description":"خاصية أو خاصيتان"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر «لينة» ضمن الخصائص","ذكر «توصل الكهرباء»","ذكر ملح الطعام مثالًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T11:15:01.697Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1339, null, null, null, '(أ) الصلابة الشديدة: لأن ذراتها مترابطة بروابط تساهمية قوية في شبكة متصلة ثلاثية الأبعاد، فخدشها أو تشويهها يتطلب كسر روابط تساهمية كثيرة. (ب) عدم توصيل الكهرباء: لأن إلكترونات التكافؤ مقيدة في الروابط التساهمية، ولا توجد إلكترونات حرة الحركة ولا أيونات تنقل الشحنة.', '["شبكة روابط تساهمية قوية متصلة","الخدش يتطلب كسر روابط كثيرة","الإلكترونات مقيدة في الروابط","لا إلكترونات حرة ولا أيونات"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير الصلابة","marks":2},{"element":"تفسير عدم التوصيل","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"ذكر نصف العناصر تقريبًا مع ربط ضعيف"},{"level":"1 درجة","description":"عنصر واحد صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تفسير الصلابة بقوى بين جزيئية قوية","القول إنها لا توصل لأنها أيونية","الخلط بين الصلابة والهشاشة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T11:15:01.697Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1340, null, null, null, 'المواد الشبكية: شديدة الصلابة (وهشة)، درجة انصهارها عالية جدًا، مثالها الألماس أو الكوارتز. المواد الجزيئية: الصلبة منها لينة، درجة انصهارها منخفضة، مثالها البارافين (الشمع). والسبب أن الشبكية ترتبط ذراتها بروابط تساهمية قوية، والجزيئية ترتبط جزيئاتها بقوى بين جزيئية ضعيفة.', '["الصلابة لكلا النوعين","درجة الانصهار لكلا النوعين","مثال لكل نوع"]'::jsonb, '[]'::jsonb, '[{"element":"الصلابة","marks":1},{"element":"درجة الانصهار","marks":1},{"element":"المثالان","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة صحيحة"},{"level":"2 درجتان","description":"إجابة صحيحة ينقصها عنصر"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس الخواص بين النوعين","ذكر السكر مثالًا على الشبكية","ذكر الألماس مثالًا على الجزيئية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T11:15:01.697Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1341, 2, 'الألماس شبكة تساهمية ترتبط فيها كل ذرة كربون بأربع ذرات كربون بروابط تساهمية قوية، فانصهاره يتطلب كسر عدد هائل من هذه الروابط، فيحتاج إلى طاقة كبيرة جدًا.', '["الألماس لا يتكون من جزيئات منفصلة، فلا تحدد قوى التشتت انصهاره.","الروابط بين ذرات الكربون تساهمية لا أيونية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-11T11:15:01.701Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1342, 0, 'حسب المذكرة: ترتبط كل ذرة C في الألماس بأربع ذرات C بترتيب رباعي الأوجه.', '["","لو ارتبطت كل ذرة بذرتين فقط لتكونت سلاسل لا شبكة ثلاثية الأبعاد.","ثلاث روابط لكل ذرة لا تمثل ترتيب الألماس رباعي الأوجه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-11T11:15:01.701Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1343, 1, 'تحيط كل ذرة كربون في الألماس أربع ذرات كربون في ترتيب رباعي الأوجه، فتمتد الشبكة في الأبعاد الثلاثة.', '["الترتيب المستوي المثلثي يكون لثلاث ذرات حول الذرة المركزية.","","الترتيب الخطي يكون لذرتين فقط حول الذرة المركزية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-11T11:15:01.701Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1344, 0, 'لا توجد في الألماس جزيئات منفصلة، فالبلورة كلها شبكة روابط تساهمية، وانصهارها يتطلب كسر عدد كبير من هذه الروابط القوية.', '["","الألماس ليس مادة جزيئية، فلا توجد فيه قوى بين جزيئية تحدد انصهاره.","الألماس لا يحتوي أيونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T11:15:01.702Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1345, 1, 'انصهار البارافين يتغلب على قوى بين جزيئية ضعيفة، وانصهار NaCl يتغلب على تجاذب أيوني، أما انصهار الألماس فيتطلب كسر روابط تساهمية قوية كثيرة في شبكة متصلة، لذلك درجته الأعلى.', '["روابط الألماس تساهمية وليست أيونية.","","كتلة ذرة الكربون (12) صغيرة، فالكتلة ليست السبب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T11:15:01.702Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1346, 2, 'الميثان يتكون من جزيئات منفصلة تترابط بقوى بين جزيئية ضعيفة جدًا فيكون غازًا، أما الألماس فشبكة متصلة من الروابط التساهمية، فانصهاره يتطلب كسر هذه الروابط لا مجرد فصل جزيئات.', '["روابط C–C في الألماس تساهمية غير قطبية.","الحالة الفيزيائية للميثان تحددها القوى بين جزيئاته لا روابط C–H.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T11:15:01.702Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1347, 0, 'العبارة الخاطئة: الألماس لا يتكون من جزيئات منفصلة ولا ينصهر بالتسخين المعتدل، بل يحتاج إلى درجة حرارة عالية جدًا لكسر روابطه التساهمية القوية.', '["","عبارة صحيحة: فهو شبكة من ذرات الكربون.","عبارة صحيحة: فانصهاره يتطلب كسر روابط تساهمية كثيرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:01.703Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1348, null, null, null, 'الألماس مادة صلبة تساهمية شبكية، ترتبط فيها كل ذرة كربون بأربع ذرات كربون أخرى بروابط تساهمية قوية في ترتيب رباعي الأوجه، فتتكون شبكة متصلة ثلاثية الأبعاد لا توجد فيها جزيئات منفصلة. وانصهار الألماس يتطلب كسر عدد هائل من هذه الروابط التساهمية القوية، فيحتاج إلى طاقة كبيرة جدًا، لذلك درجة انصهاره عالية جدًا.', '["الألماس مادة تساهمية شبكية","كل ذرة C ترتبط بأربع ذرات C","الروابط تساهمية قوية في شبكة متصلة","الانصهار يتطلب كسر روابط كثيرة وطاقة كبيرة"]'::jsonb, '[]'::jsonb, '[{"element":"نوع المادة","marks":1},{"element":"البنية (أربع روابط لكل ذرة)","marks":1},{"element":"قوة الروابط واتصال الشبكة","marks":1},{"element":"الربط بالطاقة اللازمة للانصهار","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"ذكر نصف العناصر تقريبًا مع ربط ضعيف"},{"level":"1 درجة","description":"عنصر واحد صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["التفسير بقوى بين جزيئية قوية","وصف روابط الألماس بأنها أيونية","إغفال أن الانصهار يكسر الروابط التساهمية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-11T11:15:01.703Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1349, null, null, null, 'الألماس: يتطلب الانصهار كسر روابط تساهمية قوية كثيرة في الشبكة، فيحتاج إلى طاقة كبيرة جدًا، ودرجة انصهاره عالية جدًا (أعلى من 3500 °C). البارافين: يتطلب الانصهار التغلب على قوى بين جزيئية ضعيفة فقط دون كسر الروابط داخل الجزيئات، فيحتاج إلى طاقة قليلة، ودرجة انصهاره منخفضة (نحو 60 °C).', '["ما يتغلب عليه التسخين في كل منهما","مقدار الطاقة","درجة الانصهار النسبية"]'::jsonb, '[]'::jsonb, '[{"element":"ما يتغلب عليه التسخين","marks":2},{"element":"مقدار الطاقة","marks":1},{"element":"درجة الانصهار","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"ذكر نصف العناصر تقريبًا مع ربط ضعيف"},{"level":"1 درجة","description":"عنصر واحد صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن انصهار البارافين يكسر روابطه التساهمية","القول إن انصهار الألماس يتغلب على قوى بين جزيئية","عكس درجتي الانصهار"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T11:15:01.703Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1350, null, null, null, 'الترتيب تصاعديًا: الجليد < ملح الطعام < الألماس. التفسير: انصهار الجليد يتغلب على قوى بين جزيئية (روابط هيدروجينية) وهي الأضعف، فينصهر عند 0 °C. انصهار ملح الطعام يتطلب التغلب على تجاذب كهروستاتيكي قوي بين الأيونات (801 °C). أما انصهار الألماس فيتطلب كسر روابط تساهمية قوية كثيرة في شبكة متصلة، فدرجة انصهاره هي الأعلى (أعلى من 3500 °C).', '["الترتيب الصحيح","تفسير الجليد","تفسير الملح","تفسير الألماس"]'::jsonb, '[]'::jsonb, '[{"element":"الترتيب","marks":1},{"element":"تفسير الجليد","marks":1},{"element":"تفسير الملح","marks":1},{"element":"تفسير الألماس","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"ذكر نصف العناصر تقريبًا مع ربط ضعيف"},{"level":"1 درجة","description":"عنصر واحد صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["وضع الملح قبل الجليد","القول إن انصهار الجليد يكسر روابط O–H","التفسير بالكتلة المولية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:01.704Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1351, 1, 'التركيب النسبي المئوي هو النسبة المئوية بالكتلة لكل عنصر من العناصر المكونة للمركب.', '["عدد الذرات تعبر عنه الصيغة الكيميائية لا التركيب النسبي المئوي، والنسبة تعتمد على الكتل لا على عدد الذرات.","","هذه قيمة لا معنى كيميائيًا لها، والتركيب النسبي المئوي يحسب لكل عنصر على حدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T11:15:01.707Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1352, 1, 'النسبة المئوية بالكتلة للعنصر = (كتلة العنصر في مول واحد من المركب ÷ الكتلة المولية للمركب) × 100.', '["هذه العلاقة مقلوبة فتعطي قيمة أكبر من 100%.","","هذه نسبة عددية للذرات وليست نسبة بالكتلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T11:15:01.707Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1353, 0, 'مجموع النسب المئوية لجميع عناصر المركب يساوي 100%، فنسبة العنصر الثاني = 100 − 40.0 = 60.0%.', '["","لا يلزم أن تتساوى نسبتا العنصرين؛ النسبة تعتمد على كتلة كل عنصر في المركب.","لا يمكن أن تتجاوز نسبة عنصر 100%؛ جُمع العدد بدل طرحه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T11:15:01.708Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1354, 2, 'التركيب النسبي المئوي خاصية ثابتة للمركب النقي ولا يتغير بتغير كمية العينة، لأن النسبة بين كتلتي العنصرين ثابتة.', '["كتلة الأكسجين تزداد مع كتلة العينة لكن نسبته المئوية تبقى ثابتة.","لا علاقة لصغر العينة بالنسبة المئوية لعناصرها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T11:15:01.708Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1355, 1, 'الكتلة المولية لـ CO₂ = 12.0 + 2(16.0) = 44.0 g/mol، ونسبة C = (12.0 ÷ 44.0) × 100 = 27.3%.', '["نتيجة نسيان ضرب كتلة الأكسجين في 2: (12.0 ÷ 28.0) × 100.","","نسبة عدد الذرات (1 من 3)، والتركيب النسبي المئوي يعتمد على الكتل لا عدد الذرات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T11:15:01.709Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1356, 0, 'قسمة كتلة الكربون على كتلة العينة × 100 تعطي النسبة المئوية بالكتلة للكربون، وهي ثابتة (75.0%) لأنها جزء من التركيب النسبي المئوي للمركب.', '["","الكتلة المولية لا تُحسب بقسمة كتلة العنصر على كتلة العينة، وتقاس بوحدة g/mol لا بالنسبة المئوية.","عدد المولات يتغير بتغير كتلة العينة، أما القيمة في الجدول فثابتة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T11:15:01.709Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1357, 1, 'من استخدامات التركيب النسبي المئوي إيجاد الصيغة الأولية للمركب بتحويل النسب المئوية إلى مولات ثم إلى أبسط نسبة.', '["التركيب النسبي المئوي نسبة بالكتلة، فيعتمد على الكتلة الذرية وعدد الذرات معًا.","","التركيب النسبي المئوي ثابت للمركب النقي مهما كانت كتلة العينة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T11:15:01.709Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1358, null, null, null, 'التركيب النسبي المئوي: النسبة المئوية بالكتلة لكل عنصر من العناصر المكونة للمركب. العلاقة: النسبة المئوية للعنصر = (كتلة العنصر في 1 mol من المركب ÷ الكتلة المولية للمركب) × 100. في CO₂: الكتلة المولية = 12.0 + 32.0 = 44.0 g/mol، C = (12.0 ÷ 44.0) × 100 = 27.3%، O = (32.0 ÷ 44.0) × 100 = 72.7%، والمجموع = 100%.', '["تعريف التركيب النسبي المئوي بأنه نسبة بالكتلة لكل عنصر","كتابة العلاقة الصحيحة","حساب الكتلة المولية لـ CO₂ = 44.0 g/mol","C = 27.3% و O = 72.7%","مجموع النسب = 100%"]'::jsonb, '["M(CO₂) = 12.0 + 2(16.0) = 44.0 g/mol","%C = (12.0 ÷ 44.0) × 100 = 27.3%","%O = (32.0 ÷ 44.0) × 100 = 72.7%","27.3% + 72.7% = 100%"]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"العلاقة","marks":1},{"element":"حساب النسبتين","marks":2},{"element":"التحقق من المجموع","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تعريف وعلاقة صحيحان وحساب صحيح مع التحقق"},{"level":"3–4 درجات","description":"التعريف والعلاقة صحيحان مع خطأ في إحدى النسبتين"},{"level":"1–2 درجة","description":"التعريف فقط أو العلاقة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعريفه بعدد الذرات بدل الكتلة","نسيان ضرب كتلة O في 2","قلب العلاقة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T11:15:01.712Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1359, null, null, null, 'العبارة خاطئة؛ لأن التركيب النسبي المئوي نسبة بالكتلة لا بعدد الذرات، وذرة الأكسجين أثقل كثيرًا من ذرة الهيدروجين. الكتلة المولية للماء = 2(1.0) + 16.0 = 18.0 g/mol، ونسبة H = (2.0 ÷ 18.0) × 100 = 11.1%، ونسبة O = 88.9%.', '["الحكم بخطأ العبارة","التعليل: النسبة بالكتلة لا بعدد الذرات","الكتلة المولية للماء 18.0 g/mol","نسبة H = 11.1%"]'::jsonb, '["M(H₂O) = 2(1.0) + 16.0 = 18.0 g/mol","%H = (2.0 ÷ 18.0) × 100 = 11.1%","%O = 100 − 11.1 = 88.9%"]'::jsonb, '[{"element":"الحكم والتعليل","marks":2},{"element":"الحساب الصحيح","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح مع تعليل وحساب صحيح"},{"level":"2–3 درجات","description":"حكم وتعليل دون حساب صحيح أو العكس"},{"level":"1 درجة","description":"الحكم بالخطأ دون تعليل"},{"level":"صفر","description":"تأييد العبارة"}]'::jsonb, '["تأييد الطالب في الاعتماد على عدد الذرات","استخدام كتلة H = 1.0 دون ضربها في 2"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T11:15:01.713Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.')
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check, reviewer_notes) values
(1360, null, null, null, '(أ) لأن المركب النقي يتكون من عناصره بنسبة كتلية ثابتة، فإذا تضاعفت كتلة العينة تضاعفت كتلة كل عنصر فيها فتبقى النسبة نفسها. (ب) لأن الكيميائي التحليلي يحدد العناصر الموجودة في المركب ونسبها المئوية، وهذه البيانات تُستخدم لاحقًا لإيجاد الصيغة الأولية للمركب والتعرف عليه.', '["(أ) ثبات النسبة الكتلية للعناصر في المركب النقي","(أ) تغير كتلة العنصر بالنسبة نفسها لتغير كتلة العينة","(ب) الكيميائي التحليلي يحدد العناصر ونسبها","(ب) استخدام النسب في إيجاد الصيغة"]'::jsonb, '[]'::jsonb, '[{"element":"تعليل (أ)","marks":2},{"element":"تعليل (ب)","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"التعليلان صحيحان ومكتملان"},{"level":"2–3 درجات","description":"تعليل واحد صحيح أو كلاهما ناقص"},{"level":"1 درجة","description":"إشارة عامة صحيحة دون تعليل"},{"level":"صفر","description":"لا إجابة أو تعليل خاطئ"}]'::jsonb, '["الظن بأن العينة الأكبر تحتوي نسبة أكبر","الخلط بين كتلة العنصر ونسبته المئوية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-11T11:15:01.713Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1361, 2, 'M(H₃PO₄) = 3(1.0) + 31.0 + 4(16.0) = 98.0 g/mol، ونسبة P = (31.0 ÷ 98.0) × 100 = 31.6%.', '["نتيجة نسيان ضرب كتلة الأكسجين في 4 عند حساب الكتلة المولية: (31.0 ÷ 50.0) × 100.","هذه نسبة الهيدروجين (3.0 ÷ 98.0) × 100 وليست نسبة الفوسفور.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-11T11:15:01.717Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1362, 0, 'M(Fe₂O₃) = 2(56.0) + 3(16.0) = 160.0 g/mol، ونسبة Fe = (112.0 ÷ 160.0) × 100 = 70.0%.', '["","استُخدمت كتلة ذرة حديد واحدة (56.0) بدل ذرتين في البسط.","حُذف الرقم السفلي للحديد من البسط والمقام معًا: 56.0 ÷ (56.0 + 48.0)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T11:15:01.717Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1363, 1, 'كتلة الحديد = 50.0 g × (70.0 ÷ 100) = 35.0 g.', '["نتيجة قسمة كتلة العينة على 0.700 بدل ضربها، وكتلة جزء من العينة لا يمكن أن تتجاوز كتلتها.","","استُخدم نصف النسبة (35.0%) كأن في الصيغة ذرة حديد واحدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T11:15:01.718Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1364, 2, '%N في NH₃ = (14.0 ÷ 17.0) × 100 = 82.4%، وفي NH₄NO₃ = (28.0 ÷ 80.0) × 100 = 35.0%، وفي (NH₄)₂SO₄ = (28.0 ÷ 132.0) × 100 = 21.2%؛ فالأمونيا أغنى بالنيتروجين.', '["نسبته 21.2% فقط، وهي الأقل؛ وجود ذرتي N لا يكفي لأن كتلته المولية كبيرة.","نسبته 35.0%؛ فيه ذرتا N لكن كتلته المولية أكبر بكثير من الأمونيا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-10-11T11:15:01.718Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1365, 1, 'نسبة Mg = (كتلة Mg ÷ كتلة المركب) × 100 = (2.40 ÷ 4.00) × 100 = 60.0%.', '["هذه نسبة الأكسجين: (4.00 − 2.40) ÷ 4.00 × 100.","","نتيجة قسمة كتلة المغنيسيوم على كتلة الأكسجين (2.40 ÷ 1.60) بدل كتلة المركب؛ والنسبة المئوية لعنصر لا تتجاوز 100%."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T11:15:01.719Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1366, 2, 'M(C₂H₆O) = 2(12.0) + 6(1.0) + 16.0 = 46.0 g/mol، ونسبة O = (16.0 ÷ 46.0) × 100 = 34.8%.', '["هذه نسبة الكربون (24.0 ÷ 46.0) × 100.","هذه نسبة الهيدروجين (6.0 ÷ 46.0) × 100.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-11T11:15:01.719Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1367, 0, 'مجموع النسب المئوية لعناصر المركب = 100%، فنسبة O = 100 − (40.0 + 6.7) = 53.3%.', '["","طُرحت نسبة الكربون فقط ونُسي الهيدروجين.","هذا مجموع نسبتي الكربون والهيدروجين وليس نسبة الأكسجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:01.720Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1368, null, null, null, 'M(H₂SO₄) = 2(1.0) + 32.0 + 4(16.0) = 98.0 g/mol. %H = (2.0 ÷ 98.0) × 100 = 2.04%. %S = (32.0 ÷ 98.0) × 100 = 32.7%. %O = (64.0 ÷ 98.0) × 100 = 65.3%. المجموع = 2.04 + 32.7 + 65.3 ≈ 100%.', '["الكتلة المولية 98.0 g/mol","%H = 2.04%","%S = 32.7%","%O = 65.3%","التحقق من أن المجموع ≈ 100%"]'::jsonb, '["M = 2(1.0) + 32.0 + 4(16.0) = 98.0 g/mol","%H = 2.0 ÷ 98.0 × 100 = 2.04%","%S = 32.0 ÷ 98.0 × 100 = 32.7%","%O = 64.0 ÷ 98.0 × 100 = 65.3%","2.04 + 32.7 + 65.3 ≈ 100%"]'::jsonb, '[{"element":"الكتلة المولية","marks":1},{"element":"النسب الثلاث","marks":3},{"element":"التحقق","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"جميع الخطوات صحيحة بالأرقام المعنوية"},{"level":"3–4 درجات","description":"خطأ في نسبة واحدة أو إهمال التحقق"},{"level":"1–2 درجة","description":"الكتلة المولية صحيحة فقط أو نسبة واحدة"},{"level":"صفر","description":"لا إجابة أو طريقة خاطئة"}]'::jsonb, '["نسيان ضرب كتلة O في 4","استخدام 1.0 بدل 2.0 للهيدروجين","قلب الكسر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T11:15:01.720Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1369, null, null, null, '(أ) %C = (2.88 ÷ 3.60) × 100 = 80.0%، وكتلة H = 3.60 − 2.88 = 0.72 g، و%H = 100 − 80.0 = 20.0%. (ب) في C₂H₆: M = 2(12.0) + 6(1.0) = 30.0 g/mol، و%C = (24.0 ÷ 30.0) × 100 = 80.0%، و%H = 20.0%؛ فالنتائج تتفق مع الإيثان.', '["%C = 80.0% من البيانات المخبرية","%H = 20.0%","حساب الكتلة المولية لـ C₂H₆ = 30.0 g/mol","%C النظرية في C₂H₆ = 80.0%","الاستنتاج: النتائج متفقة"]'::jsonb, '["%C = 2.88 ÷ 3.60 × 100 = 80.0%","%H = 100 − 80.0 = 20.0%","M(C₂H₆) = 30.0 g/mol ، %C = 24.0 ÷ 30.0 × 100 = 80.0%","المقارنة: متطابقة"]'::jsonb, '[{"element":"(أ) النسبتان","marks":2},{"element":"(ب) حساب النسبة النظرية","marks":2},{"element":"الاستنتاج","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حساب صحيح للجزأين مع استنتاج مبرر"},{"level":"3–4 درجات","description":"جزء واحد صحيح كاملًا مع محاولة للآخر"},{"level":"1–2 درجة","description":"حساب %C من البيانات فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["قسمة كتلة العينة على كتلة الكربون","نسيان ضرب كتلة C في 2 عند حساب النسبة النظرية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:01.721Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1370, null, null, null, 'M(CuSO₄) = 63.5 + 32.0 + 4(16.0) = 159.5 g/mol. %Cu = (63.5 ÷ 159.5) × 100 = 39.8%. كتلة Cu = 25.0 × (63.5 ÷ 159.5) = 9.95 g.', '["الكتلة المولية 159.5 g/mol","%Cu = 39.8%","كتلة النحاس = 9.95 g"]'::jsonb, '["M(CuSO₄) = 159.5 g/mol","%Cu = 63.5 ÷ 159.5 × 100 = 39.8%","m(Cu) = 25.0 g × 0.398 = 9.95 g"]'::jsonb, '[{"element":"الكتلة المولية","marks":1},{"element":"النسبة المئوية للنحاس","marks":1},{"element":"كتلة النحاس بوحدة صحيحة","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"الخطوات الثلاث صحيحة مع الوحدة"},{"level":"2–3 درجات","description":"خطأ حسابي في خطوة واحدة"},{"level":"1 درجة","description":"الكتلة المولية فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["قسمة 25.0 على النسبة بدل ضربها","اعتبار الكتلة المولية 100 g/mol"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-11T11:15:01.722Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1371, 0, 'الصيغة الأولية تبين أبسط نسبة عددية صحيحة بين ذرات العناصر المكوّنة للمركب.', '["","هذا وصف الصيغة الجزيئية لا الأولية.","ترتيب الذرات وارتباطها تبينه الصيغة البنائية، لا الأولية ولا الجزيئية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T11:15:01.725Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1372, 1, 'بقسمة الأرقام السفلية 6 : 12 : 6 على العامل المشترك الأكبر 6 نحصل على 1 : 2 : 1، فالصيغة الأولية CH₂O.', '["القسمة على 2 فقط لا تعطي أبسط نسبة؛ فما زال هناك عامل مشترك هو 3.","","هذه الصيغة الجزيئية؛ وأرقامها تقبل القسمة على 6 فليست أبسط نسبة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-11T11:15:01.725Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1373, 2, 'في CO₂ النسبة 1 : 2 لا تقبل التبسيط، فالصيغة الأولية هي نفسها الجزيئية.', '["الأرقام 2 : 4 تقبل القسمة على 2، فصيغته الأولية CH₂.","الأرقام 2 : 2 تقبل القسمة على 2، فصيغته الأولية HO.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-11T11:15:01.726Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1374, 1, 'المركبات التي لها الصيغة الأولية نفسها لها النسبة نفسها بين الذرات، فيكون لها التركيب النسبي المئوي نفسه (C = 92.3% و H = 7.7%).', '["الكتلة المولية للأستيلين 26.0 g/mol وللبنزين 78.0 g/mol، فهي مختلفة.","","جزيء الأستيلين فيه 4 ذرات والبنزين 12 ذرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T11:15:01.726Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1375, 1, 'الصيغة الأولية لـ C₄H₁₀ هي C₂H₅ (بالقسمة على 2)، وقد كتبها الطالب CH₃ خطأً، أما بقية الصفوف فصحيحة.', '["الصيغة الأولية لـ C₂H₆ هي CH₃ وهي صحيحة في الجدول.","","الصيغة الأولية لـ N₂O₄ هي NO₂ وهي صحيحة في الجدول."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T11:15:01.727Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1376, 0, 'الصيغة الجزيئية مضاعف صحيح للصيغة الأولية: الجزيئية = n × الأولية، وقد تكون n = 1 فتتطابق الصيغتان.', '["","هذه العلاقة مقلوبة؛ فالصيغة الأولية هي الأبسط والجزيئية مضاعفها.","العلاقة ضرب في عدد صحيح لا جمع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T11:15:01.727Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1377, 0, 'مركبات مختلفة قد تشترك في الصيغة الأولية، فلا تكفي الصيغة الأولية لتحديد المركب، ونحتاج إلى الكتلة المولية لتحديد الصيغة الجزيئية.', '["","كتلها المولية مختلفة: 30.0 و60.0 و180.0 g/mol.","تتطابق الصيغتان في الفورمالدهيد فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T11:15:01.727Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1378, null, null, null, '(أ) الصيغة الأولية تعبر عن أبسط نسبة عددية صحيحة بين ذرات العناصر في المركب، والصيغة الجزيئية تعبر عن العدد الفعلي لذرات كل عنصر في جزيء المركب. (ب) الجزيئية = n × الأولية، حيث n عدد صحيح يساوي الكتلة المولية للمركب ÷ الكتلة المولية للصيغة الأولية. (ج) نعم، عندما n = 1 مثل H₂O وCO₂، وقد تختلفان مثل C₃H₆ (الأولية CH₂) وH₂O₂ (الأولية HO).', '["تعريف الصيغة الأولية","تعريف الصيغة الجزيئية","العلاقة الجزيئية = n × الأولية","مثال على تطابق الصيغتين","مثال على اختلافهما"]'::jsonb, '[]'::jsonb, '[{"element":"المقارنة في (أ)","marks":2},{"element":"العلاقة (ب)","marks":1},{"element":"الحالتان مع مثالين (ج)","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"مقارنة كاملة دقيقة مع مثالين صحيحين"},{"level":"3–4 درجات","description":"المقارنة صحيحة مع نقص في العلاقة أو مثال"},{"level":"1–2 درجة","description":"تعريف إحدى الصيغتين فقط"},{"level":"صفر","description":"لا إجابة أو خلط بين الصيغتين"}]'::jsonb, '["الخلط بين التعريفين","اعتقاد أن الصيغتين لا تتطابقان أبدًا","كتابة العلاقة مقلوبة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-11T11:15:01.728Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1379, null, null, null, '(أ) الصيغة الأولية لكليهما CH₂. (ب) لأن النسبة بين عدد ذرات C وH واحدة (1 : 2) في المركبين، فتكون النسبة بين كتلتي العنصرين واحدة، فيتساوى التركيب النسبي المئوي (C = 85.7% و H = 14.3%). (ج) الكتلة المولية للمركب (28.0 g/mol للإيثين و42.0 g/mol للبروبين) لحساب n ثم الصيغة الجزيئية.', '["الصيغة الأولية CH₂ للمركبين","التفسير بتساوي نسبة الذرات ومن ثم نسبة الكتل","الحاجة إلى الكتلة المولية للتمييز"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب) التفسير","marks":2},{"element":"(ج) الكتلة المولية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الإجابات الثلاث صحيحة مع تفسير واضح"},{"level":"2–3 درجات","description":"خطأ أو نقص في التفسير"},{"level":"1 درجة","description":"الصيغة الأولية فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["كتابة C₂H₄ صيغة أولية للإيثين","الظن بأن اختلاف الصيغة الجزيئية يعني اختلاف النسب المئوية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T11:15:01.728Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1380, null, null, null, 'مطابقة: H₂O (الأولية H₂O)، NH₃ (NH₃)، CH₄ (CH₄). مختلفة: H₂O₂ (الأولية HO)، C₆H₆ (الأولية CH)، N₂O₄ (الأولية NO₂).', '["H₂O وNH₃ وCH₄ صيغتها الأولية مطابقة","H₂O₂ ← HO","C₆H₆ ← CH","N₂O₄ ← NO₂"]'::jsonb, '[]'::jsonb, '[{"element":"تصنيف المركبات المطابقة","marks":2},{"element":"الصيغ الأولية للمركبات المختلفة","marks":3}]'::jsonb, '[{"level":"5 درجات","description":"تصنيف كامل وصيغ صحيحة"},{"level":"3–4 درجات","description":"خطأ في مركب أو مركبين"},{"level":"1–2 درجة","description":"تصنيف صحيح دون صيغ أو صيغ قليلة صحيحة"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["كتابة صيغة أولية لـ H₂O₂ = H₂O","عدم التبسيط الكامل لـ C₆H₆ (C₃H₃ أو C₂H₂)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:01.729Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1381, 0, 'بعد افتراض 100 g تصبح النسبة المئوية كتلة بالجرام، ثم تُحوَّل كل كتلة إلى مولات (n = m ÷ M)، ثم يُقسم على أصغر عدد مولات.', '["","الضرب في الكتلة المولية خطأ؛ التحويل من الكتلة إلى المولات يكون بالقسمة.","هذه خطوة إيجاد الصيغة الجزيئية لا الأولية، وتحتاج إلى الكتلة المولية للمركب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-11T11:15:01.732Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1382, 2, 'في 100 g: n(C) = 80.0 ÷ 12.0 = 6.67 mol ، n(H) = 20.0 ÷ 1.0 = 20.0 mol. بالقسمة على 6.67: C = 1 ، H = 3.00 ، فالصيغة الأولية CH₃.', '["استُخدمت النسب المئوية مباشرة (80 : 20 = 4 : 1) دون تحويلها إلى مولات.","تقريب غير صحيح للنسبة؛ النسبة الناتجة 1 : 3.00 لا 1 : 4.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-10-11T11:15:01.733Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1383, 0, 'n(Fe) = 2.80 ÷ 56.0 = 0.0500 mol ، n(O) = 1.20 ÷ 16.0 = 0.0750 mol. النسبة 1 : 1.5، وبالضرب في 2 تصبح 2 : 3، فالصيغة Fe₂O₃.', '["","تقريب 1.5 إلى 1 خطأ؛ الكسر 0.5 يعالج بالضرب في 2 لا بالتقريب.","تقابل النسبة 3 : 4 (1 : 1.33)، والنسبة المحسوبة 1 : 1.5."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T11:15:01.733Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1384, 1, 'الكسر 1.33 يساوي تقريبًا 4/3، فنضرب النسبة كلها في 3: 3 : 4 : 3، فالصيغة الأولية C₃H₄O₃.', '["تقريب 1.33 إلى 1 خطأ لأن الفرق كبير، والأعداد يجب أن تكون صحيحة بعد الضرب لا بالتقريب.","","الضرب في 2 يعطي 2 : 2.66 : 2 ولا تزال النسبة غير صحيحة، والنسبة 2 : 3 : 2 تقريب خاطئ."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T11:15:01.734Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1385, 2, 'النسبة N : O = 0.500 : 1.25 = 1 : 2.5، وبالضرب في 2 تصبح 2 : 5، فالصيغة N₂O₅.', '["تقريب 2.5 إلى 2 خطأ؛ الكسر 0.5 يعالج بالضرب في 2.","عُكست النسبة بين العنصرين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T11:15:01.734Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1386, 0, 'n(N) = 63.6 ÷ 14.0 = 4.54 mol ، n(O) = 36.4 ÷ 16.0 = 2.28 mol. بالقسمة على 2.28: N = 2.00 ، O = 1، فالصيغة N₂O.', '["","اعتماد تقارب النسب المئوية دون حساب المولات.","عُكست النسبة بين العنصرين، فالمحسوب 2 ذرة N لكل ذرة O وليس العكس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-11T11:15:01.735Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1387, 1, 'n(Na) = 43.4 ÷ 23.0 = 1.89 ، n(C) = 11.3 ÷ 12.0 = 0.942 ، n(O) = 45.3 ÷ 16.0 = 2.83 mol. بالقسمة على 0.942: 2.00 : 1 : 3.01، فالصيغة Na₂CO₃.', '["يتجاهل أن نسبة مولات Na إلى C تساوي 1.89 ÷ 0.942 = 2.00 لا 1.","","نتيجة قسمة النسب المئوية مباشرة على بعضها دون التحويل إلى مولات (43.4 ÷ 11.3 ≈ 4)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T11:15:01.735Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1388, null, null, null, 'نفترض 100 g: C = 40.0 g ، H = 6.7 g ، O = 53.3 g. n(C) = 40.0 ÷ 12.0 = 3.33 mol ، n(H) = 6.7 ÷ 1.0 = 6.7 mol ، n(O) = 53.3 ÷ 16.0 = 3.33 mol. بالقسمة على 3.33: C = 1 ، H = 2.0 ، O = 1، فالصيغة الأولية CH₂O.', '["افتراض 100 g وتحويل النسب إلى كتل","حساب مولات كل عنصر","القسمة على أصغر عدد مولات","الصيغة الأولية CH₂O"]'::jsonb, '["كتل العناصر في 100 g: 40.0 g C ، 6.7 g H ، 53.3 g O","n(C) = 3.33 mol ، n(H) = 6.7 mol ، n(O) = 3.33 mol","القسمة على 3.33 → 1 : 2 : 1","الصيغة الأولية CH₂O"]'::jsonb, '[{"element":"تحويل النسب إلى كتل","marks":1},{"element":"حساب المولات","marks":2},{"element":"القسمة على الأصغر","marks":1},{"element":"الصيغة الأولية","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"خطوات كاملة صحيحة"},{"level":"3–4 درجات","description":"خطأ حسابي بسيط مع منهجية صحيحة"},{"level":"1–2 درجة","description":"حساب المولات فقط"},{"level":"صفر","description":"طريقة خاطئة أو لا إجابة"}]'::jsonb, '["قسمة النسب المئوية على بعضها مباشرة","ضرب الكتلة في الكتلة المولية","القسمة على أكبر عدد مولات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-10-11T11:15:01.736Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1389, null, null, null, '(أ) كتلة O = 2.04 − 1.08 = 0.96 g. (ب) n(Al) = 1.08 ÷ 27.0 = 0.0400 mol ، n(O) = 0.96 ÷ 16.0 = 0.060 mol. النسبة 1 : 1.5، وبالضرب في 2: 2 : 3، فالصيغة الأولية Al₂O₃.', '["كتلة الأكسجين 0.96 g بقانون حفظ الكتلة","n(Al) = 0.0400 mol","n(O) = 0.060 mol","النسبة 1 : 1.5 والضرب في 2","الصيغة Al₂O₃"]'::jsonb, '["m(O) = 2.04 − 1.08 = 0.96 g","n(Al) = 1.08 ÷ 27.0 = 0.0400 mol","n(O) = 0.96 ÷ 16.0 = 0.060 mol","0.060 ÷ 0.0400 = 1.5 → ×2 → Al₂O₃"]'::jsonb, '[{"element":"كتلة الأكسجين","marks":1},{"element":"حساب المولات","marks":2},{"element":"تحويل 1 : 1.5 إلى أعداد صحيحة","marks":1},{"element":"الصيغة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حل كامل صحيح"},{"level":"3–4 درجات","description":"خطأ في الضرب لتحويل الكسر أو خطأ حسابي"},{"level":"1–2 درجة","description":"كتلة الأكسجين أو المولات فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["استخدام 2.04 g كتلة للأكسجين","تقريب 1.5 إلى 2 فتصبح الصيغة AlO₂"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T11:15:01.736Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
