(1400, null, null, null, 'كتلة O = 6.00 − (2.40 + 0.40) = 3.20 g. n(C) = 2.40 ÷ 12.0 = 0.200 mol ، n(H) = 0.40 ÷ 1.0 = 0.40 mol ، n(O) = 3.20 ÷ 16.0 = 0.200 mol. النسبة 1 : 2 : 1، فالأولية CH₂O (30.0 g/mol). n = 60.0 ÷ 30.0 = 2، فالجزيئية C₂H₄O₂.', '["كتلة الأكسجين 3.20 g","مولات العناصر الثلاثة","الصيغة الأولية CH₂O","n = 2","الصيغة الجزيئية C₂H₄O₂"]'::jsonb, '["m(O) = 6.00 − 2.80 = 3.20 g","n(C) = 0.200 ، n(H) = 0.40 ، n(O) = 0.200 mol","النسبة 1 : 2 : 1 → CH₂O (30.0 g/mol)","n = 60.0 ÷ 30.0 = 2 → C₂H₄O₂"]'::jsonb, '[{"element":"كتلة الأكسجين","marks":1},{"element":"الصيغة الأولية","marks":2},{"element":"n","marks":1},{"element":"الصيغة الجزيئية","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"حل كامل صحيح"},{"level":"4–5 درجات","description":"خطأ بسيط في خطوة"},{"level":"2–3 درجات","description":"الصيغة الأولية صحيحة دون الجزيئية"},{"level":"1 درجة","description":"حساب كتلة الأكسجين فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["إهمال الأكسجين لأنه غير مذكور بكتلته","قسمة 30.0 على 60.0"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T11:15:01.747Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1401, 1, 'الملح المائي مركب ملحي (أيوني صلب) مرتبط بعدد معين من جزيئات الماء المحتجزة في بلوراته.', '["المحلول خليط من الملح والماء، أما الملح المائي فمركب صلب بعدد محدد من جزيئات الماء.","","هذا وصف تفاعل بعض الفلزات النشطة مع الماء ولا علاقة له بالأملاح المائية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T11:15:01.750Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1402, 0, 'النقطة في الصيغة تعني أن كل وحدة صيغة من CuSO₄ مرتبطة بخمس جزيئات ماء (ماء التبلور).', '["","جزيئات الماء منفصلة عن أيون الكبريتات وليست جزءًا منه.","الملح المائي صلب وليس محلولًا؛ الرقم يعبر عن جزيئات ماء محتجزة في البلورة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T11:15:01.751Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1403, 1, 'MgSO₄·7H₂O كبريتات المغنيسيوم سباعية الماء، وهي ملح مرتبط بسبع جزيئات ماء.', '["هذه صيغة كلوريد الكالسيوم اللامائي، ولا يرتبط بجزيئات ماء.","","H₂SO₄ حمض وليس ملحًا مائيًا، ولا تظهر في صيغته جزيئات ماء تبلور."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T11:15:01.751Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1404, 2, 'الأملاح المائية مركبات أيونية صلبة توجد فيها جزيئات ماء محتجزة داخل بلوراتها.', '["الأملاح مركبات أيونية لا تساهمية، والأملاح المائية صلبة لا سائلة.","السبائك مخاليط من الفلزات، وليست أملاحًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (3%)"}],"at":"2026-10-11T11:15:01.751Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1405, 0, 'العدد بعد النقطة يمثل جزيئات الماء لكل وحدة صيغة: Na₂CO₃·10H₂O فيها 10 جزيئات، وهي الأكثر.', '["","فيها 7 جزيئات ماء فقط.","فيها 5 جزيئات ماء فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-11T11:15:01.752Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1406, 2, 'بطرد جزيئات ماء التبلور من الملح المائي يتحول إلى ملح لامائي (خالٍ من الماء).', '["هذا اسم المادة قبل طرد الماء لا بعده.","المحلول المشبع خليط من مذاب ومذيب، والناتج هنا صلب خالٍ من الماء.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T11:15:01.752Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1407, 0, 'الكتلة المولية للملح المائي (249.5 g/mol) أكبر من اللامائي (159.5 g/mol) بسبب كتلة جزيئات الماء الخمس، فعند تساوي المولات تكون كتلة الملح المائي أكبر.', '["","جزيئات الماء المرتبطة لها كتلة تضاف إلى كتلة الملح.","هذا عكس الصحيح؛ الملح اللامائي فقد كتلة الماء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T11:15:01.753Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1408, null, null, null, 'الملح المائي: مركب ملحي (أيوني صلب) مرتبط بعدد معين من جزيئات الماء. ماء التبلور: جزيئات الماء المحتجزة في بلورات الملح المائي. الصيغة Na₂CO₃·10H₂O تعني أن كل وحدة صيغة من كربونات الصوديوم مرتبطة بعشر جزيئات ماء، ويسمى كربونات الصوديوم عشرية الماء.', '["تعريف الملح المائي","تعريف ماء التبلور","تفسير الصيغة: 10 جزيئات ماء لكل وحدة صيغة","الاسم: كربونات الصوديوم عشرية الماء"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف الملح المائي","marks":1},{"element":"تعريف ماء التبلور","marks":1},{"element":"تفسير الصيغة","marks":1},{"element":"الاسم","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"التعريفان والتفسير والاسم صحيحة"},{"level":"2–3 درجات","description":"تعريف واحد مع التفسير"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["وصف الملح المائي بأنه محلول","تفسير الرقم 10 بأنه عدد ذرات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T11:15:01.753Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1409, null, null, null, '(أ) الملح المائي يحتوي على جزيئات ماء مرتبطة تكتب بعد نقطة (CuSO₄·5H₂O)، واللامائي خالٍ منها (CuSO₄). (ب) M(CuSO₄·5H₂O) = 159.5 + 5(18.0) = 249.5 g/mol، وM(CuSO₄) = 159.5 g/mol، فالمائي أكبر كتلة مولية. (ج) كبريتات النحاس II المائية زرقاء، واللامائية بيضاء.', '["الفرق في وجود الماء بالصيغة","M(CuSO₄·5H₂O) = 249.5 g/mol","M(CuSO₄) = 159.5 g/mol","المائية زرقاء واللامائية بيضاء"]'::jsonb, '["M(CuSO₄) = 63.5 + 32.0 + 64.0 = 159.5 g/mol","M(CuSO₄·5H₂O) = 159.5 + 5 × 18.0 = 249.5 g/mol"]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب) الكتلتان","marks":2},{"element":"(ج) اللون","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"المقارنة كاملة صحيحة"},{"level":"2–3 درجات","description":"نقص في أحد الجوانب"},{"level":"1 درجة","description":"جانب واحد صحيح"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["إضافة 18.0 مرة واحدة بدل 5 مرات","عكس اللونين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T11:15:01.754Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1410, null, null, null, 'M(CuSO₄·5H₂O) = 249.5 g/mol، وكتلة الماء في مول واحد = 5 × 18.0 = 90.0 g. %H₂O = (90.0 ÷ 249.5) × 100 = 36.1%. تقل الكتلة عند التسخين لأن جزيئات ماء التبلور تنفصل وتتبخر ويبقى الملح اللامائي.', '["الكتلة المولية 249.5 g/mol","كتلة الماء 90.0 g","%H₂O = 36.1%","تفسير نقص الكتلة بطرد ماء التبلور"]'::jsonb, '["M = 249.5 g/mol","m(H₂O) = 5 × 18.0 = 90.0 g","%H₂O = 90.0 ÷ 249.5 × 100 = 36.1%"]'::jsonb, '[{"element":"الكتلة المولية","marks":1},{"element":"النسبة المئوية للماء","marks":2},{"element":"التفسير","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حساب وتفسير صحيحان"},{"level":"2–3 درجات","description":"حساب صحيح دون تفسير أو العكس"},{"level":"1 درجة","description":"الكتلة المولية فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["القسمة على كتلة CuSO₄ اللامائي (159.5)","الظن بأن الملح نفسه يتبخر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T11:15:01.754Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1411, 0, 'كتلة الماء المطرود = كتلة الملح المائي − كتلة الملح اللامائي، ثم تُحوَّل كتلتا الماء والملح اللامائي إلى مولات، فتُحسب النسبة بينهما.', '["","كتلة الملح المائي تشمل الملح والماء معًا، فلا تمثل كتلة الماء وحده.","الجمع لا معنى له؛ الماء هو الفرق بين الكتلتين لا مجموعهما."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T11:15:01.759Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1412, 2, 'كتلة الماء = 5.00 − 4.26 = 0.74 g، ومولاته = 0.74 g ÷ 18.0 g/mol = 0.0411 mol.', '["هذا الرقم هو كتلة الماء بالجرام (0.740 g) وليس عدد مولاته؛ لم يُقسم على الكتلة المولية.","ناتج قسمة كتلة العينة المائية كلها (5.00 g) على 18.0، أي اعتُبرت العينة كلها ماءً.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T11:15:01.759Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1413, 1, 'x = مولات الماء ÷ مولات الملح اللامائي = 0.140 ÷ 0.0200 = 7، أي أن كل وحدة صيغة من الملح ترتبط بسبع جزيئات ماء.', '["هذا عدد مولات الماء نفسه، ولم يُقسم على مولات الملح اللامائي.","","ناتج القسمة على ضعف مولات الملح (0.0400)، وعدد جزيئات الماء في الصيغة يكون عددًا صحيحًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:01.760Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1414, 2, 'كتلة الماء = 1.47 − 1.11 = 0.36 g ← 0.36 ÷ 18.0 = 0.020 mol. مولات CaCl₂ = 1.11 ÷ 111.0 = 0.0100 mol. x = 0.020 ÷ 0.0100 = 2، فالصيغة CaCl₂·2H₂O.', '["عُدّت مولات ذرات الهيدروجين (0.040 mol) بدل مولات جزيئات الماء.","عُكست النسبة: قُسمت مولات الملح على مولات الماء (0.5).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T11:15:01.761Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1415, 1, 'كتلة الملح المائي = 24.93 − 20.00 = 4.93 g، وكتلة اللامائي = 22.41 − 20.00 = 2.41 g، فكتلة الماء = 2.52 g ← 0.140 mol. مولات MgSO₄ = 2.41 ÷ 120.3 = 0.0200 mol. x = 0.140 ÷ 0.0200 ≈ 7، فالصيغة MgSO₄·7H₂O.', '["نتيجة قسمة كتلة الماء على كتلة الملح اللامائي (2.52 ÷ 2.41 ≈ 1)، أي استُخدمت نسبة الكتل بدل نسبة المولات.","","استُخدمت كتلة الملح المائي (4.93 g) بدل كتلة اللامائي عند حساب مولات MgSO₄ فنتجت نسبة ≈ 3.4."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T11:15:01.762Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1416, 0, 'نفترض عينة كتلتها 100 g: فيها 45.3 g ماء ← 45.3 ÷ 18.0 = 2.52 mol، و54.7 g FeSO₄ ← 54.7 ÷ 152.0 = 0.360 mol. x = 2.52 ÷ 0.360 ≈ 7، فالصيغة FeSO₄·7H₂O.', '["","هذا عدد مولات الماء في 100 g (2.52 mol) دون قسمته على مولات FeSO₄.","تقريب خاطئ؛ النسبة المحسوبة 6.99 أقرب إلى 7، وتقابل 6 جزيئات نسبة ماء 41.5% تقريبًا لا 45.3%."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-11T11:15:01.762Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1417, 2, 'بقاء جزء من الماء يجعل كتلة «اللامائي» المقيسة أكبر من الحقيقية، فتقل كتلة الماء المحسوبة وتزيد مولات الملح المحسوبة، فتصغر النسبة x = مولات الماء ÷ مولات الملح.', '["الماء المحسوب أقل من الحقيقي لا أكثر، فلا يمكن أن تزيد x.","الكتلة المقيسة بعد التسخين لم تصل إلى كتلة اللامائي الحقيقية، فالنتيجة تتأثر حتمًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T11:15:01.763Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1418, null, null, null, 'كتلة الماء = 4.76 − 2.60 = 2.16 g. مولات الماء = 2.16 ÷ 18.0 = 0.120 mol. مولات CoCl₂ = 2.60 ÷ 129.9 = 0.0200 mol. x = 0.120 ÷ 0.0200 = 6.00 ≈ 6. الصيغة: CoCl₂·6H₂O، واسمه كلوريد الكوبلت II سداسية الماء.', '["حساب كتلة الماء بالطرح","تحويل كتلة الماء إلى مولات","تحويل كتلة الملح اللامائي إلى مولات","قسمة مولات الماء على مولات الملح اللامائي","كتابة الصيغة CoCl₂·6H₂O واسمها"]'::jsonb, '["كتلة الماء = 4.76 − 2.60 = 2.16 g","n(H₂O) = 2.16 ÷ 18.0 = 0.120 mol","n(CoCl₂) = 2.60 ÷ 129.9 = 0.0200 mol","x = 0.120 ÷ 0.0200 = 6","الصيغة CoCl₂·6H₂O (كلوريد الكوبلت II سداسية الماء)"]'::jsonb, '[{"element":"كتلة الماء","marks":1},{"element":"مولات الماء ومولات CoCl₂","marks":2},{"element":"النسبة x = 6","marks":1},{"element":"الصيغة والاسم","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"خطوات كاملة وصيغة واسم صحيحان"},{"level":"4 درجات","description":"الصيغة صحيحة مع خطأ في الاسم أو نقص خطوة"},{"level":"3 درجات","description":"حساب صحيح للمولات مع خطأ في النسبة"},{"level":"2 درجتان","description":"حساب كتلة الماء ومولاته فقط"},{"level":"1 درجة","description":"حساب كتلة الماء فقط"},{"level":"صفر","description":"لا إجابة أو طريقة خاطئة كليًا"}]'::jsonb, '["قسمة كتلة الماء على كتلة الملح اللامائي (نسبة كتل)","استخدام كتلة الملح المائي 4.76 g بدل اللامائي عند حساب مولات CoCl₂","عكس النسبة (مولات الملح ÷ مولات الماء)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T11:15:01.763Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1419, null, null, null, '(أ) كرر التسخين للتأكد من طرد ماء التبلور كله؛ فثبات الكتلة في القراءتين الأخيرتين (27.12 g) دليل على انتهاء طرد الماء، فيعتمد 27.12 g. (ب) كتلة الملح المائي = 30.72 − 25.00 = 5.72 g، وكتلة اللامائي = 27.12 − 25.00 = 2.12 g، وكتلة الماء = 3.60 g ← 3.60 ÷ 18.0 = 0.200 mol. مولات Na₂CO₃ = 2.12 ÷ 106.0 = 0.0200 mol. x = 0.200 ÷ 0.0200 = 10، فالصيغة Na₂CO₃·10H₂O (كربونات الصوديوم عشرية الماء).', '["تفسير تكرار التسخين بالوصول إلى ثبات الكتلة","اعتماد القراءة 27.12 g","حساب كتلتي الملح المائي واللامائي بطرح كتلة البوتقة","حساب المولات والنسبة","الصيغة Na₂CO₃·10H₂O"]'::jsonb, '["كتلة الملح المائي = 30.72 − 25.00 = 5.72 g","كتلة اللامائي = 27.12 − 25.00 = 2.12 g","كتلة الماء = 5.72 − 2.12 = 3.60 g ← 0.200 mol","n(Na₂CO₃) = 2.12 ÷ 106.0 = 0.0200 mol","x = 0.200 ÷ 0.0200 = 10 ← Na₂CO₃·10H₂O"]'::jsonb, '[{"element":"تفسير تكرار التسخين واختيار القراءة","marks":2},{"element":"حساب الكتل بطرح كتلة البوتقة","marks":1},{"element":"حساب المولات والنسبة","marks":2},{"element":"الصيغة النهائية","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"تفسير صحيح وحساب كامل وصيغة صحيحة"},{"level":"4–5 درجات","description":"الصيغة صحيحة مع نقص في التفسير أو خطوة"},{"level":"2–3 درجات","description":"تفسير صحيح مع خطأ في الحساب، أو حساب جزئي صحيح"},{"level":"1 درجة","description":"تفسير تكرار التسخين فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["اعتماد قراءة التسخين الأول 27.50 g","نسيان طرح كتلة البوتقة الفارغة","قسمة نسبة الكتل بدل المولات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:01.764Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1420, null, null, null, 'نفترض عينة كتلتها 100 g: كتلة الماء 21.1 g، وكتلة CuCl₂ = 100 − 21.1 = 78.9 g. الكتلة المولية لـ CuCl₂ = 63.5 + 2(35.5) = 134.5 g/mol. مولات الماء = 21.1 ÷ 18.0 = 1.17 mol، ومولات CuCl₂ = 78.9 ÷ 134.5 = 0.587 mol. x = 1.17 ÷ 0.587 ≈ 2. الصيغة CuCl₂·2H₂O: كلوريد النحاس II ثنائية الماء.', '["افتراض 100 g وتحويل النسب إلى كتل","حساب الكتلة المولية لـ CuCl₂","حساب مولات الماء ومولات CuCl₂","حساب x = 2 وكتابة الصيغة والاسم"]'::jsonb, '["في 100 g: m(H₂O) = 21.1 g ، m(CuCl₂) = 78.9 g","M(CuCl₂) = 134.5 g/mol","n(H₂O) = 1.17 mol ، n(CuCl₂) = 0.587 mol","x = 1.17 ÷ 0.587 ≈ 2 ← CuCl₂·2H₂O"]'::jsonb, '[{"element":"تحويل النسب إلى كتل","marks":1},{"element":"الكتلة المولية لـ CuCl₂","marks":1},{"element":"حساب المولات","marks":1},{"element":"x والصيغة والاسم","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حل كامل وصيغة واسم صحيحان"},{"level":"3 درجات","description":"حل صحيح مع خطأ في الاسم"},{"level":"2 درجتان","description":"حساب المولات صحيح مع خطأ في النسبة"},{"level":"1 درجة","description":"تحويل النسب إلى كتل فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["استخدام 21.1 مباشرة عددًا لجزيئات الماء","حساب كتلة CuCl₂ من 100 g كاملة دون طرح الماء","الخطأ في الكتلة المولية لـ CuCl₂ باستخدام Cl بدل 2Cl"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-11T11:15:01.764Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1421, 0, 'يمتص CaCl₂ اللامائي بخار الماء بسهولة، فيُستخدم لتجفيف الهواء وحفظ المواد الكيميائية من الرطوبة.', '["","CaCl₂ ملح يُضاف إلى الماء ولا يزيل الأملاح منه، فلا يُستخدم للتحلية.","ليس هذا استخدامه المذكور؛ استخدامه المذكور مرتبط بقدرته على امتصاص الماء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:01.769Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1422, 1, 'تمتص CaSO₄ جزيئات الماء وترتبط بها مكوّنة ملحًا مائيًا، فتبقي المذيب العضوي (كالإيثانول) خاليًا من الماء.', '["الغرض من إضافتها إزالة الماء لا تغيير درجة الغليان.","","الغرض ليس التوصيل الكهربائي؛ بل امتصاص الماء من المذيب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T11:15:01.769Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1423, 2, 'الملح اللامائي فقد ماء تبلوره، فيستطيع أن يرتبط بجزيئات الماء من الوسط المحيط ويتحول إلى ملح مائي، أما الملح المائي فهو مرتبط بالماء أصلًا.', '["قابلية الاشتعال لا علاقة لها بعمل المادة المجففة.","العكس صحيح؛ كتلة الملح المائي أكبر لاحتوائه على الماء.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:01.769Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1424, 0, 'CaCl₂ اللامائي مادة مجففة تمتص بخار الماء من الهواء وترتبط به، فتزداد كتلتها؛ وهذا أساس استخدامه في تجفيف الهواء.', '["","النيتروجين غاز خامل نسبيًا ولا يتفاعل مع CaCl₂.","لا يتفاعل CaCl₂ مع الأكسجين في الظروف العادية، والزيادة سببها الماء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T11:15:01.770Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1425, 2, 'CaCl₂ في صورته اللامائية قادر على امتصاص بخار الماء، فهو المناسب للحفظ من الرطوبة. أما المادتان الأخريان فملحان مائيان مرتبطان بالماء أصلًا.', '["ملح مائي (عشري الماء) مرتبط بعشر جزيئات ماء، فلا يُستخدم مجففًا.","ملح مائي مرتبط بخمس جزيئات ماء، فلا يُستخدم مجففًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T11:15:01.770Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1426, 1, 'تُضاف CaSO₄ اللامائية إلى المذيبات العضوية كالإيثانول فتمتص ما فيها من ماء وتبقيها خالية منه.', '["إضافة الماء تزيد محتوى الماء بدل إزالته.","","الملح المائي يحتوي على ماء تبلور، فلا يزيل الماء من المذيب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-10-11T11:15:01.772Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1427, 0, 'بعد ارتباط الملح بالماء يتحول إلى ملح مائي فتقل قدرته على امتصاص المزيد، وبتسخينه يُطرد الماء ويعود لامائيًا فيُستخدم مجففًا من جديد.', '["","كلما ارتبط بالماء قل عدد المواقع المتاحة لربط ماء جديد، فتقل قدرته.","قدرته مرتبطة بكونه لامائيًا، وتتغير عند تحوله إلى ملح مائي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T11:15:01.772Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1428, null, null, null, '1) كلوريد الكالسيوم اللامائي CaCl₂: يُستخدم لتجفيف الهواء من الماء وحفظ المواد الكيميائية من الرطوبة. 2) كبريتات الكالسيوم CaSO₄: تُضاف إلى المذيبات العضوية كالإيثانول لإبقائها خالية من الماء. والخاصية المشتركة: قدرة الملح اللامائي على امتصاص جزيئات الماء والارتباط بها مكوّنًا ملحًا مائيًا.', '["CaCl₂ لتجفيف الهواء وحفظ المواد من الرطوبة","CaSO₄ لإبقاء المذيبات العضوية خالية من الماء","الخاصية: قدرة الملح اللامائي على امتصاص الماء والارتباط به"]'::jsonb, '[]'::jsonb, '[{"element":"الاستخدام الأول مع الملح","marks":1},{"element":"الاستخدام الثاني مع الملح","marks":1},{"element":"الخاصية المشتركة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"استخدامان صحيحان مع الملحين والخاصية"},{"level":"2 درجتان","description":"استخدامان صحيحان دون الخاصية، أو استخدام واحد مع الخاصية"},{"level":"1 درجة","description":"استخدام واحد صحيح"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["ذكر ملح مائي (مثل CuSO₄·5H₂O) مادةً مجففة","الخلط بين استخدام CaCl₂ واستخدام CaSO₄ دون ذكر الغرض","تفسير التجفيف بتفاعل الملح مع الهواء لا بامتصاص الماء"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:01.773Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1429, null, null, null, '(أ) لأن الملح اللامائي فقد ماء تبلوره، فيستطيع امتصاص جزيئات الماء والارتباط بها، أما المائي فمرتبط بالماء أصلًا. (ب) لأنها تمتص بخار الماء من الهواء داخل الوعاء فترتبط به وتتحول إلى ملح مائي، فتزداد كتلتها بمقدار كتلة الماء الممتص. (ج) لأن التسخين يطرد جزيئات الماء المرتبطة فيعود الملح لامائيًا قادرًا على امتصاص الماء من جديد.', '["(أ) قدرة اللامائي على الارتباط بالماء","(ب) امتصاص بخار الماء وزيادة الكتلة بمقدار الماء الممتص","(ج) التسخين يطرد الماء فيعود الملح لامائيًا"]'::jsonb, '[]'::jsonb, '[{"element":"تعليل (أ)","marks":1},{"element":"تعليل (ب)","marks":1},{"element":"تعليل (ج)","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"التعليلات الثلاثة صحيحة"},{"level":"2 درجتان","description":"تعليلان صحيحان"},{"level":"1 درجة","description":"تعليل واحد صحيح"},{"level":"صفر","description":"لا إجابة أو تعليلات خاطئة"}]'::jsonb, '["القول إن الكتلة تزداد بسبب تفاعل الملح مع الأكسجين","الاعتقاد بأن التسخين يحلل الملح نفسه","عدم الربط بين الامتصاص وتكوّن ملح مائي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T11:15:01.773Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1430, null, null, null, 'الكتلة المولية لـ CaCl₂ = 40.0 + 2(35.5) = 111.0 g/mol، فمولات CaCl₂ = 11.1 ÷ 111.0 = 0.100 mol. كل 1 mol من CaCl₂ يرتبط بـ 2 mol من الماء، فمولات الماء = 0.200 mol، وكتلته = 0.200 × 18.0 = 3.60 g. كتلة المادة بعد الامتصاص = 11.1 + 3.60 = 14.7 g.', '["الكتلة المولية لـ CaCl₂","مولات CaCl₂","استخدام النسبة 1 : 2 لإيجاد مولات الماء","كتلة الماء 3.60 g","الكتلة النهائية 14.7 g"]'::jsonb, '["M(CaCl₂) = 111.0 g/mol","n(CaCl₂) = 11.1 ÷ 111.0 = 0.100 mol","n(H₂O) = 2 × 0.100 = 0.200 mol","m(H₂O) = 0.200 × 18.0 = 3.60 g","الكتلة النهائية = 11.1 + 3.60 = 14.7 g"]'::jsonb, '[{"element":"مولات CaCl₂","marks":1},{"element":"مولات الماء بالنسبة 1 : 2","marks":1},{"element":"كتلة الماء","marks":1},{"element":"الكتلة النهائية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حل كامل صحيح بالوحدات"},{"level":"3 درجات","description":"كتلة الماء صحيحة دون الكتلة النهائية"},{"level":"2 درجتان","description":"مولات CaCl₂ والماء صحيحة مع خطأ حسابي"},{"level":"1 درجة","description":"مولات CaCl₂ فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["نسيان الضرب في 2 (أخذ 1 mol ماء فقط)","استخدام 111.0 g/mol كتلةً مولية للملح المائي","طرح كتلة الماء بدل إضافتها"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:01.773Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1431, 1, 'يُسمى الملح المائي باسم الملح اللامائي متبوعًا بالبادئة الدالة على عدد جزيئات الماء ثم كلمة «الماء»؛ والعدد 6 تقابله البادئة «سداسي»، فالاسم: كلوريد الكوبلت II سداسية الماء.', '["البادئة «سباعي» تدل على 7 جزيئات ماء لا 6.","","العدد 2 هو عدد ذرات الكلور في الصيغة، لا عدد جزيئات الماء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-11T11:15:01.776Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1432, 0, 'كلوريد الكالسيوم CaCl₂، والبادئة «ثنائي» تعني جزيئي ماء لكل وحدة صيغة، فالصيغة CaCl₂·2H₂O.', '["","هذه صيغة ملح أحادي الماء، لا ثنائي الماء.","وُضعت البادئة على أيون الكالسيوم خطأً، وصيغة كلوريد الكالسيوم الصحيحة CaCl₂."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T11:15:01.776Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1433, 2, 'البادئة «خماسي» تدل على 5 جزيئات ماء، مثل كبريتات النحاس II خماسية الماء CuSO₄·5H₂O.', '["«سداسي» تدل على 6 جزيئات ماء.","«ثلاثي» تدل على 3 جزيئات ماء.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T11:15:01.777Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1434, 0, 'شحنة أيون الفوسفات PO₄³⁻ هي −3، فشحنة الحديد +3 ويُكتب الحديد III، والعدد 4 قبل H₂O تقابله البادئة «رباعي»: فوسفات الحديد III رباعية الماء.', '["","أيون الفوسفات شحنته −3، فالحديد في FePO₄ ثلاثي الشحنة لا ثنائيها.","العدد 3 هو شحنة الحديد، أما عدد جزيئات الماء فهو 4."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-11T11:15:01.777Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1435, 2, 'العدد قبل H₂O هو 8، والبادئة المقابلة «ثماني»، فالاسم: هيدروكسيد الباريوم ثمانية الماء.', '["العدد 2 هو عدد مجموعات الهيدروكسيد في الصيغة، لا عدد جزيئات الماء.","البادئة «عشري» تدل على 10 جزيئات ماء، مثل Na₂CO₃·10H₂O.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-10-11T11:15:01.777Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1436, 1, 'Na₂CO₃·10H₂O تحتوي على 10 جزيئات ماء، فاسمها كربونات الصوديوم عشرية الماء، وهو ما كتبه الطالب. أما CuSO₄·5H₂O فهي خماسية الماء، وMgSO₄·7H₂O سباعية الماء.', '["MgSO₄·7H₂O فيها 7 جزيئات ماء فهي سباعية الماء، لا ثمانية الماء.","","CuSO₄·5H₂O فيها 5 جزيئات ماء فهي خماسية الماء، لا سداسية الماء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-11T11:15:01.777Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1437, 1, 'لا يوجد رقم قبل H₂O، أي أن كل وحدة صيغة ترتبط بجزيء ماء واحد، فالاسم: أكسالات الأمونيوم أحادية الماء.', '["العدد 2 هو عدد أيونات الأمونيوم في الصيغة، لا عدد جزيئات الماء.","","العدد 4 هو عدد ذرات الأكسجين في أيون الأكسالات C₂O₄²⁻، لا عدد جزيئات الماء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-10-11T11:15:01.778Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1438, null, null, null, '(أ) MgSO₄·7H₂O: كبريتات المغنيسيوم سباعية الماء. NaC₂H₃O₂·3H₂O: أسيتات الصوديوم ثلاثية الماء. (ب) كربونات الصوديوم عشرية الماء: Na₂CO₃·10H₂O. كبريتات النحاس II خماسية الماء: CuSO₄·5H₂O.', '["كبريتات المغنيسيوم سباعية الماء","أسيتات الصوديوم ثلاثية الماء","Na₂CO₃·10H₂O","CuSO₄·5H₂O"]'::jsonb, '[]'::jsonb, '[{"element":"اسم MgSO₄·7H₂O","marks":1},{"element":"اسم NaC₂H₃O₂·3H₂O","marks":1},{"element":"صيغة كربونات الصوديوم عشرية الماء","marks":1},{"element":"صيغة كبريتات النحاس II خماسية الماء","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الإجابات الأربع صحيحة"},{"level":"3 درجات","description":"ثلاث إجابات صحيحة"},{"level":"2 درجتان","description":"إجابتان صحيحتان"},{"level":"1 درجة","description":"إجابة واحدة صحيحة"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["كتابة Na₂CO₂ بدل Na₂CO₃ (خطأ وارد في جدول منسوخ)","الخلط بين سباعي (7) وثماني (8)","وضع عدد جزيئات الماء أسفل H₂O بدل كتابته معاملًا قبلها"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T11:15:01.778Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1439, null, null, null, 'التسمية الأولى: أخطأ الطالب في البادئة، إذ أخذ العدد 2 (عدد ذرات الصوديوم) بدل عدد جزيئات الماء 10؛ والاسم الصحيح: كربونات الصوديوم عشرية الماء. التسمية الثانية: أخطأ في شحنة الحديد؛ فثلاثة أيونات Cl⁻ تعني أن شحنة الحديد +3، والاسم الصحيح: كلوريد الحديد III سداسية الماء (البادئة «سداسية» صحيحة لأن عدد جزيئات الماء 6).', '["تحديد خطأ البادئة في الاسم الأول","الاسم الصحيح: كربونات الصوديوم عشرية الماء","تحديد خطأ شحنة الحديد في الاسم الثاني مع التعليل بثلاثة أيونات Cl⁻","الاسم الصحيح: كلوريد الحديد III سداسية الماء"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد الخطأ الأول وتصحيحه","marks":2},{"element":"تحديد الخطأ الثاني وتعليله","marks":1},{"element":"الاسم الصحيح الثاني","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحديد الخطأين وتصحيحهما مع التعليل"},{"level":"3 درجات","description":"تصحيح الاسمين دون تعليل كافٍ"},{"level":"2 درجتان","description":"تحديد خطأ واحد وتصحيحه"},{"level":"1 درجة","description":"تحديد وجود خطأ دون تصحيح"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["تسمية Fe(III) «الحديدوز» (والحديدوز للحديد II)","تغيير البادئة «سداسية» في الاسم الثاني ظنًا أنها خطأ","عدم ربط شحنة الفلز بعدد أيونات الكلوريد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T11:15:01.778Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1440, null, null, null, 'الكتلة المولية لـ Na₂SO₄ = 2(23.0) + 32.0 + 4(16.0) = 142.0 g/mol. كتلة الماء في المول الواحد = 322.0 − 142.0 = 180.0 g. x = 180.0 ÷ 18.0 = 10. الصيغة Na₂SO₄·10H₂O، واسمه كبريتات الصوديوم عشرية الماء.', '["حساب الكتلة المولية لـ Na₂SO₄","إيجاد كتلة الماء بالطرح","x = 10","الصيغة والاسم"]'::jsonb, '["M(Na₂SO₄) = 142.0 g/mol","كتلة الماء = 322.0 − 142.0 = 180.0 g","x = 180.0 ÷ 18.0 = 10","Na₂SO₄·10H₂O: كبريتات الصوديوم عشرية الماء"]'::jsonb, '[{"element":"الكتلة المولية لـ Na₂SO₄","marks":1},{"element":"كتلة الماء وقيمة x","marks":1},{"element":"الصيغة","marks":1},{"element":"الاسم","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حل صحيح مع الصيغة والاسم"},{"level":"3 درجات","description":"x والصيغة صحيحتان مع خطأ في الاسم"},{"level":"2 درجتان","description":"الكتلة المولية وكتلة الماء صحيحتان مع خطأ في x"},{"level":"1 درجة","description":"الكتلة المولية لـ Na₂SO₄ فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["قسمة 322.0 على 18.0 دون طرح كتلة الملح اللامائي","الخطأ في عدد ذرات الصوديوم عند حساب الكتلة المولية","الاسم «عشارية» أو بادئة غير مطابقة للعدد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T11:15:01.779Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1441, 1, 'بتسخين الملح المائي تنفصل جزيئات ماء التبلور وتتبخر، ويبقى الملح اللامائي.', '["الإذابة في الماء تزيد الماء ولا تطرده.","","التبريد لا يفصل جزيئات الماء المرتبطة بالملح."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T11:15:01.784Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1442, 0, 'ثبات الكتلة في قراءتين متتاليتين يدل على أنه لم يبقَ ماء يُطرد، أي أن العينة أصبحت ملحًا لامائيًا تمامًا.', '["","الكتلة المولية للملح اللامائي ثابتة ولا تتغير بالتسخين.","التسخين يطرد الماء فقط، ولا يحلل الملح إلى عناصره."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T11:15:01.785Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1443, 2, 'CuSO₄·5H₂O زرقاء، وعند فقدها جزيئات الماء الخمسة تتحول إلى CuSO₄ اللامائية البيضاء.', '["هذا عكس التغير؛ فالأبيض هو لون الملح اللامائي الناتج لا الملح الابتدائي.","لون CuSO₄ اللامائية أبيض لا أحمر.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T11:15:01.785Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1444, 0, 'يتبخر ماء التبلور ويغادر العينة، فتقل كتلتها بمقدار كتلة الماء المطرود، وكتلة الملح اللامائي أصغر من كتلة الملح المائي.', '["","الظن بأن كتلة اللامائي أكبر من المائي تصور خاطئ؛ فالعينة تفقد الماء.","العينة تفقد الماء على هيئة بخار، فلا بد أن تقل كتلتها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T11:15:01.786Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1445, 1, 'بالتسخين تنفصل جزيئات الماء السبع كلها، فتنتج 1 mol من MgSO₄ و7 mol من H₂O، والمعادلة موزونة.', '["المعادلة غير موزونة؛ ذرات الهيدروجين والأكسجين في الطرفين غير متساوية.","","الماء يُطرد بالتسخين ولا يُضاف، ووضعه في المتفاعلات خطأ."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:01.786Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1446, 2, 'ثبتت الكتلة عند 2.56 g في التسخينين الثالث والرابع، فهي كتلة الملح اللامائي، وكتلة الماء = 4.00 − 2.56 = 1.44 g.', '["اعتُمدت قراءة التسخين الأول (3.20 g) قبل اكتمال طرد الماء.","اعتُمدت قراءة التسخين الثاني (2.85 g) ولم تكن الكتلة قد ثبتت بعد.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T11:15:01.787Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1447, 1, 'يمكن أن يستعيد الملح اللامائي الماء من الهواء الرطب، فتزيد كتلته وتفسد النتيجة؛ لذلك يُبرَّد بعيدًا عن الرطوبة.', '["الملح نفسه لا يتبخر في هذه الظروف؛ الذي يتبخر عند التسخين هو الماء فقط.","","التبريد يكون بعد انتهاء طرد الماء، والهدف منع امتصاص الرطوبة لا تسريع الطرد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:01.787Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1448, null, null, null, '1) تُوزن بوتقة نظيفة جافة فارغة. 2) يوضع فيها مقدار من الملح المائي وتُوزن. 3) تُسخّن البوتقة بما فيها تسخينًا كافيًا لطرد ماء التبلور. 4) تُترك لتبرد ثم تُوزن. 5) يُكرر التسخين والوزن حتى تثبت الكتلة، فيكون المتبقي ملحًا لامائيًا. كتلة الماء المطرود = كتلة الملح المائي − كتلة الملح اللامائي.', '["وزن البوتقة فارغة ثم مع الملح المائي","التسخين لطرد ماء التبلور","التبريد ثم الوزن","تكرار التسخين حتى ثبات الكتلة","كتلة الماء = المائي − اللامائي"]'::jsonb, '[]'::jsonb, '[{"element":"وزن البوتقة والعينة","marks":1},{"element":"التسخين لطرد الماء","marks":1},{"element":"تكرار التسخين حتى ثبات الكتلة","marks":1},{"element":"علاقة حساب كتلة الماء","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"خطوات كاملة مرتبة مع علاقة كتلة الماء"},{"level":"3 درجات","description":"خطوات صحيحة دون تكرار التسخين حتى ثبات الكتلة"},{"level":"2 درجتان","description":"ذكر التسخين وعلاقة كتلة الماء فقط"},{"level":"1 درجة","description":"ذكر التسخين فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["إهمال وزن البوتقة الفارغة","الاكتفاء بتسخين واحد دون التحقق من ثبات الكتلة","جمع الكتلتين بدل طرحهما"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T11:15:01.787Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1449, null, null, null, '(1) فقدت كبريتات النحاس II جزيئات الماء الخمسة وتحولت إلى CuSO₄ اللامائية البيضاء. (2) القطرات هي ماء التبلور الذي تبخر ثم تكثف على الجزء البارد. (3) نقصت الكتلة بمقدار كتلة الماء المطرود. المعادلة: CuSO₄·5H₂O → CuSO₄ + 5H₂O. قول الزميل خطأ؛ فالذي غادر العينة هو الماء فقط، وبقي الملح اللامائي الأبيض في الأنبوب.', '["تفسير تغير اللون بفقد الماء","تفسير القطرات بتكثف بخار الماء","تفسير نقص الكتلة","المعادلة الموزونة","تصحيح فكرة تبخر الملح"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير الملاحظات الثلاث","marks":3},{"element":"المعادلة الموزونة","marks":1},{"element":"تصحيح التصور الخاطئ","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تفسير كامل ومعادلة صحيحة وتصحيح التصور"},{"level":"4 درجات","description":"نقص عنصر واحد"},{"level":"3 درجات","description":"تفسير الملاحظات الثلاث فقط"},{"level":"1–2 درجة","description":"تفسير ملاحظة أو اثنتين"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["كتابة المعادلة دون المعامل 5 أمام H₂O","تفسير القطرات بأنها ملح منصهر","الاعتقاد بأن الملح تحلل أو احترق"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-11T11:15:01.788Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1450, null, null, null, 'M(CuSO₄) = 63.5 + 32.0 + 4(16.0) = 159.5 g/mol، وM(CuSO₄·5H₂O) = 159.5 + 5(18.0) = 249.5 g/mol. مولات الملح المائي = 12.5 ÷ 249.5 = 0.0501 mol، وهي تساوي مولات CuSO₄ الناتجة (1 : 1). كتلة CuSO₄ = 0.0501 × 159.5 = 7.99 g. كتلة الماء = 12.5 − 7.99 = 4.51 g.', '["الكتلتان الموليتان للمائي واللامائي","مولات الملح المائي","النسبة 1 : 1 بين المائي واللامائي","كتلة CuSO₄ = 7.99 g","كتلة الماء = 4.51 g"]'::jsonb, '["M(CuSO₄) = 159.5 g/mol ، M(CuSO₄·5H₂O) = 249.5 g/mol","n = 12.5 ÷ 249.5 = 0.0501 mol","m(CuSO₄) = 0.0501 × 159.5 = 7.99 g","m(H₂O) = 12.5 − 7.99 = 4.51 g"]'::jsonb, '[{"element":"الكتلتان الموليتان","marks":1},{"element":"عدد المولات","marks":1},{"element":"كتلة الملح اللامائي","marks":1},{"element":"كتلة الماء","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حل كامل وأرقام معنوية صحيحة"},{"level":"3 درجات","description":"خطوات صحيحة مع خطأ تقريب"},{"level":"2 درجتان","description":"الكتل المولية والمولات صحيحة فقط"},{"level":"1 درجة","description":"الكتل المولية فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["قسمة 12.5 على الكتلة المولية للامائي 159.5","نسيان إضافة كتلة الماء الخماسية في الكتلة المولية للمائي","ضرب مولات الماء في 18.0 دون الضرب في 5"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T11:15:01.788Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1451, 1, 'المعاملات تدل على عدد الجسيمات (الجزيئات) وعدد المولات: 1 mol N₂ يتفاعل مع 3 mol H₂ لينتج 2 mol NH₃، ولا تمثل الكتل مباشرة.', '["المعاملات لا تمثل الكتل؛ فـ 1 g N₂ لا يتفاعل مع 3 g H₂.","","عدد الذرات في الجزيء تبينه الأرقام السفلية (مثل 2 في N₂) لا المعاملات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-11T11:15:01.791Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1452, 2, 'المعاملات 4 و3 و2 تمثل أعداد المولات: 4 mol Fe + 3 mol O₂ ← 2 mol Fe₂O₃.', '["المعاملات ليست كتلًا بالجرام؛ والكتل الحقيقية 224 g و96 g و320 g.","الأكسجين في المعادلة جزيئات O₂ لا ذرات O منفردة، ووحدة Fe₂O₃ وحدة صيغة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-10-11T11:15:01.791Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1453, 0, '36.5 g من HCl تساوي 1 mol، والنسبة المولية HCl : KOH = 1 : 1، فيلزم 1 mol من KOH كتلته 39.0 + 16.0 + 1.0 = 56.0 g.', '["","هذه كتلة البوتاسيوم وحده، ونُسيت كتلتا O وH في KOH.","افتُرض أن المواد تتفاعل بكتل متساوية، والصحيح أنها تتفاعل بمولات متساوية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T11:15:01.791Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1454, 1, 'كل جزيء O₂ ينتج جزيئين من H₂O (النسبة 1 : 2)، فـ 10 جزيئات O₂ تنتج 20 جزيئًا من H₂O.', '["افتُرضت النسبة 1 : 1 بين O₂ وH₂O متجاهلًا المعاملات.","","عُكست النسبة فقُسم العدد على 2 بدل ضربه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-11T11:15:01.792Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1455, 2, 'كتلة 2 mol من NH₃ = 2 × 17.0 = 34.0 g، وهي تساوي مجموع كتل المتفاعلات 28.0 + 6.0 = 34.0 g تحقيقًا لقانون حفظ الكتلة.', '["هذه كتلة 1 mol فقط من NH₃، ونُسي المعامل 2.","استُخدم المعامل 2 على أنه كتلة بالجرام.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-10-11T11:15:01.792Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1456, 0, 'في هذا التفاعل 4 mol من المتفاعلات تنتج 2 mol من النواتج، فعدد المولات غير محفوظ، أما الكتلة الكلية وعدد ذرات كل عنصر فمحفوظان دائمًا.', '["","الكتلة الكلية محفوظة دائمًا وفق قانون حفظ الكتلة (34 g = 34 g).","عدد ذرات كل عنصر محفوظ في المعادلة الموزونة (2 N و6 H في كل طرف)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-11T11:15:01.792Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1457, 1, 'العلاقات الكمية بين المتفاعلات والنواتج تُستمد من المعاملات، فلا بد أولًا من كتابة معادلة موزونة.', '["حساب الكتل المولية يأتي لاحقًا عند التحويل بين الكتلة والمول.","","التحويل إلى مولات خطوة تالية؛ فلا معنى للمولات دون معادلة موزونة تربط المواد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-11T11:15:01.793Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1458, null, null, null, '(أ) 4 ذرات Fe تتفاعل مع 3 جزيئات O₂ لتنتج 2 وحدتي صيغة من Fe₂O₃. (ب) 4 mol Fe تتفاعل مع 3 mol O₂ لتنتج 2 mol Fe₂O₃. (ج) كتلة 4 mol Fe = 4 × 56.0 = 224 g، وكتلة 3 mol O₂ = 3 × 32.0 = 96.0 g، وكتلة 2 mol Fe₂O₃ = 2 × 160.0 = 320 g. مجموع كتل المتفاعلات = 224 + 96.0 = 320 g = كتلة النواتج، فالكتلة محفوظة.', '["تفسير الجسيمات","تفسير المولات","حساب الكتل 224 g و96.0 g و320 g","المقارنة وإثبات حفظ الكتلة"]'::jsonb, '["M(Fe₂O₃) = 2(56.0) + 3(16.0) = 160.0 g/mol","كتلة Fe = 4 × 56.0 = 224 g","كتلة O₂ = 3 × 32.0 = 96.0 g","كتلة Fe₂O₃ = 2 × 160.0 = 320 g","224 + 96.0 = 320 g = 320 g"]'::jsonb, '[{"element":"تفسير الجسيمات","marks":1},{"element":"تفسير المولات","marks":1},{"element":"حساب الكتل","marks":2},{"element":"إثبات حفظ الكتلة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تفسير كامل بالمستويات الثلاثة مع إثبات حفظ الكتلة"},{"level":"4 درجات","description":"نقص عنصر واحد"},{"level":"3 درجات","description":"تفسير الجسيمات والمولات مع خطأ في الكتل"},{"level":"1–2 درجة","description":"تفسير مستوى واحد صحيح"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["اعتبار O₂ ذرات أكسجين منفردة","نسيان ضرب الكتل المولية في المعاملات","اعتبار المعاملات كتلًا بالجرام"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-10-11T11:15:01.793Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1459, null, null, null, 'قوله خطأ؛ لأن المعاملات تمثل أعداد المولات (أو الجسيمات) لا الكتل بالجرام، ويدل على خطئه أن 2 g + 1 g = 3 g لا تساوي 2 g فيخالف قانون حفظ الكتلة. التفسير الصحيح: 2 mol CO كتلتها 2 × 28.0 = 56.0 g تتفاعل مع 1 mol O₂ كتلته 32.0 g لتنتج 2 mol CO₂ كتلتها 2 × 44.0 = 88.0 g، و56.0 + 32.0 = 88.0 g.', '["الحكم بخطأ القول","التعليل: المعاملات تمثل المولات لا الكتل","ملاحظة مخالفة قوله لحفظ الكتلة","الكتل الصحيحة 56.0 g و32.0 g و88.0 g"]'::jsonb, '["M(CO) = 28.0 g/mol ، M(O₂) = 32.0 g/mol ، M(CO₂) = 44.0 g/mol","2 × 28.0 = 56.0 g CO","1 × 32.0 = 32.0 g O₂","2 × 44.0 = 88.0 g CO₂ = 56.0 + 32.0"]'::jsonb, '[{"element":"الحكم والتعليل","marks":2},{"element":"الكتل الصحيحة","marks":1},{"element":"التحقق من حفظ الكتلة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم وتعليل صحيحان مع الكتل الصحيحة والتحقق"},{"level":"3 درجات","description":"حكم وتعليل وكتل صحيحة دون التحقق"},{"level":"2 درجتان","description":"حكم وتعليل صحيحان فقط"},{"level":"1 درجة","description":"الحكم بالخطأ دون تعليل"},{"level":"صفر","description":"لا إجابة أو تأييد قول الطالب"}]'::jsonb, '["تأييد قول الطالب","حساب كتلة CO₂ لمول واحد (44.0 g) فقط","الخلط بين الكتلة المولية لـ O وO₂"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:01.793Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1460, null, null, null, '(أ) 1 mol C₃H₈ يتفاعل مع 5 mol O₂ لينتج 3 mol CO₂ و4 mol H₂O. (ب) C₃H₈: 1 × 44.0 = 44.0 g، O₂: 5 × 32.0 = 160 g، المجموع 204 g. CO₂: 3 × 44.0 = 132 g، H₂O: 4 × 18.0 = 72.0 g، المجموع 204 g. (ج) مولات المتفاعلات 6 mol ومولات النواتج 7 mol؛ لأن الذرات يُعاد ترتيبها في جزيئات جديدة يختلف عددها، أما عدد ذرات كل عنصر فلا يتغير، ولذلك تبقى الكتلة الكلية محفوظة.', '["تفسير المولات","الكتل: 44.0 و160 و132 و72.0 g","مجموع كل طرف 204 g","تعليل عدم تساوي المولات مع حفظ الكتلة"]'::jsonb, '["M(C₃H₈) = 44.0 ، M(O₂) = 32.0 ، M(CO₂) = 44.0 ، M(H₂O) = 18.0 g/mol","المتفاعلات: 44.0 + 5(32.0) = 204 g","النواتج: 3(44.0) + 4(18.0) = 204 g","المولات: 6 mol ← 7 mol"]'::jsonb, '[{"element":"تفسير المولات","marks":1},{"element":"حساب الكتل والمجموعين","marks":2},{"element":"التعليل","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة"},{"level":"4 درجات","description":"كتل صحيحة مع تعليل ناقص"},{"level":"3 درجات","description":"تفسير المولات وحساب الكتل فقط"},{"level":"1–2 درجة","description":"تفسير المولات فقط أو حساب جزئي"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["كتابة صيغة البروبان C₃H₆ بدل C₃H₈","نسيان ضرب كتلة O₂ في 5","الاعتقاد بأن عدد المولات يجب أن يكون محفوظًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T11:15:01.794Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1461, 2, 'الحسابات الكيميائية هي دراسة العلاقات الكمية بين المواد المتفاعلة والمواد الناتجة في التفاعل الكيميائي.', '["دراسة سرعة التفاعل موضوع آخر (سرعة التفاعلات الكيميائية).","هذا يخص التوزيع الإلكتروني للذرات لا الحسابات الكيميائية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T11:15:01.796Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1462, 0, 'تعتمد الحسابات الكيميائية على قانون حفظ الكتلة: المادة لا تفنى ولا تُستحدث، فكتل المتفاعلات تساوي كتل النواتج.', '["","قانون بويل يربط ضغط الغاز بحجمه، ولا يُبنى عليه حساب كميات المتفاعلات والنواتج.","قانون شارل يربط حجم الغاز بدرجة حرارته، ولا يخص العلاقات الكمية في التفاعل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T11:15:01.796Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1463, 1, 'السؤال عن كمية ناتج من كمية متفاعل معلومة يمثل علاقة كمية بين متفاعل وناتج، وهذا موضوع الحسابات الكيميائية.', '["نوع الرابطة موضوع الروابط الكيميائية، وليس علاقة كمية في تفاعل.","","الشكل الهندسي موضوع أشكال الجزيئات، وليس حسابًا لكميات المواد في تفاعل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T11:15:01.798Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1464, 2, 'العلاقات الكمية تُستمد من معاملات المعادلة، ولا تكون صحيحة إلا إذا كانت المعادلة موزونة.', '["المعادلة اللفظية لا تحتوي على معاملات تبين النسب بين المواد.","المعادلة غير الموزونة تعطي نسبًا خاطئة وتخالف قانون حفظ الكتلة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T11:15:01.798Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1465, 1, 'الحسابات الكيميائية تتعامل مع مقادير قابلة للقياس والعد: عدد الجسيمات وعدد المولات والكتل.', '["اللون والرائحة صفات نوعية لا كمية.","","الأسماء والصيغ ليست مقادير تُحسب، بل تُستخدم لتحديد المواد فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T11:15:01.799Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1466, 0, 'تعبّر المعادلة الموزونة عن العلاقات بين المواد بدلالة عدد الجسيمات وعدد المولات والكتلة، فالحسابات الكيميائية لا تقتصر على الكتل.', '["","صحيح أن الكتلة محفوظة، لكن هذا لا يعني أن الحسابات الكيميائية تقتصر عليها؛ فهي تستخدم المولات والجسيمات أيضًا.","الحسابات الكيميائية تدرس كميات المواد لا سرعة التفاعل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:01.799Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1467, 0, 'حساب كمية H₂ اللازمة لإنتاج كمية معلومة من NH₃ علاقة كمية بين متفاعل وناتج، وهذا من الحسابات الكيميائية.', '["","اختيار لون العبوات لا علاقة له بكميات المواد في التفاعل.","قياس درجة حرارة المخزن لا يعبر عن علاقة كمية بين متفاعلات ونواتج."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T11:15:01.799Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1468, null, null, null, 'الحسابات الكيميائية: دراسة العلاقات الكمية بين المواد المتفاعلة والمواد الناتجة في التفاعل الكيميائي. تعتمد على قانون حفظ الكتلة: المادة لا تفنى ولا تُستحدث، أي أن مجموع كتل المتفاعلات يساوي مجموع كتل النواتج. والخطوة الأولى في حل مسائلها: كتابة معادلة كيميائية موزونة.', '["التعريف: العلاقات الكمية بين المتفاعلات والنواتج","القانون: حفظ الكتلة مع نصه","الخطوة الأولى: كتابة معادلة موزونة"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"القانون ونصه","marks":1},{"element":"الخطوة الأولى","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"العناصر الثلاثة صحيحة"},{"level":"2 درجتان","description":"عنصران صحيحان"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["إسقاط كلمة «الكمية» من التعريف","ذكر قانون آخر غير حفظ الكتلة","القول إن الخطوة الأولى حساب الكتل المولية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T11:15:01.799Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1469, null, null, null, 'بدلالة المولات: 1 mol من N₂ يتفاعل مع 3 mol من H₂ لينتج 2 mol من NH₃. بدلالة الكتل: 1 × 28.0 = 28.0 g من N₂ تتفاعل مع 3 × 2.0 = 6.0 g من H₂ لتنتج 2 × 17.0 = 34.0 g من NH₃، ومجموع كتل المتفاعلات (34.0 g) يساوي كتلة الناتج، وفق قانون حفظ الكتلة. وبذلك تمكّننا الحسابات الكيميائية من معرفة كمية أي مادة في التفاعل إذا عُلمت كمية مادة أخرى.', '["العلاقة المولية 1 : 3 : 2","الكتل 28.0 g و6.0 g و34.0 g","ربط النتيجة بحفظ الكتلة","فائدة الحسابات: معرفة كمية مادة من كمية أخرى"]'::jsonb, '["M(N₂) = 28.0 ، M(H₂) = 2.0 ، M(NH₃) = 17.0 g/mol","28.0 g + 6.0 g = 34.0 g"]'::jsonb, '[{"element":"العلاقة بالمولات","marks":1},{"element":"العلاقة بالكتل","marks":2},{"element":"الربط بحفظ الكتلة والفائدة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"توضيح كامل بالمولات والكتل مع الربط"},{"level":"3 درجات","description":"المولات والكتل صحيحة دون الربط"},{"level":"2 درجتان","description":"العلاقة بالمولات فقط أو الكتل فقط"},{"level":"1 درجة","description":"فكرة عامة صحيحة"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["اعتبار المعاملات كتلًا (1 g و3 g و2 g)","استخدام 1.0 g/mol كتلة مولية لـ H₂","نسيان ضرب 17.0 في 2"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T11:15:01.800Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1470, null, null, null, 'تعتمد على الحسابات الكيميائية: (1) و(3)؛ لأن كلًا منهما يطلب كمية مادة (كتلة أو مولات) في تفاعل كيميائي بدلالة كمية مادة أخرى، أي علاقة كمية بين متفاعل وناتج أو متفاعلين. لا تعتمد عليها: (2) لأنه وصف لخاصية نوعية (اللون)، و(4) لأنه تمثيل لتركيب الجزيء والروابط، وليس فيهما علاقة كمية بين مواد متفاعلة وناتجة.', '["تصنيف (1) و(3) ضمن الحسابات الكيميائية","تصنيف (2) و(4) خارجها","التعليل بوجود علاقة كمية بين المتفاعلات والنواتج أو غيابها"]'::jsonb, '[]'::jsonb, '[{"element":"تصنيف المهام الأربع","marks":2},{"element":"التعليل","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"تصنيف صحيح للمهام الأربع مع تعليل مناسب"},{"level":"3 درجات","description":"تصنيف صحيح مع تعليل ناقص"},{"level":"2 درجتان","description":"تصنيف صحيح دون تعليل، أو ثلاث مهام مع تعليل"},{"level":"1 درجة","description":"تصنيف مهمتين صحيحًا"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["اعتبار أي مهمة فيها أرقام أو رسم من الحسابات الكيميائية","عدم ربط التعليل بالعلاقات الكمية في التفاعل","الخلط بين الخواص النوعية والكمية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T11:15:01.800Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1471, 1, 'ينص قانون حفظ الكتلة على أن المادة لا تفنى ولا تُستحدث من العدم في التفاعل الكيميائي، أي أن كتل المتفاعلات تساوي كتل النواتج.', '["عدد المولات قد يتغير في التفاعل (مثل N₂ + 3H₂ → 2NH₃: 4 mol ← 2 mol).","","الحجم لا يُحفظ بالضرورة، والقانون يتعلق بالكتلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-11T11:15:01.802Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1472, 0, 'وفق قانون حفظ الكتلة تتساوى كتل المتفاعلات وكتل النواتج.', '["","هذا يعني فناء جزء من المادة، وهو ما ينفيه القانون.","هذا يعني استحداث مادة من العدم، وهو ما ينفيه القانون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-11T11:15:01.803Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1473, 2, 'في التفاعل الكيميائي يُعاد ترتيب الذرات في مواد جديدة، ولا تُفقد ذرات ولا تتكون ذرات جديدة، فتبقى الكتلة ثابتة.', '["التفاعل الكيميائي لا يحوّل عنصرًا إلى عنصر آخر.","كتلة الذرة لا تتغير في التفاعل الكيميائي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T11:15:01.803Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1474, 1, 'وفق قانون حفظ الكتلة: كتلة HgO = كتلة Hg + كتلة O₂، فكتلة O₂ = 21.7 − 20.1 = 1.6 g.', '["جُمعت الكتلتان بدل طرحهما.","","افتُرض أن كتلة الأكسجين تساوي كتلة الزئبق."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T11:15:01.803Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1475, 2, 'المسحوق هو أكسيد المغنيسيوم الذي تكوّن من اتحاد المغنيسيوم بأكسجين الهواء، فالزيادة تساوي كتلة الأكسجين المتفاعل، ومجموع كتل المتفاعلات (Mg + O₂) يساوي كتلة الناتج.', '["لم تُستحدث مادة من العدم؛ الزيادة مصدرها الأكسجين.","الحرق لا يغير كتلة الذرات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-10-11T11:15:01.803Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1476, 0, 'في التجربة الثالثة كتلة ما تبقى بعد التفاعل (12.0 g) أقل من كتلة المتفاعلات (15.0 g)، والفرق (3.0 g) يمثل غازًا تصاعد ولم يُحتسب، فالكتلة محفوظة فعليًا لو جُمع الغاز.', '["","الكتلتان متساويتان (36.0 g)، فلا يوجد ما يدل على ضياع غاز.","الكتلتان متساويتان (20.0 g)، فلا يوجد ما يدل على ضياع غاز."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T11:15:01.804Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1477, 1, 'قانون حفظ الكتلة ينص على تساوي الكتل لا المولات؛ وهنا 28.0 + 6.0 = 34.0 g في الطرفين رغم اختلاف عدد المولات.', '["القانون ينطبق على جميع التفاعلات الكيميائية بما فيها تفاعلات الغازات.","","المعادلة موزونة (2 N و6 H في كل طرف)، واختلاف عدد المولات لا يعني عدم الوزن."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T11:15:01.804Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1478, null, null, null, 'نص القانون: المادة لا تفنى ولا تُستحدث في التفاعل الكيميائي، أي أن مجموع كتل المتفاعلات يساوي مجموع كتل النواتج. التفسير: في التفاعل يُعاد ترتيب الذرات فقط؛ ففي المتفاعلات 4 ذرات H وذرتا O، وفي النواتج 4 ذرات H وذرتا O أيضًا. وبالكتل: 2(2.0) + 32.0 = 36.0 g من المتفاعلات تنتج 2(18.0) = 36.0 g من الماء.', '["نص القانون","إعادة ترتيب الذرات دون فقد أو تكوّن","عدّ الذرات في الطرفين","التحقق بالكتل 36.0 g = 36.0 g"]'::jsonb, '[]'::jsonb, '[{"element":"نص القانون","marks":1},{"element":"التفسير الذري","marks":1},{"element":"عدّ الذرات","marks":1},{"element":"التحقق بالكتل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"نص صحيح وتفسير كامل مع العدّ والكتل"},{"level":"3 درجات","description":"نقص عنصر واحد"},{"level":"2 درجتان","description":"نص القانون مع تفسير ناقص"},{"level":"1 درجة","description":"نص القانون فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["الخلط بين حفظ الكتلة وحفظ عدد الجزيئات","عدّ ذرات الأكسجين في 2H₂O ذرة واحدة","ذكر أن الذرات تتحول إلى ذرات أخرى"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T11:15:01.804Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.')
