(1479, null, null, null, '(أ) وفق قانون حفظ الكتلة: كتلة Mg + كتلة O₂ = كتلة MgO، فكتلة O₂ = 4.0 − 2.4 = 1.6 g. (ب) لأن المغنيسيوم اتحد بأكسجين الهواء، فكتلة الناتج تشمل كتلة المغنيسيوم وكتلة الأكسجين معًا؛ ومجموع كتل المتفاعلات (2.4 + 1.6 = 4.0 g) يساوي كتلة الناتج، فلم تُستحدث مادة.', '["تطبيق قانون حفظ الكتلة","كتلة O₂ = 1.6 g","التفسير باتحاد الأكسجين","التحقق: 2.4 + 1.6 = 4.0 g"]'::jsonb, '["كتلة O₂ = كتلة MgO − كتلة Mg","= 4.0 − 2.4 = 1.6 g"]'::jsonb, '[{"element":"كتلة الأكسجين","marks":2},{"element":"التفسير","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"حساب وتفسير صحيحان"},{"level":"2 درجتان","description":"الحساب صحيح والتفسير ناقص"},{"level":"1 درجة","description":"التفسير فقط أو كتابة العلاقة دون ناتج"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["جمع الكتلتين (6.4 g)","إهمال الأكسجين والقول إن الزيادة غير مفسرة","الاعتقاد بأن الحرق يزيد كتلة ذرات المغنيسيوم"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-10-11T11:15:01.805Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1480, null, null, null, 'في الدورق المغلق بقيت الكتلة ثابتة (120.0 g) لأن غاز CO₂ الناتج حُجز في البالون، فهو يمثل القانون مباشرة. في الدورق المفتوح نقصت الكتلة 1.1 g لأن غاز CO₂ تصاعد إلى الهواء ولم يُحتسب؛ وهذا لا يعني فناء المادة، فلو جُمع الغاز لكانت كتلة النواتج 120.0 g. إذن الكتلة محفوظة في الحالتين، والفرق ناتج عن طريقة القياس.', '["الدورق المغلق يمثل القانون مباشرة","تعليل ثبات الكتلة بحجز الغاز","النقص 1.1 g هو كتلة CO₂ المتصاعد","الكتلة محفوظة فعليًا في الحالتين"]'::jsonb, '[]'::jsonb, '[{"element":"تحليل التجربة المغلقة","marks":1},{"element":"تحليل التجربة المفتوحة وحساب النقص","marks":2},{"element":"الاستنتاج العام","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحليل كامل للتجربتين مع الاستنتاج"},{"level":"3 درجات","description":"تحليل صحيح دون حساب النقص أو دون الاستنتاج العام"},{"level":"2 درجتان","description":"تفسير إحدى التجربتين فقط"},{"level":"1 درجة","description":"إجابة جزئية صحيحة"},{"level":"صفر","description":"لا إجابة أو القول إن القانون لا ينطبق"}]'::jsonb, '["القول إن التجربة المفتوحة تثبت عدم صحة القانون","إغفال أن الغاز له كتلة","الخلط بين نقص الكتلة وتبخر الماء"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T11:15:01.805Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1481, 2, 'كتلة النواتج = 2 × 58.5 = 117.0 g، وتساوي كتلة المتفاعلات 2(23.0) + 71.0 = 117.0 g.', '["هذه كتلة 1 mol فقط من NaCl، ونُسي المعامل 2.","ناتج 23.0 + 71.0 بإهمال المعامل 2 أمام Na، وهي كتلة لا تساوي كتلة النواتج.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-10-11T11:15:01.810Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1482, 1, 'كتلة النواتج = 1(44.0) + 2(18.0) = 80.0 g، وتساوي كتلة المتفاعلات 1(16.0) + 2(32.0) = 80.0 g، فالكتلة محفوظة.', '["ناتج 44.0 + 18.0 بإهمال المعامل 2 أمام H₂O.","","ضُرب CO₂ في 2 خطأً (2 × 44.0 + 2 × 18.0)، ومعامل CO₂ هو 1."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T11:15:01.811Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1483, 0, 'وفق قانون حفظ الكتلة: 100.0 = 56.0 + كتلة CO₂ ، فكتلة CO₂ = 44.0 g (وتطابق الكتلة المولية لـ CO₂: 12.0 + 32.0 = 44.0 g/mol).', '["","جُمعت كتلتا CaCO₃ وCaO بدل الطرح.","افتُرض أن النواتج متساوية الكتلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T11:15:01.811Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1484, 2, 'المعادلة غير موزونة (ذرتا أكسجين في المتفاعلات وذرة واحدة في الناتج). بعد وزنها 2H₂ + O₂ → 2H₂O تصبح الكتلتان 36.0 g = 36.0 g.', '["القانون ينطبق على كل التفاعلات الكيميائية بما فيها تفاعلات الغازات.","كتلة الناتج يجب أن تساوي كتل المتفاعلات مهما كانت حالته الفيزيائية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:01.812Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1485, 1, 'كتلة 3 mol O₂ = 3 × 32.0 = 96.0 g. وللتحقق: كتلة 2 mol KClO₃ = 2 × 122.5 = 245.0 g، وكتلة النواتج = 2 × 74.5 + 96.0 = 245.0 g.', '["هذه كتلة 1 mol من O₂، ونُسي المعامل 3.","","استُخدمت الكتلة الذرية للأكسجين (16.0) بدل الكتلة المولية لـ O₂ (3 × 16.0)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-10-11T11:15:01.812Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1486, 0, 'يجب ضرب الكتلة المولية في المعامل: 28.0 + 3(2.0) = 34.0 g للمتفاعلات، و2(17.0) = 34.0 g للناتج، فالكتلة محفوظة.', '["","الكتلة المولية لـ N₂ = 2 × 14.0 = 28.0 g/mol صحيحة.","المعادلة موزونة (2 N و6 H في كل طرف)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-11T11:15:01.813Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1487, 1, 'المتفاعلات: 36.5 + 56.0 = 92.5 g، والنواتج: 74.5 + 18.0 = 92.5 g، فالكتلتان متساويتان تحقيقًا للقانون.', '["نُسيت كتلة الماء (18.0 g) من النواتج.","","احتُسبت كتلة KOH وحده دون HCl."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-11T11:15:01.813Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1488, null, null, null, 'الكتل المولية: N₂ = 2(14.0) = 28.0 g/mol ، H₂ = 2(1.0) = 2.0 g/mol ، NH₃ = 14.0 + 3(1.0) = 17.0 g/mol. كتلة المتفاعلات = 1(28.0) + 3(2.0) = 34.0 g. كتلة النواتج = 2(17.0) = 34.0 g. بما أن كتلة المتفاعلات = كتلة النواتج = 34.0 g فقانون حفظ الكتلة متحقق.', '["حساب الكتل المولية الثلاث","ضرب كل كتلة مولية في معاملها","كتلة المتفاعلات 34.0 g","كتلة النواتج 34.0 g","الاستنتاج"]'::jsonb, '["M(N₂) = 28.0 ، M(H₂) = 2.0 ، M(NH₃) = 17.0 g/mol","المتفاعلات: 28.0 + 3 × 2.0 = 34.0 g","النواتج: 2 × 17.0 = 34.0 g","34.0 g = 34.0 g ← الكتلة محفوظة"]'::jsonb, '[{"element":"الكتل المولية","marks":1},{"element":"كتلة المتفاعلات","marks":1},{"element":"كتلة النواتج","marks":1},{"element":"الاستنتاج","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حل كامل صحيح"},{"level":"3 درجات","description":"خطأ في عنصر واحد"},{"level":"2 درجتان","description":"الكتل المولية وطرف واحد صحيح"},{"level":"1 درجة","description":"الكتل المولية فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["إهمال المعاملات","استخدام 1.0 g/mol لجزيء H₂","الاستنتاج دون حساب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-11T11:15:01.813Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1489, null, null, null, 'الكتل المولية: C₂H₆ = 30.0 ، O₂ = 32.0 ، CO₂ = 44.0 ، H₂O = 18.0 g/mol. المتفاعلات: 2(30.0) + 7(32.0) = 60.0 + 224 = 284 g. النواتج: 4(44.0) + 6(18.0) = 176 + 108 = 284 g. الكتلتان متساويتان (284 g)، فالقانون متحقق.', '["الكتل المولية الأربع","كتلة المتفاعلات 284 g","كتلة النواتج 284 g","الاستنتاج"]'::jsonb, '["M(C₂H₆) = 2(12.0) + 6(1.0) = 30.0 g/mol","المتفاعلات: 2 × 30.0 + 7 × 32.0 = 284 g","النواتج: 4 × 44.0 + 6 × 18.0 = 284 g","284 g = 284 g"]'::jsonb, '[{"element":"الكتل المولية","marks":1},{"element":"كتلة المتفاعلات","marks":1},{"element":"كتلة النواتج","marks":1},{"element":"الاستنتاج","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حل كامل صحيح"},{"level":"3 درجات","description":"خطأ حسابي بسيط مع منهجية صحيحة"},{"level":"2 درجتان","description":"حساب طرف واحد صحيح"},{"level":"1 درجة","description":"الكتل المولية فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["نسيان ضرب كتلة O₂ في 7","الخطأ في الكتلة المولية للإيثان","جمع المعاملات بدل ضربها في الكتل المولية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T11:15:01.814Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1490, null, null, null, '(أ) 4Al + 3O₂ → 2Al₂O₃. (ب) M(Al₂O₃) = 2(27.0) + 3(16.0) = 102.0 g/mol. المتفاعلات: 4(27.0) + 3(32.0) = 108 + 96.0 = 204 g. النواتج: 2(102.0) = 204 g، فالكتلة محفوظة. (ج) بالمعادلة غير الموزونة: المتفاعلات 27.0 + 32.0 = 59.0 g والناتج 102.0 g، فتبدو الكتلة غير محفوظة؛ لأن عدد الذرات غير متساوٍ في الطرفين، ولذلك يجب وزن المعادلة قبل التحقق.', '["المعادلة الموزونة 4Al + 3O₂ → 2Al₂O₃","كتلة المتفاعلات 204 g","كتلة النواتج 204 g","توضيح عدم التساوي في المعادلة غير الموزونة وسببه"]'::jsonb, '["الوزن: 4Al + 3O₂ → 2Al₂O₃","المتفاعلات: 4 × 27.0 + 3 × 32.0 = 204 g","النواتج: 2 × 102.0 = 204 g","غير الموزونة: 59.0 g ≠ 102.0 g"]'::jsonb, '[{"element":"وزن المعادلة","marks":1},{"element":"حساب الكتل والتحقق","marks":2},{"element":"التوضيح في (ج)","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة"},{"level":"4 درجات","description":"الوزن والتحقق صحيحان مع توضيح ناقص"},{"level":"3 درجات","description":"الوزن والتحقق فقط"},{"level":"1–2 درجة","description":"الوزن فقط أو تحقق جزئي"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["وزن المعادلة بتغيير الأرقام السفلية (مثل AlO₂)","استخدام 16.0 g/mol لـ O₂","عدم إدراك أن الخلل في (ج) سببه عدم تساوي الذرات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:01.814Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1491, 1, 'النسبة المولية هي نسبة بين عدد المولات لأي مادتين في معادلة كيميائية موزونة، وتؤخذ من المعاملات.', '["كتلة المادة ÷ كتلتها المولية تعطي عدد مولاتها، لا النسبة المولية بين مادتين.","","هذا وصف لنسب الذرات في الصيغة الكيميائية، لا للنسبة المولية بين مواد التفاعل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T11:15:01.816Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1492, 0, 'تؤخذ النسبة المولية من المعاملات: معامل Al هو 4 ومعامل Al₂O₃ هو 2، فالنسبة 4 : 2 (أي 2 : 1).', '["","هذه نسبة Al₂O₃ إلى Al (معكوسة).","هذه نسبة Al إلى O₂ لا إلى Al₂O₃."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-10-11T11:15:01.817Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1493, 2, 'عدد المواد n = 4، وعدد النسب المولية = n(n − 1) = 4 × 3 = 12.', '["هذا عدد النسب لمعادلة فيها ثلاث مواد فقط (3 × 2).","حُسب n² = 16 بدل n(n − 1).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-11T11:15:01.817Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1494, 1, 'معامل Fe هو 3 ومعامل Fe₃O₄ هو 1، فالنسبة المولية Fe : Fe₃O₄ = 3 : 1. (الرقم السفلي 3 في Fe₃O₄ لا يدخل في النسبة المولية.)', '["هذه النسبة معكوسة (Fe₃O₄ : Fe).","","هذه نسبة Fe إلى H₂O أو إلى H₂، لا إلى Fe₃O₄."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-10-11T11:15:01.817Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1495, 2, 'معاملا HgO وHg متساويان (2 و2)، فالنسبة بينهما 2 : 2 أي 1 : 1، فالنسبة 1 mol HgO / 2 mol Hg غير صحيحة. أما النسبتان الأخريان فمأخوذتان من المعاملات مباشرة.', '["نسبة صحيحة: معامل HgO = 2 ومعامل O₂ = 1.","نسبة صحيحة: معامل Hg = 2 ومعامل O₂ = 1.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-10-11T11:15:01.817Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1496, 0, 'المواد ثلاث، فعدد النسب 3 × 2 = 6. الموجود في الجدول خمس نسب، والناقصة مقلوب النسبة (1 mol Br₂ / 2 mol KBr) وهي 2 mol KBr / 1 mol Br₂.', '["","معاملا KBr وBr₂ هما 2 و1 على الترتيب، فهذه النسبة مقلوبة الأرقام.","معامل Br₂ هو 1 ومعامل K هو 2، فهذه النسبة خاطئة الأرقام."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T11:15:01.818Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1497, 2, 'معامل O₂ هو 3 ومعامل Fe هو 4، فالنسبة O₂ : Fe = 3 : 4.', '["هذه النسبة معكوسة (Fe : O₂).","استُخدم الرقم السفلي 2 في O₂ بدل المعامل 3.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-10-11T11:15:01.818Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1498, null, null, null, 'المواد ثلاث (n = 3)، فعدد النسب = 3 × 2 = 6، وهي: 4 mol Fe / 3 mol O₂ ، 3 mol O₂ / 4 mol Fe ، 4 mol Fe / 2 mol Fe₂O₃ ، 2 mol Fe₂O₃ / 4 mol Fe ، 3 mol O₂ / 2 mol Fe₂O₃ ، 2 mol Fe₂O₃ / 3 mol O₂.', '["عدد النسب 6 بالعلاقة n(n − 1)","النسب بين Fe وO₂ (نسبتان)","النسب بين Fe وFe₂O₃ (نسبتان)","النسب بين O₂ وFe₂O₃ (نسبتان)"]'::jsonb, '["n = 3","عدد النسب = 3 × (3 − 1) = 6","كتابة كل زوج من المواد ومقلوبه"]'::jsonb, '[{"element":"حساب عدد النسب","marks":1},{"element":"كتابة النسب الست (نصف درجة لكل نسبة)","marks":3}]'::jsonb, '[{"level":"4 درجات","description":"العدد صحيح والنسب الست صحيحة"},{"level":"3 درجات","description":"العدد صحيح وأربع أو خمس نسب صحيحة"},{"level":"2 درجتان","description":"العدد صحيح ونسبتان أو ثلاث صحيحة"},{"level":"1 درجة","description":"العدد فقط أو نسبتان"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["استخدام الأرقام السفلية بدل المعاملات","نسيان مقلوب كل نسبة","حساب العدد n² = 9"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-11T11:15:01.818Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1499, null, null, null, '(أ) n = 4 مواد، فعدد النسب = 4 × 3 = 12. (ب) النسب التي يدخل فيها O₂ (ست نسب): 2 mol O₂ / 1 mol CH₄ ، 1 mol CH₄ / 2 mol O₂ ، 2 mol O₂ / 1 mol CO₂ ، 1 mol CO₂ / 2 mol O₂ ، 2 mol O₂ / 2 mol H₂O ، 2 mol H₂O / 2 mol O₂.', '["عدد النسب 12","نسبتا O₂ مع CH₄","نسبتا O₂ مع CO₂","نسبتا O₂ مع H₂O"]'::jsonb, '["n = 4 ← 4 × 3 = 12","O₂ مع كل مادة من المواد الثلاث الأخرى في الاتجاهين ← 6 نسب"]'::jsonb, '[{"element":"عدد النسب","marks":1},{"element":"النسب التي يدخل فيها O₂","marks":3}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة"},{"level":"3 درجات","description":"العدد صحيح وأربع أو خمس نسب صحيحة"},{"level":"2 درجتان","description":"العدد صحيح ونسبتان أو ثلاث"},{"level":"1 درجة","description":"العدد فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["حساب العدد 6 بإهمال إحدى المواد","كتابة 1 mol O₂ بدل 2 mol O₂","اختصار 2 : 2 إلى نسبة خاطئة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-11T11:15:01.819Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1500, null, null, null, '(أ) النسبة المناسبة: 2 mol NH₃ / 3 mol H₂؛ لأن المادة المجهولة (NH₃) توضع في البسط والمعلومة (H₂) في المقام، فتُختصر وحدة H₂. (ب) n(NH₃) = 6.0 mol H₂ × (2 mol NH₃ / 3 mol H₂) = 4.0 mol NH₃. (ج) لو استُخدمت 3 mol H₂ / 2 mol NH₃ لكان الناتج 9.0 بوحدة لا معنى لها (mol² H₂/mol NH₃)، وهو خطأ.', '["النسبة 2 mol NH₃ / 3 mol H₂","تعليل الاختيار: المجهول في البسط والمعلوم في المقام","الناتج 4.0 mol NH₃","توضيح خطأ النسبة المقلوبة"]'::jsonb, '["النسبة: 2 mol NH₃ / 3 mol H₂","6.0 × 2 ÷ 3 = 4.0 mol NH₃","النسبة المقلوبة: 6.0 × 3 ÷ 2 = 9.0 (وحدات غير متجانسة)"]'::jsonb, '[{"element":"النسبة والتعليل","marks":2},{"element":"الحساب","marks":1},{"element":"تحليل الخطأ","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة"},{"level":"3 درجات","description":"النسبة والحساب صحيحان مع تحليل ناقص"},{"level":"2 درجتان","description":"النسبة صحيحة دون تعليل مع حساب صحيح"},{"level":"1 درجة","description":"النسبة فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["قلب النسبة","استخدام نسبة N₂ : NH₃ بدل H₂ : NH₃","عدم كتابة الوحدات لمتابعة الاختصار"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T11:15:01.820Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1501, 0, 'مولات المجهول = مولات المعلوم × (معامل المجهول ÷ معامل المعلوم)، فتُختصر وحدة المادة المعلومة ويبقى المجهول.', '["","هذه النسبة مقلوبة، فلا تُختصر وحدة المادة المعلومة وينتج رقم خاطئ.","الضرب في الكتلة المولية يحوّل المولات إلى كتلة، لا إلى مولات مادة أخرى."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-11T11:15:01.822Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
