(1519, null, null, null, 'n(Fe) = 2.50 × (2/1) = 5.00 mol ، m(Fe) = 5.00 × 56.0 = 2.80×10² g. n(CO₂) = 2.50 × (3/1) = 7.50 mol ، m(CO₂) = 7.50 × 44.0 = 3.30×10² g.', '["النسبة 2 : 1 لإيجاد مولات Fe","كتلة Fe = 2.80×10² g","النسبة 3 : 1 لإيجاد مولات CO₂","كتلة CO₂ = 3.30×10² g"]'::jsonb, '["n(Fe) = 5.00 mol","m(Fe) = 5.00 × 56.0 = 280 g = 2.80×10² g","n(CO₂) = 7.50 mol","m(CO₂) = 7.50 × 44.0 = 330 g = 3.30×10² g"]'::jsonb, '[{"element":"مولات Fe وكتلته","marks":2},{"element":"مولات CO₂ وكتلته","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"حل كامل صحيح"},{"level":"3 درجات","description":"خطأ في جزئية واحدة"},{"level":"2 درجتان","description":"حساب الحديد فقط أو CO₂ فقط"},{"level":"1 درجة","description":"حساب المولات دون الكتل"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["افتراض نسبة 1 : 1","استخدام 28.0 g/mol (CO) بدل 44.0 g/mol (CO₂)","نسيان التحويل من مولات إلى كتلة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T11:15:01.831Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1520, null, null, null, 'حل الطالب خطأ؛ لأنه ضرب مولات O₂ مباشرة في الكتلة المولية للماء، أي أهمل النسبة المولية بين O₂ وH₂O (1 : 2). الحل الصحيح: n(H₂O) = 1.5 mol O₂ × (2 mol H₂O / 1 mol O₂) = 3.0 mol ، m(H₂O) = 3.0 × 18.0 = 54 g.', '["الحكم بالخطأ مع تحديد السبب (إهمال النسبة المولية)","تحويل مولات O₂ إلى مولات H₂O = 3.0 mol","ضرب المولات في 18.0 g/mol","الناتج 54 g"]'::jsonb, '["n(H₂O) = 1.5 × 2 ÷ 1 = 3.0 mol","m(H₂O) = 3.0 × 18.0 = 54 g"]'::jsonb, '[{"element":"تحديد الخطأ","marks":1},{"element":"مولات الماء","marks":1},{"element":"كتلة الماء","marks":1},{"element":"الوحدات والأرقام المعنوية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تقويم صحيح وحل كامل"},{"level":"3 درجات","description":"حل صحيح دون تحديد واضح للخطأ"},{"level":"2 درجتان","description":"تحديد الخطأ مع حل ناقص"},{"level":"1 درجة","description":"تحديد الخطأ فقط"},{"level":"صفر","description":"لا إجابة أو تأييد حل الطالب"}]'::jsonb, '["تأييد حل الطالب","استخدام النسبة المقلوبة (1/2)","الخلط بين الكتلة المولية لـ H₂O وO₂"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-11T11:15:01.831Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1521, 0, 'المادة المحددة هي المادة التي تُستهلك تمامًا في التفاعل، فتحدد سير التفاعل وكمية المواد الناتجة.', '["","هذا تعريف المادة الفائضة لا المحددة.","الكتلة المولية لا تحدد أي المتفاعلات ينفد أولًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-11T11:15:01.834Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1522, 1, 'الخبز يكفي لـ 10 ÷ 2 = 5 شطائر، والجبن يكفي لـ 3 ÷ 1 = 3 شطائر فقط؛ فالجبن ينفد أولًا ويحدد عدد الشطائر (3)، فهو المحدد.', '["الخبز يكفي لخمس شطائر فيتبقى منه 4 شرائح، فهو «الفائض».","","الكميتان لا تتناسبان مع نسبة الوصفة (2 : 1)، فلا بد من وجود مكوّن ينفد أولًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T11:15:01.834Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1523, 2, 'نقسم عدد مولات كل متفاعل المتوافر على معامله في المعادلة الموزونة، والمتفاعل الذي يعطي أصغر ناتج هو المادة المحددة.', '["الكتلة وحدها لا تكفي؛ يجب التحويل إلى مولات ومراعاة النسبة المولية.","المعامل وحده لا يحدد المادة المحددة دون مقارنته بالكمية المتوافرة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-11T11:15:01.834Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1524, 0, 'N₂: 2.0 ÷ 1 = 2.0 ، H₂: 3.0 ÷ 3 = 1.0 ؛ الأصغر لـ H₂ فهو المادة المحددة رغم أن عدد مولاته أكبر.', '["","عدد المولات الأقل لا يعني بالضرورة أن المادة محددة؛ يجب القسمة على المعاملات.","وجود مادة محددة لا يعتمد على تقارب الكميات بل على النسبة المولية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-10-11T11:15:01.834Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1525, 1, 'المادة المحددة تُستهلك تمامًا، فلا يتكون مزيد من الناتج بعد نفادها، ولذلك تحدد كمية المواد الناتجة.', '["اللون خاصية للمادة الناتجة نفسها ولا تحدده الكمية.","","الحالة الفيزيائية للناتج لا تعتمد على المادة المحددة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-11T11:15:01.835Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1526, 2, 'في التجربة الأولى: Na: 2.0 ÷ 2 = 1.0 ، Cl₂: 2.0 ÷ 1 = 2.0 ، فالأصغر لـ Na وهو المحدد. في الثانية والثالثة يكون Cl₂ هو المحدد.', '["Na: 4.0 ÷ 2 = 2.0 وCl₂: 1.0 ÷ 1 = 1.0 ، فالمحدد Cl₂.","Na: 6.0 ÷ 2 = 3.0 وCl₂: 2.0 ÷ 1 = 2.0 ، فالمحدد Cl₂.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T11:15:01.835Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1527, 2, 'المادة المحددة تُستهلك تمامًا، فلا يتبقى منها شيء عند توقف التفاعل.', '["هذا وصف المادة الفائضة لا المحددة.","المادة المحددة تتحول إلى نواتج، ولا تتحول إلى «مادة فائضة».",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-11T11:15:01.835Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1528, null, null, null, 'المادة المحددة: المادة التي تُستهلك تمامًا في التفاعل وتحدد سير التفاعل وكمية المواد الناتجة. سُميت محددة لأن التفاعل يتوقف عند نفادها، فهي تحدد (تقيّد) أقصى كمية من الناتج يمكن الحصول عليها. طريقة تحديدها: نقسم عدد مولات كل متفاعل المتوافر على معامله في المعادلة الموزونة، والأصغر ناتجًا هي المادة المحددة.', '["التعريف","سبب التسمية: تحدد كمية الناتج ويتوقف التفاعل بنفادها","طريقة التحديد بقسمة المولات على المعاملات"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"سبب التسمية","marks":1},{"element":"طريقة التحديد","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"العناصر الثلاثة صحيحة"},{"level":"2 درجتان","description":"عنصران صحيحان"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["الخلط بين المادة المحددة والفائضة","القول إن المادة الأقل كتلة هي المحددة","إغفال القسمة على المعاملات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-11T11:15:01.835Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1529, null, null, null, '(أ) P: 8.0 ÷ 4 = 2.0 ، O₂: 8.0 ÷ 5 = 1.6 ؛ الأصغر لـ O₂ فهو المادة المحددة رغم تساوي عدد المولات. (ب) تُحسب كمية الناتج من المادة المحددة: n(P₂O₅) = 8.0 mol O₂ × (2/5) = 3.2 mol.', '["قسمة مولات P على 4 = 2.0","قسمة مولات O₂ على 5 = 1.6","O₂ هي المادة المحددة","حساب P₂O₅ من المادة المحددة = 3.2 mol"]'::jsonb, '["P: 8.0 ÷ 4 = 2.0","O₂: 8.0 ÷ 5 = 1.6 ← O₂ محددة","n(P₂O₅) = 8.0 × 2 ÷ 5 = 3.2 mol"]'::jsonb, '[{"element":"المقارنة بالقسمة على المعاملات","marks":2},{"element":"تحديد المادة المحددة","marks":1},{"element":"حساب الناتج","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحديد صحيح مع حساب الناتج"},{"level":"3 درجات","description":"تحديد صحيح مع خطأ في حساب الناتج"},{"level":"2 درجتان","description":"تحديد صحيح دون توضيح أو حساب"},{"level":"1 درجة","description":"إجراء القسمة دون استنتاج صحيح"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["القول بعدم وجود مادة محددة لتساوي المولات","حساب الناتج من المادة الفائضة (4.0 mol)","القسمة على الأرقام السفلية بدل المعاملات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-10-11T11:15:01.836Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1530, null, null, null, '(أ) H₂: 6 ÷ 2 = 3 ، O₂: 4 ÷ 1 = 4 ؛ الأصغر لـ H₂ فهو المادة المحددة. (ب) 6 جزيئات H₂ تنتج 6 جزيئات H₂O (النسبة 2 : 2). (ج) 6 جزيئات H₂ تستهلك 3 جزيئات O₂، فيتبقى 4 − 3 = 1 جزيء O₂.', '["H₂ هي المادة المحددة مع التعليل","6 جزيئات ماء","يتبقى جزيء واحد من O₂"]'::jsonb, '["H₂: 6 ÷ 2 = 3 ، O₂: 4 ÷ 1 = 4 ← H₂ محددة","H₂O = 6 × (2/2) = 6 جزيئات","O₂ المستهلك = 6 × (1/2) = 3 ← المتبقي 1"]'::jsonb, '[{"element":"تحديد المادة المحددة","marks":1},{"element":"عدد جزيئات الماء","marks":1},{"element":"المادة المتبقية وعددها","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"الأجزاء الثلاثة صحيحة"},{"level":"2 درجتان","description":"جزءان صحيحان"},{"level":"1 درجة","description":"جزء واحد صحيح"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["اختيار O₂ لأن عدد جزيئاته أقل","حساب الماء من O₂ (8 جزيئات)","نسيان أن المتبقي هو المادة الفائضة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T11:15:01.836Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1531, 1, 'المادة الفائضة هي المادة المتفاعلة التي يتبقى منها جزء بعد توقف التفاعل، لأن كميتها أكبر مما يلزم للتفاعل مع المادة المحددة.', '["المادة الفائضة من المتفاعلات لا من النواتج.","","المادة التي تُستهلك أولًا هي المادة المحددة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T11:15:01.839Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1532, 0, 'وجود فائض من أحد المتفاعلات يضمن استمرار التفاعل حتى تُستهلك المادة المحددة كلها، كما يزيد سرعة التفاعل.', '["","كمية الناتج لا تتجاوز ما تسمح به المادة المحددة مهما زاد الفائض.","الفائض لا يقلل كتلة النواتج، والكتلة الكلية محفوظة دائمًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-11T11:15:01.840Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1533, 2, 'H₂: 5.0 ÷ 2 = 2.5 ، O₂: 5.0 ÷ 1 = 5.0 ، فـ H₂ محددة وO₂ فائضة. الـ 5.0 mol من H₂ تستهلك 2.5 mol من O₂، فيتبقى 5.0 − 2.5 = 2.5 mol من O₂.', '["H₂ هي المادة المحددة وتُستهلك تمامًا، فلا يتبقى منها شيء.","هذه الكمية الأصلية من O₂ دون طرح ما استُهلك منها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (55%)"}],"at":"2026-10-11T11:15:01.840Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1534, 0, 'الحمض فائض، فيتبقى جزء منه بعد التفاعل، أما المغنيسيوم فهو المادة المحددة فيُستهلك تمامًا.', '["","المغنيسيوم هو المادة المحددة لأن الحمض فائض، فلا يتبقى منه شيء.","لا يمكن أن يتبقى المتفاعلان معًا؛ التفاعل يستمر حتى نفاد أحدهما."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-11T11:15:01.841Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1535, 1, 'في التجربة الأولى: CH₄: 3.0 ÷ 1 = 3.0 ، O₂: 4.0 ÷ 2 = 2.0 ؛ فـ O₂ محددة وCH₄ فائضة.', '["CH₄: 1.0 ÷ 1 = 1.0 ، O₂: 4.0 ÷ 2 = 2.0 ، فـ CH₄ هي المحددة لا الفائضة.","","CH₄: 2.0 ÷ 1 = 2.0 ، O₂: 4.0 ÷ 2 = 2.0 ، فالكميتان بالنسبة المولية تمامًا ولا توجد مادة فائضة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:01.841Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1536, 1, 'N₂: 3.0 ÷ 1 = 3.0 ، H₂: 6.0 ÷ 3 = 2.0 ، فـ H₂ محددة وN₂ فائضة. 6.0 mol H₂ تستهلك 2.0 mol N₂، فيتبقى 3.0 − 2.0 = 1.0 mol N₂.', '["هذه كمية N₂ المستهلكة لا المتبقية.","","H₂ هي المادة المحددة فلا يتبقى منها شيء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (55%)"}],"at":"2026-10-11T11:15:01.841Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1537, 2, 'كمية الناتج تحددها المادة المحددة، وقد نفدت؛ فإضافة المزيد من المادة الفائضة لا تُنتج ناتجًا جديدًا.', '["المادة المضافة لا تجد ما تتفاعل معه بعد نفاد المادة المحددة.","لا يوجد أي متفاعل آخر متبقٍّ ليُنتج كمية جديدة من الناتج.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-11T11:15:01.842Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1538, null, null, null, 'المادة الفائضة: المادة المتفاعلة التي يتبقى جزء منها بعد توقف التفاعل. أسباب استخدامها: (1) لضمان استمرار التفاعل حتى تُستهلك المادة المحددة كلها. (2) لزيادة سرعة التفاعل.', '["التعريف","السبب الأول: استمرار التفاعل حتى نفاد المحددة","السبب الثاني: زيادة سرعة التفاعل"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"السبب الأول","marks":1},{"element":"السبب الثاني","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"التعريف والسببان صحيحة"},{"level":"2 درجتان","description":"عنصران صحيحان"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["تعريف المادة الفائضة بأنها التي تُستهلك تمامًا","القول إن الفائض يزيد الناتج فوق ما تسمح به المحددة","الخلط بين الفائضة والناتج"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-11T11:15:01.842Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1539, null, null, null, '(أ) M(S₈) = 8 × 32.0 = 256.0 g/mol ← n(S₈) = 80.0 ÷ 256.0 = 0.313 mol (0.3125). M(Cl₂) = 71.0 g/mol ← n(Cl₂) = 71.0 ÷ 71.0 = 1.00 mol. القسمة على المعاملات: S₈: 0.3125 ÷ 1 = 0.313 ، Cl₂: 1.00 ÷ 4 = 0.250 ← Cl₂ محددة وS₈ فائضة. (ب) S₈ المستهلك = 1.00 × (1/4) = 0.250 mol = 0.250 × 256.0 = 64.0 g ، المتبقي = 80.0 − 64.0 = 16.0 g من S₈.', '["تحويل الكتلتين إلى مولات","القسمة على المعاملات وتحديد Cl₂ محددة وS₈ فائضة","مولات S₈ المستهلكة 0.250 mol","كتلة S₈ المتبقية 16.0 g"]'::jsonb, '["n(S₈) = 80.0 ÷ 256.0 = 0.3125 mol","n(Cl₂) = 71.0 ÷ 71.0 = 1.00 mol","S₈: 0.3125 ، Cl₂: 1.00 ÷ 4 = 0.250 ← Cl₂ محددة","S₈ المستهلك = 0.250 mol = 64.0 g","المتبقي = 80.0 − 64.0 = 16.0 g"]'::jsonb, '[{"element":"تحويل الكتل إلى مولات","marks":1},{"element":"تحديد المحددة والفائضة","marks":2},{"element":"حساب الكتلة المتبقية","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"حل كامل صحيح"},{"level":"4 درجات","description":"تحديد صحيح مع خطأ حسابي بسيط في الكتلة المتبقية"},{"level":"3 درجات","description":"تحديد صحيح دون حساب المتبقي"},{"level":"1–2 درجة","description":"تحويل الكتل إلى مولات فقط أو تحديد دون تعليل"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["استخدام 32.0 g/mol لـ S₈ بدل 256.0 g/mol","مقارنة المولات دون القسمة على المعاملات","إعطاء الكتلة المستهلكة (64.0 g) على أنها المتبقية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T11:15:01.842Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1540, null, null, null, 'التجربة 1: H₂: 2.0 ÷ 2 = 1.0 ، O₂: 2.0 ؛ H₂ محددة وO₂ فائضة، يتبقى 2.0 − 1.0 = 1.0 mol O₂. التجربة 2: H₂: 4.0 ÷ 2 = 2.0 = O₂ ؛ الكميتان بالنسبة المولية تمامًا فلا فائض. التجربة 3: O₂ محددة وH₂ فائض، يتبقى 6.0 − 4.0 = 2.0 mol H₂. التجربة 4: O₂ محددة، يتبقى 8.0 − 4.0 = 4.0 mol H₂. ثبتت كمية الماء عند 4.0 mol لأن O₂ (2.0 mol) أصبح المادة المحددة، ولا يكفي إلا لـ 4.0 mol H₂؛ فالزيادة في H₂ تبقى فائضة ولا تزيد الناتج.', '["التجربة 1: O₂ فائض 1.0 mol","التجربة 2: لا فائض","التجربتان 3 و4: H₂ فائض 2.0 mol و4.0 mol","تفسير ثبات الماء بأن O₂ أصبح محددًا"]'::jsonb, '["2.0 mol O₂ يكفي لـ 4.0 mol H₂","المتبقي = الكمية الأصلية − الكمية المستهلكة في كل تجربة"]'::jsonb, '[{"element":"تحديد الفائض والمتبقي في التجارب الأربع","marks":4},{"element":"تفسير ثبات كمية الماء","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"تحليل كامل للتجارب الأربع مع التفسير"},{"level":"4–5 درجات","description":"تحليل صحيح لثلاث تجارب مع التفسير"},{"level":"2–3 درجات","description":"تحليل تجربتين أو التفسير فقط"},{"level":"1 درجة","description":"فكرة صحيحة جزئيًا"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["اعتبار H₂ فائضًا في كل التجارب","عدم ملاحظة أن التجربة الثانية لا فائض فيها","تفسير ثبات الماء بتوقف التفاعل لأسباب أخرى"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-11T11:15:01.843Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1541, 1, 'يتوقف التفاعل عندما تنفد المادة المحددة، حتى لو بقيت كمية من المادة الفائضة.', '["المادة الفائضة يتبقى جزء منها بعد توقف التفاعل، فلا تنفد.","","كتلة المتفاعلات تساوي كتلة النواتج دائمًا وفق قانون حفظ الكتلة، وهذا ليس شرطًا لتوقف التفاعل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T11:15:01.845Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1542, 2, 'بقاء قطع من المغنيسيوم يعني أنه المادة الفائضة، فتوقف التفاعل سببه نفاد HCl، وهو المادة المحددة.', '["المغنيسيوم ما زال موجودًا في الوعاء، فلم ينفد.","المغنيسيوم المتبقي يتفاعل لو أُضيف حمض جديد، فالتوقف سببه نفاد الحمض.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-11T11:15:01.846Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1543, 0, 'الاحتراق يحتاج إلى الأكسجين، والأكسجين داخل الكأس محدود؛ فلما نفد (المادة المحددة) توقف التفاعل وبقي الشمع فائضًا.', '["","الشمع لم ينفد؛ بقي جزء كبير منه، فهو المادة الفائضة.","كتلة الشمع لا تزيد بالاحتراق، والتوقف سببه نفاد الأكسجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T11:15:01.846Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1544, 1, 'H₂: 4 ÷ 2 = 2 ، O₂: 4 ÷ 1 = 4 ، فـ H₂ محددة. 4 mol H₂ تستهلك 2 mol O₂ وتنتج 4 mol H₂O، فيتوقف التفاعل وفي الوعاء 2 mol O₂ (فائض) و4 mol H₂O.', '["H₂ هي المادة المحددة فلا يتبقى منها شيء عند التوقف.","","8 mol من الماء تتطلب 8 mol من H₂، والمتوافر 4 mol فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T11:15:01.847Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1545, 0, 'عند t₂ أصبح عدد مولات B صفرًا (نفدت المادة المحددة)، ولم تتغير الكميات بين t₂ وt₃، فالتفاعل توقف عند t₂ مع بقاء 1.0 mol من A فائضًا.', '["","A لم تنفد؛ بقي منها 1.0 mol عند t₃.","عند t₁ ما زالت المواد تتغير، وتكوّن C لا يوقف التفاعل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:01.847Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1546, 2, 'التفاعل توقف لنفاد المادة المحددة، فإضافة كمية جديدة منها تسمح لها بالتفاعل مع المادة الفائضة المتبقية فيستأنف التفاعل.', '["المادة الفائضة موجودة أصلًا، وإضافة المزيد منها لا تعوض المادة التي نفدت.","الناتج ليس متفاعلًا، فإضافته لا تعيد التفاعل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T11:15:01.847Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1547, 1, 'تُستهلك المادتان معًا عندما تكونان بالنسبة المولية نفسها في المعادلة (2 : 1)؛ و4 mol H₂ و2 mol O₂ تحقق ذلك (4 ÷ 2 = 2 ÷ 1 = 2).', '["4 ÷ 2 = 2 و4 ÷ 1 = 4 ، فيتبقى 2 mol من O₂.","","2 ÷ 2 = 1 و2 ÷ 1 = 2 ، فيتبقى 1 mol من O₂."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T11:15:01.847Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1548, null, null, null, 'يتوقف التفاعل عندما تُستهلك المادة المحددة استهلاكًا تامًا؛ إذ لا يبقى ما يتفاعل مع المادة الأخرى، فتبقى كمية من المادة الفائضة دون تفاعل. مثال: في التفاعل N₂ + 3H₂ → 2NH₃ عند خلط 1.5 mol N₂ مع 3.0 mol H₂، تحتاج 3.0 mol H₂ إلى 1.0 mol N₂ فقط، فيتوقف التفاعل بعد نفاد H₂ (المادة المحددة)، ويبقى 0.5 mol N₂ فائضًا، ويتكون 2.0 mol NH₃.', '["التوقف بسبب نفاد المادة المحددة","بقاء المادة الفائضة لعدم وجود ما تتفاعل معه","مثال صحيح بالأرقام"]'::jsonb, '[]'::jsonb, '[{"element":"التفسير بنفاد المادة المحددة","marks":1},{"element":"تفسير بقاء المادة الفائضة","marks":1},{"element":"المثال","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تفسير كامل مع مثال صحيح"},{"level":"2 درجتان","description":"تفسير صحيح دون مثال أو مثال دون تفسير كافٍ"},{"level":"1 درجة","description":"ذكر المادة المحددة دون ربط بالتوقف"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["القول إن التفاعل يتوقف عند نفاد جميع المتفاعلات","الخلط بين المادة المحددة والفائضة","مثال بأرقام لا تحقق وجود فائض"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T11:15:01.848Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1549, null, null, null, '(أ) Zn: 0.30 ÷ 1 = 0.30 ، HCl: 0.40 ÷ 2 = 0.20 ؛ فـ HCl هي المادة المحددة. (ب) توقف تصاعد H₂ لأن HCl (المادة المحددة) نفد، فلم يبقَ حمض يتفاعل مع الخارصين المتبقي (الفائض). (ج) Zn المستهلك = 0.40 × (1/2) = 0.20 mol ، المتبقي = 0.30 − 0.20 = 0.10 mol. H₂ الناتج = 0.40 × (1/2) = 0.20 mol.', '["HCl هي المادة المحددة","التفسير بنفاد HCl","Zn المتبقي 0.10 mol","H₂ الناتج 0.20 mol"]'::jsonb, '["Zn: 0.30 ÷ 1 = 0.30 ، HCl: 0.40 ÷ 2 = 0.20 ← HCl محددة","Zn المستهلك = 0.20 mol ← المتبقي 0.10 mol","n(H₂) = 0.40 ÷ 2 = 0.20 mol"]'::jsonb, '[{"element":"تحديد المادة المحددة","marks":1},{"element":"تفسير توقف التفاعل","marks":1},{"element":"مولات Zn المتبقية","marks":1},{"element":"مولات H₂","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الأجزاء كلها صحيحة"},{"level":"3 درجات","description":"خطأ في جزء واحد"},{"level":"2 درجتان","description":"تحديد المحددة والتفسير فقط"},{"level":"1 درجة","description":"تحديد المحددة فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["اختيار Zn محددًا لأن مولاته أقل","حساب H₂ من Zn (0.30 mol)","إهمال المعامل 2 أمام HCl"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-11T11:15:01.848Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1550, null, null, null, 'كمية HCl (0.050 mol) تكفي للتفاعل مع 0.050 ÷ 2 = 0.025 mol من Mg فقط. في التجربتين الأولى والثانية (Mg = 0.010 و0.020 mol) يكون Mg هو المادة المحددة، فيتوقف التفاعل عند نفاده وتساوي مولات H₂ مولات Mg. في التجربتين الثالثة والرابعة يصبح HCl هو المادة المحددة، فيتوقف التفاعل عند نفاده بعد إنتاج 0.050 ÷ 2 = 0.025 mol من H₂، ويبقى المغنيسيوم الزائد فائضًا؛ لذا لا تزيد كمية H₂ عن 0.025 mol مهما زاد Mg.', '["HCl يكفي لـ 0.025 mol Mg","Mg محدد في التجربتين الأولى والثانية","HCl محدد في الثالثة والرابعة","تفسير ثبات H₂ عند 0.025 mol بنفاد HCl"]'::jsonb, '["Mg اللازم لـ 0.050 mol HCl = 0.050 ÷ 2 = 0.025 mol","أقصى H₂ = 0.050 ÷ 2 = 0.025 mol"]'::jsonb, '[{"element":"حساب الكمية التي يكفيها HCl","marks":1},{"element":"تحديد المادة المحددة في التجارب","marks":2},{"element":"تفسير ثبات كمية H₂","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"تحليل كامل صحيح"},{"level":"4 درجات","description":"تحديد صحيح مع تفسير ناقص"},{"level":"3 درجات","description":"تفسير الثبات دون تحديد تفصيلي"},{"level":"1–2 درجة","description":"فكرة صحيحة جزئيًا"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["القول إن Mg هو المحدد في كل التجارب","إهمال المعامل 2 أمام HCl (الظن بأن H₂ يصل إلى 0.050 mol)","تفسير الثبات بخطأ في القياس"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T11:15:01.849Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1551, 1, 'Fe: 6.0 ÷ 4 = 1.5 ، O₂: 6.0 ÷ 3 = 2.0 ؛ الأصغر لـ Fe فهو المحدد وO₂ فائض.', '["عُكست المقارنة؛ ناتج القسمة لـ O₂ (2.0) أكبر من ناتج Fe (1.5).","","تساوي المولات لا يعني عدم وجود فائض؛ فالمعاملات مختلفة (4 و3)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (53%)"}],"at":"2026-10-11T11:15:01.851Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1552, 2, 'n(CH₄) = 16.0 ÷ 16.0 = 1.00 mol ← 1.00 ÷ 1 = 1.00 ، n(O₂) = 48.0 ÷ 32.0 = 1.50 mol ← 1.50 ÷ 2 = 0.750 ؛ الأصغر لـ O₂ فهو المحدد رغم أن كتلته أكبر.', '["الكتلة الأقل لا تعني أن المادة محددة؛ يجب التحويل إلى مولات والقسمة على المعاملات.","الكميتان لا تتناسبان مع النسبة المولية (1 : 2)، فلا بد من مادة محددة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T11:15:01.851Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1553, 0, 'Al: 0.40 ÷ 2 = 0.20 ، Cl₂: 0.45 ÷ 3 = 0.15 ؛ فـ Cl₂ محددة وAl فائض. Al المستهلك = 0.45 × (2/3) = 0.30 mol، والمتبقي = 0.40 − 0.30 = 0.10 mol.', '["","Cl₂ هي المادة المحددة فلا يتبقى منها شيء.","استُخدمت نسبة 1 : 1 فطُرحت 0.15 mol من 0.40 mol."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T11:15:01.852Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1554, 1, 'n(N₂) = 56.0 ÷ 28.0 = 2.00 mol ← 2.00 ÷ 1 = 2.00 ، n(H₂) = 9.0 ÷ 2.0 = 4.5 mol ← 4.5 ÷ 3 = 1.5 ؛ الأصغر لـ H₂ فهو المحدد.', '["المقارنة خاطئة: 1.5 (لـ H₂) أصغر من 2.00 (لـ N₂).","","الكتلة وحدها لا تحدد المادة المحددة؛ تُقارن نواتج قسمة المولات على المعاملات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:01.852Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1555, 2, 'H₂: 3.0 ÷ 2 = 1.5 ، O₂: 2.0 ÷ 1 = 2.0 ؛ فـ H₂ محددة، وكمية الماء تُحسب منها: 3.0 × (2/2) = 3.0 mol.', '["حُسب الماء من O₂ (المادة الفائضة): 2.0 × 2 = 4.0 mol.","جُمعت مولات المتفاعلين، وهذا لا يمثل الناتج.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-11T11:15:01.852Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1556, 0, 'P: 20 ÷ 4 = 5 ، O₂: 20 ÷ 5 = 4 ؛ الأصغر لـ O₂ فهي المادة المحددة وP فائضة.', '["","تساوي المولات لا يكفي؛ المعاملات مختلفة فتختلف الحاجة إلى كل مادة.","المعامل الأصغر يعني أن المادة يلزم منها كمية أقل، فهي الأقرب لأن تكون فائضة لا محددة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (53%)"}],"at":"2026-10-11T11:15:01.853Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1557, 1, 'Fe₂O₃: 1.0 ÷ 1 = 1.0 ، CO: 2.4 ÷ 3 = 0.80 ؛ فـ CO محددة. n(Fe) = 2.4 × (2/3) = 1.6 mol.', '["Fe₂O₃ هي المادة الفائضة، وحساب الناتج منها يعطي كمية أكبر من الممكن.","","افتُرضت نسبة 1 : 1 بين CO وFe."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T11:15:01.853Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1558, null, null, null, '(أ) n(Fe) = 14.0 ÷ 56.0 = 0.250 mol ← 0.250 ÷ 2 = 0.125. n(Cl₂) = 21.3 ÷ 71.0 = 0.300 mol ← 0.300 ÷ 3 = 0.100. الأصغر لـ Cl₂ فهو المحدد، وFe فائض. (ب) n(FeCl₃) = 0.300 × (2/3) = 0.200 mol ، M(FeCl₃) = 56.0 + 3(35.5) = 162.5 g/mol ، m = 0.200 × 162.5 = 32.5 g. (ج) Fe المستهلك = 0.300 × (2/3) = 0.200 mol = 0.200 × 56.0 = 11.2 g ، المتبقي = 14.0 − 11.2 = 2.8 g.', '["تحويل الكتلتين إلى مولات","تحديد Cl₂ محددة وFe فائضة","كتلة FeCl₃ = 32.5 g","كتلة Fe المتبقية = 2.8 g"]'::jsonb, '["n(Fe) = 0.250 mol ، n(Cl₂) = 0.300 mol","Fe: 0.125 ، Cl₂: 0.100 ← Cl₂ محددة","n(FeCl₃) = 0.200 mol ← 32.5 g","Fe المستهلك = 11.2 g ← المتبقي 2.8 g"]'::jsonb, '[{"element":"تحويل الكتل إلى مولات","marks":1},{"element":"تحديد المحددة والفائضة","marks":1},{"element":"كتلة FeCl₃","marks":2},{"element":"كتلة الفائض المتبقي","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"حل كامل صحيح"},{"level":"4–5 درجات","description":"خطأ في جزء واحد"},{"level":"2–3 درجات","description":"تحديد المادة المحددة صحيح مع خطأ في الحسابات اللاحقة"},{"level":"1 درجة","description":"تحويل الكتل إلى مولات فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["استخدام 35.5 g/mol لـ Cl₂","حساب الناتج من المادة الفائضة","إعطاء الكتلة المستهلكة بدل المتبقية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-11T11:15:01.854Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1559, null, null, null, '(أ) NH₃: 2.0 ÷ 4 = 0.50 ، O₂: 3.0 ÷ 5 = 0.60 ؛ فـ NH₃ محددة وO₂ فائض. (ب) O₂ المستهلك = 2.0 × (5/4) = 2.5 mol ، المتبقي = 3.0 − 2.5 = 0.5 mol. (ج) n(NO) = 2.0 × (4/4) = 2.0 mol ، n(H₂O) = 2.0 × (6/4) = 3.0 mol.', '["NH₃ محددة وO₂ فائض","O₂ المتبقي 0.5 mol","NO = 2.0 mol","H₂O = 3.0 mol"]'::jsonb, '["NH₃: 0.50 ، O₂: 0.60 ← NH₃ محددة","O₂ المستهلك = 2.5 mol ← المتبقي 0.5 mol","NO = 2.0 mol ، H₂O = 3.0 mol"]'::jsonb, '[{"element":"تحديد المحددة والفائضة","marks":1},{"element":"الفائض المتبقي","marks":1},{"element":"مولات NO","marks":1},{"element":"مولات H₂O","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الأجزاء كلها صحيحة"},{"level":"3 درجات","description":"خطأ في جزء واحد"},{"level":"2 درجتان","description":"التحديد وجزء حسابي واحد"},{"level":"1 درجة","description":"التحديد فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["اختيار O₂ محددًا لأن معامله أكبر","حساب النواتج من O₂","قلب النسبة عند حساب O₂ المستهلك"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-11T11:15:01.854Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1560, null, null, null, '(أ) n(H₂) = 4.0 ÷ 2.0 = 2.0 mol ← 2.0 ÷ 2 = 1.0. n(O₂) = 16.0 ÷ 32.0 = 0.50 mol ← 0.50 ÷ 1 = 0.50. الأصغر لـ O₂ فهو المحدد، فقول الطالب خطأ؛ لأن المقارنة تكون بالمولات مقسومة على المعاملات لا بالكتل. (ب) n(H₂O) = 0.50 × 2 = 1.0 mol ← 1.0 × 18.0 = 18 g. H₂ المستهلك = 0.50 × 2 = 1.0 mol، فالمتبقي = 2.0 − 1.0 = 1.0 mol = 2.0 g من H₂.', '["تحويل الكتل إلى مولات","المقارنة بالقسمة على المعاملات وتحديد O₂ محددة","الحكم بخطأ الطالب مع التعليل","كتلة الماء 18 g","كتلة H₂ المتبقية 2.0 g"]'::jsonb, '["n(H₂) = 2.0 mol ، n(O₂) = 0.50 mol","H₂: 1.0 ، O₂: 0.50 ← O₂ محددة","n(H₂O) = 1.0 mol ← 18 g","H₂ المتبقي = 1.0 mol = 2.0 g"]'::jsonb, '[{"element":"التقويم بالحساب والتعليل","marks":2},{"element":"كتلة الماء","marks":1},{"element":"كتلة الفائض المتبقي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تقويم صحيح وحسابات كاملة"},{"level":"3 درجات","description":"تقويم صحيح مع خطأ في أحد الحسابين"},{"level":"2 درجتان","description":"تقويم صحيح دون حسابات (ب)"},{"level":"1 درجة","description":"الحكم بالخطأ دون تعليل حسابي"},{"level":"صفر","description":"لا إجابة أو تأييد الطالب"}]'::jsonb, '["تأييد الطالب بمقارنة الكتل","حساب الماء من H₂ (36 g)","استخدام 1.0 g/mol لـ H₂"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-10-11T11:15:01.854Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1561, 0, 'المردود النظري هو أكبر كمية من الناتج يمكن الحصول عليها من كمية المتفاعل المعطاة، ويُحسب من المعادلة الكيميائية الموزونة.', '["","هذا تعريف المردود الفعلي الذي يُقاس من التجربة لا من الحسابات.","هذه هي المادة الفائضة، ولا علاقة لها بتعريف المردود النظري."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T11:15:01.860Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1562, 2, 'نسبة المردود المئوية هي نسبة المردود الفعلي (من التجربة) إلى المردود النظري (من الحسابات) مضروبة في 100.', '["قلبت النسبة؛ فالمردود النظري في المقام لا في البسط.","التعريف يقارن بين كميتين للمادة الناتجة نفسها لا بين الناتج والمتفاعلات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T11:15:01.860Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1563, 1, 'المردود النظري قيمة محسوبة (من الحسابات الكيميائية) اعتمادًا على كمية المتفاعل والمعادلة الموزونة، بينما المردود الفعلي يُقاس من التجربة.', '["وزن الناتج عمليًا يعطي المردود الفعلي لا النظري.","","هذه علاقة رياضية مشتقة لا تعبر عن مصدر المردود النظري؛ فهو يُحسب أولًا من المعادلة الموزونة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T11:15:01.861Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1564, 2, 'القيمة 20.0 g ناتجة عن الحسابات من المعادلة الموزونة، فهي المردود النظري، أما 17.0 g فهي المردود الفعلي المقيس من التجربة.', '["المردود الفعلي هو ما حصل عليه الطالب من التجربة (17.0 g).","نسبة المردود المئوية نسبة بلا وحدة كتلة، وليست كتلة بالجرام.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:01.861Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1565, 1, 'نسبة المردود المئوية تتعلق بالمادة الناتجة؛ إذ تقارن بين الكمية الفعلية والكمية النظرية للناتج نفسه.', '["المادة الفائضة لا تدخل في حساب نسبة المردود.","","المحفز لا يُستهلك ولا يدخل في تعريف المردود."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T11:15:01.861Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1566, 0, 'نسبة المردود = (الفعلي ÷ النظري) × 100 = (98 ÷ 100) × 100 = 98%.', '["","ناتج قلب النسبة (100 ÷ 98) × 100 تقريبًا؛ ونسبة المردود لا تزيد على 100% في الظروف الصحيحة.","هذه نسبة الفاقد (100 − 98) لا نسبة المردود."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-11T11:15:01.862Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1567, 2, 'المردود النظري هو أكبر كمية ممكنة من الناتج، لذا فالمردود الفعلي يكون أقل منه عادةً (لفقد جزء من الناتج أو عدم اكتمال التفاعل أو حدوث تفاعلات جانبية) ولا يتجاوزه.', '["لا يمكن الحصول على ناتج أكبر من أكبر كمية ممكنة نظريًا؛ وظهور ذلك يدل على خطأ تجريبي كوجود شوائب أو رطوبة.","التساوي حالة مثالية نادرة؛ ففي الواقع يُفقد جزء من الناتج غالبًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T11:15:01.862Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1568, null, null, null, '(أ) المردود النظري: أكبر كمية من الناتج يمكن الحصول عليها من كمية المتفاعل المعطاة، ويُحسب من المعادلة الموزونة. (ب) المردود الفعلي: كمية الناتج التي يُحصل عليها عند إجراء التفاعل عمليًا. (ج) نسبة المردود المئوية: نسبة المردود الفعلي إلى المردود النظري في صورة نسبة مئوية. العلاقة: نسبة المردود المئوية = (المردود الفعلي ÷ المردود النظري) × 100%.', '["تعريف المردود النظري بأنه أكبر كمية ممكنة من الناتج محسوبة","تعريف المردود الفعلي بأنه الكمية الناتجة عمليًا","تعريف نسبة المردود المئوية","كتابة العلاقة (الفعلي ÷ النظري) × 100"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف المردود النظري","marks":1},{"element":"تعريف المردود الفعلي","marks":1},{"element":"تعريف نسبة المردود المئوية","marks":1},{"element":"العلاقة الرياضية الصحيحة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"التعريفات الثلاثة صحيحة والعلاقة صحيحة"},{"level":"3 درجات","description":"خطأ أو نقص في أحد العناصر الأربعة"},{"level":"2 درجتان","description":"عنصران صحيحان فقط"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"لا إجابة أو تعريفات خاطئة"}]'::jsonb, '["الخلط بين المردود النظري والفعلي","قلب العلاقة إلى (النظري ÷ الفعلي) × 100","نسيان الضرب في 100"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T11:15:01.862Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1569, null, null, null, '(أ) المردود النظري يُحصل عليه من الحسابات الكيميائية المبنية على المعادلة الموزونة وكمية المتفاعل المعطاة، أما المردود الفعلي فيُحصل عليه من التجربة بقياس كمية الناتج فعليًا. (ب) المردود النظري أكبر عادةً؛ لأنه يمثل أكبر كمية ممكنة من الناتج، بينما في التجربة قد لا يكتمل التفاعل، أو تحدث تفاعلات جانبية، أو يُفقد جزء من الناتج أثناء الترشيح والنقل.', '["النظري من الحسابات والمعادلة الموزونة","الفعلي من التجربة (القياس العملي)","النظري أكبر عادةً","تعليل بسبب واحد على الأقل (عدم اكتمال التفاعل، تفاعلات جانبية، فقد جزء من الناتج)"]'::jsonb, '[]'::jsonb, '[{"element":"طريقة الحصول على المردود النظري","marks":1},{"element":"طريقة الحصول على المردود الفعلي","marks":1},{"element":"تحديد الأكبر عادةً","marks":1},{"element":"التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة كاملة مع تعليل صحيح"},{"level":"3 درجات","description":"مقارنة صحيحة مع تعليل ناقص"},{"level":"2 درجتان","description":"طريقة الحصول صحيحة فقط أو الأكبر مع التعليل فقط"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"لا إجابة أو مقارنة خاطئة"}]'::jsonb, '["القول إن المردود الفعلي أكبر لأنه «حقيقي»","عكس مصدري المردودين","ذكر الأكبر دون تعليل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T11:15:01.863Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1570, null, null, null, '(أ) المردود النظري = 100 g (من الحسابات)، والمردود الفعلي = 98 g (من التجربة). (ب) نسبة المردود = (98 ÷ 100) × 100 = 98%. (ج) تعني أن كمية الناتج الفعلية تساوي أكبر كمية ممكنة نظريًا، أي أن كل المتفاعل المحدد تحول إلى ناتج دون أي فقد، وهي حالة مثالية.', '["المردود النظري 100 g","المردود الفعلي 98 g","العلاقة والناتج 98%","تفسير معنى 100%"]'::jsonb, '["نسبة المردود = (الفعلي ÷ النظري) × 100","= (98 ÷ 100) × 100 = 98%"]'::jsonb, '[{"element":"تحديد المردودين","marks":2},{"element":"حساب النسبة","marks":1},{"element":"تفسير معنى 100%","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الأجزاء الثلاثة صحيحة"},{"level":"3 درجات","description":"خطأ في جزء واحد"},{"level":"2 درجتان","description":"تحديد المردودين فقط"},{"level":"1 درجة","description":"تحديد أحد المردودين أو العلاقة فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["تبديل قيمتي المردودين","حساب نسبة الفاقد 2% بدل المردود","تفسير 100% بأن التفاعل «سريع»"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-11T11:15:01.863Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1571, 1, 'نسبة المردود = (الفعلي ÷ النظري) × 100 = (42.5 ÷ 50.0) × 100 = 85.0%.', '["ناتج قلب النسبة (50.0 ÷ 42.5) × 100؛ ونسبة المردود لا تتجاوز 100% في تجربة سليمة.","","هذه نسبة الفاقد (100% − 85.0%) لا نسبة المردود."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T11:15:01.866Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1572, 2, 'مولات CaCO₃ = 25.0 ÷ 100 = 0.250 mol، والنسبة المولية 1 : 1، فالمردود النظري لـ CaO = 0.250 × 56.0 = 14.0 g. نسبة المردود = (12.6 ÷ 14.0) × 100 = 90.0%.', '["قُسمت كتلة الناتج الفعلية على كتلة المتفاعل (12.6 ÷ 25.0) بدل المردود النظري لـ CaO.","ناتج قلب النسبة (14.0 ÷ 12.6) × 100.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T11:15:01.866Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1573, 0, 'مولات Fe₂O₃ = 80.0 ÷ 160 = 0.500 mol، وكل 1 mol منه يعطي 2 mol Fe، فالمولات النظرية للحديد = 1.00 mol، والمردود النظري = 1.00 × 56.0 = 56.0 g. نسبة المردود = (47.6 ÷ 56.0) × 100 = 85.0%.', '["","أُهمل المعامل 2 للحديد فحُسب المردود النظري 28.0 g، فظهرت نسبة تتجاوز 100% وهذا مستحيل.","قُسمت كتلة الحديد على كتلة Fe₂O₃ (47.6 ÷ 80.0) بدل المردود النظري للحديد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-11T11:15:01.867Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1574, 1, 'المردود الفعلي = (نسبة المردود ÷ 100) × المردود النظري = 0.750 × 60.0 = 45.0 g.', '["ناتج قسمة المردود النظري على 0.750 بدل الضرب؛ ولا يمكن أن يزيد الفعلي على النظري.","","هذه كتلة الجزء المفقود (25.0% من 60.0 g) لا المردود الفعلي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T11:15:01.867Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1575, 0, 'نسب المردود: (أ) 18.0 ÷ 20.0 × 100 = 90.0% ، (ب) 21.5 ÷ 25.0 × 100 = 86.0% ، (ج) 13.8 ÷ 15.0 × 100 = 92.0%؛ فأعلاها للطالب (ج) مع أنه حصل على أقل كتلة.', '["","حصل على أكبر كتلة فعلية لكن نسبة مردوده 86.0% فقط؛ فالمقارنة تكون بالنسبة لا بالكتلة.","نسبة مردوده 90.0% وهي أقل من 92.0%."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T11:15:01.868Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1576, 2, 'مولات SiO₂ = 100000 ÷ 60 = 1666.7 mol = مولات SiC النظرية (1 : 1)، فالمردود النظري = 1666.7 × 40 = 66667 g تقريبًا. نسبة المردود = (51400 ÷ 66667) × 100 ≈ 77.1%.', '["قُسمت كتلة SiC الناتجة على كتلة SiO₂ مباشرة دون حساب المردود النظري لـ SiC.","ناتج قلب النسبة (66667 ÷ 51400) × 100 ≈ 130%.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (55%)"}],"at":"2026-10-11T11:15:01.868Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1577, 1, 'لا يمكن أن يزيد الناتج الحقيقي على المردود النظري، فالنسبة الأكبر من 100% تعني أن الكتلة المقيسة تضمنت مواد غير الناتج كالماء أو الشوائب.', '["فقد جزء من الناتج يُنقص المردود الفعلي فتقل النسبة عن 100% لا تزيد.","","عدم اكتمال التفاعل يقلل كمية الناتج فتقل النسبة عن 100%."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T11:15:01.868Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1578, null, null, null, '(أ) الكتلة المولية لـ SiO₂ = 28.0 + 2(16.0) = 60.0 g/mol، ولـ SiC = 28.0 + 12.0 = 40.0 g/mol. مولات SiO₂ = 50.0 ÷ 60.0 = 0.833 mol، والنسبة المولية SiO₂ : SiC = 1 : 1، فمولات SiC = 0.833 mol، والمردود النظري = 0.833 × 40.0 = 33.3 g. (ب) نسبة المردود = (25.0 ÷ 33.3) × 100 = 75.0%.', '["حساب الكتل المولية","تحويل كتلة SiO₂ إلى مولات","استخدام النسبة المولية 1 : 1","المردود النظري 33.3 g","نسبة المردود 75.0%"]'::jsonb, '["M(SiO₂) = 60.0 g/mol ، M(SiC) = 40.0 g/mol","n(SiO₂) = 50.0 ÷ 60.0 = 0.833 mol","n(SiC) = 0.833 mol (نسبة 1 : 1)","المردود النظري = 0.833 × 40.0 = 33.3 g","نسبة المردود = (25.0 ÷ 33.3) × 100 = 75.0%"]'::jsonb, '[{"element":"الكتل المولية والمولات","marks":1},{"element":"النسبة المولية والمردود النظري","marks":2},{"element":"نسبة المردود المئوية","marks":1},{"element":"الوحدات والأرقام المعنوية","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"خطوات كاملة وناتجان صحيحان (33.3 g و75.0%)"},{"level":"3–4 درجات","description":"المردود النظري صحيح مع خطأ في النسبة أو الأرقام المعنوية"},{"level":"1–2 درجة","description":"حساب المولات أو الكتل المولية فقط"},{"level":"صفر","description":"لا إجابة أو طريقة خاطئة"}]'::jsonb, '["قسمة 25.0 على 50.0 مباشرة (50.0%)","قلب النسبة (133%)","خطأ في الكتلة المولية لـ SiO₂"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (55%)"}],"at":"2026-10-11T11:15:01.869Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1579, null, null, null, 'M(KClO₃) = 39.0 + 35.5 + 3(16.0) = 122.5 g/mol. مولات KClO₃ = 24.5 ÷ 122.5 = 0.200 mol. من المعادلة: 2 mol KClO₃ تعطي 3 mol O₂، فمولات O₂ = 0.200 × 3/2 = 0.300 mol. المردود النظري = 0.300 × 32.0 = 9.60 g. نسبة المردود = (8.16 ÷ 9.60) × 100 = 85.0%.', '["الكتلة المولية لـ KClO₃ = 122.5 g/mol","مولات KClO₃ = 0.200 mol","استخدام النسبة المولية 2 : 3","المردود النظري 9.60 g","نسبة المردود 85.0%"]'::jsonb, '["n(KClO₃) = 24.5 ÷ 122.5 = 0.200 mol","n(O₂) = 0.200 × (3 ÷ 2) = 0.300 mol","المردود النظري = 0.300 × 32.0 = 9.60 g","نسبة المردود = (8.16 ÷ 9.60) × 100 = 85.0%"]'::jsonb, '[{"element":"مولات KClO₃","marks":1},{"element":"النسبة المولية ومولات O₂","marks":1},{"element":"المردود النظري","marks":1},{"element":"نسبة المردود مع الأرقام المعنوية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حل كامل وناتج 85.0%"},{"level":"3 درجات","description":"خطأ واحد في النسبة المولية أو الأرقام المعنوية مع طريقة صحيحة"},{"level":"2 درجتان","description":"المولات صحيحة دون إكمال"},{"level":"1 درجة","description":"العلاقة الصحيحة لنسبة المردود فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["إهمال النسبة المولية 2 : 3 (مردود نظري 6.40 g ونسبة 128%)","قسمة كتلة O₂ على كتلة KClO₃ (33.3%)","استخدام 16.0 كتلةً مولية لـ O₂ بدل 32.0"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T11:15:01.870Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1580, null, null, null, '(أ) مولات Na = 4.60 ÷ 23.0 = 0.200 mol، والنسبة Na : NaCl = 2 : 2 = 1 : 1، فمولات NaCl = 0.200 mol، والمردود النظري = 0.200 × 58.5 = 11.7 g. (ب) الأول: (10.5 ÷ 11.7) × 100 = 89.7%. الثاني: (12.3 ÷ 11.7) × 100 = 105%. (ج) نتيجة الطالب الثاني غير مقبولة؛ لأن المردود الفعلي لا يمكن أن يزيد على المردود النظري (أكبر كمية ممكنة)، والسبب المحتمل أن الناتج لم يُجفف جيدًا أو احتوى على شوائب أو حدث خطأ في الوزن.', '["المردود النظري 11.7 g","نسبة الطالب الأول 89.7%","نسبة الطالب الثاني 105%","تحديد نتيجة الطالب الثاني غير مقبولة مع التعليل","ذكر سبب محتمل (رطوبة/شوائب/خطأ وزن)"]'::jsonb, '["n(Na) = 4.60 ÷ 23.0 = 0.200 mol","n(NaCl) = 0.200 mol ، المردود النظري = 0.200 × 58.5 = 11.7 g","الأول: 10.5 ÷ 11.7 × 100 = 89.7%","الثاني: 12.3 ÷ 11.7 × 100 = 105%"]'::jsonb, '[{"element":"المردود النظري","marks":2},{"element":"نسبتا المردود","marks":2},{"element":"الحكم والتعليل والسبب المحتمل","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"الحسابات صحيحة والحكم معلل مع سبب محتمل"},{"level":"4–5 درجات","description":"الحسابات صحيحة مع تعليل ناقص"},{"level":"2–3 درجات","description":"المردود النظري صحيح فقط أو نسبة واحدة صحيحة"},{"level":"1 درجة","description":"العلاقة فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["الحكم بأن نتيجة الطالب الثاني أفضل لأنها أكبر","استخدام الكتلة المولية لـ Na بدل NaCl","تفسير زيادة النسبة بفقد جزء من الناتج"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:01.870Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1581, 2, 'التصادم المرن هو التصادم الذي يبقى فيه مجموع الطاقة الحركية للجسيمات قبل التصادم مساويًا لمجموعها بعده، فلا تُفقد طاقة حركية.', '["توقف الجسيمات يعني فقد طاقتها الحركية، وهذا عكس التصادم المرن.","الالتصاق يصاحبه فقد في الطاقة الحركية فهو تصادم غير مرن.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T11:15:01.873Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1582, 0, 'من فرضيات نظرية الحركة الجزيئية أن تصادمات جسيمات الغاز مرنة، أي لا تُفقد فيها الطاقة الحركية الكلية.', '["","لو فقدت الجسيمات طاقتها في كل تصادم لتباطأت تدريجيًا وتجمعت في قاع الإناء، وهذا لا يحدث.","جسيمات الغاز في حركة مستمرة عشوائية فتتصادم باستمرار لا نادرًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:01.873Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1583, 1, 'في التصادم المرن يمكن أن يتسارع أحد الجسيمين ويتباطأ الآخر بانتقال الطاقة بينهما، لكن الطاقة الحركية الكلية تبقى ثابتة.', '["هذا مفهوم خاطئ شائع؛ فالثابت هو مجموع الطاقة لا طاقة كل جسيم على حدة.","","تحول الطاقة إلى حرارة يعني فقد الطاقة الحركية، وهذا يناقض التصادم المرن."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:01.873Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1584, 0, 'الطاقة الكلية قبل التصادم = 5.0 + 3.0 = 8.0×10⁻²¹ J، وتبقى ثابتة في التصادم المرن، فطاقة (B) بعده = 8.0 − 2.0 = 6.0×10⁻²¹ J.', '["","افتُرض أن (B) يحتفظ بطاقته، مع أن (A) فقد 3.0×10⁻²¹ J انتقلت إلى (B).","هذه الطاقة الكلية للجسيمين معًا لا طاقة (B) وحده."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (48%)"}],"at":"2026-10-11T11:15:01.874Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1585, 2, 'في الحالة 2 بقي مجموع الطاقة الحركية ثابتًا (9.0 قبل التصادم و9.0 بعده)، وهذا هو شرط التصادم المرن.', '["نقص المجموع من 9.0 إلى 7.5 فالتصادم غير مرن.","نقص المجموع إلى الصفر (توقف الجسيمان) فالتصادم غير مرن.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T11:15:01.874Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1586, 1, 'بما أن التصادمات مرنة فلا تُفقد الطاقة الحركية الكلية مع تكرار التصادمات، فتستمر الجسيمات في حركتها ولا تتباطأ.', '["صغر حجم الجسيمات يفسر قابلية الانضغاط والكثافة المنخفضة لا استمرار الحركة.","","تباعد الجسيمات يفسر الكثافة المنخفضة والانضغاط، ولا يمنع فقد الطاقة عند التصادم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-11T11:15:01.875Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1587, 0, 'توقف كرة الصلصال يعني فقد طاقتها الحركية فهو تصادم غير مرن، أما تصادمات جسيمات الغاز فمرنة لا تُفقد فيها الطاقة الحركية الكلية.', '["","عكس الوصفين؛ فالكرة توقفت ففقدت طاقتها، وتصادمات الغاز هي المرنة.","توقف الكرة دليل على فقد الطاقة، فلا يمكن أن يكون تصادمها مرنًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:01.875Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1588, null, null, null, '(أ) التصادم المرن: تصادم لا تُفقد فيه الطاقة الحركية، أي أن مجموع الطاقة الحركية للجسيمات قبل التصادم يساوي مجموعها بعده. (ب) تفترض النظرية أن جسيمات الغاز تتصادم بعضها ببعض وبجدران الإناء تصادمات مرنة. (ج) لأن التصادمات مرنة فلا تُفقد الطاقة الحركية الكلية مهما تكررت التصادمات؛ قد تنتقل الطاقة من جسيم إلى آخر لكن مجموعها يبقى ثابتًا، فتستمر الجسيمات في حركتها العشوائية.', '["تعريف التصادم المرن بثبات الطاقة الحركية الكلية","ذكر فرضية التصادمات المرنة","الربط بين مرونة التصادم وعدم فقد الطاقة","الإشارة إلى انتقال الطاقة بين الجسيمات مع ثبات المجموع"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"الفرضية","marks":1},{"element":"التفسير","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"تعريف وفرضية صحيحان وتفسير كامل"},{"level":"3 درجات","description":"تفسير ناقص مع تعريف وفرضية صحيحين"},{"level":"2 درجتان","description":"التعريف والفرضية دون تفسير"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"لا إجابة أو إجابة خاطئة"}]'::jsonb, '["القول إن كل جسيم يحتفظ بسرعته نفسها بعد التصادم","تعريف التصادم المرن بأنه تصادم «ضعيف»","تفسير استمرار الحركة بانعدام التصادمات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-11T11:15:01.876Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1589, null, null, null, '(أ) الطاقة الكلية قبل التصادم = 4.0 + 1.0 = 5.0×10⁻²¹ J، وفي التصادم المرن تبقى ثابتة، فطاقة (Y) = 5.0 − 1.5 = 3.5×10⁻²¹ J. (ب) المجموع بعد التصادم = 1.5 + 2.0 = 3.5×10⁻²¹ J وهو أقل من 5.0×10⁻²¹ J، أي فُقد 1.5×10⁻²¹ J من الطاقة الحركية، فالتصادم غير مرن.', '["حساب الطاقة الكلية قبل التصادم 5.0×10⁻²¹ J","تطبيق ثبات الطاقة الكلية","طاقة (Y) = 3.5×10⁻²¹ J","مقارنة المجموعين في (ب)","الحكم بأن التصادم غير مرن"]'::jsonb, '["الطاقة الكلية قبل التصادم = 4.0 + 1.0 = 5.0×10⁻²¹ J","طاقة (Y) بعد التصادم المرن = 5.0 − 1.5 = 3.5×10⁻²¹ J","في (ب): المجموع = 1.5 + 2.0 = 3.5×10⁻²¹ J < 5.0×10⁻²¹ J ← غير مرن"]'::jsonb, '[{"element":"(أ) الطاقة الكلية","marks":1},{"element":"(أ) طاقة (Y)","marks":1},{"element":"(ب) المقارنة","marks":1},{"element":"(ب) الحكم والتبرير","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الجزءان صحيحان مع التبرير"},{"level":"3 درجات","description":"(أ) صحيح و(ب) حكم صحيح دون تبرير كافٍ"},{"level":"2 درجتان","description":"(أ) صحيح فقط"},{"level":"1 درجة","description":"حساب الطاقة الكلية فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["افتراض أن (Y) يحتفظ بطاقته الأصلية","طرح طاقتي (X) قبل التصادم وبعده فقط (2.5×10⁻²¹ J) دون إضافة طاقة (Y) الأصلية","الحكم بالمرونة لأن الجسيمين ما زالا يتحركان"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (48%)"}],"at":"2026-10-11T11:15:01.876Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1590, null, null, null, 'العبارة غير صحيحة؛ ففي التصادم المرن قد تنتقل الطاقة الحركية من جسيم إلى آخر، فيتسارع أحدهما ويتباطأ الآخر، ولذلك قد تتغير سرعة كل جسيم. الصحيح: «في التصادم المرن يبقى مجموع الطاقة الحركية للجسيمين قبل التصادم مساويًا لمجموعها بعده». فالثابت هو الطاقة الحركية الكلية لا سرعة كل جسيم أو طاقته على حدة.', '["الحكم بأن العبارة خاطئة","التعليل بانتقال الطاقة بين الجسيمين","صياغة العبارة الصحيحة","تحديد الثابت: مجموع الطاقة الحركية"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"التعليل","marks":1},{"element":"التصحيح وتحديد الكمية الثابتة","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح مع تعليل وتصحيح دقيق"},{"level":"3 درجات","description":"حكم وتصحيح صحيحان مع تعليل ناقص"},{"level":"2 درجتان","description":"حكم صحيح مع تعليل دون تصحيح"},{"level":"1 درجة","description":"حكم صحيح فقط"},{"level":"صفر","description":"تأييد العبارة أو لا إجابة"}]'::jsonb, '["تأييد العبارة","القول إن السرعة الكلية هي الثابتة بدل الطاقة الحركية الكلية","الخلط بين التصادم المرن وتوقف الجسيمات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:01.876Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1591, 1, 'نظرية الحركة الجزيئية تفسر سلوك المادة (ومنها الغازات) بالاعتماد على حركة جسيماتها وطاقتها.', '["اللون خاصية لا علاقة لها بفرضيات النظرية.","","الرائحة خاصية حسية لا تبنى عليها النظرية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T11:15:01.879Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1592, 0, 'تفترض النظرية عدم وجود قوى تجاذب أو تنافر تُذكر بين جسيمات الغاز، فعبارة «تتجاذب بقوى كبيرة» ليست من فرضياتها.', '["","الحركة العشوائية المستمرة في خطوط مستقيمة من فرضيات النظرية.","صغر حجم الجسيمات مقارنة بالمسافات بينها من فرضيات النظرية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T11:15:01.879Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1593, 2, 'درجة الحرارة مقياس لمتوسط الطاقة الحركية، فعند درجة الحرارة نفسها يتساوى المتوسط، وبما أن KE = ½mv² فالأقل كتلة (H₂) يتحرك بسرعة أكبر.', '["مفهوم خاطئ شائع؛ فالمتوسط متساوٍ عند درجة الحرارة نفسها.","تساوي درجة الحرارة يعني تساوي متوسط الطاقة لا تساوي السرعة؛ فالكتل مختلفة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:01.881Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1594, 2, 'تفترض النظرية أن جسيمات الغاز في حركة مستمرة عشوائية في خطوط مستقيمة إلى أن تصطدم بغيرها أو بجدران الإناء.', '["صغر الحجم يفسر الانضغاط وانخفاض الكثافة لا مسار الحركة.","الطاقة الحركية تعتمد على الكتلة والسرعة معًا، ولا تصف هذه الفرضية مسار الحركة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T11:15:01.881Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1595, 0, 'انخفاض الكثافة (كتلة قليلة في وحدة الحجم) وقابلية الانضغاط (تقارب الجسيمات عند الضغط) يفسَّران كلاهما بكبر المسافات بين جسيمات الغاز.', '["","مرونة التصادمات تفسر استمرار الحركة دون فقد للطاقة، لا الكثافة أو الانضغاط.","هذه الفرضية تتعلق بالطاقة الحركية ولا تفسر انخفاض الكثافة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T11:15:01.881Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1596, 1, 'جسيمات الغاز في حركة مستمرة عشوائية ولا توجد بينها قوى تجاذب تُبقيها متقاربة، فتنتشر حتى تشغل الحيز كله.', '["حجم الجسيم نفسه لا يتغير، وإنما تتحرك الجسيمات وتتباعد.","","تفترض النظرية عدم وجود قوى تجاذب تُذكر، ولا تنجذب الجسيمات نحو الجدران."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-11T11:15:01.882Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.')
