(1597, 2, 'درجة الحرارة مقياس لمتوسط الطاقة الحركية، فارتفاعها يعني زيادة متوسط الطاقة الحركية وزيادة سرعة الجسيمات.', '["التسخين يزيد سرعة الجسيمات فيزيد متوسط طاقتها لا العكس.","ثبات عدد الجسيمات لا يمنع تغير متوسط طاقتها بتغير درجة الحرارة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T11:15:01.882Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1598, null, null, null, 'من الفرضيات: (1) حجم جسيمات الغاز صغير جدًا مقارنة بالمسافات الكبيرة بينها. (2) لا توجد قوى تجاذب أو تنافر تُذكر بين الجسيمات. (3) الجسيمات في حركة مستمرة عشوائية في خطوط مستقيمة. (4) التصادمات مرنة. تفسير الانضغاط: لأن المسافات بين الجسيمات كبيرة فعند الضغط تقترب الجسيمات بعضها من بعض فيقل الحجم. تفسير استمرار الحركة: لأن التصادمات مرنة فلا تُفقد الطاقة الحركية الكلية، فتظل الجسيمات تتحرك.', '["ذكر ثلاث فرضيات صحيحة","تفسير الانضغاط بالمسافات الكبيرة","تفسير استمرار الحركة بمرونة التصادمات"]'::jsonb, '[]'::jsonb, '[{"element":"الفرضيات الثلاث","marks":3},{"element":"تفسير الانضغاط","marks":1},{"element":"تفسير استمرار الحركة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"ثلاث فرضيات صحيحة وتفسيران صحيحان"},{"level":"4 درجات","description":"ثلاث فرضيات وتفسير واحد صحيح"},{"level":"3 درجات","description":"ثلاث فرضيات دون تفسير، أو فرضيتان وتفسيران"},{"level":"1–2 درجة","description":"فرضية أو فرضيتان فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["القول إن الجسيمات نفسها تنكمش عند الضغط","ذكر خصائص الغاز (الكثافة، الانتشار) على أنها فرضيات","تفسير الانضغاط بمرونة التصادمات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T11:15:01.882Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1599, null, null, null, '(أ) متوسط الطاقة الحركية متساوٍ للغازين؛ لأن درجة الحرارة مقياس لمتوسط الطاقة الحركية، والغازان عند درجة الحرارة نفسها (30 °C). (ب) جسيمات H₂ أسرع؛ لأن KE = ½mv² متساوية للغازين، وكتلة جزيء H₂ أصغر بكثير من كتلة جزيء O₂، فلا بد أن تكون سرعته أكبر حتى تتساوى الطاقتان.', '["تساوي متوسط الطاقة الحركية","التعليل بأن درجة الحرارة مقياس لمتوسط الطاقة","H₂ أسرع","التعليل بالعلاقة KE = ½mv² والكتلة الأصغر"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) الحكم","marks":1},{"element":"(أ) التعليل","marks":1},{"element":"(ب) الحكم","marks":1},{"element":"(ب) التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكمان صحيحان مع تعليلين"},{"level":"3 درجات","description":"حكمان صحيحان وتعليل واحد"},{"level":"2 درجتان","description":"حكمان دون تعليل"},{"level":"1 درجة","description":"حكم واحد صحيح"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["القول إن O₂ أكبر طاقة لأنه أثقل","القول إن السرعتين متساويتان لتساوي درجة الحرارة","الخلط بين الطاقة الكلية ومتوسطها"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:01.882Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1600, null, null, null, 'الملاحظة الأولى: جسيمات الغاز في حركة مستمرة عشوائية في خطوط مستقيمة، والمسافات بين جسيمات الهواء كبيرة ولا تجاذب يُذكر بينها، فتتحرك جسيمات الغاز خلال الهواء وتنتشر حتى تصل إلى أنحاء الغرفة. الملاحظة الثانية: درجة الحرارة مقياس لمتوسط الطاقة الحركية، فارتفاعها يزيد متوسط الطاقة الحركية وبالتالي سرعة الجسيمات، فتصل الرائحة أسرع.', '["الحركة المستمرة العشوائية","المسافات الكبيرة وانعدام التجاذب يسمحان بالحركة خلال الهواء","ارتفاع درجة الحرارة يزيد متوسط الطاقة الحركية","زيادة السرعة تسرّع وصول الرائحة"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير الملاحظة الأولى","marks":2},{"element":"تفسير الملاحظة الثانية","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"تفسيران كاملان مرتبطان بالفرضيات"},{"level":"3 درجات","description":"تفسير كامل وآخر ناقص"},{"level":"2 درجتان","description":"تفسير واحد كامل"},{"level":"1 درجة","description":"إشارة صحيحة جزئية"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["تفسير وصول الرائحة بأن الهواء «يحملها» فقط دون ذكر حركة الجسيمات","القول إن الحرارة تكبّر حجم الجسيمات","عدم الربط بين درجة الحرارة ومتوسط الطاقة الحركية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T11:15:01.883Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1601, 2, 'الطاقة الحركية KE = ½mv²، فهي تعتمد على كتلة الجسيم (m) وسرعته (v).', '["اللون لا يدخل في حساب الطاقة الحركية.","حجم الإناء وشكله لا يظهران في العلاقة KE = ½mv².",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T11:15:01.885Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1602, 0, 'v هي سرعة الجسيم (velocity)، وm كتلته.', '["","الحجم يُرمز له عادة بـ V في قوانين الغازات، لكنه لا يدخل في علاقة الطاقة الحركية.","الكتلة يرمز لها بـ m في العلاقة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T11:15:01.886Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1603, 1, 'الطاقة الحركية تتناسب مع مربع السرعة (KE = ½mv²)، فمضاعفة السرعة تجعل الطاقة (2)² = 4 أمثال.', '["هذا يصح لو كانت الطاقة تتناسب طرديًا مع السرعة لا مع مربعها.","","السرعة أحد العاملين اللذين تعتمد عليهما الطاقة الحركية، فتغيرها يغير الطاقة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:01.886Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1604, 0, 'عند ثبات السرعة تتناسب الطاقة الحركية طرديًا مع الكتلة، فمضاعفة الكتلة تضاعف الطاقة: النسبة 2 : 1.', '["","التربيع خاص بالسرعة لا بالكتلة.","عُكست النسبة؛ فالأكبر كتلة له طاقة أكبر عند السرعة نفسها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:01.886Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1605, 1, 'KE = ½mv² = ½ × 5.3×10⁻²⁶ × (480)² = 6.1×10⁻²¹ J.', '["نُسي العامل ½ في العلاقة.","","نُسي تربيع السرعة (½ × 5.3×10⁻²⁶ × 480)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:01.887Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1606, 2, 'KE(X) = ½ × 4.0×10⁻²⁶ × 400² = 3.2×10⁻²¹ J، KE(Y) = ½ × 8.0×10⁻²⁶ × 400² = 6.4×10⁻²¹ J، KE(Z) = ½ × 4.0×10⁻²⁶ × 800² = 1.28×10⁻²⁰ J؛ فـ Z الأكبر لأن مضاعفة السرعة تضاعف الطاقة أربع مرات بينما مضاعفة الكتلة تضاعفها مرتين.', '["X أصغرها طاقة: كتلته وسرعته هما الأصغر.","Y طاقته ضعف X فقط، أما Z فطاقته أربعة أمثال X.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:01.887Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1607, 1, 'بما أن KE = ½mv² متساوية، فالجسيم الأصغر كتلة (H₂) لا بد أن تكون سرعته أكبر.', '["كتلة H₂ (2 g/mol) أصغر من كتلة O₂ (32 g/mol) لا أكبر.","","الطاقة الحركية تعتمد على الكتلة والسرعة معًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:01.887Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1608, null, null, null, '(أ) KE = ½mv²، حيث m كتلة الجسيم وv سرعته؛ فالطاقة الحركية تعتمد على الكتلة والسرعة. (ب) السرعة؛ لأن الطاقة الحركية تتناسب مع مربع السرعة، فمضاعفة السرعة تزيد الطاقة 4 أمثال، بينما مضاعفة الكتلة تزيدها مثلين فقط.', '["كتابة العلاقة KE = ½mv²","تحديد الكتلة والسرعة","اختيار السرعة","التعليل بالتربيع (4 أمثال مقابل مثلين)"]'::jsonb, '[]'::jsonb, '[{"element":"العلاقة","marks":1},{"element":"العاملان","marks":1},{"element":"اختيار السرعة","marks":1},{"element":"التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة"},{"level":"3 درجات","description":"العلاقة والعاملان والاختيار دون تعليل كافٍ"},{"level":"2 درجتان","description":"العلاقة والعاملان فقط"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["نسيان التربيع في العلاقة","القول إن الطاقة تعتمد على حجم الجسيم","القول إن العاملين متساويان في التأثير"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T11:15:01.887Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1609, null, null, null, '(أ) KE = ½mv² = ½ × 6.6×10⁻²⁷ × (1300)² = 5.6×10⁻²¹ J. (ب) السرعة الجديدة 2600 m/s: KE = ½ × 6.6×10⁻²⁷ × (2600)² = 2.2×10⁻²⁰ J، أي أن الطاقة زادت 4 مرات لأنها تتناسب مع مربع السرعة.', '["التعويض الصحيح في العلاقة","KE = 5.6×10⁻²¹ J","KE الجديدة = 2.2×10⁻²⁰ J","زيادة الطاقة 4 مرات"]'::jsonb, '["KE = ½mv²","KE = ½ × 6.6×10⁻²⁷ × (1300)² = 5.6×10⁻²¹ J","عند v = 2600 m/s: KE = ½ × 6.6×10⁻²⁷ × (2600)² = 2.2×10⁻²⁰ J","2.2×10⁻²⁰ ÷ 5.6×10⁻²¹ ≈ 4"]'::jsonb, '[{"element":"(أ) التعويض","marks":1},{"element":"(أ) الناتج","marks":1},{"element":"(ب) الناتج","marks":1},{"element":"(ب) عدد المرات","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الحسابات والاستنتاج صحيحة بالوحدات"},{"level":"3 درجات","description":"خطأ بسيط في الناتج أو الوحدة"},{"level":"2 درجتان","description":"(أ) صحيح فقط"},{"level":"1 درجة","description":"كتابة العلاقة والتعويض فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["نسيان تربيع السرعة","نسيان العامل ½","القول إن الطاقة تتضاعف مرتين فقط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:01.888Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1610, null, null, null, 'KE(A) = ½ × 3.0×10⁻²⁶ × (500)² = 3.8×10⁻²¹ J (3.75×10⁻²¹ J). KE(B) = ½ × 6.0×10⁻²⁶ × (300)² = 2.7×10⁻²¹ J. فالجسيم (A) الأخف له طاقة أكبر، والعبارة خاطئة؛ لأن الطاقة الحركية تعتمد على الكتلة والسرعة معًا، والسرعة تؤثر بمربعها.', '["KE(A) ≈ 3.8×10⁻²¹ J","KE(B) = 2.7×10⁻²¹ J","الحكم بخطأ العبارة","التعليل باعتماد الطاقة على الكتلة والسرعة معًا"]'::jsonb, '["KE(A) = ½ × 3.0×10⁻²⁶ × 500² = 3.75×10⁻²¹ J ≈ 3.8×10⁻²¹ J","KE(B) = ½ × 6.0×10⁻²⁶ × 300² = 2.7×10⁻²¹ J","KE(A) > KE(B) رغم أن (A) أخف"]'::jsonb, '[{"element":"حساب KE(A)","marks":1},{"element":"حساب KE(B)","marks":1},{"element":"الحكم","marks":1},{"element":"التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حسابان صحيحان وحكم معلل"},{"level":"3 درجات","description":"حسابان صحيحان وحكم دون تعليل"},{"level":"2 درجتان","description":"حساب واحد صحيح مع حكم صحيح"},{"level":"1 درجة","description":"حساب واحد صحيح"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["الحكم من الكتلة وحدها دون حساب","نسيان تربيع السرعة فتنقلب المقارنة","تأييد العبارة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:01.888Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1611, 1, 'الانتشار هو تحرك مادة خلال مادة أخرى، كتحرك جسيمات العطر خلال الهواء.', '["هذا تعريف التدفق لا الانتشار.","","هذا تعريف التسامي، وهو تغير في الحالة الفيزيائية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T11:15:01.890Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1612, 2, 'تنتقل الجسيمات بحركتها العشوائية من المنطقة الأعلى تركيزًا إلى الأقل تركيزًا حتى يتجانس الخليط.', '["عُكس الاتجاه؛ فالانتشار يقلل الفرق في التركيز ولا يزيده.","الانتشار يحدث في جميع الاتجاهات بسبب الحركة العشوائية لا في اتجاه الجاذبية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:01.891Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1613, 0, 'رائحة العطر تصل إلى أرجاء الغرفة بتحرك جسيماته خلال جسيمات الهواء، وهذا انتشار.', '["","خروج الغاز من ثقب صغير تدفق لا انتشار.","التكاثف تحول من الحالة الغازية إلى السائلة، لا تحرك مادة خلال أخرى."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T11:15:01.891Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1614, 2, 'الحركة المستمرة العشوائية والفراغات الكبيرة بين جسيمات الغاز تسمح لجسيمات غاز بالتحرك خلال غاز آخر.', '["تفترض النظرية أن قوى التجاذب بين جسيمات الغاز لا تُذكر.","جسيمات الغاز في حركة مستمرة لا ثابتة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T11:15:01.891Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1615, 0, 'عند درجة الحرارة نفسها ينتشر الغاز الأقل كتلة أسرع، فرائحة NH₃ تصل أولًا.', '["","الغاز الأكبر كتلة ينتشر أبطأ لا أسرع.","تساوي درجة الحرارة يعني تساوي متوسط الطاقة الحركية، لكن الأخف أسرع فلا تصلان معًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T11:15:01.891Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1616, 1, 'كلما ارتفعت درجة الحرارة قل الزمن اللازم، أي زاد معدل الانتشار؛ لأن متوسط الطاقة الحركية للجسيمات وسرعتها يزدادان.', '["قلة الزمن تعني زيادة المعدل لا نقصه.","","الزمن تغير بوضوح مع درجة الحرارة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-11T11:15:01.892Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1617, 0, 'تحركت جسيمات الحبر خلال الماء من التركيز الأعلى إلى الأقل حتى تجانس اللون، وهذا ينطبق عليه تعريف الانتشار (تحرك مادة خلال مادة أخرى).', '["","التدفق خروج غاز من ثقب صغير، ولا ينطبق على ما حدث.","تلوّن الماء كله دون تحريك سببه حركة الجسيمات، فلا يصح إنكار علاقتها بما حدث."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T11:15:01.892Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1618, null, null, null, '(أ) الانتشار: تحرك مادة خلال مادة أخرى. (ب) مثال: انتشار رائحة العطر أو البخور في أرجاء الغرفة. (ج) جسيمات الغاز في حركة مستمرة عشوائية، والمسافات بينها كبيرة ولا توجد قوى تجاذب تُذكر، فتتحرك جسيمات الغاز خلال جسيمات الغاز الآخر من التركيز الأعلى إلى الأقل حتى يتجانس الخليط.', '["تعريف الانتشار","مثال صحيح","الحركة العشوائية المستمرة","الفراغات الكبيرة/انعدام التجاذب","الانتقال من التركيز الأعلى إلى الأقل"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"المثال","marks":1},{"element":"التفسير","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"تعريف ومثال وتفسير كامل"},{"level":"3 درجات","description":"تعريف ومثال وتفسير ناقص"},{"level":"2 درجتان","description":"تعريف ومثال فقط"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["تعريف الانتشار بخروج الغاز من ثقب","ذكر مثال على التدفق بدل الانتشار","القول إن الجسيمات تنتقل من التركيز الأقل إلى الأعلى"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T11:15:01.892Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1619, null, null, null, '(أ) كلما قلت الكتلة المولية زاد معدل الانتشار؛ لأن الغازات عند درجة الحرارة نفسها لها متوسط الطاقة الحركية نفسه، والجسيم الأخف يتحرك بسرعة أكبر (KE = ½mv²). (ب) كلما ارتفعت درجة الحرارة زاد معدل الانتشار؛ لأن درجة الحرارة مقياس لمتوسط الطاقة الحركية فتزداد سرعة الجسيمات.', '["الغاز الأخف ينتشر أسرع","التعليل بتساوي متوسط الطاقة وKE = ½mv²","ارتفاع الحرارة يزيد معدل الانتشار","التعليل بزيادة متوسط الطاقة الحركية والسرعة"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) الأثر","marks":1},{"element":"(أ) التعليل","marks":1},{"element":"(ب) الأثر","marks":1},{"element":"(ب) التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"أثران صحيحان مع تعليلين"},{"level":"3 درجات","description":"أثران وتعليل واحد"},{"level":"2 درجتان","description":"أثران دون تعليل"},{"level":"1 درجة","description":"أثر واحد صحيح"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["القول إن الغاز الأثقل ينتشر أسرع لأنه «أقوى»","القول إن الحرارة تكبّر الجسيمات فتبطئها","الخلط بين الانتشار والتدفق"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-11T11:15:01.892Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1620, null, null, null, '(أ) الانتشار: تحرك مادة خلال مادة أخرى (تحرك جسيمات الغاز خلال الهواء). (ب) يقل الزمن؛ لأن ارتفاع درجة الحرارة يزيد متوسط الطاقة الحركية وسرعة الجسيمات فيزيد معدل الانتشار. (ج) يزداد الزمن؛ لأن الغاز الأكبر كتلة مولية يتحرك أبطأ عند درجة الحرارة نفسها فينتشر بمعدل أقل.', '["تسمية الانتشار","تعريفه","قلة الزمن في الغرفة الأدفأ مع التعليل","زيادة الزمن مع الغاز الأثقل مع التعليل"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) التسمية والتعريف","marks":2},{"element":"(ب) التوقع والتعليل","marks":2},{"element":"(ج) التوقع والتعليل","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة معللة"},{"level":"4–5 درجات","description":"توقعات صحيحة مع نقص في أحد التعليلات"},{"level":"2–3 درجات","description":"التسمية والتعريف مع توقع واحد"},{"level":"1 درجة","description":"التسمية فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["تسمية العملية تدفقًا","توقع زيادة الزمن عند التسخين","توقع أن الغاز الأثقل أسرع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-11T11:15:01.893Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1621, 0, 'التدفق هو خروج الغاز (تسربه) من ثقب صغير جدًا في الإناء الذي يحتويه.', '["","هذا تعريف الانتشار.","هذا وصف التكاثف لا التدفق."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T11:15:01.895Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1622, 2, 'خروج الغاز من ثقب صغير هو التدفق.', '["الانتشار تحرك مادة خلال مادة أخرى.","التبخر تحول السائل إلى غاز.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T11:15:01.895Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1623, 1, 'تسرب الهواء من ثقب دقيق في الإطار خروج غاز من ثقب صغير، وهذا تدفق.', '["انتشار الرائحة تحرك مادة خلال أخرى، فهو انتشار.","","اختلاط غازين انتشار لا تدفق."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T11:15:01.896Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1624, 0, 'يتسرب الغاز من مسام المطاط الدقيقة (تدفق)، والغاز الأقل كتلة مولية يتدفق أسرع، فيخرج الهيليوم أسرع.', '["","كتلة الهيليوم المولية (4) أصغر من كتلة الهواء (29) لا أكبر.","الهواء يتدفق أيضًا لكن بمعدل أبطأ."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:01.896Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1625, 2, 'التدفق: خروج الغاز من ثقب صغير، أما الانتشار: تحرك مادة خلال مادة أخرى.', '["التدفق خاص بالغازات الخارجة من ثقب، والانتشار يحدث في الغازات والسوائل.","معدل كل منهما يعتمد على الكتلة المولية (قانون جراهام).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:01.896Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1626, 0, 'معدل N₂ ÷ معدل He = √(4 ÷ 28) = √0.143 ≈ 0.38، أي أن N₂ يتدفق أبطأ.', '["","عُكست النسبة: √(28 ÷ 4) = 2.65 هي نسبة معدل He إلى معدل N₂.","نُسي الجذر التربيعي: 4 ÷ 28 = 0.14."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T11:15:01.896Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1627, 1, 'الغاز الأقل كتلة مولية يتدفق أسرع فيستغرق زمنًا أقل، وأقل زمن (18 s) للغاز B.', '["زمن A (35 s) أكبر من زمن B فكتلته المولية أكبر.","","زمن C (52 s) هو الأطول فهو أكبرها كتلة مولية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T11:15:01.897Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1628, null, null, null, '(أ) التدفق: خروج الغاز من ثقب صغير جدًا في الإناء الذي يحتويه. (ب) مثال: تسرب الهيليوم من البالون المطاطي، أو تسرب الهواء من ثقب في إطار السيارة. (ج) الكتلة المولية للغاز؛ فكلما قلت الكتلة المولية زاد معدل التدفق (المعدل يتناسب عكسيًا مع الجذر التربيعي للكتلة المولية).', '["تعريف التدفق","مثال صحيح","تحديد الكتلة المولية","العلاقة العكسية"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"المثال","marks":1},{"element":"العامل","marks":1},{"element":"أثره","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"2 درجتان","description":"عنصران صحيحان"},{"level":"1 درجة","description":"عنصر واحد"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["الخلط بين تعريفي التدفق والانتشار","ذكر انتشار الرائحة مثالًا على التدفق","القول إن الغاز الأثقل يتدفق أسرع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-11T11:15:01.897Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1629, null, null, null, 'الانتشار: تحرك مادة خلال مادة أخرى؛ مثاله انتشار رائحة العطر في الغرفة؛ الغاز الأقل كتلة مولية ينتشر أسرع. التدفق: خروج الغاز من ثقب صغير جدًا؛ مثاله تسرب الهيليوم من البالون؛ الغاز الأقل كتلة مولية يتدفق أسرع. ويخضع كلاهما لقانون جراهام.', '["تعريف الانتشار","تعريف التدفق","مثال لكل منهما","أثر الكتلة المولية في الحالتين"]'::jsonb, '[]'::jsonb, '[{"element":"التعريفان","marks":2},{"element":"المثالان","marks":1},{"element":"أثر الكتلة المولية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة كاملة صحيحة"},{"level":"3 درجات","description":"التعريفان والمثالان دون أثر الكتلة أو العكس"},{"level":"2 درجتان","description":"التعريفان فقط"},{"level":"1 درجة","description":"تعريف واحد صحيح"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["تبديل التعريفين","القول إن الكتلة المولية تؤثر في أحدهما فقط","ذكر المثال نفسه للحالتين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T11:15:01.897Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1630, null, null, null, '(أ) التدفق. (ب) زمنًا أكبر؛ لأن كتلة O₂ المولية أكبر فمعدل تدفقه أقل. (ج) معدل He ÷ معدل O₂ = √(32 ÷ 4) = √8 ≈ 2.83، أي أن الهيليوم يتدفق أسرع بنحو 2.83 مرة (فيستغرق O₂ نحو 57 s).', '["تسمية العملية تدفقًا","زمن O₂ أكبر","التعليل بالكتلة المولية","النسبة ≈ 2.83"]'::jsonb, '["معدل He ÷ معدل O₂ = √(M_O₂ ÷ M_He)","= √(32 ÷ 4) = √8","≈ 2.83"]'::jsonb, '[{"element":"(أ) التسمية","marks":1},{"element":"(ب) الحكم والتعليل","marks":2},{"element":"(ج) الحساب","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة"},{"level":"4 درجات","description":"خطأ بسيط في الحساب أو التعليل"},{"level":"2–3 درجات","description":"(أ) و(ب) صحيحان دون الحساب"},{"level":"1 درجة","description":"التسمية فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["تسمية العملية انتشارًا","عكس النسبة داخل الجذر","نسيان الجذر (الناتج 8)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T11:15:01.898Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1631, 1, 'نص قانون جراهام: معدل تدفق الغاز يتناسب عكسيًا مع الجذر التربيعي لكتلته المولية.', '["العلاقة عكسية لا طردية؛ فالغاز الأثقل أبطأ.","","نُسي الجذر التربيعي، وهو خطأ شائع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-11T11:15:01.900Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1632, 0, 'بما أن المعدل يتناسب عكسيًا مع √M، فإن نسبة معدل A إلى معدل B تساوي √(M_B ÷ M_A)؛ أي أن كتلة B في البسط.', '["","قُلبت النسبة داخل الجذر، فتعطي الغاز الأثقل معدلًا أكبر.","نُسي الجذر التربيعي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T11:15:01.901Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1633, 2, 'صاغ جراهام القانون لمعدل التدفق، وينطبق أيضًا على معدل الانتشار.', '["القانون ينطبق على الانتشار أيضًا.","التكاثف والتبخر تغيرات في الحالة لا يصفها قانون جراهام.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-11T11:15:01.904Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
