(1635, 1, 'المعدل ∝ 1/√M، و√4 = 2، فمعدل الغاز الأثقل نصف معدل الآخر.', '["هذا ينتج عن نسيان الجذر التربيعي (التناسب العكسي مع M مباشرة).","","الغاز الأثقل أبطأ لا أسرع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T11:15:01.905Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1636, 2, 'معدل NH₃ ÷ معدل HCl = √(36.5 ÷ 17) = √2.15 ≈ 1.47.', '["نُسي الجذر التربيعي (36.5 ÷ 17 = 2.15).","قُلبت النسبة: √(17 ÷ 36.5) = 0.68 وهي نسبة معدل HCl إلى NH₃.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-11T11:15:01.905Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1637, 0, 'وفق قانون جراهام الأقل كتلة مولية أسرع: Ne (20) ثم N₂ (28) ثم Ar (40).', '["","هذا ترتيب من الأبطأ إلى الأسرع (عكس المطلوب).","N₂ أثقل من Ne فهو أبطأ منه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T11:15:01.905Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1638, null, null, null, '(أ) معدل تدفق الغاز يتناسب عكسيًا مع الجذر التربيعي لكتلته المولية (وينطبق كذلك على الانتشار). (ب) معدل A ÷ معدل B = √(M_B ÷ M_A). (ج) N₂ أسرع؛ لأن كتلته المولية (28) أقل من كتلة O₂ (32)، ومعدل N₂ ÷ معدل O₂ = √(32 ÷ 28) ≈ 1.07.', '["نص القانون بدقة (عكسيًا + الجذر التربيعي + الكتلة المولية)","الصيغة الرياضية الصحيحة","تحديد N₂ أسرع مع التعليل"]'::jsonb, '["معدل N₂ ÷ معدل O₂ = √(M_O₂ ÷ M_N₂) = √(32 ÷ 28) ≈ 1.07"]'::jsonb, '[{"element":"النص","marks":2},{"element":"الصيغة","marks":1},{"element":"التطبيق","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"نص دقيق وصيغة صحيحة وتطبيق صحيح"},{"level":"3 درجات","description":"نص ناقص عنصرًا مع صيغة وتطبيق صحيحين"},{"level":"2 درجتان","description":"النص فقط أو الصيغة والتطبيق فقط"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["حذف الجذر التربيعي من النص","قلب النسبة في الصيغة","القول إن O₂ أسرع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T11:15:01.906Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1639, null, null, null, 'عند درجة الحرارة نفسها يكون متوسط الطاقة الحركية لجسيمات الغازين متساويًا لأن درجة الحرارة مقياس لمتوسط الطاقة الحركية. وبما أن KE = ½mv²، فإن الجسيم الأصغر كتلة لا بد أن تكون سرعته أكبر حتى تتساوى الطاقتان؛ لذلك تصل جسيماته إلى الثقب وتخرج منه بمعدل أكبر، فيتدفق أسرع.', '["تساوي متوسط الطاقة الحركية عند درجة الحرارة نفسها","استخدام KE = ½mv²","الأقل كتلة أكبر سرعة","الربط بمعدل التدفق"]'::jsonb, '[]'::jsonb, '[{"element":"تساوي متوسط الطاقة","marks":1},{"element":"العلاقة KE = ½mv² والاستنتاج عن السرعة","marks":2},{"element":"الربط بالتدفق","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير متكامل"},{"level":"3 درجات","description":"تفسير صحيح ينقصه الربط بالتدفق"},{"level":"2 درجتان","description":"ذكر أن الأخف أسرع دون تعليل بالطاقة"},{"level":"1 درجة","description":"إشارة جزئية صحيحة"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["القول إن الغاز الأخف طاقته أكبر","التفسير بحجم الجسيم بدل كتلته","عدم ذكر شرط تساوي درجة الحرارة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T11:15:01.909Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1640, null, null, null, 'عمل الطالب غير صحيح؛ فقد أسقط «الجذر التربيعي» من نص القانون. النص الصحيح: معدل تدفق الغاز يتناسب عكسيًا مع الجذر التربيعي لكتلته المولية. والحساب الصحيح: معدل He ÷ معدل N₂ = √(28 ÷ 4) = √7 ≈ 2.65، أي أن الهيليوم أسرع بنحو 2.65 مرة لا 7 مرات.', '["تحديد الخطأ: نسيان الجذر التربيعي","كتابة النص الصحيح","الحساب الصحيح ≈ 2.65"]'::jsonb, '["معدل He ÷ معدل N₂ = √(M_N₂ ÷ M_He)","= √(28 ÷ 4) = √7 ≈ 2.65"]'::jsonb, '[{"element":"تحديد الخطأ","marks":1},{"element":"النص الصحيح","marks":1},{"element":"الحساب الصحيح","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"تحديد الخطأ وتصحيح النص والحساب"},{"level":"3 درجات","description":"تحديد الخطأ والنص مع خطأ حسابي بسيط"},{"level":"2 درجتان","description":"تحديد الخطأ والنص دون حساب"},{"level":"1 درجة","description":"تحديد الخطأ فقط"},{"level":"صفر","description":"تأييد عمل الطالب"}]'::jsonb, '["تأييد الطالب","تصحيح النص دون تصحيح الحساب","قلب النسبة داخل الجذر (0.38) دون تفسير اتجاهها"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T11:15:01.909Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
