(1642, 0, 'معدل CO ÷ معدل CO₂ = √(44 ÷ 28) = √1.57 ≈ 1.25.', '["","نُسي الجذر التربيعي (44 ÷ 28 = 1.57).","قُلبت النسبة: √(28 ÷ 44) ≈ 0.80."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-11T11:15:01.916Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1643, 1, 'الكتلة المولية لـ N₂ = 2 × 14 = 28 g/mol. معدل N₂ ÷ معدل Ne = √(20 ÷ 28) = √0.714 ≈ 0.845.', '["قُلبت النسبة: √(28 ÷ 20) ≈ 1.18 وهي نسبة معدل Ne إلى N₂.","","نُسي الجذر التربيعي (20 ÷ 28 = 0.714)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T11:15:01.917Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1644, 0, 'معدل X ÷ معدل He = √(4.0 ÷ M_X) = 0.378 ← 4.0 ÷ M_X = 0.143 ← M_X = 4.0 ÷ 0.143 ≈ 28 g/mol.', '["","نُسي تربيع النسبة (4.0 ÷ 0.378 ≈ 10.6).","ضُربت الكتلة في النسبة بدل القسمة (4.0 × 0.378 ≈ 1.5)، ولا يمكن أن يكون الغاز الأبطأ أخف من He."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-11T11:15:01.920Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1645, 2, 'معدل CH₄ ÷ معدل He = √(4.0 ÷ 16) = √0.25 = 0.50، أي أن الميثان ينتشر بنصف معدل الهيليوم.', '["قُلبت النسبة: √(16 ÷ 4.0) = 2.0 هي نسبة معدل He إلى CH₄.","نُسي الجذر التربيعي (4.0 ÷ 16 = 0.25).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-11T11:15:01.921Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1646, 1, 'NH₃ أقل كتلة مولية فينتشر أسرع (بنحو 1.47 مرة)، فيقطع مسافة أكبر قبل أن يلتقي HCl، فتتكون الحلقة أقرب إلى طرف HCl.', '["هذا يحدث لو كان HCl هو الأسرع، لكنه الأثقل فهو الأبطأ.","","لو تساوى المعدلان لتكونت في المنتصف، لكن الكتلتين الموليتين مختلفتان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-10-11T11:15:01.921Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1647, 2, 'تتساوى معدلات الانتشار عندما تتساوى الكتل المولية: √(28 ÷ 28) = 1.00.', '["√(32 ÷ 28) ≈ 1.07، فالنسبة ليست 1.00.","√(44 ÷ 28) ≈ 1.25، فالفرق كبير.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T11:15:01.921Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1648, null, null, null, '(أ) معدل CH₄ ÷ معدل SO₂ = √(64 ÷ 16) = √4 = 2.0، أي أن الميثان ينتشر أسرع بمرتين. (ب) في الزمن نفسه تتناسب المسافة مع المعدل، فمسافة SO₂ = 50 ÷ 2.0 = 25 cm.', '["التعويض الصحيح في قانون جراهام","النسبة = 2.0","المسافة تتناسب مع المعدل","مسافة SO₂ = 25 cm"]'::jsonb, '["معدل CH₄ ÷ معدل SO₂ = √(M_SO₂ ÷ M_CH₄)","= √(64 ÷ 16) = √4 = 2.0","مسافة SO₂ = 50 cm ÷ 2.0 = 25 cm"]'::jsonb, '[{"element":"(أ) التعويض","marks":1},{"element":"(أ) الناتج","marks":1},{"element":"(ب) الطريقة","marks":1},{"element":"(ب) الناتج","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حل كامل صحيح بالوحدات"},{"level":"3 درجات","description":"(أ) صحيح مع خطأ بسيط في (ب)"},{"level":"2 درجتان","description":"(أ) صحيح فقط"},{"level":"1 درجة","description":"كتابة القانون فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["نسيان الجذر (النسبة 4)","ضرب المسافة في 2.0 بدل القسمة","قلب النسبة داخل الجذر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T11:15:01.922Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1649, null, null, null, '(أ) الهيليوم؛ لأنه استغرق زمنًا أقل للحجم نفسه. (ب) المعدل يتناسب عكسيًا مع الزمن، فمعدل He ÷ معدل X = 39.8 ÷ 12.0 = 3.32. وبقانون جراهام: √(M_X ÷ 4.0) = 3.32 ← M_X ÷ 4.0 = 11.0 ← M_X ≈ 44 g/mol. (ج) CO₂.', '["He أسرع لأنه أقل زمنًا","نسبة المعدلين = 39.8 ÷ 12.0 = 3.32","تربيع النسبة وحساب M_X ≈ 44 g/mol","اختيار CO₂"]'::jsonb, '["معدل He ÷ معدل X = t_X ÷ t_He = 39.8 ÷ 12.0 = 3.32","√(M_X ÷ M_He) = 3.32 ← M_X ÷ 4.0 = (3.32)² = 11.0","M_X = 4.0 × 11.0 = 44 g/mol ← الغاز CO₂"]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب) نسبة المعدلين","marks":1},{"element":"(ب) الكتلة المولية","marks":2},{"element":"(ج)","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حل كامل صحيح"},{"level":"4 درجات","description":"خطأ بسيط في التقريب أو الوحدة"},{"level":"2–3 درجات","description":"نسبة المعدلين صحيحة مع خطأ في التربيع"},{"level":"1 درجة","description":"(أ) فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["اعتبار المعدل متناسبًا طرديًا مع الزمن","نسيان تربيع النسبة (M ≈ 13 g/mol)","قلب نسبة الأزمنة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T11:15:01.926Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1650, null, null, null, '(أ) معدل NH₃ ÷ معدل HCl = √(36.5 ÷ 17) = √2.15 ≈ 1.47. (ب) في الزمن نفسه تتناسب المسافتان مع المعدلين: d(NH₃) ÷ d(HCl) = 1.47، ومجموعهما 100 cm، فـ d(NH₃) = 100 × 1.47 ÷ (1 + 1.47) ≈ 59 cm من طرف الأمونيا (أي نحو 41 cm من طرف HCl).', '["التعويض في قانون جراهام","النسبة ≈ 1.47","المسافتان تتناسبان مع المعدلين ومجموعهما 100 cm","بُعد الحلقة ≈ 59 cm من طرف NH₃"]'::jsonb, '["معدل NH₃ ÷ معدل HCl = √(36.5 ÷ 17) ≈ 1.47","d(NH₃) = 1.47 × d(HCl)، وd(NH₃) + d(HCl) = 100 cm","d(NH₃) = 100 × 1.47 ÷ 2.47 ≈ 59 cm"]'::jsonb, '[{"element":"(أ) الناتج","marks":2},{"element":"(ب) فكرة التناسب","marks":1},{"element":"(ب) الناتج","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حل كامل صحيح"},{"level":"3 درجات","description":"(أ) صحيح وفكرة (ب) صحيحة مع خطأ حسابي"},{"level":"2 درجتان","description":"(أ) صحيح فقط"},{"level":"1 درجة","description":"كتابة القانون فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["افتراض أن الحلقة في المنتصف","قسمة 100 على 1.47 مباشرة (68 cm) دون مراعاة مجموع المسافتين","قلب النسبة فيُحسب البعد من طرف HCl على أنه من طرف NH₃"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-10-11T11:15:01.927Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1651, 0, 'الكثافة = الكتلة ÷ الحجم، أي كتلة وحدة الحجم من المادة.', '["","هذا مقلوب الكثافة.","هذا تعريف الضغط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-11T11:15:01.929Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1652, 1, 'لأن جسيمات الغاز متباعدة جدًا فمعظم حجم الغاز فراغ، فتكون الكتلة في وحدة الحجم صغيرة.', '["لجسيمات الغاز كتلة، والسبب هو التباعد لا انعدام الكتلة.","","لا توجد قوى تجاذب تُذكر بين جسيمات الغاز، ولو وُجدت لتقاربت الجسيمات وزادت الكثافة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (37%)"}],"at":"2026-10-11T11:15:01.930Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1653, 2, 'صغر حجم الجسيمات مقارنة بالمسافات الكبيرة بينها يعني أن معظم حجم الغاز فراغ فتنخفض الكثافة.', '["مرونة التصادمات تفسر استمرار الحركة لا الكثافة.","هذه الفرضية تتعلق بالطاقة الحركية لا بالكثافة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T11:15:01.930Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1654, 2, 'كثافة C (0.0032 g/cm³) أقل بكثير من كثافة المادتين الأخريين، والغازات كثافتها منخفضة جدًا لتباعد جسيماتها.', '["كثافة A (2.7 g/cm³) مرتفعة، وهي من رتبة كثافة المواد الصلبة.","كثافة B (1.0 g/cm³) من رتبة كثافة السوائل كالماء.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T11:15:01.930Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1655, 0, 'الكثافة = الكتلة ÷ الحجم = 6.4 g ÷ 4.48 L ≈ 1.43 g/L.', '["","قُسم الحجم على الكتلة (4.48 ÷ 6.4 = 0.70).","ضُربت الكتلة في الحجم (6.4 × 4.48 ≈ 28.7) بدل القسمة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T11:15:01.930Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1656, 1, 'الجزيء نفسه (H₂O) في الحالتين، لكن المسافات بين جزيئات البخار أكبر بكثير، فتقل الكتلة في وحدة الحجم.', '["كتلة جزيء H₂O واحدة في الحالتين.","","حجم الجزيء نفسه لا يتغير، وإنما تزداد المسافات بين الجزيئات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-11T11:15:01.931Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1657, 0, 'الكثافة = الكتلة ÷ الحجم؛ فثبات الكتلة ونقص الحجم بتقارب الجسيمات يزيد الكثافة.', '["","الضغط يقرّب الجسيمات لا يباعدها.","الكثافة تعتمد على الكتلة والحجم معًا، والحجم تغير."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T11:15:01.931Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1658, null, null, null, 'الكثافة هي الكتلة في وحدة الحجم. وتفترض نظرية الحركة الجزيئية أن حجم جسيمات الغاز صغير جدًا مقارنة بالمسافات الكبيرة بينها، فيكون معظم حجم الغاز فراغًا، وبذلك تكون كتلة الغاز في وحدة الحجم صغيرة جدًا، أي أن كثافته منخفضة. أما في السوائل والمواد الصلبة فالجسيمات متقاربة فتكون الكثافة أعلى.', '["تعريف الكثافة","ذكر فرضية تباعد الجسيمات/صغر حجمها","معظم حجم الغاز فراغ","المقارنة بالسوائل والمواد الصلبة"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"الفرضية","marks":1},{"element":"الاستنتاج","marks":1},{"element":"المقارنة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل مدعوم بالفرضية"},{"level":"3 درجات","description":"تفسير صحيح ينقصه عنصر"},{"level":"2 درجتان","description":"ذكر التباعد دون ربطه بالكثافة"},{"level":"1 درجة","description":"إشارة جزئية"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["القول إن جسيمات الغاز أخف من جسيمات السائل","تفسير الكثافة بسرعة الجسيمات","الخلط بين الكثافة والضغط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (37%)"}],"at":"2026-10-11T11:15:01.931Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1659, null, null, null, '(أ) 1 ÷ 0.003 ≈ 333 مرة تقريبًا (أي نحو 300 مرة). (ب) الكثافة لا تعتمد على كتلة الجزيء وحدها، بل على عدد الجسيمات في وحدة الحجم أيضًا؛ وجزيئات الكلور الغازي متباعدة جدًا فمعظم حجمه فراغ، فيحوي كل سنتيمتر مكعب منه عددًا قليلًا جدًا من الجزيئات مقارنة بالماء السائل المتقاربة جزيئاته، فتكون كتلة وحدة الحجم من الكلور أصغر.', '["حساب النسبة ≈ 333 مرة","الكثافة تعتمد على عدد الجسيمات في وحدة الحجم","تباعد جزيئات الغاز","تقارب جزيئات السائل"]'::jsonb, '["النسبة = 1 g/cm³ ÷ 0.003 g/cm³ ≈ 333"]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب) فكرة عدد الجسيمات في وحدة الحجم","marks":2},{"element":"(ب) المقارنة بالسائل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حساب صحيح وتفسير متكامل"},{"level":"3 درجات","description":"حساب صحيح وتفسير ناقص"},{"level":"2 درجتان","description":"تفسير صحيح دون حساب أو العكس مع إشارة جزئية"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["قسمة 0.003 على 1 (0.003 مرة)","القول إن الجزيء الأثقل يعطي دائمًا كثافة أكبر","إهمال المسافات بين الجزيئات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-11T11:15:01.932Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1660, null, null, null, '(أ) تمثل الخرز جسيمات المادة (الجزيئات). (ب) الكتلة نفسها (20 خرزة) تشغل في حالة الغاز حجمًا أكبر بعشر مرات، فتقل الكتلة في وحدة الحجم، أي تنخفض الكثافة؛ وهذا لأن المسافات بين جسيمات الغاز كبيرة ومعظم حجمه فراغ. (ج) لا يمثل النموذج الحركة المستمرة العشوائية لجسيمات الغاز وتصادماتها، أو أن المسافات الحقيقية بين جسيمات الغاز أكبر بكثير من ذلك.', '["الخرز تمثل الجسيمات","الكتلة نفسها في حجم أكبر ← كثافة أقل","الربط بالمسافات الكبيرة/الفراغ","ذكر قصور صحيح في النموذج"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":2},{"element":"(ج)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة"},{"level":"3 درجات","description":"(أ) و(ب) صحيحان مع قصور غير دقيق"},{"level":"2 درجتان","description":"(أ) صحيح و(ب) ناقص"},{"level":"1 درجة","description":"(أ) فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["القول إن الكتلة في نموذج الغاز أقل","عدم ربط النموذج بتعريف الكثافة","ذكر قصور غير متعلق بالغاز"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-11T11:15:01.932Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1661, 2, 'قابلية التمدد تعني أن الغاز يملأ الإناء الذي يوضع فيه مهما كان حجمه وشكله.', '["الغاز ليس له حجم ثابت؛ فحجمه هو حجم إنائه.","زيادة حجم الإناء لا تحول الغاز إلى سائل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T11:15:01.934Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1662, 1, 'الحركة المستمرة العشوائية مع انعدام قوى التجاذب تقريبًا تجعل الجسيمات تتحرك بحرية حتى تشغل الحيز المتاح كله.', '["لو تجاذبت الجسيمات بقوة لبقيت متقاربة ولم تملأ الإناء.","","هذا وصف جسيمات المادة الصلبة لا الغاز."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T11:15:01.934Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1663, 0, 'الغاز يتمدد ليملأ الإناء الذي يوضع فيه كاملًا، فيصبح حجمه 5 L (حجم الإناء الجديد).', '["","الغاز لا يحتفظ بحجم ثابت كالسوائل.","حجم الغاز لا يقل عند نقله إلى إناء أكبر، بل يملؤه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T11:15:01.935Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1664, 2, 'المادة Z ملأت الإناء الجديد كله واتخذت شكله، وهذا سلوك الغاز؛ فليس له حجم ثابت ولا شكل ثابت.', '["X احتفظت بشكلها وحجمها فهي مادة صلبة.","Y اتخذت شكل الإناء واحتفظت بحجمها فهي سائل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T11:15:01.935Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1665, 0, 'الغاز يملأ الإناء الذي يوضع فيه عند أي درجة حرارة لأن جسيماته في حركة مستمرة؛ والتسخين يزيد سرعة الجسيمات لكنه ليس شرطًا للتمدد.', '["","جسيمات الغاز البارد ما زالت تتحرك باستمرار فلا تتجمع في القاع.","جسيمات الغاز لا تتوقف عن الحركة بالتبريد العادي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-11T11:15:01.935Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1666, 1, 'جسيمات السائل تربطها قوى تجاذب تُبقيها متقاربة فيثبت حجمه، أما جسيمات الغاز فلا تجاذب يُذكر بينها فتتحرك بحرية وتملأ الإناء.', '["الفرق ليس في حجم الجسيمات بل في قوى التجاذب والمسافات بينها.","","جسيمات الغاز في حركة مستمرة، بل أكثر حرية من جسيمات السائل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T11:15:01.935Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1667, 2, 'بسبب قابلية التمدد يتحرك الغاز بحرية حتى يشغل الحيز المتاح كله، فيتوزع في الغرفة.', '["جسيمات الغاز لا تبقى متجمعة لعدم وجود تجاذب يُذكر بينها.","جسيمات الغاز تتحرك عشوائيًا في كل الاتجاهات، لا نحو القاع فقط.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T11:15:01.935Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1668, null, null, null, 'جسيمات الغاز في حركة مستمرة عشوائية في خطوط مستقيمة، ولا توجد بينها قوى تجاذب تُذكر تُبقيها متقاربة، فتتحرك بحرية حتى تشغل الحيز المتاح كله؛ لذلك يملأ الغاز أي إناء يوضع فيه وليس له شكل ثابت ولا حجم ثابت. مثال: عند فتح قارورة غاز في غرفة يتوزع الغاز في أرجائها، أو امتلاء البالون بالهواء من جميع جهاته.', '["الحركة المستمرة العشوائية","انعدام قوى التجاذب تقريبًا","الغاز يملأ الإناء/لا شكل ولا حجم ثابت","مثال صحيح"]'::jsonb, '[]'::jsonb, '[{"element":"الحركة المستمرة","marks":1},{"element":"انعدام التجاذب","marks":1},{"element":"النتيجة","marks":1},{"element":"المثال","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل مع مثال"},{"level":"3 درجات","description":"تفسير كامل دون مثال أو بعنصر ناقص"},{"level":"2 درجتان","description":"ذكر أحد سببي التمدد مع النتيجة"},{"level":"1 درجة","description":"وصف الخاصية دون تفسير"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["تفسير التمدد بتمدد الجسيمات نفسها","ربط التمدد بالتسخين فقط","ذكر الانضغاط بدل التمدد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T11:15:01.936Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1669, null, null, null, '(أ) الشكل: كلاهما يأخذ شكل الإناء. (ب) الحجم: للسائل حجم ثابت، أما الغاز فيملأ الإناء فحجمه حجم الإناء. (ج) قوى التجاذب: بين جسيمات السائل قوى تجاذب تُبقيها متقاربة، أما بين جسيمات الغاز فلا تُذكر. الاستنتاج: لأن جسيمات الغاز لا تجاذب يُذكر بينها وهي في حركة مستمرة، فتتحرك بحرية وتملأ الإناء (تتمدد)، بينما قوى التجاذب في السائل تمنعه من التمدد.', '["الشكل","الحجم","قوى التجاذب","الاستنتاج"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":1},{"element":"(ج)","marks":1},{"element":"الاستنتاج","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"مقارنة كاملة مع استنتاج صحيح"},{"level":"4 درجات","description":"مقارنة كاملة مع استنتاج ناقص"},{"level":"3 درجات","description":"مقارنة كاملة دون استنتاج"},{"level":"1–2 درجة","description":"عنصر أو عنصران من المقارنة"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["القول إن للغاز شكلًا ثابتًا","القول إن السائل يملأ الإناء كله","إغفال دور قوى التجاذب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T11:15:01.937Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1670, null, null, null, '(أ) 2 L؛ لأن الغاز يتمدد ليملأ الإناء كله بسبب حركة جسيماته المستمرة وانعدام التجاذب بينها تقريبًا (لكن عدد جسيماته في كل mL يقل). (ب) لا؛ فجسيمات الغاز تبقى في حركة مستمرة عشوائية عند التبريد ولا توجد قوى تجاذب تجمعها، فتظل تملأ القارورة (وإن قلت سرعتها). (ج) يخرج الغاز ويتوزع في أرجاء الغرفة لأنه يتمدد ليشغل الحيز المتاح.', '["حجم الغاز 2 L مع التعليل","لا يتجمع في القاع مع التعليل","يتوزع في الغرفة"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":2},{"element":"(ب)","marks":2},{"element":"(ج)","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابات صحيحة معللة"},{"level":"4 درجات","description":"خطأ في تعليل واحد"},{"level":"2–3 درجات","description":"إجابتان صحيحتان دون تعليل كافٍ"},{"level":"1 درجة","description":"إجابة واحدة صحيحة"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["القول إن حجم الغاز يبقى 50 mL","القول إن الغاز البارد يتجمع في القاع","القول إن الغاز يبقى في القارورة بعد فتحها"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T11:15:01.938Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1671, 1, 'الانضغاط هو إمكانية تقليل حجم الغاز عند الضغط عليه.', '["الضغط لا يغير كتلة الغاز.","","هذا تعريف التدفق."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T11:15:01.940Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1672, 0, 'المسافات (الفراغات) الكبيرة بين جسيمات الغاز تسمح بتقريبها عند الضغط فيقل الحجم.', '["","حجم الجسيم نفسه لا يتغير؛ الذي يقل هو المسافات بينها.","لا توجد قوى تجاذب تُذكر بين جسيمات الغاز."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-10-11T11:15:01.940Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1673, 2, 'عند الانضغاط تقترب الجسيمات بعضها من بعض فتقل المسافات بينها، أما حجم الجسيم نفسه وعددها فلا يتغيران.', '["مفهوم خاطئ شائع؛ فالجسيمات لا تنكمش.","الأسطوانة مغلقة فعدد الجسيمات ثابت.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:01.940Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1674, 2, 'الحجم في المحقنة 3 نقص كثيرًا (من 50 mL إلى 20 mL)، والغازات قابلة للانضغاط بدرجة كبيرة لتباعد جسيماتها.', '["حجم المحقنة 1 لم يتغير تقريبًا، وهذا سلوك السائل.","حجم المحقنة 2 لم يتغير، وهذا سلوك مادة صلبة أو سائل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T11:15:01.941Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1675, 1, 'المسافات بين جزيئات السائل صغيرة جدًا فلا يمكن تقريبها كثيرًا، بخلاف الهواء الذي بين جسيماته فراغات كبيرة.', '["صعوبة الانضغاط سببها صغر المسافات لا كتلة الجزيئات.","","جزيئات السائل تتحرك، لكن المسافات بينها صغيرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T11:15:01.941Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1676, 0, 'تُضغط كمية كبيرة من الهواء في أسطوانة الغوص الصغيرة بفضل قابلية الغاز للانضغاط.', '["","المياه سائل لا يقبل الانضغاط تقريبًا، والخزانات لا تعتمد على ذلك.","صب الفلز المنصهر يعتمد على ميوعة السائل لا على الانضغاط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-10-11T11:15:01.941Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1677, 1, 'لأن حجم الجسيمات صغير والمسافات بينها كبيرة، فمعظم حجم الغاز فراغ يمكن تقليله بالضغط.', '["هذه الفرضية تتعلق بالطاقة الحركية لا بالانضغاط.","","مرونة التصادمات تفسر استمرار الحركة لا الانضغاط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-10-11T11:15:01.941Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1678, null, null, null, 'تفترض النظرية أن حجم جسيمات الغاز صغير جدًا مقارنة بالمسافات الكبيرة بينها، فمعظم حجم الغاز فراغ؛ فعند الضغط على الغاز تقترب الجسيمات بعضها من بعض فتقل المسافات بينها ويقل حجم الغاز. تطبيق: تعبئة الغاز في أسطوانات الطبخ أو أسطوانات الغوص أو إطارات السيارات.', '["المسافات الكبيرة بين الجسيمات","اقتراب الجسيمات عند الضغط","نقص الحجم","تطبيق صحيح"]'::jsonb, '[]'::jsonb, '[{"element":"المسافات الكبيرة","marks":1},{"element":"اقتراب الجسيمات ونقص الحجم","marks":2},{"element":"التطبيق","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل مع تطبيق"},{"level":"3 درجات","description":"تفسير كامل دون تطبيق"},{"level":"2 درجتان","description":"ذكر المسافات الكبيرة فقط مع تطبيق"},{"level":"1 درجة","description":"عنصر واحد"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["القول إن الجسيمات تنكمش","تفسير الانضغاط بمرونة التصادمات","ذكر تطبيق لا علاقة له بالانضغاط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-10-11T11:15:01.941Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1679, null, null, null, '(أ) يقل حجم الهواء بوضوح (مثلًا إلى 20 mL)، أما حجم الماء فلا يتغير تقريبًا. (ب) بين جزيئات الهواء مسافات كبيرة يمكن تقليلها بالضغط، أما جزيئات الماء فمتقاربة والمسافات بينها صغيرة جدًا فلا ينضغط تقريبًا. (ج) لا؛ لأن المحقنة مغلقة، فالذي تغير هو المسافات بين الجزيئات لا عددها.', '["الهواء ينضغط والماء لا ينضغط تقريبًا","تفسير بالمسافات الكبيرة في الغاز","تفسير بتقارب الجزيئات في السائل","عدد الجزيئات ثابت مع التعليل"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":2},{"element":"(ج)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة"},{"level":"3 درجات","description":"توقع وتفسير صحيحان مع خطأ في (ج)"},{"level":"2 درجتان","description":"التوقع مع تفسير ناقص"},{"level":"1 درجة","description":"التوقع فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["توقع أن الماء ينضغط بسهولة","القول إن جزيئات الهواء تصغر","القول إن عدد الجزيئات يقل بالضغط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T11:15:01.942Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1680, null, null, null, 'العبارة خاطئة؛ فحجم الجزيء نفسه لا يتغير عند الضغط، وإنما تقل المسافات بين الجزيئات لأنها كبيرة أصلًا ومعظم حجم الغاز فراغ. الصحيح: «عند ضغط الغاز تقترب جزيئاته بعضها من بعض فتقل المسافات بينها فيقل حجمه». ولا يمكن ضغطه إلى الصفر لأن للجزيئات نفسها حجمًا (وإن كان صغيرًا)، فعندما تتلاصق لا يمكن تقليل الحجم أكثر.', '["الحكم بخطأ العبارة","حجم الجزيء ثابت والمسافات هي التي تقل","صياغة العبارة الصحيحة","للجزيئات حجم فلا يصل الحجم إلى الصفر"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم والتعليل","marks":2},{"element":"التصحيح","marks":1},{"element":"تفسير عدم الوصول إلى الصفر","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تقويم وتصحيح وتفسير كاملة"},{"level":"3 درجات","description":"تقويم وتصحيح صحيحان دون الجزء الأخير"},{"level":"2 درجتان","description":"حكم صحيح مع تعليل"},{"level":"1 درجة","description":"حكم صحيح فقط"},{"level":"صفر","description":"تأييد العبارة"}]'::jsonb, '["تأييد العبارة","القول إن الجزيئات تختفي عند الضغط","القول إن الغاز يمكن ضغطه بلا حد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:01.942Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1681, 2, 'الضغط هو القوة الواقعة على وحدة المساحة، P = F/A.', '["هذا تعريف الكثافة.","هذا تعريف السرعة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:01.944Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1682, 0, 'الضغط = القوة ÷ المساحة، أي P = F/A.', '["","قُلبت العلاقة؛ فالمساحة في المقام.","الضغط ليس حاصل ضرب القوة في المساحة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:01.944Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1683, 1, 'كل تصادم لجسيم غاز بالجدار يؤثر بقوة صغيرة، ومجموع هذه القوى على وحدة المساحة هو ضغط الغاز.', '["جسيمات الغاز تتحرك وتصطدم بالجدران ولا تلتصق بها.","","لا توجد قوى تجاذب تُذكر بين جسيمات الغاز، والضغط ناتج عن التصادمات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-11T11:15:01.945Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1684, 0, 'P = F/A = 500 N ÷ 0.25 m² = 2000 Pa = 2.0×10³ Pa.', '["","ضُربت القوة في المساحة (500 × 0.25 = 125) بدل القسمة.","قُسمت المساحة على القوة (0.25 ÷ 500)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T11:15:01.945Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1685, 2, 'بما أن P = F/A فوحدة الضغط هي N/m²، والباسكال يساوي نيوتنًا واحدًا على متر مربع.', '["الضغط قسمة القوة على المساحة لا ضربهما.","kg/m³ وحدة كثافة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T11:15:01.945Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1686, 1, 'P(1) = 600 ÷ 0.040 = 1.5×10⁴ Pa، P(2) = 600 ÷ 0.020 = 3.0×10⁴ Pa، P(3) = 300 ÷ 0.040 = 7.5×10³ Pa؛ فالحالة 2 أكبر لأن القوة نفسها تؤثر على مساحة أصغر.', '["P(1) = 1.5×10⁴ Pa، وهو نصف الضغط في الحالة 2 لأن المساحة ضعفها.","","P(3) = 7.5×10³ Pa وهو الأقل؛ قوة صغيرة على مساحة كبيرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T11:15:01.945Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1687, 0, 'زيادة عدد جسيمات الهواء في الحجم نفسه تزيد عدد تصادماتها بالجدران في كل ثانية، فيزداد الضغط.', '["","حجم الجسيم لا يتغير بنفخ الهواء.","الجسيمات لا تلتصق بالجدران، والضغط ناتج عن تصادمها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-10-11T11:15:01.946Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1688, null, null, null, '(أ) الضغط: القوة الواقعة على وحدة المساحة، P = F/A، حيث F القوة بالنيوتن (N)، وA المساحة بالمتر المربع (m²)، وP الضغط بالباسكال (Pa = N/m²). (ب) جسيمات الغاز في حركة مستمرة عشوائية فتتصادم باستمرار بجدران الإناء، وكل تصادم يؤثر بقوة صغيرة على الجدار، ومجموع هذه القوى على وحدة المساحة هو ضغط الغاز.', '["تعريف الضغط","العلاقة P = F/A","الوحدات (N، m²، Pa)","التفسير بتصادم الجسيمات بالجدران"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"العلاقة","marks":1},{"element":"الوحدات","marks":1},{"element":"التفسير","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"2 درجتان","description":"عنصران صحيحان"},{"level":"1 درجة","description":"عنصر واحد"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["تعريف الضغط بالقوة فقط دون المساحة","قلب العلاقة","تفسير الضغط بوزن الغاز أو تجاذب جسيماته"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-11T11:15:01.946Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1689, null, null, null, '(أ) P = F/A = 600 ÷ 0.040 = 1.5×10⁴ Pa. (ب) P = 600 ÷ 0.020 = 3.0×10⁴ Pa. (ج) عند ثبات القوة يتناسب الضغط عكسيًا مع المساحة؛ فعندما قلت المساحة إلى النصف تضاعف الضغط.', '["P = 1.5×10⁴ Pa","P = 3.0×10⁴ Pa","الضغط يتناسب عكسيًا مع المساحة"]'::jsonb, '["P = F/A","(أ) P = 600 N ÷ 0.040 m² = 15000 Pa = 1.5×10⁴ Pa","(ب) P = 600 N ÷ 0.020 m² = 30000 Pa = 3.0×10⁴ Pa","(ج) نصف المساحة ← ضعف الضغط"]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":1},{"element":"(ج)","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"حسابان صحيحان واستنتاج صحيح"},{"level":"3 درجات","description":"حسابان صحيحان واستنتاج ناقص"},{"level":"2 درجتان","description":"حسابان دون استنتاج"},{"level":"1 درجة","description":"حساب واحد صحيح"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["ضرب القوة في المساحة","نسيان الوحدة","استنتاج أن الضغط يتناسب طرديًا مع المساحة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T11:15:01.946Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1690, null, null, null, '(أ) F = P × A = 101.3×10³ Pa × 0.50 m² = 5.07×10⁴ N. (ب) لأن الهواء يؤثر على السطح السفلي للطاولة أيضًا بضغط مساوٍ تقريبًا، فتتوازن القوى. (ج) لا؛ فضغط الغاز يؤثر في جميع الاتجاهات لأن جسيمات الهواء تتحرك عشوائيًا في كل الاتجاهات وتتصادم بالأسطح من كل جهة.', '["تحويل kPa إلى Pa","F = 5.07×10⁴ N","توازن القوى من الجهتين","الضغط يؤثر في جميع الاتجاهات مع التعليل"]'::jsonb, '["F = P × A","101.3 kPa = 101300 Pa","F = 101300 × 0.50 = 50650 N ≈ 5.07×10⁴ N"]'::jsonb, '[{"element":"(أ) التحويل والتعويض","marks":1},{"element":"(أ) الناتج","marks":1},{"element":"(ب)","marks":1},{"element":"(ج)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة"},{"level":"3 درجات","description":"حساب صحيح مع خطأ في أحد التفسيرين"},{"level":"2 درجتان","description":"حساب صحيح فقط"},{"level":"1 درجة","description":"التعويض دون التحويل الصحيح"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["نسيان تحويل kPa إلى Pa (الناتج 50.65 N)","قسمة الضغط على المساحة","القول إن ضغط الهواء يؤثر إلى أسفل فقط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T11:15:01.947Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1691, 1, 'الجاذبية تسحب جسيمات الهواء نحو سطح الأرض فتتجمع معظمها قريبًا منه، ووزن عمود الهواء فوق السطح هو سبب الضغط الجوي.', '["الجاذبية تجذب نحو الأرض لا تدفع بعيدًا عنها.","","جسيمات الهواء تبقى في حركة مستمرة؛ والجاذبية لا توقفها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (55%)"}],"at":"2026-10-11T11:15:01.949Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1692, 2, 'كلما ارتفعنا قصر عمود الهواء فوقنا وقل عدد جسيماته (الهواء أقل كثافة)، فيقل عدد التصادمات ويقل الضغط.', '["مفهوم خاطئ شائع؛ فالجاذبية لا تنعدم على قمم الجبال.","كتلة جسيمات الهواء لا تتغير بالارتفاع.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T11:15:01.949Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1693, 0, 'عند مستوى سطح البحر يكون عمود الهواء فوق المكان أطول وعدد جسيمات الهواء في وحدة الحجم أكبر بسبب سحب الجاذبية لها نحو الأرض.', '["","على قمة الجبل يكون عمود الهواء أقصر والهواء أقل كثافة.","على الارتفاعات العالية يكون الهواء مخلخلًا والضغط منخفضًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T11:15:01.950Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1694, 1, 'تتناقص قيم الضغط من 101.3 kPa عند سطح البحر إلى 34 kPa عند 8800 m، فالضغط يقل بزيادة الارتفاع لقلة جسيمات الهواء فوق المكان.', '["القيم في الجدول تتناقص لا تتزايد.","","القيم تتغير بانتظام مع الارتفاع، فثمة علاقة واضحة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T11:15:01.950Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1695, 0, 'الجاذبية هي التي تُبقي جسيمات الهواء متجمعة قرب سطح الأرض؛ فإذا ضعفت قل عدد الجسيمات قرب السطح وقل وزن عمود الهواء فيقل الضغط.', '["","ضعف الجاذبية يجعل الهواء أقل تجمعًا قرب السطح فيقل الضغط لا يزداد.","الضغط الجوي ينشأ أساسًا بسبب جذب الجاذبية لجسيمات الهواء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-11T11:15:01.950Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1696, 2, 'مع الارتفاع يقل الضغط الجوي الخارجي فيصبح ضغط الهواء داخل الأذن أكبر منه، فيحدث الإحساس بالألم.', '["الضغط الجوي يقل لا يزداد مع الارتفاع.","الجاذبية لا تزداد بالارتفاع، بل تقل قليلًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T11:15:01.951Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1697, 1, 'تسحب الجاذبية جسيمات الهواء نحو سطح الأرض فيتركز معظمها في الطبقات القريبة من السطح، فيقل عدد الجسيمات في وحدة الحجم كلما ارتفعنا.', '["الجاذبية تسحب نحو الأرض فتتجمع الجسيمات في الطبقات السفلى.","","الجاذبية تؤثر في جسيمات الهواء في كل الارتفاعات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T11:15:01.951Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1698, null, null, null, 'تسحب الجاذبية الأرضية جسيمات الهواء نحو سطح الأرض، فيتجمع معظمها قرب السطح، ويكون لعمود الهواء فوق أي سطح وزن يسبب الضغط الجوي (وتتصادم جسيمات الهواء بالأسطح). وفي المرتفعات يكون عمود الهواء فوق المكان أقصر وعدد جسيمات الهواء فيه أقل (الهواء أقل كثافة)، فيقل عدد التصادمات ويقل الضغط الجوي.', '["الجاذبية تسحب جسيمات الهواء نحو الأرض","وزن عمود الهواء/تجمع الجسيمات قرب السطح يسبب الضغط","في المرتفعات عمود الهواء أقصر وعدد الجسيمات أقل","يقل عدد التصادمات فيقل الضغط"]'::jsonb, '[]'::jsonb, '[{"element":"دور الجاذبية","marks":2},{"element":"تعليل انخفاض الضغط","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"تفسير وتعليل كاملان"},{"level":"3 درجات","description":"تفسير كامل وتعليل ناقص أو العكس"},{"level":"2 درجتان","description":"أحد الجزأين كامل"},{"level":"1 درجة","description":"إشارة جزئية صحيحة"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["القول إن الجاذبية تنعدم في المرتفعات","تفسير انخفاض الضغط بانخفاض درجة الحرارة فقط","القول إن جسيمات الهواء أثقل عند السطح"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (55%)"}],"at":"2026-10-11T11:15:01.951Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1699, null, null, null, '(أ) المدينة A الساحلية. (ب) الجاذبية تسحب جسيمات الهواء نحو سطح الأرض، فيكون عمود الهواء فوق المدينة الساحلية أطول ويحوي جسيمات أكثر، فيكون وزنه وعدد التصادمات أكبر فيرتفع الضغط؛ أما المدينة المرتفعة فعمود الهواء فوقها أقصر. (ج) المدينة A؛ لأن الهواء قرب سطح البحر أكثر كثافة (جسيمات أكثر في وحدة الحجم).', '["المدينة A","التفسير بسحب الجاذبية وطول عمود الهواء","المدينة A لكثافة الهواء الأعلى"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":2},{"element":"(ج)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة معللة"},{"level":"3 درجات","description":"(أ) و(ج) صحيحان مع تفسير ناقص"},{"level":"2 درجتان","description":"(أ) و(ج) دون تفسير"},{"level":"1 درجة","description":"(أ) فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["اختيار المدينة المرتفعة لأنها «أقرب إلى الهواء»","إغفال دور الجاذبية في التفسير","القول إن عدد الجسيمات متساوٍ في المدينتين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:01.951Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1700, null, null, null, 'العبارة خاطئة؛ فالجاذبية الأرضية لا تنعدم على قمم الجبال، بل تبقى مؤثرة تقريبًا بالمقدار نفسه. والتفسير الصحيح: الجاذبية تسحب معظم جسيمات الهواء نحو سطح الأرض فتتركز في الطبقات السفلى، وعلى قمة الجبل يكون عمود الهواء فوق المكان أقصر وعدد جسيمات الهواء أقل (الهواء مخلخل)، فيقل وزن عمود الهواء وعدد التصادمات فيقل الضغط الجوي.', '["الحكم بخطأ العبارة","الجاذبية لا تنعدم على قمم الجبال","التفسير الصحيح: عمود هواء أقصر وجسيمات أقل","ربط ذلك بانخفاض الضغط"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم وتعليله","marks":2},{"element":"التفسير الصحيح","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"تقويم صحيح وتفسير كامل"},{"level":"3 درجات","description":"تقويم صحيح وتفسير ناقص"},{"level":"2 درجتان","description":"حكم صحيح مع تعليل دون تفسير بديل"},{"level":"1 درجة","description":"حكم صحيح فقط"},{"level":"صفر","description":"تأييد العبارة"}]'::jsonb, '["تأييد العبارة","القول إن الجاذبية أقوى على قمة الجبل","تفسير الانخفاض بزيادة سرعة الرياح"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T11:15:01.952Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1701, 0, 'الضغط الجوي هو الضغط الناتج عن تصادم جسيمات الهواء (مكونات الغلاف الجوي) بجميع الأسطح المعرضة له.', '["","هذا وصف ضغط غاز محصور في إناء لا الضغط الجوي.","قطرات المطر ليست سبب الضغط الجوي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T11:15:01.954Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1702, 2, 'الضغط الجوي عند مستوى سطح البحر = 1 atm = 101.3 kPa = 760 mmHg.', '["خُلط بين 760 mmHg و76.0 kPa.","خطأ في موضع الفاصلة العشرية؛ 1.013 قريبة من قيمته بالبار لا بالكيلوباسكال.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-11T11:15:01.954Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1703, 1, '1 atm = 760 mmHg = 760 torr.', '["101.3 هي القيمة بوحدة kPa.","","14.7 هي القيمة بوحدة psi."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-11T11:15:01.954Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1704, 0, 'P = 84.0 kPa × (1 atm ÷ 101.3 kPa) = 0.829 atm.', '["","قُسم 101.3 على 84.0 (معامل التحويل مقلوب)، فنتج ضغط أكبر من ضغط سطح البحر، وهذا غير منطقي.","ضُرب 84.0 في 101.3 بدل القسمة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-11T11:15:01.955Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1705, 2, 'جسيمات الهواء تتحرك عشوائيًا في كل الاتجاهات وتتصادم بالأسطح من كل جهة، فيؤثر الضغط الجوي في جميع الاتجاهات.', '["مفهوم خاطئ؛ فالضغط الجوي لا يؤثر إلى أسفل فقط.","الضغط لا يقتصر على اتجاه واحد.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T11:15:01.955Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1706, 1, 'المكان L قراءته 101.0 kPa وهي الأقرب إلى الضغط المعياري عند سطح البحر (101.3 kPa)؛ والضغط يقل كلما ارتفعنا.', '["قراءة K (79.5 kPa) منخفضة فهو مرتفع عن سطح البحر.","","قراءة M (92.0 kPa) أقل من 101.3 kPa فهو أعلى من L."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-11T11:15:01.955Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1707, 0, 'قبل التفريغ يتوازن ضغط الهواء داخل العلبة مع الضغط الجوي خارجها؛ وبعد التفريغ يقل الضغط داخلها فيدفع الضغط الجوي الخارجي جدرانها إلى الداخل.', '["","لو كان الضغط الداخلي أكبر لانتفخت العلبة لا انبعجت.","الضغط الجوي لا ينعدم حول العلبة؛ فهي ما زالت محاطة بالهواء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T11:15:01.955Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1708, null, null, null, '(أ) الضغط الجوي: الضغط الناتج عن تصادم جسيمات الهواء (مكونات الغلاف الجوي) بجميع الأسطح المعرضة له. (ب) 1 atm = 101.3 kPa = 760 mmHg (= 760 torr). (ج) لأن جسيمات الهواء تتحرك حركة عشوائية في جميع الاتجاهات، فتتصادم بالأسطح من كل جهة.', '["تعريف الضغط الجوي","1 atm","101.3 kPa","760 mmHg","التعليل بالحركة العشوائية"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"القيم الثلاث","marks":2},{"element":"التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة"},{"level":"3 درجات","description":"التعريف والقيم مع تعليل ناقص"},{"level":"2 درجتان","description":"التعريف وقيمة واحدة أو القيم فقط"},{"level":"1 درجة","description":"عنصر واحد"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["تعريف الضغط الجوي بضغط غاز محصور","كتابة 760 kPa بدل 760 mmHg","القول إن الضغط الجوي يؤثر إلى أسفل فقط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-10-11T11:15:01.956Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1709, null, null, null, '(أ) 84.0 kPa × (1 atm ÷ 101.3 kPa) = 0.829 atm. (ب) 84.0 kPa × (760 mmHg ÷ 101.3 kPa) = 630 mmHg. (ج) لأن المدينة مرتفعة عن سطح البحر فيكون عمود الهواء فوقها أقصر وعدد جسيمات الهواء أقل، فيقل عدد التصادمات ويقل الضغط الجوي.', '["التحويل إلى atm = 0.829","التحويل إلى mmHg = 630","التفسير بقلة جسيمات الهواء في المرتفعات"]'::jsonb, '["84.0 kPa × (1 atm ÷ 101.3 kPa) = 0.829 atm","84.0 kPa × (760 mmHg ÷ 101.3 kPa) = 630 mmHg"]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":1},{"element":"(ج)","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"تحويلان صحيحان وتفسير كامل"},{"level":"3 درجات","description":"تحويلان صحيحان وتفسير ناقص"},{"level":"2 درجتان","description":"تحويلان دون تفسير"},{"level":"1 درجة","description":"تحويل واحد صحيح"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["قلب معامل التحويل","ضرب 84.0 في 760 مباشرة دون القسمة على 101.3","تفسير الانخفاض بانعدام الجاذبية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-11T11:15:01.956Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1710, null, null, null, '(أ) قوة الضغط الجوي المؤثرة على البطاقة من أسفل. (ب) جسيمات الهواء تتصادم بالبطاقة من أسفل فتؤثر عليها بضغط جوي (≈101.3 kPa) قوته أكبر من وزن الماء الضاغط عليها من أعلى، فتبقى البطاقة ملتصقة ولا ينسكب الماء. (ج) الضغط الجوي يؤثر في جميع الاتجاهات، ومنها إلى أعلى.', '["تحديد الضغط الجوي من أسفل","المقارنة بين قوة الضغط الجوي ووزن الماء","الضغط الجوي يؤثر في جميع الاتجاهات"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":2},{"element":"(ج)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة"},{"level":"3 درجات","description":"(أ) و(ب) صحيحان دون (ج)"},{"level":"2 درجتان","description":"(أ) صحيح مع تفسير ناقص"},{"level":"1 درجة","description":"(أ) فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["تفسير الظاهرة بالتصاق الماء بالورق فقط","القول إن الضغط الجوي يؤثر إلى أسفل فقط","إغفال المقارنة مع وزن الماء"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T11:15:01.958Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
