(1714, 2, 'ارتفاع عمود الزئبق في البارومتر يتناسب مع الضغط الجوي، وأقصر عمود (630 mm) في المكان 3 فضغطه أقل.', '["عمود المكان 1 (760 mm) هو الأطول فضغطه الأعلى (مستوى سطح البحر).","عمود المكان 2 (700 mm) أطول من المكان 3 فضغطه أكبر.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:01.961Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1715, 0, '740 mmHg × (1 atm ÷ 760 mmHg) = 0.974 atm.', '["","قُلب معامل التحويل (760 ÷ 740)، فنتج ضغط أكبر من 1 atm مع أن العمود أقصر من 760 mm.","قُسم على 1000 بدل 760."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T11:15:01.961Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1716, 1, 'في المانومتر مغلق الطرف يُحدَّد ضغط الغاز من الفرق بين ارتفاعي الزئبق في الذراعين مباشرة: 250 mmHg.', '["760 mmHg هو الضغط الجوي عند سطح البحر، والمانومتر لا يقيسه.","","طُرح الفرق من 760 دون مبرر؛ فالطرف مغلق ولا يدخل الضغط الجوي في الحساب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:01.961Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1717, 0, 'ضغط الغاز المحصور في الأسطوانة يُقاس بالمانومتر، والضغط الجوي يُقاس بالبارومتر.', '["","عُكس الجهازان.","البارومتر لا يقيس ضغط غاز محصور في وعاء مغلق."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:01.962Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1718, null, null, null, 'البارومتر: (أ) يقيس الضغط الجوي. (ب) أنبوب زجاجي طويل مملوء بالزئبق ومنكس في حوض من الزئبق. (ج) يُحدَّد الضغط من ارتفاع عمود الزئبق في الأنبوب (760 mm عند سطح البحر). المانومتر: (أ) يقيس ضغط غاز محصور في وعاء مغلق. (ب) أنبوب على شكل حرف U يحتوي على الزئبق ويتصل أحد طرفيه بالوعاء. (ج) يُحدَّد الضغط من الفرق بين ارتفاعي الزئبق في ذراعي الأنبوب.', '["استخدام كل جهاز","تركيب البارومتر","تركيب المانومتر","طريقة القراءة لكل منهما"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) الاستخدام","marks":2},{"element":"(ب) التركيب","marks":2},{"element":"(ج) طريقة القياس","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"مقارنة كاملة دقيقة"},{"level":"4–5 درجات","description":"مقارنة صحيحة في بندين وناقصة في الثالث"},{"level":"2–3 درجات","description":"الاستخدام صحيح مع بند آخر ناقص"},{"level":"1 درجة","description":"استخدام جهاز واحد فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["تبديل استخدامي الجهازين","القول إن المانومتر يقيس الضغط الجوي","وصف البارومتر بأنه أنبوب على شكل U"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T11:15:01.962Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1719, null, null, null, '(أ) البارومتر (الزئبقي)، ويقيس الضغط الجوي. (ب) لأن الضغط الجوي المؤثر على سطح الزئبق في الحوض عند سطح البحر يعادل ضغط عمود من الزئبق ارتفاعه 760 mm، فيهبط الزئبق في الأنبوب حتى يتساوى الضغطان. (ج) يقل ارتفاع العمود؛ لأن الضغط الجوي على قمة الجبل أقل (عمود الهواء فوقه أقصر)، فيوازن عمودًا أقصر من الزئبق.', '["البارومتر","يقيس الضغط الجوي","توازن عمود الزئبق مع الضغط الجوي","يقل الارتفاع على قمة الجبل لانخفاض الضغط"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":1},{"element":"(ج)","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة معللة"},{"level":"3 درجات","description":"(أ) و(ج) صحيحان مع تفسير ناقص لـ(ب)"},{"level":"2 درجتان","description":"(أ) و(ج) دون تعليل"},{"level":"1 درجة","description":"(أ) فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["تسمية الجهاز مانومتر","توقع زيادة ارتفاع العمود على قمة الجبل","القول إن الزئبق يهبط تمامًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:01.962Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
