begin;
التركيب: P في الوسط مرتبطة بخمس ذرات Cl بروابط أحادية، وعلى كل Cl ثلاثة أزواج حرة.
عدد الإلكترونات حول P = 5 × 2 = 10 إلكترونات، أي أكثر من ثمانية (تمدد الثمانية).', '["مجموع الإلكترونات 40","خمس روابط أحادية P–Cl","ثلاثة أزواج حرة على كل Cl","لا زوج حر على P","10 إلكترونات حول P"]'::jsonb, '["مجموع الإلكترونات = 5 + 5(7) = 40 (20 زوجًا)","5 أزواج رابطة","15 زوجًا حرًا (3 على كل Cl)","حول P: 5 × 2 = 10"]'::jsonb, '[{"element":"حساب الإلكترونات والأزواج","marks":1},{"element":"الروابط والأزواج الحرة","marks":2},{"element":"عدد الإلكترونات حول P","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"خطوات ورسم صحيحان وحساب صحيح للإلكترونات حول P"},{"level":"3 درجات","description":"رسم صحيح مع خطأ في عدد الإلكترونات حول P"},{"level":"2 درجتان","description":"حساب صحيح للمجموع مع رسم ناقص الأزواج الحرة"},{"level":"1 درجة","description":"حساب مجموع الإلكترونات فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["الاكتفاء بأربع روابط لتحقيق الثمانية","وضع زوج حر على P","احتساب المجموع 12 بإهمال تعدد ذرات Cl"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-11T11:15:01.575Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1129, null, null, null, 'الكبريت في الدورة الثالثة، ويمكنه استيعاب أكثر من ثمانية إلكترونات حوله لتوافر المستوى الفرعي d في غلاف تكافؤه، فيكوّن ست روابط. أما الأكسجين ففي الدورة الثانية، وغلاف تكافؤه (n = 2) لا يحتوي على مستوى d، فلا يمكن أن يحيط به أكثر من ثمانية إلكترونات، فلا يكوّن ست روابط. عدد الإلكترونات حول S في SF₆ = 6 روابط × 2 = 12 إلكترونًا.', '["الكبريت في الدورة الثالثة","توافر المستوى d يسمح بتمدد الثمانية","الأكسجين في الدورة الثانية بلا مستوى d","حول S في SF₆ = 12 إلكترونًا"]'::jsonb, '["عدد الروابط حول S = 6","عدد الإلكترونات = 6 × 2 = 12"]'::jsonb, '[{"element":"تعليل قدرة الكبريت","marks":1},{"element":"تعليل عجز الأكسجين","marks":1},{"element":"حساب الإلكترونات حول S","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تعليل كامل للعنصرين وحساب صحيح"},{"level":"2 درجتان","description":"تعليل صحيح لعنصر واحد مع حساب صحيح، أو تعليل كامل دون حساب"},{"level":"1 درجة","description":"حساب صحيح فقط أو ذكر الدورة دون تفسير"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["تعليل الاختلاف بعدد إلكترونات التكافؤ","تعليله بالكهروسالبية","احتساب الإلكترونات حول S ستة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T11:15:01.577Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1130, null, null, null, 'BH₃: ثلاث روابط ولا أزواج حرة على B ← 6 إلكترونات (أقل من 8). NH₃: ثلاث روابط وزوج حر على N ← 8 إلكترونات (يساوي 8). PCl₅: خمس روابط ولا أزواج حرة على P ← 10 إلكترونات (أكثر من 8). SF₆: ست روابط ولا أزواج حرة على S ← 12 إلكترونًا (أكثر من 8).', '["BH₃ = 6 أقل من 8","NH₃ = 8","PCl₅ = 10 أكثر من 8","SF₆ = 12 أكثر من 8"]'::jsonb, '["BH₃: 3 × 2 = 6","NH₃: 3 × 2 + 2 = 8","PCl₅: 5 × 2 = 10","SF₆: 6 × 2 = 12"]'::jsonb, '[{"element":"BH₃","marks":1},{"element":"NH₃","marks":1},{"element":"PCl₅","marks":1},{"element":"SF₆","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تصنيف صحيح للأربعة مع عدد الإلكترونات"},{"level":"3 درجات","description":"ثلاثة صحيحة"},{"level":"2 درجتان","description":"اثنان صحيحان"},{"level":"1 درجة","description":"واحد صحيح"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["احتساب الإلكترونات حول N في NH₃ ستة بإهمال الزوج الحر","تصنيف PCl₅ ضمن «يساوي 8»","احتساب SF₆ عشرة إلكترونات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:01.578Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1131, 2, 'الرابطة التساهمية التناسقية رابطة تنتج من تقديم ذرة واحدة فقط زوج إلكترونات حرًا لذرة أو أيون آخر يشاركها فيه.', '["انتقال الإلكترونات يكوّن رابطة أيونية لا تساهمية.","هذا وصف الرابطة التساهمية العادية التي تسهم فيها كل ذرة بإلكترون.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T11:15:01.589Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1132, 0, 'يحمل النيتروجين في NH₃ زوجًا حرًا، والبورون في BH₃ ينقصه زوج لإكمال ثمانيته، فيقدّم N زوجه الحر للبورون.', '["","البورون في BH₃ لا يحمل أي زوج حر (حوله 6 إلكترونات فقط)، فهو المستقبل لا المانح.","ذرات الهيدروجين لا تحمل أزواجًا حرة، وكل منها مرتبط برابطة أحادية فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T11:15:01.590Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1133, 1, 'تتكون الرابطة التناسقية عندما تمتلك إحدى الذرتين زوج إلكترونات حرًا (مانح)، وتحتاج الأخرى إلى زوج لإكمال ثمانيتها أو استقراره (مستقبل) مثل BH₃ أو H⁺.', '["الرابطة التناسقية تتكون غالبًا بين ذرتين مختلفتين مثل N وB، وتشابه العنصر ليس شرطًا.","","فرق الكهروسالبية الكبير يؤدي إلى رابطة أيونية، وليس شرطًا للرابطة التناسقية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:01.590Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1134, 0, 'أيون H⁺ لا يملك أي إلكترون، والنيتروجين يحمل زوجًا حرًا، فيقدّمه لأيون H⁺ لتتكوّن رابطة تساهمية تناسقية N–H.', '["","الرابطة الجديدة تكونت بمشاركة زوج إلكترونات لا بانتقال إلكترونات، فهي تساهمية (تناسقية) لا أيونية.","أيون H⁺ ليس معه إلكترونات أصلًا، فلا يمكنه تقديم زوج؛ هو المستقبل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T11:15:01.592Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1135, 1, 'يحمل النيتروجين في NH₃ زوجًا حرًا يستطيع تقديمه لذرة أو أيون يحتاج إليه.', '["BH₃ لا يحمل زوجًا حرًا على B، بل ينقصه زوج، فهو مستقبل لا مانح.","","CH₄ لا يحمل أزواجًا حرة؛ أزواج الكربون الأربعة كلها رابطة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T11:15:01.593Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1136, 2, 'كلتا الرابطتين تتكون من زوج إلكترونات مشترك، لكن في التناسقية يأتي الزوج كاملًا من ذرة واحدة، وفي العادية تسهم كل ذرة بإلكترون.', '["الرابطتان كلتاهما تتكونان من زوج إلكترونات مشترك (إلكترونين)، فلا اختلاف في العدد.","انتقال الإلكترونات كليًا يميز الرابطة الأيونية، أما التناسقية فهي مشاركة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T11:15:01.593Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1137, 2, 'يحمل الأكسجين في H₂O زوجين حرين، وأيون H⁺ ليس معه إلكترونات ويستقبل زوجًا، فيتكون أيون الهيدرونيوم H₃O⁺ برابطة تناسقية.', '["H⁺ مستقبل مناسب، لكن CH₄ لا يحمل أي زوج حر ليقدّمه.","BF₃ مستقبل مناسب، لكن CH₄ لا يحمل أي زوج حر ليقدّمه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T11:15:01.593Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1138, null, null, null, 'الرابطة التساهمية التناسقية: رابطة تنتج من تقديم ذرة واحدة فقط زوج إلكترونات حرًا لذرة أو أيون آخر. في NH₃ يحيط بالنيتروجين ثلاثة أزواج رابطة وزوج حر، وأيون H⁺ لا يملك إلكترونات. يقدّم النيتروجين زوجه الحر لأيون H⁺ فتتكوّن رابطة N–H رابعة تناسقية: NH₃ + H⁺ → NH₄⁺. في الأيون الناتج يحيط بالنيتروجين أربعة أزواج رابطة (8 إلكترونات) ولا زوج حر عليه، ويحمل الأيون شحنة موجبة.', '["التعريف","N في NH₃ يحمل زوجًا حرًا","H⁺ بلا إلكترونات (مستقبل)","تقديم N زوجه لـ H⁺ وتكوّن الرابطة","وصف الناتج NH₄⁺ (أربعة أزواج رابطة وشحنة +)"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"تحديد المانح والمستقبل","marks":1},{"element":"توضيح تكوّن الرابطة","marks":1},{"element":"وصف الناتج","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف دقيق وتوضيح كامل لتكوّن NH₄⁺"},{"level":"3 درجات","description":"تعريف وتوضيح مع نقص وصف الناتج"},{"level":"2 درجتان","description":"تعريف صحيح مع تحديد المانح فقط"},{"level":"1 درجة","description":"التعريف فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["القول إن H⁺ يقدّم الإلكترونات","إبقاء زوج حر على N في NH₄⁺","وصف الرابطة بأنها أيونية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T11:15:01.594Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1139, null, null, null, 'الذرة المانحة: N في NH₃ لأنها تحمل زوجًا حرًا. الذرة المستقبلة: B في BH₃ لأنها لا تحمل أزواجًا حرة ويحيط بها 6 إلكترونات فقط فينقصها زوج. قبل التفاعل: حول B ستة إلكترونات (3 أزواج رابطة)، وحول N ثمانية (3 أزواج رابطة + زوج حر). بعد التفاعل: حول B ثمانية إلكترونات (4 أزواج رابطة)، وحول N ثمانية (4 أزواج رابطة، ولم يعد عليه زوج حر).', '["N مانحة لأنها تحمل زوجًا حرًا","B مستقبلة لأن حولها 6 إلكترونات","قبل: B = 6 ، N = 8","بعد: B = 8 ، N = 8"]'::jsonb, '["قبل: B = 3 × 2 = 6 ، N = 3 × 2 + 2 = 8","بعد: B = 4 × 2 = 8 ، N = 4 × 2 = 8"]'::jsonb, '[{"element":"تحديد المانح مع التعليل","marks":1},{"element":"تحديد المستقبل مع التعليل","marks":1},{"element":"الإلكترونات قبل التفاعل","marks":1},{"element":"الإلكترونات بعد التفاعل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحديد صحيح مع التعليل وحساب صحيح قبل التفاعل وبعده"},{"level":"3 درجات","description":"تحديد صحيح وحساب صحيح لإحدى الحالتين"},{"level":"2 درجتان","description":"تحديد صحيح للمانح والمستقبل دون حساب"},{"level":"1 درجة","description":"تحديد أحدهما فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["عكس دوري المانح والمستقبل","القول إن N يصبح حوله 10 إلكترونات بعد التفاعل","احتساب الإلكترونات حول B قبل التفاعل ثمانية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T11:15:01.594Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1140, null, null, null, 'مصدر الزوج: في الرابطة التساهمية العادية تسهم كل ذرة بإلكترون واحد، وفي التناسقية تقدّم ذرة واحدة الزوج كاملًا. طبيعة الرابطة: كلتاهما مشاركة لزوج إلكترونات بين ذرتين (لا انتقال للإلكترونات). مثال على العادية: الرابطة H–H في H₂ أو روابط N–H في NH₃. مثال على التناسقية: الرابطة N–B في H₃N–BH₃ أو الرابطة الرابعة في NH₄⁺.', '["مصدر الزوج في العادية: كل ذرة بإلكترون","مصدر الزوج في التناسقية: ذرة واحدة","كلتاهما مشاركة لا انتقال","مثال صحيح للعادية","مثال صحيح للتناسقية"]'::jsonb, '[]'::jsonb, '[{"element":"مصدر الزوج في الرابطتين","marks":2},{"element":"طبيعة الرابطة","marks":1},{"element":"المثالان","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"مقارنة كاملة ومثالان صحيحان"},{"level":"4 درجات","description":"مقارنة كاملة مع مثال واحد"},{"level":"3 درجات","description":"مقارنة مصدر الزوج مع مثالين دون ذكر طبيعة الرابطة"},{"level":"2 درجتان","description":"مقارنة مصدر الزوج فقط"},{"level":"1 درجة","description":"مثال صحيح واحد فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["القول إن الرابطة التناسقية تنتج من انتقال الإلكترونات","ذكر مثال أيوني مثل NaCl","القول إن الرابطة التناسقية تتكون من إلكترون واحد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T11:15:01.594Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1141, 0, 'VSEPR اختصار لنموذج التنافر بين أزواج إلكترونات التكافؤ، ويُستخدم لتحديد الشكل الهندسي للجزيء.', '["","النموذج يتعامل مع أزواج إلكترونات التكافؤ حول الذرة المركزية لا مع الأنوية.","النموذج قائم على التنافر بين أزواج الإلكترونات لا على التجاذب بينها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T11:15:01.597Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1142, 1, 'نموذج VSEPR نموذج يحدد الشكل الهندسي للجزيء اعتمادًا على تنافر أزواج إلكترونات التكافؤ حول الذرة المركزية.', '["الكتلة المولية تُحسب من الكتل الذرية ولا علاقة لها بالنموذج.","","عدد التأكسد مفهوم آخر لا يحدده نموذج VSEPR."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:01.598Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1143, 0, 'لأن أزواج الإلكترونات سالبة الشحنة فإنها تتنافر، فتتخذ أوضاعًا تجعلها أبعد ما يمكن بعضها عن بعض فيقل التنافر إلى أدنى حد.', '["","تقارب الأزواج يزيد التنافر بينها، والنموذج يفترض تقليل التنافر.","تجمع الأزواج في جهة واحدة يزيد التنافر ويخالف أساس النموذج."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-11T11:15:01.598Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1144, 1, 'يأخذ النموذج في الحسبان جميع أزواج إلكترونات التكافؤ حول الذرة المركزية، الرابطة منها والحرة، لأنها جميعًا تتنافر.', '["الإلكترونات الداخلية لا تشارك في الترابط ولا يعتمد عليها النموذج.","","إهمال الأزواج الحرة خطأ؛ فهي تتنافر مع غيرها وتؤثر في الشكل والزاوية (كما في NH₃ وH₂O)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-11T11:15:01.598Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1145, 0, 'من الجدول: الذرة المركزية في NH₃ لها زوج حر، وفي H₂O زوجان حران، بينما لا توجد أزواج حرة حول الذرة المركزية في BeCl₂ وAlCl₃ وCH₄.', '["","عدد الأزواج الحرة حول Be وAl صفر حسب الجدول.","عدد الأزواج الحرة حول C وAl صفر حسب الجدول."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T11:15:01.598Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1146, 2, 'زاوية الرابطة ناتجة عن تنافر أزواج إلكترونات التكافؤ حول الذرة المركزية، فتتحدد بعدد الأزواج الرابطة والحرة.', '["الحالة الفيزيائية تحددها القوى بين الجزيئات لا زوايا الروابط.","النيوترونات في النواة لا تؤثر في ترتيب الإلكترونات ولا في الزاوية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-11T11:15:01.598Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1147, 2, 'أربعة أزواج رابطة بلا أزواج حرة تتباعد إلى أقصى حد في اتجاهات رباعي الأوجه، فيكون الشكل رباعي الأوجه منتظمًا بزاوية 109.5° كما في CH₄.', '["المثلث المستوي يناسب ثلاثة أزواج رابطة فقط (مثل AlCl₃).","الشكل الخطي يناسب زوجين رابطين فقط (مثل BeCl₂).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (34%)"}],"at":"2026-10-11T11:15:01.599Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1148, null, null, null, 'نموذج VSEPR: نموذج يُستخدم لتحديد الشكل الهندسي للجزيء، ويقوم على أن أزواج إلكترونات التكافؤ (الرابطة والحرة) المحيطة بالذرة المركزية تتنافر لأنها سالبة الشحنة، فتترتب في الفراغ بحيث تكون أبعد ما يمكن بعضها عن بعض ليصبح التنافر أقل ما يمكن.', '["النموذج يحدد الشكل الهندسي للجزيء","التنافر بين أزواج إلكترونات التكافؤ","الأزواج تشمل الرابطة والحرة حول الذرة المركزية","الأزواج تتباعد أقصى ما يمكن لتقليل التنافر"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف النموذج (تحديد الشكل الهندسي)","marks":1},{"element":"ذكر التنافر بين أزواج إلكترونات التكافؤ","marks":1},{"element":"ذكر أن الأزواج الرابطة والحرة تؤخذ في الحسبان","marks":1},{"element":"تباعد الأزواج إلى أقصى حد لتقليل التنافر","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف كامل مع الفكرة الأساسية والأزواج الرابطة والحرة"},{"level":"3 درجات","description":"تعريف صحيح مع إغفال عنصر واحد"},{"level":"2 درجتان","description":"ذكر التنافر وتحديد الشكل فقط"},{"level":"1 درجة","description":"ذكر أن النموذج يتعلق بشكل الجزيء دون توضيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الأزواج تتجاذب","إهمال الأزواج الحرة","الخلط بين VSEPR والتهجين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T11:15:01.600Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1149, null, null, null, 'في CH₄ الأزواج الأربعة حول ذرة الكربون كلها رابطة، فتتباعد في اتجاهات رباعي الأوجه ويكون الشكل رباعي الأوجه منتظمًا بزاوية 109.5°. أما في H₂O فحول ذرة الأكسجين زوجان رابطان وزوجان حران؛ تترتب الأزواج الأربعة تقريبًا في اتجاهات رباعي الأوجه، لكن الشكل الهندسي يُحدد بمواقع الذرات فقط فيكون منحنيًا، والأزواج الحرة تشغل حيزًا أكبر وتتنافر بقوة أكبر فتضغط الزاوية إلى 104.5°.', '["CH₄: أربعة أزواج رابطة ولا أزواج حرة","CH₄ رباعي الأوجه 109.5°","H₂O: زوجان رابطان وزوجان حران","H₂O منحنٍ 104.5°","الأزواج الحرة تتنافر بقوة أكبر وتقلل الزاوية"]'::jsonb, '[]'::jsonb, '[{"element":"توزيع الأزواج في CH₄ وشكله وزاويته","marks":2},{"element":"توزيع الأزواج في H₂O وشكله وزاويته","marks":2},{"element":"تعليل أثر الأزواج الحرة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"مقارنة كاملة مع الشكلين والزاويتين وتعليل أثر الأزواج الحرة"},{"level":"4 درجات","description":"مقارنة صحيحة مع نقص في التعليل"},{"level":"3 درجات","description":"تحديد الشكلين صحيحًا دون الزوايا أو التعليل"},{"level":"1–2 درجة","description":"تحديد شكل جزيء واحد فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اعتبار H₂O رباعي الأوجه لأن حول الأكسجين أربعة أزواج","اعتبار H₂O خطيًا","إهمال دور الأزواج الحرة في تقليل الزاوية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (34%)"}],"at":"2026-10-11T11:15:01.600Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1150, null, null, null, 'الترتيب: زوج حر–زوج حر > زوج حر–زوج رابط > زوج رابط–زوج رابط. السبب أن الزوج الحر لا يرتبط إلا بنواة واحدة فيشغل حيزًا أكبر حول الذرة المركزية. في NH₃ يوجد زوج حر واحد يتنافر بقوة مع الأزواج الرابطة الثلاثة فيقربها بعضها من بعض فتقل الزاوية إلى 107.3°، أما في CH₄ فالأزواج الأربعة رابطة متساوية التنافر فتبقى الزاوية 109.5°.', '["الترتيب الصحيح لأنواع التنافر","الزوج الحر يشغل حيزًا أكبر","في NH₃ زوج حر يضغط الأزواج الرابطة","في CH₄ لا توجد أزواج حرة فالزاوية 109.5°"]'::jsonb, '[]'::jsonb, '[{"element":"الترتيب الصحيح","marks":1},{"element":"تعليل قوة تنافر الزوج الحر","marks":1},{"element":"تفسير زاوية NH₃","marks":1},{"element":"تفسير زاوية CH₄","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"ترتيب صحيح وتفسير كامل للزاويتين"},{"level":"3 درجات","description":"ترتيب صحيح وتفسير زاوية واحدة"},{"level":"2 درجتان","description":"ترتيب صحيح دون تفسير أو تفسير دون ترتيب"},{"level":"1 درجة","description":"ترتيب ناقص"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل تنافر الأزواج الرابطة هو الأقوى","القول إن الزوج الحر يزيد الزاوية","عدم ربط الترتيب بقيم الزوايا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:01.600Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1151, 1, 'حول ذرة Be زوجان رابطان ولا توجد أزواج حرة، فيتباعد الزوجان في اتجاهين متعاكسين ويكون الجزيء خطيًا.', '["الشكل المنحني يتطلب وجود أزواج حرة حول الذرة المركزية كما في H₂O، ولا توجد أزواج حرة حول Be.","","المثلث المستوي يتطلب ثلاثة أزواج رابطة كما في AlCl₃."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-10-11T11:15:01.603Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1152, 0, 'الزوجان الرابطان حول Be يتباعدان إلى أقصى حد في اتجاهين متعاكسين، فتكون الزاوية 180°.', '["","الزاوية 120° زاوية المثلث المستوي (ثلاثة أزواج رابطة).","الزاوية 109.5° زاوية رباعي الأوجه (أربعة أزواج رابطة)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T11:15:01.603Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1153, 0, 'لذرة Be إلكترونا تكافؤ فقط تشارك بهما في رابطتين مع ذرتي Cl، فيحيط بها زوجان رابطان ولا يبقى لها أزواج حرة.', '["","ثلاثة أزواج رابطة وزوج حر هو وضع النيتروجين في NH₃.","زوجان رابطان مع زوجين حرين هو وضع الأكسجين في H₂O، وBe لا يملك إلكترونات تكافؤ إضافية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T11:15:01.603Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1154, 2, 'الشكل يحدده عدد الأزواج حول الذرة المركزية: حول Be زوجان رابطان فقط فيتباعدان بزاوية 180°، أما حول O فأربعة أزواج منها اثنان حران فيصبح الشكل منحنيًا.', '["الروابط في كلا الجزيئين أحادية، والفرق في الأزواج الحرة حول الذرة المركزية.","حجم الذرات الطرفية ليس هو ما يحدد الشكل في نموذج VSEPR، بل عدد أزواج الإلكترونات حول الذرة المركزية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T11:15:01.604Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1155, 2, 'زوجان من الإلكترونات حول Be يقابلهما مستويان مهجنان من نوع sp متباعدان بزاوية 180°، فيكون الشكل خطيًا.', '["sp³ يقابل أربعة أزواج (CH₄، NH₃، H₂O).","sp² يقابل ثلاثة أزواج والشكل المثلث المستوي (AlCl₃).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-11T11:15:01.604Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1156, 1, 'لا توجد أزواج حرة حول Be، فالزوجان الرابطان يتنافران ويتخذان أبعد وضع ممكن على جانبي الذرة المركزية، فتكون الزاوية 180°.', '["لا توجد أزواج حرة حول Be؛ الزاوية 104.5° تخص H₂O.","","حول Be زوجان فقط لا أربعة؛ الزاوية 109.5° تخص CH₄."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-11T11:15:01.604Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1157, 2, 'CO₂ خطي بزاوية 180° لأن ذرة الكربون لا تحمل أزواجًا حرة وترتبط بذرتي أكسجين في اتجاهين متعاكسين (تعامل كل رابطة ثنائية كمجموعة واحدة)، مثل BeCl₂.', '["NH₃ مثلث هرمي بزاوية 107.3°.","H₂O منحنٍ بزاوية 104.5° بسبب زوجين حرين على الأكسجين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T11:15:01.604Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1158, null, null, null, 'حول ذرة Be المركزية زوجان من الإلكترونات الرابطة (رابطتان Be–Cl) ولا توجد أزواج حرة. يتنافر الزوجان فيتخذان أبعد وضع ممكن على جانبي ذرة Be، فيكون الجزيء خطيًا: Cl–Be–Cl، وزاوية الرابطة 180°، والتهجين sp.', '["زوجان رابطان ولا أزواج حرة حول Be","الشكل خطي","الزاوية 180°","التعليل بالتنافر وأقصى تباعد","رسم صحيح Cl–Be–Cl"]'::jsonb, '[]'::jsonb, '[{"element":"عدد الأزواج حول Be","marks":1},{"element":"الشكل الخطي مع الرسم","marks":1},{"element":"الزاوية 180°","marks":1},{"element":"التعليل بالتنافر","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"شكل وزاوية ورسم وتعليل صحيح"},{"level":"3 درجات","description":"شكل وزاوية صحيحان مع تعليل ناقص"},{"level":"2 درجتان","description":"الشكل أو الزاوية فقط مع رسم"},{"level":"1 درجة","description":"ذكر الشكل فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رسم الجزيء منحنيًا","وضع أزواج حرة على Be","كتابة الزاوية 120° أو 109.5°"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-10-11T11:15:01.604Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1159, null, null, null, 'BeCl₂: زوجان رابطان، لا أزواج حرة، خطي، 180°، sp. AlCl₃: ثلاثة أزواج رابطة، لا أزواج حرة، مثلث مستوٍ، 120°، sp².', '["الأزواج الرابطة 2 مقابل 3","الأزواج الحرة صفر في كليهما","خطي مقابل مثلث مستوٍ","180° مقابل 120°","sp مقابل sp²"]'::jsonb, '[]'::jsonb, '[{"element":"الأزواج الرابطة والحرة","marks":1},{"element":"الشكل الهندسي","marks":1},{"element":"زاوية الرابطة","marks":1},{"element":"نوع التهجين","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة صحيحة في جميع البنود"},{"level":"3 درجات","description":"خطأ في بند واحد"},{"level":"2 درجتان","description":"خطأ في بندين"},{"level":"1 درجة","description":"بند واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تبديل التهجين بين الجزيئين","كتابة 109.5° لـ AlCl₃","افتراض زوج حر على Al"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:01.605Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1160, null, null, null, 'التنبؤ غير صحيح. شكل الجزيء يتحدد بعدد أزواج التكافؤ حول الذرة المركزية لا بتشابه عدد الذرات الطرفية. حول Be زوجان رابطان فقط ولا توجد أزواج حرة، فيتباعدان إلى أقصى حد فيكون الجزيء خطيًا بزاوية 180°. أما الماء فمنحنٍ لأن حول الأكسجين زوجين حرين إلى جانب الزوجين الرابطين، وتنافرهما يجعل الشكل منحنيًا بزاوية 104.5°.', '["الحكم بأن التنبؤ خاطئ","الشكل يحدده عدد الأزواج حول الذرة المركزية","Be: زوجان رابطان بلا أزواج حرة → خطي 180°","H₂O منحنٍ بسبب زوجين حرين على O"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم الصحيح","marks":1},{"element":"المبدأ: الأزواج حول الذرة المركزية","marks":1},{"element":"تحليل BeCl₂","marks":1},{"element":"تحليل H₂O والفرق بينهما","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح مع تحليل كامل للجزيئين"},{"level":"3 درجات","description":"حكم صحيح مع تحليل جزيء واحد"},{"level":"2 درجتان","description":"حكم صحيح مع تعليل عام"},{"level":"1 درجة","description":"حكم صحيح دون تعليل"},{"level":"صفر","description":"تأييد التنبؤ أو لا إجابة"}]'::jsonb, '["تأييد التنبؤ","الاعتماد على عدد الذرات الطرفية فقط","عدم ذكر الأزواج الحرة في الماء"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:01.605Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1161, 0, 'حول ذرة N ثلاثة أزواج رابطة وزوج حر، والشكل يحدد بمواقع الذرات فقط، فيكون مثلثًا هرميًا (هرميًا ثلاثيًا).', '["","رباعي الأوجه المنتظم يكون عند وجود أربعة أزواج رابطة (CH₄)، وNH₃ فيه زوج حر.","المثلث المستوي يكون عند وجود ثلاثة أزواج رابطة دون أزواج حرة (AlCl₃)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:01.607Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1162, 1, 'زاوية الرابطة في NH₃ تساوي 107.3°، وهي أقل من 109.5° بسبب تنافر الزوج الحر مع الأزواج الرابطة.', '["109.5° زاوية رباعي الأوجه المنتظم (CH₄) الذي لا يحوي أزواجًا حرة.","","104.5° زاوية H₂O التي تحوي زوجين حرين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T11:15:01.607Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1163, 0, 'الفوسفور في المجموعة 15 مثل النيتروجين، له خمسة إلكترونات تكافؤ: ثلاثة تشارك في ثلاث روابط مع H، واثنان يكونان زوجًا حرًا.', '["","إهمال الزوج الحر؛ للفوسفور خمسة إلكترونات تكافؤ يبقى منها زوج حر.","زوجان رابطان وزوجان حران هو وضع الأكسجين في H₂O."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-11T11:15:01.608Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1164, 2, 'حول P ثلاثة أزواج رابطة وزوج حر كما في NH₃، فيكون شكله مثلثًا هرميًا أيضًا (مع أن زاويته الفعلية أصغر من زاوية NH₃).', '["AlCl₃ لا يحوي زوجًا حرًا حول الذرة المركزية، أما PH₃ ففيه زوج حر.","الشكل المنحني يكون عند وجود ذرتين طرفيتين وزوجين حرين، وPH₃ فيه ثلاث ذرات H.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:01.608Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1165, 2, 'حول N أربعة أزواج (ثلاثة رابطة وزوج حر)؛ الزوج الحر يشغل حيزًا أكبر ويتنافر بقوة أكبر مع الأزواج الرابطة فيقربها، فتقل الزاوية إلى 107.3°.', '["حول N أربعة أزواج لا ثلاثة؛ والزوج الحر جزء منها.","ذرات H المرتبطة لا تتجاذب، بل إن أزواج الروابط تتنافر.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T11:15:01.608Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1166, 1, 'AlCl₃ فيه ثلاثة أزواج رابطة مثل NH₃، لكنه بلا زوج حر فيكون مثلثًا مستويًا، بينما NH₃ مثلث هرمي.', '["H₂O فيه زوجان رابطان لا ثلاثة.","","CH₄ فيه أربعة أزواج رابطة لا ثلاثة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:01.609Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1167, 2, 'النيتروجين والفوسفور في المجموعة 15، فحول كل منهما ثلاثة أزواج رابطة وزوج حر، والشكل في الحالتين مثلث هرمي.', '["توزيع الأزواج الأربعة رباعي الأوجه تقريبًا، لكن الشكل الهندسي يحدد بمواقع الذرات فقط فيكون هرميًا.","عدد الذرات الطرفية وحده لا يحدد الشكل؛ الزوج الحر يجعل الشكل هرميًا لا مستويًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:01.609Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1168, null, null, null, 'حول ذرة N في NH₃ أربعة أزواج من إلكترونات التكافؤ: ثلاثة أزواج رابطة وزوج حر، فتترتب الأزواج تقريبًا في اتجاهات رباعي الأوجه (تهجين sp³)، لكن الشكل الهندسي يُحدد بمواقع الذرات فيكون مثلثًا هرميًا، وزاوية الرابطة 107.3°. وتكون أقل من زاوية CH₄ (109.5°) لأن الزوج الحر يشغل حيزًا أكبر ويتنافر بقوة أكبر مع الأزواج الرابطة فيقربها بعضها من بعض، بينما الأزواج الأربعة في CH₄ كلها رابطة.', '["3 أزواج رابطة وزوج حر حول N","الشكل مثلث هرمي","الزاوية 107.3°","تنافر الزوج الحر الأقوى يقلل الزاوية عن 109.5°"]'::jsonb, '[]'::jsonb, '[{"element":"عدد الأزواج حول N","marks":1},{"element":"الشكل الهندسي","marks":1},{"element":"قيمة الزاوية","marks":1},{"element":"تفسير الفرق عن CH₄","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة"},{"level":"3 درجات","description":"الشكل والزاوية صحيحان مع تفسير ناقص"},{"level":"2 درجتان","description":"الشكل أو الزاوية مع عدد الأزواج"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تسمية الشكل رباعي الأوجه","كتابة الزاوية 109.5°","إهمال الزوج الحر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T11:15:01.609Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1169, null, null, null, 'للفوسفور خمسة إلكترونات تكافؤ؛ يشارك بثلاثة منها في ثلاث روابط مع ثلاث ذرات H، ويبقى زوج حر. فيحيط بذرة P ثلاثة أزواج رابطة وزوج حر، والشكل مثلث هرمي مثل NH₃. ولا يكون مثلثًا مستويًا لأن الزوج الحر يشغل موقعًا في الفراغ فوق الذرة المركزية ويدفع الروابط الثلاث إلى أسفل، فلا تقع الذرات الأربع في مستوى واحد.', '["5 إلكترونات تكافؤ للفوسفور","3 أزواج رابطة وزوج حر","الشكل مثلث هرمي","الزوج الحر يمنع الشكل المستوي"]'::jsonb, '[]'::jsonb, '[{"element":"عدد إلكترونات التكافؤ","marks":1},{"element":"الأزواج الرابطة والحرة","marks":1},{"element":"الشكل الهندسي","marks":1},{"element":"تعليل عدم كونه مستويًا","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"استنتاج كامل صحيح"},{"level":"3 درجات","description":"خطأ أو نقص في عنصر واحد"},{"level":"2 درجتان","description":"عنصران صحيحان"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اعتبار PH₃ مثلثًا مستويًا","نسيان الزوج الحر","نقل زاوية NH₃ (107.3°) إلى PH₃"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-11T11:15:01.610Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1170, null, null, null, 'بلا أزواج حرة: BeCl₂ (180°)، AlCl₃ (120°)، CH₄ (109.5°). بأزواج حرة: NH₃ (زوج حر، 107.3°)، H₂O (زوجان حران، 104.5°). القاعدة: عندما يحيط بالذرة المركزية أربعة أزواج، فإن وجود أزواج حرة يقلل زاوية الرابطة عن 109.5°، وكلما زاد عدد الأزواج الحرة قلت الزاوية أكثر؛ فـ NH₃ بزوج حر واحد زاويته 107.3° وهي أقل من 109.5°.', '["تصنيف صحيح للمجموعتين","ذكر زوايا الجزيئات","القاعدة: الأزواج الحرة تقلل الزاوية عن 109.5°","الاستشهاد بـ NH₃ (107.3°)"]'::jsonb, '[]'::jsonb, '[{"element":"التصنيف","marks":2},{"element":"صياغة القاعدة","marks":2},{"element":"الاستشهاد بـ NH₃","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تصنيف وقاعدة واستشهاد كامل"},{"level":"4 درجات","description":"تصنيف صحيح وقاعدة دون استشهاد دقيق"},{"level":"3 درجات","description":"تصنيف صحيح وقاعدة ناقصة"},{"level":"1–2 درجة","description":"تصنيف جزئي"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["وضع NH₃ مع الجزيئات بلا أزواج حرة","القول إن الأزواج الحرة تزيد الزاوية","مقارنة زاوية BeCl₂ بزاوية رباعي الأوجه دون مراعاة عدد الأزواج"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:01.611Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1171, 2, 'حول ذرة O زوجان رابطان وزوجان حران، والشكل يحدد بمواقع الذرات الثلاث فيكون منحنيًا.', '["الشكل الخطي يكون عند وجود زوجين رابطين فقط دون أزواج حرة (BeCl₂).","المثلث الهرمي يكون عند وجود ثلاثة أزواج رابطة وزوج حر (NH₃).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-11T11:15:01.614Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1172, 1, 'زاوية الرابطة في الماء 104.5°، وهي أقل من زاوية رباعي الأوجه بسبب تنافر الزوجين الحرين على ذرة الأكسجين.', '["107.3° زاوية NH₃ التي فيها زوج حر واحد فقط.","","180° زاوية الجزيء الخطي الذي لا يحوي أزواجًا حرة حول الذرة المركزية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T11:15:01.615Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1173, 2, 'للأكسجين 6 إلكترونات تكافؤ؛ يشارك باثنين في رابطتين مع ذرتي H، ويبقى 4 إلكترونات تكون زوجين حرين.', '["زوج حر واحد هو حال النيتروجين في NH₃ (5 إلكترونات تكافؤ).","ثلاثة أزواج حرة تعني أن الأكسجين يكوّن رابطة واحدة فقط، وهو هنا يكوّن رابطتين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T11:15:01.615Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1174, 0, 'كلما زاد عدد الأزواج الحرة حول الذرة المركزية زاد ضغطها على الأزواج الرابطة؛ في الماء زوجان حران وفي NH₃ زوج واحد، فتكون زاوية الماء أصغر.', '["","حجم الذرة المركزية ليس هو السبب المعتمد في نموذج VSEPR، والسبب عدد الأزواج الحرة.","عدد الذرات الطرفية وحده لا يحدد الزاوية؛ فـ BeCl₂ فيه ذرتان طرفيتان وزاويته 180°."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T11:15:01.615Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1175, 1, 'حول الأكسجين أربعة أزواج (اثنان رابطان واثنان حران)، فيقابلها أربعة مستويات مهجنة من نوع sp³.', '["sp² يقابل ثلاثة أزواج حول الذرة المركزية كما في AlCl₃.","","sp يقابل زوجين كما في BeCl₂."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T11:15:01.615Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1176, 0, 'الماء: زوجان رابطان، وزوجان حران، وشكل منحنٍ، وزاوية 104.5°، وهذا هو الصف (ج).', '["","الصف (أ) يصف جزيئًا خطيًا بلا أزواج حرة مثل BeCl₂.","الصف (ب) يصف جزيئًا مثلثًا هرميًا مثل NH₃."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:01.615Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1177, 1, 'الشكل الخطي يناسب ذرة مركزية تحيط بها أزواج رابطة فقط، لكن الأكسجين يحمل زوجين حرين يتنافران مع الأزواج الرابطة فيصبح الشكل منحنيًا بزاوية 104.5°.', '["الروابط في الماء أحادية، ونوع الروابط ليس سبب الخطأ هنا.","","على الأكسجين في الماء زوجان حران لا زوج واحد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:01.616Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1178, null, null, null, 'للأكسجين ستة إلكترونات تكافؤ؛ يشارك باثنين منها في رابطتين تساهميتين مع ذرتي الهيدروجين، ويبقى زوجان حران. يحيط بالأكسجين أربعة أزواج (2 رابطة + 2 حرة) تترتب تقريبًا في اتجاهات رباعي الأوجه (sp³)، لكن الشكل الهندسي يُحدد بمواقع الذرات فيكون منحنيًا، وزاوية الرابطة 104.5° لأن الزوجين الحرين يتنافران بقوة مع الزوجين الرابطين فيقربانهما.', '["زوجان رابطان وزوجان حران حول O","الشكل منحنٍ","الزاوية 104.5°","رسم يظهر الزوجين الحرين","تعليل صغر الزاوية بتنافر الأزواج الحرة"]'::jsonb, '[]'::jsonb, '[{"element":"عدد الأزواج حول O","marks":1},{"element":"الشكل الهندسي مع الرسم","marks":1},{"element":"قيمة الزاوية","marks":1},{"element":"التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة مع رسم صحيح"},{"level":"3 درجات","description":"شكل وزاوية صحيحان مع تعليل أو رسم ناقص"},{"level":"2 درجتان","description":"الشكل أو الزاوية مع عدد الأزواج"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رسم الجزيء خطيًا","إغفال الأزواج الحرة في الرسم","كتابة الزاوية 107.3° أو 109.5°"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-11T11:15:01.616Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1179, null, null, null, 'الترتيب التصاعدي: H₂O (104.5°) < NH₃ (107.3°) < CH₄ (109.5°). التفسير: حول الذرة المركزية في الجزيئات الثلاثة أربعة أزواج، لكن CH₄ لا أزواج حرة فيه فتبقى الزاوية 109.5°، وNH₃ فيه زوج حر واحد يضغط الأزواج الرابطة فتقل الزاوية إلى 107.3°، وH₂O فيه زوجان حران يضغطان الأزواج الرابطة أكثر فتقل الزاوية إلى 104.5°.', '["الترتيب الصحيح مع القيم","أربعة أزواج حول الذرة المركزية في الجميع","عدد الأزواج الحرة: 0، 1، 2","زيادة الأزواج الحرة تقلل الزاوية"]'::jsonb, '[]'::jsonb, '[{"element":"الترتيب الصحيح","marks":1},{"element":"ذكر قيم الزوايا","marks":1},{"element":"عدد الأزواج الحرة في كل جزيء","marks":1},{"element":"ربط عدد الأزواج الحرة بالزاوية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"ترتيب وقيم وتفسير كامل"},{"level":"3 درجات","description":"ترتيب وتفسير مع خطأ في قيمة"},{"level":"2 درجتان","description":"ترتيب صحيح دون تفسير"},{"level":"1 درجة","description":"ترتيب جزئي"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس الترتيب","القول إن الزوج الحر يزيد الزاوية","إهمال أن العدد الكلي للأزواج أربعة في الجميع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T11:15:01.617Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1180, null, null, null, 'BeCl₂: لا أزواج حرة حول Be، خطي، 180°، sp. H₂O: زوجان حران حول O، منحنٍ، 104.5°، sp³.', '["الأزواج الحرة: صفر مقابل اثنين","الشكل: خطي مقابل منحنٍ","الزاوية: 180° مقابل 104.5°","التهجين: sp مقابل sp³"]'::jsonb, '[]'::jsonb, '[{"element":"الأزواج الحرة","marks":1},{"element":"الشكل الهندسي","marks":1},{"element":"زاوية الرابطة","marks":1},{"element":"نوع التهجين","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة صحيحة في البنود الأربعة"},{"level":"3 درجات","description":"خطأ في بند واحد"},{"level":"2 درجتان","description":"خطأ في بندين"},{"level":"1 درجة","description":"بند واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اعتبار الجزيئين خطيين لتشابه عدد الذرات","كتابة تهجين الأكسجين sp","إغفال الأزواج الحرة على O"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T11:15:01.617Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1181, 0, 'التهجين هو خلط (دمج) المستويات الفرعية في الذرة (مثل s وp) لتكوين مستويات مهجنة جديدة متماثلة في الطاقة والشكل.', '["","التداخل بين ذرتين يكوّن الرابطة، أما التهجين فيحدث داخل الذرة الواحدة.","انتقال الإلكترونات وتكوين الأيونات يصف الرابطة الأيونية لا التهجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-11T11:15:01.621Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1182, 1, 'ينتج التهجين مستويات جديدة متماثلة؛ فمستويات sp³ الأربعة في الكربون متساوية الطاقة ومتماثلة الشكل.', '["التماثل في الطاقة والشكل هو جوهر التهجين.","","المستويات المهجنة متساوية الطاقة، وهذا ما يميزها عن مستويات s وp الأصلية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T11:15:01.621Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1183, 0, 'عدد المستويات المهجنة يساوي عدد المستويات الذرية التي اختلطت: 1 + 3 = 4 مستويات sp³.', '["","عدد المستويات المهجنة يساوي مجموع المستويات المختلطة (s وثلاثة p)، أي أربعة لا ثلاثة.","الخلط لا يدمج المستويات في مستوى واحد؛ يبقى العدد الكلي محفوظًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:01.621Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1184, 2, 'الرمز sp² يعني خلط مستوى s واحد مع مستويين p، فيتكون ثلاثة مستويات مهجنة sp².', '["خلط s مع p واحد ينتج sp.","خلط s مع ثلاثة p ينتج sp³.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T11:15:01.622Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1185, 1, 'التوزيع الإلكتروني للكربون 1s² 2s² 2p² يتضمن مستويات مختلفة في الطاقة والشكل، بينما الروابط الأربع في CH₄ متماثلة؛ فيُفسر ذلك بخلط 2s مع مستويات 2p الثلاثة لتكوين أربعة مستويات sp³ متماثلة.', '["الكربون يحتوي على إلكترونين في 2p حسب توزيعه 1s² 2s² 2p².","","روابط C–H تساهمية لا أيونية، والكربون لا يكوّن أيون C⁴⁺ هنا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T11:15:01.622Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1186, 1, 'من الجدول: sp (مستويان) 180°، sp² (3 مستويات) 120°، sp³ (4 مستويات) 109.5°؛ فزيادة عدد المستويات تقلل الزاوية لأن الأزواج تتوزع حول الذرة في اتجاهات أكثر.', '["عكس العلاقة؛ القيم في الجدول تتناقص من 180° إلى 109.5°.","","الجدول يبين تغير الزاوية من 180° إلى 109.5°."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-11T11:15:01.622Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1187, 2, 'التهجين خلط لمستويات التكافؤ الفرعية داخل الذرة الواحدة، تنتج عنه مستويات مهجنة تستخدمها الذرة في تكوين روابطها.', '["التهجين يشمل مستويات التكافؤ (مثل 2s و2p في الكربون) لا المستويات الداخلية.","خلط مستويات ذرتين مختلفتين هو تداخل يكوّن الرابطة وليس تهجينًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T11:15:01.622Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1188, null, null, null, 'التهجين: خلط (دمج) المستويات الفرعية في الذرة (مثل s وp) لتكوين مستويات مهجنة جديدة متماثلة. من خصائص المستويات المهجنة: (1) متماثلة متساوية في الطاقة والشكل، (2) عددها يساوي عدد المستويات الذرية التي اختلطت، (3) تتوزع حول الذرة بزوايا محددة (مثل 109.5° في sp³).', '["تعريف التهجين بأنه خلط مستويات فرعية","تكوين مستويات جديدة مهجنة","المستويات المهجنة متماثلة","عددها يساوي عدد المستويات المختلطة"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":2},{"element":"خاصية أولى","marks":1},{"element":"خاصية ثانية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف دقيق وخاصيتان صحيحتان"},{"level":"3 درجات","description":"تعريف دقيق وخاصية واحدة"},{"level":"2 درجتان","description":"تعريف دقيق فقط أو تعريف ناقص مع خاصيتين"},{"level":"1 درجة","description":"تعريف ناقص"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعريف التهجين بأنه تداخل مستويات ذرتين","القول إن المستويات المهجنة مختلفة الطاقة","الخلط بين التهجين والرابطة الأيونية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T11:15:01.623Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1189, null, null, null, '1) في الحالة الأرضية: 2s² 2p² (إلكترونان منفردان فقط في 2p). 2) يُثار إلكترون من 2s إلى مستوى 2p الفارغ فيصبح: 2s¹ 2p³ (أربعة إلكترونات منفردة). 3) يختلط مستوى 2s مع مستويات 2p الثلاثة فتتكون أربعة مستويات مهجنة sp³ متماثلة، في كل منها إلكترون واحد. 4) يتداخل كل مستوى sp³ مع مستوى 1s لذرة هيدروجين فتتكون أربع روابط C–H متماثلة باتجاهات رباعي الأوجه (109.5°).', '["الحالة الأرضية 2s² 2p²","إثارة إلكترون من 2s إلى 2p","خلط 2s مع ثلاثة 2p لتكوين 4 مستويات sp³","في كل مستوى sp³ إلكترون واحد","تكوين 4 روابط متماثلة مع H"]'::jsonb, '["كتابة التوزيع في الحالة الأرضية: 2s² 2p²","الإثارة: 2s¹ 2p³","التهجين: 4 مستويات sp³ في كل منها إلكترون","التداخل مع 1s لأربع ذرات H"]'::jsonb, '[{"element":"الإثارة الصحيحة","marks":1},{"element":"عملية الخلط وعدد المستويات الناتجة","marks":2},{"element":"عدد الإلكترونات في كل مستوى","marks":1},{"element":"تكوين الروابط الأربع المتماثلة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"خطوات كاملة صحيحة"},{"level":"4 درجات","description":"خطوات صحيحة مع إغفال خطوة التداخل"},{"level":"3 درجات","description":"الإثارة والتهجين صحيحان فقط"},{"level":"1–2 درجة","description":"ذكر تكوين sp³ دون خطوات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إغفال خطوة الإثارة","وضع إلكترونين في كل مستوى مهجن","القول إن التهجين ينتج ثلاثة مستويات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:01.623Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1190, null, null, null, 'sp: يختلط s واحد مع p واحد ← مستويان مهجنان، الزاوية 180°، مثال BeCl₂. sp²: s واحد مع p اثنين ← ثلاثة مستويات، 120°، مثال AlCl₃. sp³: s واحد مع ثلاثة p ← أربعة مستويات، 109.5°، مثال CH₄ (وكذلك NH₃ وH₂O).', '["sp: s+p، مستويان، 180°، BeCl₂","sp²: s+2p، ثلاثة، 120°، AlCl₃","sp³: s+3p، أربعة، 109.5°، CH₄"]'::jsonb, '[]'::jsonb, '[{"element":"صف sp","marks":1},{"element":"صف sp²","marks":1},{"element":"صف sp³","marks":1},{"element":"الأمثلة الصحيحة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جدول كامل صحيح مع الأمثلة"},{"level":"3 درجات","description":"خطأ واحد"},{"level":"2 درجتان","description":"خطآن أو ثلاثة"},{"level":"1 درجة","description":"صف واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تبديل زاويتي sp² وsp³","خلط عدد مستويات p المختلطة","إعطاء AlCl₃ مثالًا على sp³"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-11T11:15:01.623Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1191, 0, 'حول الكربون أربعة أزواج رابطة، فيقابلها أربعة مستويات مهجنة sp³ تتجه نحو رؤوس رباعي أوجه منتظم.', '["","sp² يقابل ثلاثة أزواج كما في AlCl₃.","sp يقابل زوجين كما في BeCl₂."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-10-11T11:15:01.625Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1192, 0, 'حول Al ثلاثة أزواج رابطة ولا أزواج حرة، فيقابلها ثلاثة مستويات مهجنة sp² في مستوى واحد بزاوية 120°.', '["","sp يتطلب زوجين فقط حول الذرة المركزية.","sp³ يتطلب أربعة أزواج حول الذرة المركزية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-10-11T11:15:01.626Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1193, 2, 'إلكترونات Al الثلاثة تشارك في ثلاث روابط مع Cl، فلا يبقى زوج حر، وثلاثة أزواج تحتاج ثلاثة مستويات مهجنة (sp²).', '["Al لا يملك إلكترونات تكافؤ إضافية لتكوين زوج حر.","حول Al ثلاث روابط لا اثنتان، ولا أزواج حرة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T11:15:01.626Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1194, 2, 'مستويات sp³ في CH₄ تتجه نحو رؤوس رباعي أوجه بزاوية 109.5°، ومستويات sp² في AlCl₃ في مستوى واحد بزاوية 120°.', '["180° زاوية التهجين sp (الشكل الخطي) لا sp².","عكس الترتيب؛ 120° لـ AlCl₃ و109.5° لـ CH₄.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T11:15:01.626Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1195, 1, 'تهجين الكربون في CH₄ هو sp³: خلط 2s مع مستويات 2p الثلاثة لتكوين أربعة مستويات مهجنة متماثلة.', '["هذا وصف التهجين sp² الذي يكوّن ثلاثة مستويات فقط، والكربون في CH₄ يكوّن أربع روابط.","","الروابط الأربع تتكون من تداخل مستويات sp³ مع 1s لأربع ذرات H، لا من 2s وحده."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T11:15:01.626Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1196, 1, 'تهجين Al في AlCl₃ هو sp² لأن حوله ثلاثة أزواج رابطة بلا أزواج حرة؛ والجزيء (ب) ذرته المركزية تحيط بها ثلاثة أزواج رابطة بلا أزواج حرة فتهجينها sp².', '["الجزيء (أ): أربعة أزواج رابطة، فتهجينه sp³ مثل CH₄.","","الجزيء (ج): ثلاثة أزواج رابطة وزوج حر، أي أربعة أزواج، فتهجينه sp³."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T11:15:01.627Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1197, 1, 'التهجين يتحدد بالعدد الكلي للأزواج حول الذرة المركزية (رابطة وحرة): Al حوله 3 أزواج ← sp²، وN حوله 3 أزواج رابطة وزوج حر = 4 ← sp³.', '["إهمال الزوج الحر على N؛ مجموع الأزواج حوله أربعة فتهجينه sp³.","","Al لا يحمل زوجًا حرًا، فحوله ثلاثة أزواج فقط وتهجينه sp²."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T11:15:01.627Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1198, null, null, null, 'CH₄: حول الكربون أربعة أزواج رابطة ولا أزواج حرة ← التهجين sp³، والشكل رباعي الأوجه منتظم، والزاوية 109.5°. AlCl₃: حول الألومنيوم ثلاثة أزواج رابطة ولا أزواج حرة ← التهجين sp²، والشكل مثلث مستوٍ، والزاوية 120°.', '["CH₄: 4 أزواج، sp³","CH₄: رباعي الأوجه، 109.5°","AlCl₃: 3 أزواج، sp²","AlCl₃: مثلث مستوٍ، 120°"]'::jsonb, '[]'::jsonb, '[{"element":"تهجين CH₄ مع عدد الأزواج","marks":1},{"element":"شكل CH₄ وزاويته","marks":1},{"element":"تهجين AlCl₃ مع عدد الأزواج","marks":1},{"element":"شكل AlCl₃ وزاويته","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة للجزيئين"},{"level":"3 درجات","description":"خطأ في بند واحد"},{"level":"2 درجتان","description":"جزيء واحد صحيح كاملًا"},{"level":"1 درجة","description":"نوع تهجين واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تبديل التهجين بين الجزيئين","كتابة 109.5° لـ AlCl₃","عد ذرات Cl بدل الأزواج حول Al"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T11:15:01.627Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1199, null, null, null, 'الخطوات: 1) حدد الذرة المركزية وعدد إلكترونات تكافؤها. 2) حدد عدد الروابط مع الذرات الطرفية (عدد الأزواج الرابطة). 3) احسب الأزواج الحرة المتبقية. 4) اجمع الأزواج الرابطة والحرة: 2 ← sp، 3 ← sp²، 4 ← sp³. التطبيق على AlCl₃: الذرة المركزية Al لها 3 إلكترونات تكافؤ، تكوّن 3 روابط مع 3 ذرات Cl، فلا يبقى أزواج حرة؛ مجموع الأزواج 3 ← التهجين sp² (مثلث مستوٍ، 120°).', '["تحديد الذرة المركزية وإلكترونات التكافؤ","عد الأزواج الرابطة والحرة","ربط المجموع بنوع التهجين","تطبيق صحيح على AlCl₃ ← sp²"]'::jsonb, '["الذرة المركزية Al: 3 إلكترونات تكافؤ","عدد الروابط مع Cl = 3","الأزواج الحرة = 0","المجموع 3 ← sp²"]'::jsonb, '[{"element":"كتابة الخطوات العامة","marks":2},{"element":"قاعدة الربط بين عدد الأزواج والتهجين","marks":1},{"element":"التطبيق على AlCl₃","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"خطوات صحيحة وتطبيق كامل"},{"level":"4 درجات","description":"خطوات ناقصة مع تطبيق صحيح"},{"level":"3 درجات","description":"تطبيق صحيح دون خطوات عامة"},{"level":"1–2 درجة","description":"ذكر sp² دون تبرير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إغفال الأزواج الحرة في الخطوات العامة","عد ذرات الكلور مع إلكتروناتها الحرة كأزواج حول Al","الربط الخاطئ: 3 أزواج ← sp³"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T11:15:01.627Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1200, null, null, null, 'في CH₄ أربعة مستويات sp³ تحمل أربعة أزواج رابطة؛ أبعد توزيع ممكن لأربعة أزواج حول ذرة هو اتجاهات رؤوس رباعي أوجه منتظم في الفراغ بزاوية 109.5°، فلا يمكن وضعها في مستوى واحد دون زيادة التنافر. أما في AlCl₃ فثلاثة مستويات sp² تحمل ثلاثة أزواج؛ وأبعد توزيع لثلاثة أزواج هو رؤوس مثلث متساوي الأضلاع في مستوى واحد بزاوية 120°.', '["CH₄: أربعة مستويات sp³","أبعد توزيع لأربعة أزواج: رباعي أوجه في الفراغ 109.5°","AlCl₃: ثلاثة مستويات sp²","أبعد توزيع لثلاثة أزواج: مثلث مستوٍ 120°","مبدأ تقليل التنافر"]'::jsonb, '[]'::jsonb, '[{"element":"تحليل CH₄","marks":2},{"element":"تحليل AlCl₃","marks":2},{"element":"ربط التوزيع بتقليل التنافر","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تفسير كامل للجزيئين مع مبدأ التنافر"},{"level":"4 درجات","description":"تفسير الجزيئين دون ذكر صريح للتنافر"},{"level":"3 درجات","description":"تفسير جزيء واحد مع المبدأ"},{"level":"1–2 درجة","description":"ذكر نوعي التهجين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن CH₄ مستوٍ بزوايا 90°","عدم ربط عدد المستويات بالتوزيع الفراغي","تبديل التهجين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T11:15:01.628Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1201, 1, 'الميل الإلكتروني هو مقدار الطاقة المصاحبة لإضافة إلكترون إلى ذرة متعادلة مفردة في الحالة الغازية لتكوين أيون سالب.', '["هذا تعريف الكهروسالبية، وهي تخص الذرة المرتبطة في رابطة.","","هذا تعريف طاقة التأين، وهي تتعلق بنزع الإلكترون لا باكتسابه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T11:15:01.630Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1202, 1, 'اكتساب الذرة المتعادلة إلكترونًا يجعل عدد إلكتروناتها أكبر من عدد بروتوناتها، فتتحول إلى أيون سالب.', '["الأيون الموجب يتكون بفقد الإلكترونات (طاقة التأين).","","إضافة إلكترون تغير شحنة الذرة فلا تبقى متعادلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:01.630Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1203, 1, 'الميل الإلكتروني مقدار طاقة لكل مول من الذرات، فيقاس بوحدة kJ/mol.', '["J·s وحدة ثابت بلانك، لا وحدة طاقة لكل مول.","","الكهروسالبية هي التي تُعطى قيمًا نسبية بلا وحدة، أما الميل الإلكتروني فمقدار طاقة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T11:15:01.631Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1204, 2, 'تحتاج ذرات الهالوجينات (المجموعة 17) إلى إلكترون واحد لإكمال ثمانيتها، فتميل بقوة إلى اكتساب الإلكترون فيكون ميلها الإلكتروني كبيرًا.', '["الفلزات القلوية لها إلكترون تكافؤ واحد وتميل إلى فقده لا إلى اكتساب إلكترون.","الغازات النبيلة مستوياتها الخارجية ممتلئة، فليس لها ميل لاكتساب الإلكترونات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-11T11:15:01.631Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1205, 0, 'الميل الإلكتروني يخص الذرة الغازية المفردة غير المرتبطة ويقاس بـ kJ/mol، أما الكهروسالبية فهي قابلية الذرة لجذب إلكترونات الرابطة عندما تكون مرتبطة، وقيمها نسبية بلا وحدة.', '["","هذا خطأ شائع؛ المصطلحان مختلفان في المعنى والوحدة.","عكس الصحيح؛ الكهروسالبية هي التي تتعلق بالذرة داخل الرابطة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T11:15:01.631Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1206, 2, 'الغازات النبيلة ذات مستوى خارجي ممتلئ (ثماني مستقر، أو 1s² في He)، فإضافة إلكترون تعني وضعه في مستوى أعلى بعيد عن النواة، فلا تميل إلى ذلك.', '["أنوية جميع الذرات تحتوي على بروتونات.","الغازات النبيلة لها طاقات تأين عالية، أي أنها لا تفقد إلكتروناتها بسهولة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-11T11:15:01.631Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1207, 0, 'الميل الإلكتروني يرتبط بإضافة إلكترون إلى ذرة غازية متعادلة لتكوين أيون سالب: Cl(g) + e⁻ → Cl⁻(g) (الطاقة المصاحبة لهذه العملية).', '["","هذه عملية تكسير رابطة في جزيء الكلور لا اكتساب إلكترون.","هذه عملية نزع إلكترون، أي طاقة التأين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T11:15:01.631Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1208, null, null, null, 'الميل الإلكتروني: مقدار الطاقة المصاحبة لإضافة إلكترون إلى ذرة متعادلة مفردة في الحالة الغازية لتكوين أيون سالب. الفروق: (1) الميل الإلكتروني خاصية للذرة المنفردة غير المرتبطة، أما الكهروسالبية فقابلية الذرة لجذب إلكترونات الرابطة وهي مرتبطة بذرة أخرى. (2) الميل الإلكتروني يقاس بوحدة طاقة (kJ/mol)، أما الكهروسالبية فقيم نسبية بلا وحدة.', '["تعريف الميل الإلكتروني (طاقة، ذرة غازية متعادلة، أيون سالب)","فرق: الذرة المنفردة مقابل الذرة المرتبطة","فرق: kJ/mol مقابل قيم بلا وحدة"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":2},{"element":"الفرق الأول","marks":1},{"element":"الفرق الثاني","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف دقيق وفرقان صحيحان"},{"level":"3 درجات","description":"تعريف دقيق وفرق واحد"},{"level":"2 درجتان","description":"تعريف ناقص وفرق واحد أو فرقان دون تعريف"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين الميل الإلكتروني وطاقة التأين","عد المصطلحين مترادفين","إغفال شرط الحالة الغازية والذرة المتعادلة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T11:15:01.631Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1209, null, null, null, 'الكلور من الهالوجينات، في مستواه الخارجي سبعة إلكترونات، فيحتاج إلى إلكترون واحد فقط لإكمال الثمانية والوصول إلى ترتيب مستقر، فيميل بقوة إلى اكتساب إلكترون ويكوّن أيون Cl⁻. أما النيون فمستواه الخارجي ممتلئ بثمانية إلكترونات (ترتيب مستقر)، والإلكترون المضاف لا يجد مكانًا إلا في مستوى أعلى بعيد عن النواة، فلا يميل إلى اكتسابه.', '["الكلور: 7 إلكترونات تكافؤ يحتاج إلكترونًا واحدًا","اكتساب الإلكترون يكمل الثمانية ويكوّن Cl⁻","النيون: مستوى خارجي ممتلئ","الإلكترون المضاف يدخل مستوى أعلى فلا يميل لاكتسابه"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير حالة الكلور","marks":2},{"element":"تفسير حالة النيون","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل للعنصرين"},{"level":"3 درجات","description":"تفسير كامل لعنصر وناقص للآخر"},{"level":"2 درجتان","description":"تفسير عنصر واحد"},{"level":"1 درجة","description":"ذكر الثمانية دون ربط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن النيون يفقد الإلكترونات بسهولة","الخلط بين الميل الإلكتروني والكهروسالبية في التعليل","القول إن الكلور يكتسب إلكترونين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-11T11:15:01.632Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1210, null, null, null, '(1) ميل إلكتروني: إضافة إلكترون إلى ذرة فلور غازية متعادلة وتكوين أيون سالب. (2) طاقة تأين: نزع إلكترون من ذرة بوتاسيوم غازية وتكوين أيون موجب. (3) ميل إلكتروني: إضافة إلكترون إلى ذرة بروم غازية وتكوين أيون سالب. (4) غير ذلك: تبخر (تغير حالة فيزيائية) لا إضافة فيه ولا نزع لإلكترون.', '["(1) ميل إلكتروني مع السبب","(2) طاقة تأين مع السبب","(3) ميل إلكتروني مع السبب","(4) تغير حالة فيزيائية"]'::jsonb, '[]'::jsonb, '[{"element":"العملية 1","marks":1},{"element":"العملية 2","marks":1},{"element":"العملية 3","marks":1},{"element":"العملية 4","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تصنيف صحيح ومعلل للعمليات الأربع"},{"level":"3 درجات","description":"ثلاث عمليات صحيحة"},{"level":"2 درجتان","description":"عمليتان صحيحتان"},{"level":"1 درجة","description":"عملية واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تصنيف العملية 2 ميلًا إلكترونيًا","عدم الانتباه إلى اتجاه حركة الإلكترون","عد التبخر ميلًا إلكترونيًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T11:15:01.632Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1211, 2, 'حسب المذكرة: إذا كان فرق الكهروسالبية أكبر من 1.7 تكون الرابطة أيونية (مثل NaCl).', '["التساهمية غير القطبية يكون فيها الفرق صفرًا أو صغيرًا جدًا.","التساهمية القطبية يكون فيها الفرق أقل من 1.7.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T11:15:01.635Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1212, 0, 'الفرق = 3.1 − 0.9 = 2.2، وهو أكبر من 1.7، فالرابطة أيونية.', '["","جمع القيمتين (3.1 + 0.9) بدل طرحهما.","الفرق صحيح لكن 2.2 أكبر من 1.7 فالرابطة أيونية لا قطبية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (47%)"}],"at":"2026-10-11T11:15:01.635Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1213, 2, 'الفرق = 3.1 − 1.6 = 1.5، وهو أقل من 1.7 وأكبر بوضوح من الصفر، فالرابطة تساهمية قطبية.', '["1.5 أقل من 1.7 فلا تكون الرابطة أيونية مع أن Al فلز.","الفرق 1.5 كبير، والرابطة غير القطبية تكون عند التساوي أو التقارب البسيط.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:01.636Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1214, 1, 'الذرتان متماثلتان فالفرق في الكهروسالبية صفر، وتتشارك الذرتان إلكترونات الرابطة بالتساوي، فالرابطة تساهمية غير قطبية.', '["الرابطة الأيونية تتطلب فرقًا أكبر من 1.7.","","القطبية تتطلب فرقًا في الكهروسالبية، والفرق هنا صفر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-11T11:15:01.636Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1215, 1, 'الذرة الأكبر كهروسالبية (O) تجذب إلكترونات الرابطة نحوها أكثر فتحمل δ−، وتحمل S الشحنة δ+.', '["الذرة الأقل كهروسالبية تحمل δ+ لا δ−.","","الفرق 0.9 يجعل الرابطة قطبية فتظهر شحنات جزئية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:01.636Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1216, 1, 'N–F: الفرق = 3.9 − 3.0 = 0.9 (أقل من 1.7) فهي تساهمية قطبية. Na–F: الفرق 3.0 فهي أيونية. O–O: الفرق صفر فهي غير قطبية.', '["O–O ذرتان متماثلتان فالفرق صفر والرابطة غير قطبية.","","Na–F فرقها 3.0 فهي أيونية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T11:15:01.638Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1217, 0, 'الفروق: Br–Br = 0 ، Al–Br = 1.3 ، Na–Br = 2.0؛ فكلما زاد الفرق زادت القطبية (حتى تصبح أيونية في Na–Br).', '["","هذا ترتيب تنازلي لا تصاعدي.","Br–Br فرقها صفر فهي الأقل قطبية، لا Al–Br."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T11:15:01.638Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1218, null, null, null, 'Na–O: 3.4 − 0.9 = 2.5 > 1.7 ← أيونية. Al–Cl: 3.1 − 1.6 = 1.5 < 1.7 ← تساهمية قطبية. S–O: 3.4 − 2.5 = 0.9 ← تساهمية قطبية. F–F: 3.9 − 3.9 = 0 ← تساهمية غير قطبية.', '["Na–O: 2.5 أيونية","Al–Cl: 1.5 تساهمية قطبية","S–O: 0.9 تساهمية قطبية","F–F: 0 تساهمية غير قطبية"]'::jsonb, '["Na–O: |3.4 − 0.9| = 2.5 ← أكبر من 1.7 ← أيونية","Al–Cl: |3.1 − 1.6| = 1.5 ← أقل من 1.7 ← تساهمية قطبية","S–O: |3.4 − 2.5| = 0.9 ← تساهمية قطبية","F–F: 0 ← تساهمية غير قطبية"]'::jsonb, '[{"element":"Na–O (الفرق والنوع)","marks":1},{"element":"Al–Cl (الفرق والنوع)","marks":1},{"element":"S–O (الفرق والنوع)","marks":1},{"element":"F–F (الفرق والنوع)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حساب وتصنيف صحيح للروابط الأربع"},{"level":"3 درجات","description":"ثلاث روابط صحيحة"},{"level":"2 درجتان","description":"رابطتان صحيحتان"},{"level":"1 درجة","description":"رابطة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جمع القيم بدل طرحها","تصنيف Al–Cl أيونية لأن Al فلز","مقارنة الفرق بـ 1.7 بصورة معكوسة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (47%)"}],"at":"2026-10-11T11:15:01.639Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1219, null, null, null, 'غير القطبية: الفرق صفر أو صغير جدًا، تتشارك الذرتان الإلكترونات بالتساوي، مثل C–C أو Cl–Cl. القطبية: الفرق أقل من 1.7، تتشارك الذرتان الإلكترونات بصورة غير متساوية فتنجذب نحو الأكبر كهروسالبية (δ−) وتظهر شحنات جزئية، مثل H–F وH–O. الأيونية: الفرق أكبر من 1.7، تنتقل الإلكترونات من الذرة الأقل كهروسالبية إلى الأكبر فتتكون أيونات، مثل NaCl وAlF₃.', '["غير القطبية: فرق صفري/صغير، مشاركة متساوية، مثال","القطبية: فرق < 1.7، مشاركة غير متساوية وشحنات جزئية، مثال","الأيونية: فرق > 1.7، انتقال إلكترونات وتكوين أيونات، مثال"]'::jsonb, '[]'::jsonb, '[{"element":"الرابطة غير القطبية","marks":2},{"element":"الرابطة القطبية","marks":2},{"element":"الرابطة الأيونية","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"مقارنة كاملة مع أمثلة صحيحة"},{"level":"4–5 درجات","description":"مقارنة صحيحة مع نقص في الأمثلة أو التوزيع"},{"level":"2–3 درجات","description":"تحديد مدى الفرق لكل نوع دون شرح التوزيع"},{"level":"1 درجة","description":"نوع واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الإلكترونات تنتقل في الرابطة القطبية","إعطاء NaCl مثالًا على القطبية","عدم ذكر الشحنات الجزئية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T11:15:01.639Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1220, null, null, null, 'Al–F: الفرق = 3.9 − 1.6 = 2.3 > 1.7 ← أيونية (AlF₃ مثال المذكرة). Al–Cl: الفرق = 3.1 − 1.6 = 1.5 < 1.7 ← تساهمية قطبية. إذن العبارة غير صحيحة على إطلاقها؛ فنوع الرابطة يحدده فرق الكهروسالبية لا مجرد كون إحدى الذرتين فلزًا، فقد تكون الرابطة بين فلز ولافلز تساهمية قطبية إذا كان الفرق أقل من 1.7.', '["حساب فرق Al–F = 2.3 وتصنيفها أيونية","حساب فرق Al–Cl = 1.5 وتصنيفها تساهمية قطبية","الحكم بأن العبارة غير صحيحة على إطلاقها","المعيار هو فرق الكهروسالبية"]'::jsonb, '["Al–F: 3.9 − 1.6 = 2.3 ← أيونية","Al–Cl: 3.1 − 1.6 = 1.5 ← تساهمية قطبية","الاستنتاج: العبارة لا تصح دائمًا"]'::jsonb, '[{"element":"حساب وتصنيف Al–F","marks":1},{"element":"حساب وتصنيف Al–Cl","marks":1},{"element":"الحكم على العبارة","marks":1},{"element":"ذكر المعيار الصحيح","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حسابات وحكم ومعيار صحيح"},{"level":"3 درجات","description":"حسابات صحيحة وحكم دون معيار"},{"level":"2 درجتان","description":"حساب واحد صحيح مع حكم"},{"level":"1 درجة","description":"حساب واحد صحيح"},{"level":"صفر","description":"تأييد العبارة دون دليل أو لا إجابة"}]'::jsonb, '["تأييد العبارة لأن Al فلز","خطأ في الطرح","عدم المقارنة بالحد 1.7"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T11:15:01.639Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1221, 1, 'الجزيء القطبي ثنائي القطب له طرف δ+ وطرف δ−، فيتوجه الطرف δ+ نحو اللوح السالب والطرف δ− نحو اللوح الموجب.', '["الجزيء متعادل كليًا لكنه يحمل شحنات جزئية تجعله يتأثر بالمجال.","","الشحنات المتشابهة تتنافر، فلا يتجه الطرف الموجب نحو اللوح الموجب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T11:15:01.642Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1222, 2, 'الجزيئات القطبية تحمل شحنات جزئية (δ+ وδ−) على طرفيها نتيجة عدم تساوي توزيع الإلكترونات، فتتأثر بالمجال الكهربائي وتتوجه فيه.', '["الجزيء القطبي متعادل الشحنة كليًا، والشحنات فيه جزئية فقط.","الجزيئات التساهمية القطبية لا تحتوي على أيونات حرة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:01.642Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1223, 1, 'جزيء الماء قطبي (روابط قطبية وشكل منحنٍ غير متماثل)، فهو ثنائي القطب ويتوجه في المجال الكهربائي.', '["CH₄ غير قطبي، فلا يتوجه في المجال الكهربائي.","","CO₂ روابطه قطبية لكنه خطي متماثل فمحصلة القطبية صفر، فلا يتوجه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T11:15:01.642Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1224, 0, 'جزيئات الماء قطبية، فيتوجه طرفها المخالف لشحنة الساق نحوها فتنجذب، بينما السائل غير القطبي لا يحمل شحنات جزئية.', '["","الانحراف سببه القطبية لا خفة الجزيئات، فالسائل غير القطبي لا ينحرف.","الماء النقي يحتوي على نسبة ضئيلة جدًا من الأيونات، والتفسير بقطبية الجزيئات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:01.643Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1225, 2, 'CCl₄ رباعي الأوجه متماثل، فمحصلة قطبيات الروابط الأربع صفر، والجزيء غير قطبي فلا يتوجه في المجال.', '["روابط C–Cl قطبية والكلور يحمل δ−، لكن المحصلة صفر بسبب التماثل.","كهروسالبية الكلور أكبر من الكربون، ولذلك فالروابط قطبية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T11:15:01.643Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1226, 0, 'المواد التي تتوجه جزيئاتها في المجال الكهربائي قطبية، وهما (أ) و(ج).', '["","(ب) لم تتوجه جزيئاتها فهي غير قطبية.","(ب) و(د) لم تتوجه جزيئاتهما فهما غير قطبيتين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:01.643Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1227, 1, 'الكلور أكبر كهروسالبية من الهيدروجين فيحمل δ−، فيتجه نحو اللوح الموجب، ويتجه طرف H (δ+) نحو اللوح السالب.', '["الكلور يحمل δ− لا δ+، فيتجه نحو اللوح الموجب.","","الهيدروجين هو الأقل كهروسالبية فيحمل δ+ لا δ−."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T11:15:01.644Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1228, null, null, null, 'الجزيء القطبي ثنائي القطب: توزيع الإلكترونات فيه غير متساوٍ فيحمل طرف منه شحنة جزئية سالبة (δ−) والطرف الآخر شحنة جزئية موجبة (δ+). فعند وضعه في مجال كهربائي يتجه طرفه δ− نحو اللوح الموجب وطرفه δ+ نحو اللوح السالب فتنتظم الجزيئات. أما الجزيء غير القطبي فلا يحمل شحنات جزئية محصلة (محصلة القطبية صفر)، فلا يتأثر بالمجال ويبقى عشوائي الاتجاه.', '["الجزيء القطبي ثنائي القطب يحمل δ+ وδ−","δ− يتجه نحو اللوح الموجب وδ+ نحو السالب","غير القطبي محصلة قطبيته صفر","غير القطبي لا يتأثر بالمجال"]'::jsonb, '[]'::jsonb, '[{"element":"وجود الشحنات الجزئية في القطبي","marks":1},{"element":"اتجاه الطرفين نحو اللوحين","marks":1},{"element":"محصلة القطبية صفر في غير القطبي","marks":1},{"element":"عدم تأثر غير القطبي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعليل كامل للنوعين"},{"level":"3 درجات","description":"تعليل كامل للقطبي وناقص لغير القطبي"},{"level":"2 درجتان","description":"تعليل القطبي فقط"},{"level":"1 درجة","description":"ذكر الشحنات الجزئية دون ربط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الجزيء القطبي يحمل شحنة كلية","عكس اتجاه الطرفين","القول إن الجزيئات القطبية تتحرك نحو لوح واحد بدل أن تتوجه"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T11:15:01.644Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1229, null, null, null, 'في جزيء الماء تحمل ذرة الأكسجين (الأعلى كهروسالبية) شحنة جزئية سالبة δ−، وتحمل ذرتا الهيدروجين شحنة جزئية موجبة δ+. وعند وضعه بين لوحين تتوجه الجزيئات بحيث تشير ذرات O (δ−) نحو اللوح الموجب، وذرات H (δ+) نحو اللوح السالب، فتصطف الجزيئات في اتجاه المجال.', '["O يحمل δ− وH يحمل δ+","تعليل الشحنات بالكهروسالبية","طرف O نحو اللوح الموجب","طرف H نحو اللوح السالب"]'::jsonb, '[]'::jsonb, '[{"element":"الشحنات الجزئية الصحيحة","marks":1},{"element":"تعليلها بالكهروسالبية","marks":1},{"element":"اتجاه طرف O","marks":1},{"element":"اتجاه طرف H","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مخطط/وصف صحيح كامل"},{"level":"3 درجات","description":"خطأ في عنصر واحد"},{"level":"2 درجتان","description":"الشحنات صحيحة والاتجاه خاطئ"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["وضع δ− على الهيدروجين","رسم الماء خطيًا","توجيه O نحو اللوح السالب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T11:15:01.644Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1230, null, null, null, 'الخطوات: يُترك كل سائل يسيل في خيط رفيع، ثم تُقرَّب الساق المشحونة من الخيط دون أن تلمسه، وتُلاحظ حركة الخيط، ويُكرَّر ذلك مع السائل الآخر. النتيجة: خيط السائل القطبي ينحرف نحو الساق، وخيط السائل غير القطبي لا ينحرف تقريبًا. التفسير: جزيئات السائل القطبي ثنائية القطب تحمل شحنات جزئية، فتتوجه بحيث يقابل الطرف المخالف لشحنة الساق الساق فتنجذب، أما جزيئات السائل غير القطبي فلا تحمل شحنات جزئية محصلة فلا تتأثر.', '["خطوات واضحة مع ضبط المتغيرات","القطبي ينحرف نحو الساق","غير القطبي لا ينحرف","التفسير بالشحنات الجزئية وتوجه الجزيئات"]'::jsonb, '[]'::jsonb, '[{"element":"خطوات التجربة","marks":1},{"element":"النتيجة المتوقعة للسائلين","marks":2},{"element":"التفسير","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"تصميم ونتائج وتفسير كامل"},{"level":"4 درجات","description":"نتائج وتفسير صحيحان مع خطوات ناقصة"},{"level":"3 درجات","description":"نتائج صحيحة وتفسير ناقص"},{"level":"1–2 درجة","description":"نتيجة سائل واحد فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["توقع انحراف السائلين معًا","تفسير الانحراف بوجود أيونات","لمس الساق للخيط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:01.644Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1231, 2, 'القاعدة العامة للذوبان «الأشباه تذوب في الأشباه»: المذاب القطبي يذوب في المذيب القطبي، وغير القطبي في غير القطبي.', '["المذيب القطبي كالماء لا يذيب المواد غير القطبية كالزيت.","المواد غير القطبية لا تذوب في الماء لأنه مذيب قطبي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:01.647Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1232, 0, 'الكحول مركب قطبي، والماء مذيب قطبي، فتذوب جزيئات الكحول في الماء وفق قاعدة «الأشباه تذوب في الأشباه» (مثال المذكرة).', '["","الزيت مادة غير قطبية فلا يذوب في الماء القطبي.","البارافين مادة غير قطبية فلا يذوب في الماء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T11:15:01.647Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1233, 1, 'كل من NH₃ وH₂O قطبي يحمل شحنات جزئية، فيحدث تجاذب بين الطرف السالب جزئيًا لجزيء والطرف الموجب جزئيًا لجزيء المادة الأخرى، فتنتشر جزيئات المذاب بين جزيئات المذيب.', '["الماء مذيب قطبي وليس غير قطبي.","","الذوبان لا يكسر الروابط التساهمية داخل جزيء الأمونيا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T11:15:01.647Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1234, 1, 'HCl جزيء قطبي، والماء مذيب قطبي، فيذوب فيه. أما CCl₄ وCH₄ فجزيئاتهما غير قطبية لذا لا تذوب في الماء.', '["جزيء CCl₄ غير قطبي لتماثل شكله مع أن روابطه قطبية.","","جزيء CH₄ غير قطبي، فلا يذوب في الماء القطبي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T11:15:01.648Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1235, 2, 'المادة القطبية تذوب في مذيب قطبي، والماء هو المذيب القطبي الوحيد بين البدائل.', '["البنزين مذيب غير قطبي يذيب المواد غير القطبية كالزيت.","زيت الطبخ سائل غير قطبي لا يذيب المواد القطبية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T11:15:01.648Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1236, 0, 'الكحول والماء كلاهما قطبي، فيتجاذبان وتذوب جزيئات الكحول في الماء مكونة محلولًا متجانسًا من طبقة واحدة.', '["","الطبقتان تظهران عند خلط مادة غير قطبية كالزيت مع الماء.","الكحول سائل يذوب في الماء ولا يترسب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:01.648Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1237, 1, 'الكحول قطبي فتنشأ قوى تجاذب بين جزيئاته وجزيئات الماء القطبية فيذوب، أما الزيت فغير قطبي فلا ينجذب إلى جزيئات الماء بالقدر الكافي فلا يذوب.', '["الذوبان يتحدد بالقطبية وليس بالكثافة، والزيت أصلًا يطفو على الماء.","","الكحول مركب تساهمي قطبي وليس أيونيًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T11:15:01.648Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1238, null, null, null, 'جزيء الكحول قطبي يحمل شحنات جزئية (δ+ وδ−)، وجزيء الماء قطبي كذلك. فعند خلطهما تنجذب الأطراف الموجبة جزئيًا في جزيئات إحدى المادتين إلى الأطراف السالبة جزئيًا في جزيئات الأخرى، فتنتشر جزيئات الكحول بين جزيئات الماء ويتكون محلول متجانس. وهذا تطبيق لقاعدة «الأشباه تذوب في الأشباه»: المذاب القطبي يذوب في المذيب القطبي.', '["الكحول قطبي","الماء قطبي","التجاذب بين الشحنات الجزئية المختلفة","ذكر القاعدة وتطبيقها"]'::jsonb, '[]'::jsonb, '[{"element":"الكحول قطبي","marks":1},{"element":"الماء قطبي","marks":1},{"element":"التجاذب بين δ+ وδ−","marks":1},{"element":"ربط ذلك بقاعدة الأشباه تذوب في الأشباه","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"ذكر نصف العناصر تقريبًا مع ربط ضعيف"},{"level":"1 درجة","description":"عنصر واحد صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الكحول مركب أيوني يتفكك في الماء","ذكر القاعدة دون تفسير التجاذب","الخلط بين الذوبان والتفاعل الكيميائي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T11:15:01.648Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.')
